SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Sixtus I was Roman Pontiff in the period 115–120.'::text) || jsonb_build_object('background', 'Pope Sixtus I, whose name is also spelled Xystus, was a Roman of Greek descent and served as Rome''s bishop from c. 117 or 119 until c. 126 or 128, when he died. Alexander I came before him and Telesphorus after. His feast is kept on 6 April.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Sixtus_I", "summary": "rewritten", "background": "rewritten"}'::jsonb),
