UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'The Roman Pontiff Pope Pius I held office from 140–154.'::text) || jsonb_build_object('background', 'Pope Pius I was bishop of Rome from c. 140 until he died c. 154, as the Annuario Pontificio records it. Its alternative dates are 142 or 146 for the start and 157 or 161 for the end, respectively. During his papacy he is regarded as having stood against both the Valentinians and the Gnostics. The Catholic Church counts him as a saint and keeps his feast day on 11 July, though it is uncertain whether he died as a martyr.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Pius_I", "summary": "rewritten", "background": "rewritten"}'::jsonb),
