UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Anicetus was bishop of Rome from c. 157 until he died in April 168. The Annuario Pontificio suggests his papacy may have begun in 153. He took an active stand against Gnosticism and Marcionism, and he invited Polycarp of Smyrna to come to Rome so that they could talk over the Easter controversy.'::text) || jsonb_build_object('summary', 'Pope Anicetus was Roman Pontiff in the period 150–160.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Anicetus", "background": "rewritten", "summary": "rewritten"}'::jsonb),
