UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'From c. 167 until he died c. 174, Pope Soter was bishop of Rome, though the Annuario Pontificio says his years may have run from 162–168 to 170–177. His birthplace was Fundi, in Italy''s Lazio region. He is remembered for ruling that a marriage counted as valid only when a priest blessed it as a sacrament, and for formally establishing Easter as a yearly festival in Rome. Since he lived before the custom of taking a papal name, his name, taken from the Greek Σωτήριος, from σωτήρ "saviour", would have been the one given at baptism.'::text) || jsonb_build_object('summary', 'The Roman Pontiff Pope Soter held office from 168–174.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Soter", "background": "rewritten", "summary": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
