UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Eleutherius, also called Eleutherus, was Rome''s bishop from c. 174 until he died in 189. Some date his pontificate instead to 171–185 or 177–193. The Catholic Church venerates him as a saint.'::text) || jsonb_build_object('summary', 'Pope Eleuterus was Roman Pontiff in the period 175–189.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Eleutherius", "background": "rewritten", "summary": "rewritten"}'::jsonb),
