UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'The Roman Pontiff Pope Victor I held office from 189–199.'::text) || jsonb_build_object('background', 'Pope Victor I, a prelate of Roman African background in the Catholic Church, was Bishop of Rome during the late second century. His term is not firmly dated; one source says he became pope in 189 and died in 199. His birthplace was the Roman Province of Africa, and his origin was Berber. Later he came to be regarded as a saint, and his feast day, 28 July, is kept as "St Victor I, Pope and Martyr".'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Victor_I", "summary": "rewritten", "background": "rewritten"}'::jsonb),
