UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Zephyrinus was bishop of Rome from 199 until he died on 20 December 217. A native of Rome, he followed Victor I, and after his death on 20 December 217 his chief advisor, Callixtus I, took his place. He is remembered for fighting heresies and upholding the divinity of Christ.'::text) || jsonb_build_object('summary', 'Pope Zephyrinus was Roman Pontiff in the period 199–217.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Zephyrinus", "background": "rewritten", "summary": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
