UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Callixtus I, who is also called Callistus I, was bishop of Rome from c. 218 until his death c. 222 or 223, a period covering the reigns of Elagabalus and of Alexander Severus, both Roman emperors. His episcopate is listed by Eusebius and by the Liberian catalogue as five years (217–222). On succeeding Zephyrinus as Bishop of Rome in 217, he began receiving into the Church converts who came from sects or schisms. Put to death for being a Christian, he is venerated by the Catholic Church as a saint and martyr.'::text) || jsonb_build_object('summary', 'The Roman Pontiff Pope Callixtus I held office from 218–222.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Callixtus_I", "background": "rewritten", "summary": "rewritten"}'::jsonb),
