UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Gelasius I was bishop of Rome, beginning on 1 March 492, until he died on 21 November 496. A productive writer, he stood at the threshold between Late Antiquity and the Early Middle Ages in style. Certain scholars suggest his predecessor Felix III may have had him compose papal documents, but this is not certain.'::text) || jsonb_build_object('summary', 'The Roman Pontiff Pope Gelasius I held office from 492–496.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Gelasius_I", "background": "rewritten", "summary": "rewritten"}'::jsonb),
