UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Anastasius II was Roman Pontiff in the period 496–498.'::text) || jsonb_build_object('background', 'Pope Anastasius II was Rome''s bishop. His tenure began on 24 November 496, and he died on 19 November 498. He played a major part in the effort to end the Acacian schism, yet his efforts led to the Laurentian schism that came after his death. Born in Rome as a priest''s son, Anastasius is buried in St. Peter''s Basilica.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Anastasius_II", "summary": "rewritten", "background": "rewritten"}'::jsonb),
