UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Symmachus was Rome''s bishop, from 22 November 498 to 19 July 514, when he died. His tenure saw a grave schism about who had been chosen pope by the majority of the Roman clergy.'::text) || jsonb_build_object('summary', 'Pope Symmachus held office as Roman Pontiff from 498 to 514.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Symmachus", "background": "rewritten", "summary": "rewritten"}'::jsonb),
