UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'The Roman Pontiff Pope Hormisdas held office from 514–523.'::text) || jsonb_build_object('background', 'Pope Hormisdas held the see of Rome as bishop from 20 July 514 until he died on 6 August 523. The Acacian schism, which began in 484 when Acacius of Constantinople tried to appease the non-Chalcedonians, was the chief concern of his papacy. He succeeded in ending it, and on 28 March 519 the cathedral of Constantinople hosted a ceremony, in front of a large crowd, that confirmed Constantinople and Rome as reunited.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Hormisdas", "summary": "rewritten", "background": "rewritten"}'::jsonb),
