UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope John I was Roman Pontiff in the period 523–526.'::text) || jsonb_build_object('background', 'Pope John I was bishop of Rome. His tenure began on 13 August 523, and he died on 18 May 526. Siena, in Italy, was his birthplace. In 525 he was central to unifying the way the Western Church worked out the date of Easter, assisted by the monk Dionysius Exiguus. The Ostrogoth King Theoderic dispatched him to Constantinople on a diplomatic mission to win better treatment for Arians. John achieved relative success, but when he returned to Ravenna, Theoderic imprisoned him on the allegation of conspiring with Constantinople. Neglect and ill-treatment killed the frail pope.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_John_I", "summary": "rewritten", "background": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmq9l5w7q00fkg92dn85rfwvo'
