UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Felix IV served as bishop of Rome. His papacy began on 12 July 526 and ended with his death on 22 September 530. The Ostrogoth king Theodoric the Great, having imprisoned Felix''s predecessor John I, chose Felix as his candidate.'::text) || jsonb_build_object('summary', 'Pope Felix IV held office as Roman Pontiff during 526–530.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Felix_IV", "background": "rewritten", "summary": "rewritten"}'::jsonb),
