UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope John II held office as Roman Pontiff during 533–535.'::text) || jsonb_build_object('background', 'Pope John II, whose birth name was Mercurius, was Bishop of Rome. He took office on 2 January 533 and died on 8 May 535. Back when he was a priest serving St. Clement''s Basilica, he gave gifts to that church and had stone carvings made for it. Upon becoming pope, Mercurius was the first to take a new papal name. During his pontificate John II removed Bishop Contumeliosus of Riez from office, called a council about readmitting Arian clergy, and endorsed an edict of the emperor Justinian that proclaimed doctrine his predecessor, Pope Hormisdas, had opposed.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_John_II", "summary": "rewritten", "background": "rewritten"}'::jsonb),
