UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Silverius, who held the office of Roman Pontiff from 536–537.'::text) || jsonb_build_object('background', 'Pope Silverius was Rome''s bishop from 8 June 536 until he was deposed in 537, some months before his death. His quick rise from deacon to the papacy matched the plans of the Ostrogothic king Theodahad, who wanted a pro-Gothic candidate installed shortly before the Gothic War. The Byzantine general Belisarius later deposed him; he was tried and exiled to Palmarola, a deserted island, and there he starved to death in 537.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Silverius", "summary": "rewritten", "background": "rewritten"}'::jsonb),
