UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Pelagius I served as bishop of Rome. He took office on 16 April 556 and died on 3 March 561. He had earlier been apocrisiarius to Constantinople. Emperor Justinian I put him forward as his candidate, and the Western Church received his election poorly. Before becoming pope he resisted Justinian''s attempts to condemn the "Three Chapters", seeking to reconcile the theological factions within the Church, but he afterwards took up Justinian''s position.'::text) || jsonb_build_object('summary', 'Pope Pelagius I held office as Roman Pontiff during 556–561.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Pelagius_I", "background": "rewritten", "summary": "rewritten"}'::jsonb),
