UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Eugene II held office as Roman Pontiff during 824–827.'::text) || jsonb_build_object('background', 'Pope Eugene II, a Roman by birth, governed as bishop of Rome and head of the Papal States. His reign began on 6 June 824 and ended with his death on 27 August 827. Nobles selected him as Paschal I''s successor, although the clergy and the people preferred Zinzinnus. This established firmly the Carolingian Franks'' influence over papal elections. In 826 he called a council at Rome that condemned simony and suspended clergy lacking training. The council decreed that cathedral churches and other places should set up schools teaching sacred and secular literature. He played only a minor part in the Byzantine Iconoclasm controversy.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Eugene_II", "summary": "rewritten", "background": "rewritten"}'::jsonb),
