UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Valentine held office as Roman Pontiff during 827–827.'::text) || jsonb_build_object('background', 'Pope Valentine governed as bishop of Rome and head of the Papal States for just two months in 827. He was a nobleman, chosen by the nobility, as later became customary. He had an unusually close bond with his predecessor, Eugene II, whom rumour made Valentine''s father or lover, and he was made pope before he had been ordained as a priest.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Valentine", "summary": "rewritten", "background": "rewritten"}'::jsonb),
