UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Gregory IV led the Papal States, and was bishop of Rome, from October 827 until he died on 25 January 844. Notable in his pontificate were the papacy’s efforts to step into the disputes of Emperor Louis the Pious with his sons. The Carolingian Empire also broke up in 843 during this time.'::text) || jsonb_build_object('summary', 'Pope Gregory IV, who held the office of Roman Pontiff from 827–844.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Gregory_IV", "background": "rewritten", "summary": "rewritten"}'::jsonb),
