UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Sergius II held office as Roman Pontiff during 844–847.'::text) || jsonb_build_object('background', 'Pope Sergius II governed as bishop of Rome and head of the Papal States. His term began in January 844 and ended with his death in 847. During his pontificate the Arabs raided Rome, and the city was also redeveloped.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Sergius_II", "summary": "rewritten", "background": "rewritten"}'::jsonb),
