UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'The Roman Pontiff Pope Leo IV held office from 847–855.'::text) || jsonb_build_object('background', 'Pope Leo IV, bishop of Rome and head of the Papal States, held office from 10 April 847 until he died in 855. He is remembered for restoring the Roman churches damaged in the Arab attack on Rome, and for raising a defensive wall, the Leonine Wall, around Vatican Hill. He also gathered a league of Italian cities that won the naval Battle of Ostia against the Saracens.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Leo_IV", "summary": "rewritten", "background": "rewritten"}'::jsonb),
