UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Joan was a woman who allegedly ruled as popess for two years in the Middle Ages. The story is first found in chronicles of the 13th century, and from there it spread across Europe. People widely believed it for centuries, but most scholars today consider it fiction.'::text) || jsonb_build_object('summary', 'Pope Joan, who ruled as Roman Pontiff from 855 to 858.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Joan", "background": "rewritten", "summary": "rewritten"}'::jsonb),
