UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Benedict III governed as bishop of Rome and head of the Papal States. He took office on 29 September 855 and died on 17 April 858.'::text) || jsonb_build_object('summary', 'Pope Benedict III held office as Roman Pontiff during 855–858.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Benedict_III", "background": "rewritten", "summary": "rewritten"}'::jsonb),
