UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Nicholas I held office as Roman Pontiff during 858–867.'::text) || jsonb_build_object('background', 'Pope Nicholas I, known as Nicholas the Great, governed as bishop of Rome and head of the Papal States. He took office on 24 April 858 and died on 13 November 867. The Annuario Pontificio lists three popes with the title "the Great": Leo I, Gregory I and, last of the three, Nicholas I.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Nicholas_I", "summary": "rewritten", "background": "rewritten"}'::jsonb),
