UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Adrian II, who held the office of Roman Pontiff from 867–872.'::text) || jsonb_build_object('background', 'Pope Adrian II ruled the Papal States as Rome''s bishop from 867 until he died on 14 December 872. His policy was that of his predecessor, Nicholas I. He tried to stay on good terms with Louis II of Italy, yet was put under watch, and supporters of Louis killed his wife and daughters.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Adrian_II", "summary": "rewritten", "background": "rewritten"}'::jsonb),
