UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope John VIII held office as Roman Pontiff during 872–882.'::text) || jsonb_build_object('background', 'Pope John VIII governed as bishop of Rome and head of the Papal States. His term began on 14 December 872 and ended with his death. Many regard him as among the ablest popes of the 9th century.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_John_VIII", "summary": "rewritten", "background": "rewritten"}'::jsonb),
