UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Marinus I governed as bishop of Rome and head of the Papal States. His term began in 882 and ended with his death on 15 May 884. He had been papal legate to Constantinople and was already a bishop when elected pope, which was controversial at the time. He was mistakenly known as Pope Martin II, with the result that the next pope to choose the name Martin became Martin IV.'::text) || jsonb_build_object('summary', 'Pope Marinus I held office as Roman Pontiff during 882–884.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Marinus_I", "background": "rewritten", "summary": "rewritten"}'::jsonb),
