UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Adrian III held office as Roman Pontiff during 884–885.'::text) || jsonb_build_object('background', 'Pope Adrian III, also written Hadrian III, was bishop of Rome and head of the Papal States. His term began on 17 May 884 and ended with his death on 8 July 885. His pontificate lasted barely over a year, and in that time, which was marked by famine and war in Italy, he worked to assist the Italian people.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Adrian_III", "summary": "rewritten", "background": "rewritten"}'::jsonb),
