UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Stephen V governed as bishop of Rome and head of the Papal States. His term began in September 885 and ended with his death on 14 September 891. Toward Photius I of Constantinople and toward the young Slavic Orthodox church, he continued the policy of Pope Nicholas I.'::text) || jsonb_build_object('summary', 'Pope Stephen V held office as Roman Pontiff during 885–891.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Stephen_V", "background": "rewritten", "summary": "rewritten"}'::jsonb),
