UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Formosus held the office of Roman Pontiff from 891 to 896.'::text) || jsonb_build_object('background', 'Formosus ruled as pope, and as ruler of the Papal States, between 6 October 891 and 4 April 896, the day he died. His time as pope was troubled, since he became involved in power struggles over the Holy Roman Empire, over West Francia''s kingdom, and over the Patriarchate of Constantinople. He had taken the side of Arnulf of Carinthia and opposed Lambert of Spoleto, and for this his remains were dug up and tried at the Cadaver Synod. A number of his immediate successors were chiefly occupied with the disputed legacy of his pontificate, pointing out that he had left his diocese in Portus, seeking personal ambition at Rome. He was regarded as having failed the ideals of the Church, and on that ground Stephen VI judged him for taking a higher office while still holding another. Because of these controversies, no pope before or after him has taken the papal name Formosus.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Formosus", "summary": "rewritten", "background": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmq9l6adm012dg92d92xggz6f'
  AND content."slug" = 'pope-formosus'
  AND md5(content."payload"->>'summary') = '6540b84db27752ee6a5dbe82e25a97bc' AND md5(content."payload"->>'background') = '915b518378c87252ef6def81c74782e8';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Benedict IX held office as Roman Pontiff during 1045–1045.'::text) || jsonb_build_object('background', 'Pope Benedict IX, born Theophylact of Tusculum in Rome, governed as bishop of Rome and head of the Papal States in three separate stretches, all between October 1032 and July 1048. He was about 20 years old at his first election and could have been the youngest pope the Catholic Church has had. No one else has been pope on more than one occasion, and no one else has ever been accused of selling the papacy.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Benedict_IX", "summary": "rewritten", "background": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
