UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Born Giovanni Graziano in Rome, Pope Gregory VI was bishop of Rome and ruled the Papal States. His reign began on 1 May 1045 and ended with his resignation, which took place on 20 December 1046 at the Council of Sutri.'::text) || jsonb_build_object('summary', 'Pope Gregory VI was Roman Pontiff in the period 1045–1047.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Gregory_VI", "background": "rewritten", "summary": "rewritten"}'::jsonb),
