UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Leo IX ruled as Bishop of Rome and over the Papal States, starting on 12 February 1049 and lasting until he died in 1054. Among the popes of the Middle Ages he is counted as one of the most significant historically, since he helped bring about the Great Schism of 1054, regarded as the turning point when the Catholic and Eastern Orthodox Churches were formally divided.'::text) || jsonb_build_object('summary', 'The Roman Pontiff Pope Leo IX held office from 1049–1054.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Leo_IX", "background": "rewritten", "summary": "rewritten"}'::jsonb),
