UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Stephen IX held the office of Roman Pontiff from 1057 to 1058.'::text) || jsonb_build_object('background', 'Pope Stephen IX was Bishop of Rome, ruling the Papal States, beginning 3 August 1057; he died on 29 March 1058. He belonged to the Ardenne-Verdun family, rulers of the Duchy of Lorraine, and began his Church career as a canon in Liège. Pope Leo IX called him to Rome, appointed him chancellor in 1051 and made him one of three legates sent to Constantinople in 1054. The talks they held with Archbishop Leo of Ohrid and with Patriarch Michael I Cerularius of Constantinople failed, bringing about the permanent East–West Schism. He stayed on as chancellor under the following pope, Victor II, and was chosen abbot at Montecassino, a Benedictine monastery.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Stephen_IX", "summary": "rewritten", "background": "rewritten"}'::jsonb),
