UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Benedict X held office as Roman Pontiff during 1058–1059.'::text) || jsonb_build_object('background', 'Benedict X, whose birth name was Giovanni, was elected on 5 April 1058 as successor to Pope Stephen IX, yet a rival faction opposed him and elected Nicholas II. He left Rome in flight on 24 January 1059, and he is now generally considered an antipope.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Antipope_Benedict_X", "summary": "rewritten", "background": "rewritten"}'::jsonb),
