UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Nicholas II, also known as Gerard of Burgundy, led the Catholic Church and governed the Papal States, taking office on 24 January 1059 and dying on 27 July 1061. He was bishop of Florence when elected. In his pontificate he expanded papal influence in Milan and southern Italy with success. He also carried through reforms of papal elections, the chief one confining the discussion of candidates to the Cardinal Bishops; this began the process of shutting the City''s nobility, religious and lesser clergy out of the election.'::text) || jsonb_build_object('summary', 'Pope Nicholas II held the office of Roman Pontiff from 1059 to 1061.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Nicholas_II", "background": "rewritten", "summary": "rewritten"}'::jsonb),
