UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Alexander II, whose birth name was Anselm of Baggio, led the Roman Catholic Church and governed the Papal States from 1061 until he died in 1073. A native of Milan, Anselm took a deep part in the Pataria reform movement. His election followed the terms of the bull In nomine Domini issued by his predecessor, and it was the first held by the cardinals alone, without the people and lesser clergy of Rome taking part. In 1066 he gave his authorization to the Norman conquest of England.'::text) || jsonb_build_object('summary', 'Pope Alexander II held office as Roman Pontiff during 1061–1073.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Alexander_II", "background": "rewritten", "summary": "rewritten"}'::jsonb),
