UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Born Dauferio Epifani Del Zotto, Pope Victor III headed the Catholic Church and ruled the Papal States. His reign began on 24 May 1086 and ended with his death. He succeeded Pope Gregory VII. Before his election he was abbot of the leading monastery at Montecassino, an important post that he held with the monastic name Desiderius, and in those years he had a historically significant role.'::text) || jsonb_build_object('summary', 'Pope Victor III was Roman Pontiff in the period 1086–1087.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Victor_III", "background": "rewritten", "summary": "rewritten"}'::jsonb),
