UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Urban II, also known by the names Odo of Châtillon and Otho de Lagery, led the Catholic Church and governed the Papal States. He took office on 12 March 1088 and held it until his death. His best-known act was calling the Council of Clermont, which set off the Crusades, the series of Catholic military expeditions.'::text) || jsonb_build_object('summary', 'The Roman Pontiff Pope Urban II held office from 1088–1099.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Urban_II", "background": "rewritten", "summary": "rewritten"}'::jsonb),
