UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Gelasius II was Roman Pontiff in the period 1118–1119.'::text) || jsonb_build_object('background', 'Pope Gelasius II, whose birth name was Giovanni Caetani (or Giovanni da Gaeta), headed the Catholic Church and ruled the Papal States. His reign began on 24 January 1118 and ended with his death in 1119. Caetani, who was a monk of Monte Cassino and had been chancellor to Pope Paschal II, was elected unanimously as his successor, and thereby took on the investiture conflict with Emperor Henry V as well. Much of Gelasius''s short papacy passed in exile.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Gelasius_II", "summary": "rewritten", "background": "rewritten"}'::jsonb),
