UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'The Roman Pontiff Pope Celestine V held office from 1294–1294.'::text) || jsonb_build_object('background', 'Pope Celestine V, born Pietro Angelerio and also named Pietro da Morrone, Peter of Morrone or Peter Celestine, led the Catholic Church and governed the Papal States for just five months. He took office on 5 July and abdicated on 13 December 1294. As a monk and hermit, he had established the Celestines, an order that was a branch of the Benedictine order.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Celestine_V", "summary": "rewritten", "background": "rewritten"}'::jsonb),
