UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope John XXII, whose birth name was Jacques Duèze, led the Catholic Church. His term began on 7 August 1316 and ended with his death in December 1334. The conclave of cardinals that elected him met in Lyon. He was the second Avignon pope and the one with the longest reign. Following the example of his predecessor, Clement V, he drew power and revenue toward the Papacy and lived in princely style at Avignon.'::text) || jsonb_build_object('summary', 'Pope John XXII held office as Roman Pontiff during 1316–1334.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_John_XXII", "background": "rewritten", "summary": "rewritten"}'::jsonb),
