UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Benedict XII held office as Roman Pontiff during 1335–1342.'::text) || jsonb_build_object('background', 'Pope Benedict XII, born Jacques Fournier, had served as an inquisitor and cardinal prior to becoming head of the Catholic Church. His papacy ran from 30 December 1334 until he died in April 1342. The third Avignon pope, he reformed the monastic orders and opposed nepotism. Since he could not move his capital to Rome or Bologna, he began building the great palace at Avignon. With the bull Benedictus Deus he resolved the controversy over the beatific vision raised under Pope John XXII, teaching that souls can reach the "fullness of the beatific vision" ahead of the Last Judgment. He tried many times to settle differences with Emperor Louis IV by diplomacy, but could not return the Holy Roman Empire to papal dominance. Benedict died on 25 April 1342 and his burial took place in Avignon.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Benedict_XII", "summary": "rewritten", "background": "rewritten"}'::jsonb),
