UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Clement VI held office as Roman Pontiff during 1342–1352.'::text) || jsonb_build_object('background', 'Pope Clement VI, born Pierre Roger, led the Catholic Church. His term began on 7 May 1342 and ended with his death in December 1352. The fourth Avignon pope, he reigned when the Black Death first struck (1348–1350), and he granted remission of sins to everyone who died of the plague.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Clement_VI", "summary": "rewritten", "background": "rewritten"}'::jsonb),
