UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Innocent VI, born Étienne Aubert, led the Catholic Church and governed the Papal States. His term began on 18 December 1352 and ended with his death in September 1362. The fifth Avignon pope, he was also the only one of them to take the papal name "Innocent".'::text) || jsonb_build_object('summary', 'Pope Innocent VI held office as Roman Pontiff during 1353–1362.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Innocent_VI", "background": "rewritten", "summary": "rewritten"}'::jsonb),
