UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Urban V led the Catholic Church, beginning 28 September 1362 and ending at his death on 19 December 1370. A Benedictine, belonging to the Order of Saint Benedict, he is the only pope of the Avignon period to be beatified.'::text) || jsonb_build_object('summary', 'Pope Urban V held the office of Roman Pontiff from 1362 to 1370.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Urban_V", "background": "rewritten", "summary": "rewritten"}'::jsonb),
