UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Urban VI, whose birth name was Bartolomeo Prignano, led the Catholic Church beginning on 8 April 1378 and until he died in October 1389. No later pope has been chosen from outside the College of Cardinals; he was the last one elected from outside it. His pontificate opened soon after the Avignon Papacy ended, and it was dominated by fierce strife between rival camps in the Western Schism. Much of Europe, including France, the Iberian Kingdoms of Castile and Aragon, and Scotland, accepted Clement VII, who was in Avignon, as the true pope.'::text) || jsonb_build_object('summary', 'Pope Urban VI reigned as Roman Pontiff from 1378 to 1389.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Urban_VI", "background": "rewritten", "summary": "rewritten"}'::jsonb),
