UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Boniface IX reigned as Roman Pontiff from 1389 to 1404.'::text) || jsonb_build_object('background', 'Pope Boniface IX led the Catholic Church between 2 November 1389 and his death in October 1404. During the Western Schism he was the second Roman pope. Meanwhile the Avignon claimants, Clement VII and Benedict XIII, kept the Roman Curia at Avignon under French royal protection. No later pope has taken the pontifical name "Boniface".'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Boniface_IX", "summary": "rewritten", "background": "rewritten"}'::jsonb),
