UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Innocent VII reigned as Roman Pontiff from 1404 to 1406.'::text) || jsonb_build_object('background', 'Pope Innocent VII, born Cosimo de'' Migliorati, led the Catholic Church between 17 October 1404 and his death in November 1406. He served during the Western Schism (1378–1417), when the Avignon claimant Benedict XIII opposed him. His intentions were good, yet he achieved little toward ending the schism, because Rome was in turmoil and he did not trust that Benedict XIII and King Ladislaus of Naples were sincere.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Innocent_VII", "summary": "rewritten", "background": "rewritten"}'::jsonb),
