UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Paul II, born Pietro Barbo, headed the Catholic Church and ruled the Papal States between 30 August 1464 and his death in 1471. Barbo had been preparing for a career as a merchant, but he turned to religious studies once Eugene IV, his mother''s brother, became pope. He advanced fairly quickly in the Church. After his election as pope in 1464, Paul built up a large collection of art and antiquities.'::text) || jsonb_build_object('summary', 'Pope Paul II reigned as Roman Pontiff from 1464 to 1471.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Paul_II", "background": "rewritten", "summary": "rewritten"}'::jsonb),
