UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'From 4 August 1903 until he died in August 1914, Pope Pius X led the Catholic Church. He opposed modernist readings of Catholic doctrine and encouraged liturgical reform and Thomist scholastic theology. He began preparing the Code of Canon Law of 1917, the first full and systematic work of its type, which his successor ended up promulgating. The Catholic Church venerates him as a saint.'::text) || jsonb_build_object('summary', 'The Roman Pontiff Pope Pius X held office from 1903–1914.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Pius_X", "background": "rewritten", "summary": "rewritten"}'::jsonb),
