UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Paul VI led the Catholic Church and was Vatican City''s sovereign. He held these roles from 21 June 1963 until he died on 6 August 1978. He took over from John XXIII, carried on the Second Vatican Council and closed it in 1965, putting its many reforms into effect. His efforts to improve ecumenical relations with the Eastern Orthodox and Protestant churches produced many historic meetings and agreements.'::text) || jsonb_build_object('summary', 'The Roman Pontiff Pope Paul VI held office from 1963–1978.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Paul_VI", "background": "rewritten", "summary": "rewritten"}'::jsonb),
