UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'The Roman Pontiff Pope John Paul II held office from 1978–2005.'::text) || jsonb_build_object('background', 'Pope John Paul II led the Catholic Church and was Vatican City''s sovereign. He held these roles from 16 October 1978 until he died in 2005. Before him, the last non-Italian pope was Adrian VI, back in the 16th century, and only St. Peter and Pius IX served longer, which put him third for length of service among all popes.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_John_Paul_II", "summary": "rewritten", "background": "rewritten"}'::jsonb),
