UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'The Roman Pontiff Pope Francis held office from 2013–2025.'::text) || jsonb_build_object('background', 'Pope Francis led the Catholic Church and was Vatican City''s sovereign. He held these roles starting 13 March 2013; his death in 2025 ended his tenure. Francis was the first Jesuit to be pope, and the first from Latin America. He was also the first pope with a birth or upbringing outside Europe since Gregory III, the Syrian pope of the 8th century.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Francis", "summary": "rewritten", "background": "rewritten"}'::jsonb),
