UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Urban I was Roman Pontiff in the period 222–230.'::text) || jsonb_build_object('background', 'Pope Urban I, also called Saint Urban (175?–230), served as bishop of Rome from 222 until 23 May 230. A Roman by birth, he followed Callixtus I, who had been martyred. For centuries people believed Urban I had also been martyred, but recent historical discoveries lead scholars to think he died naturally.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Urban_I", "summary": "rewritten", "background": "rewritten"}'::jsonb),
