UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'The Roman Pontiff Pope Pontian held office from 230–235.'::text) || jsonb_build_object('background', 'Pope Pontian served as bishop of Rome. His term began on 21 July 230 and ended on 28 September 235. When Christians were being persecuted under the Emperor Maximinus Thrax in 235, he was arrested and sent off to the island of Sardinia.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Pontian", "summary": "rewritten", "background": "rewritten"}'::jsonb),
