UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Fabian succeeded Anterus as bishop of Rome and leader of the Catholic Church. His term began on 10 January 236 and ended with his death on 20 January 250. It is said that a dove landed on his head, marking him as the Holy Spirit''s surprising choice as the next pope. Cornelius followed him.'::text) || jsonb_build_object('summary', 'The Roman Pontiff Pope Fabian held office from 236–250.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Fabian", "background": "rewritten", "summary": "rewritten"}'::jsonb),
