UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Between 25 June 253 and his death on 5 March 254, Lucius I served as pope, the bishop of Rome. Shortly after his consecration he was sent into exile, but he obtained leave to come back. He has been wrongly counted as a martyr of the persecution under Emperor Valerian, which only began after Lucius'' death.'::text) || jsonb_build_object('summary', 'Pope Lucius I reigned as Roman Pontiff from 253 to 254.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Lucius_I", "background": "rewritten", "summary": "rewritten"}'::jsonb),
