UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Sixtus II, whose name is also written Xystus II, served as bishop of Rome. His term began on 31 August 257 and ended with his death on 6 August 258. During the Emperor Valerian''s persecution of Christians, he was put to death with seven deacons, one of them Lawrence of Rome.'::text) || jsonb_build_object('summary', 'The Roman Pontiff Pope Sixtus II held office from 257–258.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Sixtus_II", "background": "rewritten", "summary": "rewritten"}'::jsonb),
