UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'The Roman Pontiff Pope Dionysius held office from 259–268.'::text) || jsonb_build_object('background', 'Pope Dionysius served as Bishop of Rome. His term began on 22 July 259 and ended on 26 December 268. His pontificate saw the change from the persecutions of Valerian to the toleration that Gallienus granted in 260. In those years he restructured the Roman church by giving presbyters charge of separate parishes.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Dionysius", "summary": "rewritten", "background": "rewritten"}'::jsonb),
