UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Caius held the office of Roman Pontiff from 283 to 296.'::text) || jsonb_build_object('background', 'Pope Caius, also called Gaius, was Rome''s bishop from 17 December 283 until his death in 296. Almost all that is known about him comes from the Liber Pontificalis, which takes its details from a legend about Susanna of Rome''s martyrdom. Legend holds that Caius baptized the men and women converted by Tiburtius and Castulus, that he sheltered in the catacombs of Rome, and that he died a martyr.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Caius", "summary": "rewritten", "background": "rewritten"}'::jsonb),
