UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Marcellinus served as bishop of Rome. His term began on 30 June 296 and ended with his death in 304. Some sources accused him of possibly having renounced Christianity when Emperor Diocletian''s persecution of Christians was under way, and of repenting later; this would account for his absence from martyr lists. Augustine of Hippo, among others, dismissed the charge. Today the Catholic Church and the Serbian Orthodox Church venerate him as a saint.'::text) || jsonb_build_object('summary', 'The Roman Pontiff Pope Marcellinus held office from 296–304.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Marcellinus", "background": "rewritten", "summary": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmq9l6pd302a8g92dwvw0w832'
  AND content."slug" = 'pope-marcellinus'
  AND md5(content."payload"->>'background') = '40994bded3af72b19a6e2bfe22751de7' AND md5(content."payload"->>'summary') = 'a2e0ae9f263c60d21833892c941aea1e';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Marcellus I reigned as Roman Pontiff from 308 to 309.'::text) || jsonb_build_object('background', 'Between May or June 308 and his death on 16 January 309, Marcellus I served as pope, the bishop of Rome. He followed Marcellinus after a long vacancy. Under Maxentius he was exiled from Rome in 309 because of the uproar over the harsh penances he imposed on Christians who had lapsed in the recent persecution. He died that same year, and Eusebius followed him. His relics lie beneath the altar of the church of San Marcello al Corso, in the city of Rome. The Catholic Church traditionally kept his feast day on 16 January, but since 1969 it has been left to local calendars and does not appear in the General Roman Calendar.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Marcellus_I", "summary": "rewritten", "background": "rewritten"}'::jsonb),
