SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Eusebius held office as Roman Pontiff during 309–309.'::text) || jsonb_build_object('background', 'Between 18 April 309 and his exile on 17 August 310, Eusebius served as pope, the bishop of Rome.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Eusebius", "summary": "rewritten", "background": "rewritten"}'::jsonb),
