UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Mechtildis of Edelstetten, known too as Mechtildis of Andechs and Mechtildis of Diessen, was a Benedictine abbess, and legend counts her a famous miracle worker. Her father was Count Berthold of Andechs; his wife Sophie founded a monastery on the family estate in Diessen, Bavaria, and Mechtildis was placed there at age five. The Bishop of Augsburg made her Abbess of Edelstetten Abbey in 1153. She had a reputation for mystical gifts and miracles. At Diessen, Germany, she died on 31 May 1160, and her adorned remains are kept in a glass shrine in that town''s Marienmünster church.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Mechtildis_of_Edelstetten", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmq9l75yn02k6g92d33jdzei9'
