UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Ceferino Giménez Malla was a catechist and activist from Spain, a Romani Catholic. He was killed by Republican militias in the Spanish Civil War and was beatified on 4 May 1997, the date that is now his feast day. Romani people count him as their patron.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Ceferino_Gim%C3%A9nez_Malla", "biography": "rewritten"}'::jsonb),
