SET "payload" = content."payload" || jsonb_build_object('biography', 'Pope Innocent XI, whose birth name was Benedetto Odescalchi, led the Catholic Church and ruled the Papal States, beginning 21 September 1676 and ending with his death on 12 August 1689.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Innocent_XI", "biography": "rewritten"}'::jsonb),
