  AND content."slug" = 'saint-marcellus-i'
  AND md5(content."payload"->>'biography') = '4ecac6dbc4ea94e48870dd1ee9d432e0';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Boethius, in full Anicius Manlius Severinus Boethius, lived in the Early Middle Ages and was a philosopher and historian, a polymath, a Roman senator and consul, and magister officiorum. He played a pivotal part in rendering Greek classics into Latin, foreshadowed the Scholastic movement and, together with Cassiodorus, was one of the two foremost Christian scholars in the 6th century. In 1883 the Sacred Congregation of Rites sanctioned the Pavia diocese''s local cult of Boethius, which confirmed that the diocese customarily honors him on 23 October.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Boethius", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmq9l790902klg92dvvs5qp61'
  AND content."slug" = 'saint-boethius'
  AND md5(content."payload"->>'biography') = 'a26aa9ac8276fb0e06f4c941ed301a78';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pope Julius I served as Rome''s bishop from 6 February 337 until he died on 12 April 352. Athanasius, deposed by Arian bishops from his position as patriarch, appealed to Julius, who then supported him and condemned his deposition as unjust. Julius was notable for asserting papal authority over the Arian Eastern bishops, and he is also credited with setting Jesus'' official birthdate at December 25.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Julius_I", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
