WHERE content."id" = 'cmq9l792902kog92dwmibo0a8'
  AND content."slug" = 'saint-julius-i'
  AND md5(content."payload"->>'biography') = '9c0575a872c7f442621cb5d5fca56766';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pope Gregory III was Rome''s bishop from 11 February 731 until he died on 28 November 741. Like that of his predecessor, his pontificate was troubled by Byzantine iconoclasm and by the Lombard advance; he called on Charles Martel to intervene, though the effort failed. Gregory was the last pope of Syrian origin, the last to ask the Byzantine exarch of Ravenna for consent to his election, and, until Pope Francis was elected 1,272 years later in 2013, the last pope born outside Europe.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Gregory_III", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmq9l794a02krg92dkxhsn3gv'
  AND content."slug" = 'saint-gregory-iii'
  AND md5(content."payload"->>'biography') = '416028e6c8f4730b1f518ab622110c9a';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pope Gregory II was Rome''s bishop from 19 May 715 until he died on 11 February 731. Because the Eastern Empire was embroiled in the iconoclastic controversy, he defied Emperor Leo III the Isaurian, and this opposition opened the way to a long run of revolts, schisms and civil wars, out of which the temporal power of the popes eventually arose.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Gregory_II", "biography": "rewritten"}'::jsonb),
