UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pope Paul I was Rome''s bishop and ruled the developing Papal States from 29 May 757 until he died on 28 June 767. Before that he was a Roman deacon, and his brother, Pope Stephen II, often sent him to negotiate with the Lombard kings.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Paul_I", "biography": "rewritten"}'::jsonb),
