UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Sabinian held the office of bishop of Rome, as pope, from 13 September 604 until he died on 22 February 606. His pontificate fell in the period when the Eastern Roman Empire dominated the papacy. Of the former apocrisiarii to Constantinople, he was the fourth to be elected pope.'::text) || jsonb_build_object('summary', 'Pope Sabinian held the office of Roman Pontiff from 604 to 606.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Sabinian", "background": "rewritten", "summary": "rewritten"}'::jsonb),
