UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Boniface III held office as Roman Pontiff during 607–607.'::text) || jsonb_build_object('background', 'Between 19 February 607 and his death on 12 November of that same year, Boniface III served as pope, the bishop of Rome. His pontificate was short, yet his contribution to the Catholic Church was significant.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Boniface_III", "summary": "rewritten", "background": "rewritten"}'::jsonb),
