UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Boniface IV held the office of Roman Pontiff from 608 to 615.'::text) || jsonb_build_object('background', 'A Benedictine, Boniface IV governed as bishop of Rome from 608 until he died on 8 May 615. Earlier he had served Pope Gregory I as a deacon, and, as Gregory had done, he made the Lateran Palace a monastery. Monasticism received his encouragement as pope. With the emperor''s permission he turned the Pantheon into a church. He consulted, in 610, Bishop Mellitus of London on what the English Church needed. The Catholic Church venerates him as a saint, and his universal feast day is 8 May.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Boniface_IV", "summary": "rewritten", "background": "rewritten"}'::jsonb),
