UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Adeodatus I, who is also known as Deodatus I or Deusdedit, was Rome''s bishop, taking office on 19 October 615 and serving until he died on 8 November 618. Not since John II in 533 had a priest been elected pope. Papal documents are said to have first carried lead seals, or bullae, under him. 8 November is his feast day.'::text) || jsonb_build_object('summary', 'Pope Adeodatus I reigned as Roman Pontiff from 615 to 618.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Adeodatus_I", "background": "rewritten", "summary": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmq9l7cmw02vgg92dbl6bmoxu'
  AND content."slug" = 'pope-adeodatus-i'
  AND md5(content."payload"->>'background') = '1b6bce44782e4c5c7a31d3160b3a7c3c' AND md5(content."payload"->>'summary') = '55934bb728b3e439ffb90fcdcfddd18e';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Between 23 December 619 and his death on 25 October 625, Boniface V served as pope, the bishop of Rome. He contributed greatly to bringing Christianity to Anglo-Saxon England and put into effect the decree making churches places of sanctuary.'::text) || jsonb_build_object('summary', 'Pope Boniface V reigned as Roman Pontiff from 619 to 625.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Boniface_V", "background": "rewritten", "summary": "rewritten"}'::jsonb),
