  AND md5(content."payload"->>'summary') = 'abd50a5ea55a291c4d81f2ceed1059ec' AND md5(content."payload"->>'background') = '122da64346e13ae677c5040d947393d9';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Between 24 November 642 and his death on 14 May 649, Theodore I served as pope, the bishop of Rome. The struggle against Monothelitism was the main concern of his pontificate.'::text) || jsonb_build_object('summary', 'Pope Theodore I reigned as Roman Pontiff from 642 to 649.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Theodore_I", "background": "rewritten", "summary": "rewritten"}'::jsonb),
