UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Martin I, also called Martin the Confessor, held the see of Rome as bishop from 21 July 649 until 653 or 654. He had earlier represented Pope Theodore I as ambassador in Constantinople, and he was chosen to succeed Theodore. Of the popes in the period of Constantinople''s control over the papacy, he was the only one elected without waiting for imperial approval. Because he strongly opposed Monothelitism, Emperor Constans II had Pope Martin I arrested and taken to Constantinople, and he was finally exiled to Cherson. The Catholic Church and the Eastern Orthodox Church each regard him as a saint, and he is also the final pope recognised as a martyr.'::text) || jsonb_build_object('summary', 'Pope Martin I held office as Roman Pontiff between 649 and 655.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Martin_I", "background": "rewritten", "summary": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmq9l7cy502vyg92dfmoamnd8'
