UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Between 10 August 654 and his death on 2 June 657, Eugene I served as pope, the bishop of Rome. Emperor Constans II had deposed and banished Martin I in the dispute over Monothelitism, and Eugene was then chosen as pope.'::text) || jsonb_build_object('summary', 'Pope Eugene I reigned as Roman Pontiff from 656 to 657.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Eugene_I", "background": "rewritten", "summary": "rewritten"}'::jsonb),
