UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Between 30 July 657 and his death in 672, Vitalian served as pope, the bishop of Rome. During his pontificate, a quarrel dominated events: the papacy and the imperial government at Constantinople disagreed over Monothelitism, which Rome condemned. Vitalian sought to settle it and kept up cordial relations with Emperor Constans II, who came to see him in Rome and brought him gifts. The Archbishopric of Ravenna also broke away from papal authority in his pontificate.'::text) || jsonb_build_object('summary', 'Pope Vitalian reigned as Roman Pontiff from 657 to 672.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Vitalian", "background": "rewritten", "summary": "rewritten"}'::jsonb),
