UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Adeodatus II reigned as Roman Pontiff from 672 to 676.'::text) || jsonb_build_object('background', 'Pope Adeodatus II, who is sometimes called Deodatus, served as bishop of Rome from 672 until he died on 17 June 676. Much of his papacy went to improving churches and combating monothelitism.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Adeodatus_II", "summary": "rewritten", "background": "rewritten"}'::jsonb),
