UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Donus served as bishop of Rome from 676 until he died on 11 April 678. Apart from what the Liber Pontificalis records, little detail survives about him or what he accomplished.'::text) || jsonb_build_object('summary', 'Pope Donus reigned as Roman Pontiff from 676 to 678.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Donus", "background": "rewritten", "summary": "rewritten"}'::jsonb),
