UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Agatho was bishop of Rome beginning on 27 June 678, and his life ended on 10 January 681. Wilfrid of York, displaced from his see because Theodore of Canterbury had ordered the archdiocese divided, appealed to him, and Agatho heard the case. The Sixth Ecumenical Council, summoned to deal with monothelitism, took place while he was pope. The Catholic and Eastern Orthodox churches each venerate him as a saint. Of all the popes, he is said to have lived the longest.'::text) || jsonb_build_object('summary', 'Pope Agatho held office as Roman Pontiff in the years 678–681.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Agatho", "background": "rewritten", "summary": "rewritten"}'::jsonb),
