UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Peter Yu Tae-chol was among the 103 canonised Korean Martyrs and was martyred in the Gihae persecution of 1839. His father, Augustine Nyou Tjin-kil, a government interpreter, was a martyr as well. Peter''s feast day is October 21, and on September 20 he is honored together with all 103 Korean martyrs.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Peter_Yu_Tae-chol", "biography": "rewritten"}'::jsonb),
