UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Severus was bishop of Naples in the 4th and 5th centuries. He counts as the eleventh legitimate bishop of Naples in the Catholic line, and the twelfth overall, and he followed Maximus. His time as bishop lasted from February 363 until 29 April 409, the date traditionally given for his death. Between Maximus and Severus the see was held by Zosimus, an Arian, whom the Catholic Church condemned as heretical.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Severus_of_Naples", "biography": "rewritten"}'::jsonb),
