UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Fabrician and Philibert, two Christian saints, died as martyrs for their faith in Christ at Toledo, Spain, at some point in the third century. Both the Eastern Orthodox Church and the Roman Catholic church venerate them as saints and commemorate them on 22 August. Not much is known about them.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Fabrician_and_Philibert", "biography": "rewritten"}'::jsonb),
