UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Domninus of Fidenza is a saint of the Catholic Church in Italy. Tradition holds that he was a native of Parma who died in 304 AD. Fidenza''s cathedral honours him with its dedication. The Hieronymian Martyrology mentions Domninus without giving further details about him, and gives his feast day as 9 October. The martyrologies of Bede, Ado, Notker and the Parvum Romanum do not mention him.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Domninus_of_Fidenza", "biography": "rewritten"}'::jsonb),
