UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Akash Bashir was a Pakistani layman who had studied at the Don Bosco Technical Institute in Lahore, Pakistan. In December 2014 he became part of the security team guarding Lahore''s Church of Saint John, located in Youhanabad, a mainly Christian neighborhood. On Sunday, 15 March 2015, he stopped a suicide bomber who was trying to get into the church. The attacker set off his explosives outside the building, and both men died. Pope Francis named him a Servant of God in January 2022, when his cause for beatification was opened.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Akash_Bashir", "biography": "rewritten"}'::jsonb),
