UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Boniface VI, who came from Rome, was bishop of Rome and governed the Papal States for only a very short time, in April of 896. Formosus died on April 4, and the riots that followed brought about his election. Before becoming pope he had been sentenced twice to deprivation of orders, once as a subdeacon and once as a priest. His pontificate lasted fifteen days; some say he died of gout, while others say he was violently removed to clear the way for the Spoletan party''s candidate, Stephen VI.'::text) || jsonb_build_object('summary', 'Pope Boniface VI held the office of Roman Pontiff in 896–896.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Boniface_VI", "background": "rewritten", "summary": "rewritten"}'::jsonb),
