UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Stephen VI held office as Roman Pontiff in the years 896–897.'::text) || jsonb_build_object('background', 'From 22 May 896 to his death in August 897, Pope Stephen VI served as bishop of Rome and governed the Papal States. He is chiefly remembered for bringing about the Cadaver Synod, which in the end caused his fall and death.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Stephen_VI", "summary": "rewritten", "background": "rewritten"}'::jsonb),
