UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Between August and November 897, Pope Romanus served as bishop of Rome and governed the Papal States. The brief reign fell in a time of factional conflict within the Catholic Church, set against violence and disorder in central Italy. It came to an end when he was removed from office and shut away in a monastery.'::text) || jsonb_build_object('summary', 'Pope Romanus held office as Roman Pontiff from 897 to 897.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Romanus", "background": "rewritten", "summary": "rewritten"}'::jsonb),
