UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Theodore II held the office of Roman Pontiff in 897–897.'::text) || jsonb_build_object('background', 'Pope Theodore II was bishop of Rome, and for twenty days in December 897 he governed the Papal States. He reigned in an era of factional conflict within the Catholic Church, tied up with violence and disorder across central Italy. Chiefly, he annulled the Cadaver Synod, which had been held not long before, restoring Pope Formosus''s acts and ordinations that Pope Stephen VI had himself annulled. By his order the corpse of Formosus was also retrieved out of the Tiber river and given an honourable reburial. Theodore died while still pope in late December 897.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Theodore_II", "summary": "rewritten", "background": "rewritten"}'::jsonb),
