UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Benedict IV held office as Roman Pontiff in the years 900–903.'::text) || jsonb_build_object('background', 'Beginning on 1 February 900 and lasting until he died, Pope Benedict IV served as bishop of Rome and governed the Papal States. Flodoard, a historian of the tenth century, praised his noble birth and his generosity toward the public, and gave him the nickname "the Great".'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Benedict_IV", "summary": "rewritten", "background": "rewritten"}'::jsonb),
