UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'In 903 Pope Leo V served as bishop of Rome and as nominal governor of the Papal States. His papacy came just before the Saeculum obscurum, an era in which popes held little temporal power. It took place in the latter half of 903, and the precise months are hard to determine.'::text) || jsonb_build_object('summary', 'Pope Leo V held office as Roman Pontiff in the years 903–904.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Leo_V", "background": "rewritten", "summary": "rewritten"}'::jsonb),
