UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Sergius III held office as Roman Pontiff in the years 904–911.'::text) || jsonb_build_object('background', 'Beginning 29 January 904 and continuing until he died, Pope Sergius III was bishop of Rome and also the nominal ruler of the Papal States. Central Italy in his day was torn by violence and disorder, with feuding aristocratic factions trying to turn the papacy''s material and military resources to their own ends. Theophylact I of Tusculum urged Sergius to take the papal throne by force from Antipope Christopher, who had himself deposed Pope Leo V.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Sergius_III", "summary": "rewritten", "background": "rewritten"}'::jsonb),
