UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Anastasius III held office as Roman Pontiff during 911–913.'::text) || jsonb_build_object('background', 'Pope Anastasius III governed as bishop of Rome and head of the Papal States. His term began in April 911 and ended with his death.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Anastasius_III", "summary": "rewritten", "background": "rewritten"}'::jsonb),
