UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Lando reigned as Roman Pontiff from 913 to 914.'::text) || jsonb_build_object('background', 'Lando was pope from 913 until he died in 914. His brief pontificate took place in a murky stretch of papal and Roman history known as the Saeculum obscurum (904–964).'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Lando", "summary": "rewritten", "background": "rewritten"}'::jsonb),
