UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope John X held the office of Roman Pontiff from 914–928.'::text) || jsonb_build_object('background', 'Pope John X served as bishop of Rome, and as the Papal States'' nominal ruler, from March 914 until he died. Backed by the counts of Tusculum, he tried to bring Italy together under Berengar of Friuli, and he played a key part in the Battle of Garigliano, where the Saracens were beaten. In time he quarreled with Marozia, who had him deposed, jailed, and finally killed. His pontificate fell within the era called the Saeculum obscurum.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_John_X", "summary": "rewritten", "background": "rewritten"}'::jsonb),
