UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Beginning in February 929 and ending with his death in 931, Pope Stephen VII served as bishop of Rome and nominal governor of the Papal States. He was the candidate of the notorious Marozia, and his pontificate fell within the Saeculum obscurum.'::text) || jsonb_build_object('summary', 'Pope Stephen VII held office as Roman Pontiff in the years 929–931.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Stephen_VII", "background": "rewritten", "summary": "rewritten"}'::jsonb),
