UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Blath, also called Blathnait, is an Irish saint who was a lay-sister and the cook at Saint Brigid''s abbey in Kildare. Her name means ''flower'' in Irish. The Martyrology of Gorman jokingly calls her ''blooming Blath'', and that is the source of the Latinized name Flora by which she is also known. Apart from her work as cook and a part in one notable miracle linked to Saint Brigid, she is remembered mainly through her connection with Saint Brigid and through short mentions in martyrologies and hagiographical texts. January 29 is her feast day.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Blath_of_Kildare", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
