UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Wite was a holy Saxon woman of 9th-century Dorset who was killed by raiding Danes. The Orthodox Church venerates her, she is Dorset''s patron saint, and her feast day, 1 June, is also marked as Dorset Day. She is likewise called Saint Candida.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Wite", "biography": "rewritten"}'::jsonb),
