UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Bieuzy, a Breton hermit of the 6th century, was a companion of Saint Gildas. Both Bieuzy and Bieuzy-Lanvaux, villages in Morbihan, take their names from him. His name likely derives from the Old Breton words biu and bihui, meaning "living". He is commemorated on 24 November.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Bieuzy", "biography": "rewritten"}'::jsonb),
