UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Afra died a martyr in the Diocletian persecution. She shares the patronage of Augsburg with Saint Ulrich & St Simpert. Her feast day is August 7. Her mother, Hilaria, had given her over to serve the goddess Venus. Bishop Narcissus taught Afra and her family and brought them to Christianity. After her Christian faith came to light she was taken before Diocletian and told to offer sacrifice to the pagan gods. When she would not, she was sentenced to death by fire.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Afra", "biography": "rewritten"}'::jsonb),
