UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'On January 24, 1874, soldiers of the Imperial Russian Army killed the Martyrs of Pratulin, a company of 13 Greek Catholic men and boys from Poland, in the village of Pratulin, close to Biała Podlaska.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Martyrs_of_Pratulin", "biography": "rewritten"}'::jsonb),
