UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Cassien of Nantes, OFM Cap., worked in Africa in the 17th century as a French Capuchin missionary priest. His parents were of Portuguese ancestry, and he was born in Nantes on 14 January 1607. With a fellow Capuchin, Agathange of Vendome, he journeyed through Syria, Egypt and Ethiopia. The King of Gondar ordered the two killed by a blow to the head, on the accusation that they had preached to the Copts. Their martyrdom took place on 7 August 1638.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Cassien_de_Nantes", "biography": "rewritten"}'::jsonb),
