  AND md5(content."payload"->>'biography') = '5790483751fd2d7eb52facbbb87c5329';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'David Lewis, S.J., a Jesuit Catholic priest and martyr, also went by the name Charles Baker, and Welsh speakers commonly called him Tad y Tlodion. The Catholic Church in Wales suffered religious persecution that started under Henry VIII and lasted until Catholic Emancipation in 1829. In those years Lewis was superior of the clandestine, illegal Jesuit mission centred at Cwm, until the priest hunter John Arnold of Monmouthshire arrested him. Besides his priestly work, he was accused of taking part in the Popish Plot. This was a conspiracy theory about regime change, invented by Titus Oates, which the dominant Whig political party exploited as a pretext, during the Stuart Restoration, to stir up a moral panic and witch hunt directed against Catholics. Lewis was tried at Monmouth and convicted of high treason, and was executed at Usk on 27 August 1679 by being hanged, drawn and quartered.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/David_Lewis_(Jesuit_priest)", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmq9ldv1t0doeg92du1idb4r8'
  AND content."slug" = 'saint-david-lewis'
  AND md5(content."payload"->>'biography') = 'c836dc79f45cc781edc160d295e6f60f';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Of Bulgarian origin, Cyprian was a prelate. He served first as Metropolitan of Kiev, Rus'' and Lithuania, then as Metropolitan of Kiev and all Rus'', under the Ecumenical Patriarchate of Constantinople. In both periods rival hierarchs and the grand prince of Moscow opposed him. He was known as a brilliant writer of opinion, as well as an editor, translator and book copyist. September 16 (O.S.) and May 27 are his commemoration days in the Russian Orthodox Church.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Cyprian%2C_Metropolitan_of_Kiev", "biography": "rewritten"}'::jsonb),
