UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Quiteria, a saint and virgin martyr of the fifth century, is known with certainty only by name, along with when, where and why she died and the fact that she has a cult. The Roman Martyrology lists her on 22 May. She is among the patron saints of Toledo, Spain. Stories about her life tell of her refusal to marry, her protection of the vulnerable, and a guerilla war she fought against the Roman Empire.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Quiteria", "biography": "rewritten"}'::jsonb),
