UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Foundress of the monastery of the Franciscan Sisters of Saint Philippa Mareri, also called Poor Clares, Philippa Mareri was beatified in 1247. Her sanctuary stands at Borgo San Pietro, a frazione (borough) belonging to Petrella Salto. Her feast day falls on 16 February.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Philippa_Mareri", "biography": "rewritten"}'::jsonb),
