SET "payload" = content."payload" || jsonb_build_object('biography', 'Theophylact, a Byzantine, served as Archbishop of Ohrid and wrote commentaries on the Bible. The Eastern Orthodox Church counts him a saint and commemorates him on December 31st.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Theophylact_of_Ohrid", "biography": "rewritten"}'::jsonb),
