UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Poemen the Great was an early Desert Father and a Christian monk, and the Apophthegmata Patrum quotes him more than any other Abba (Father). What people quoted most was his gift as a spiritual guide, which is reflected in his name "Poemen" ("Shepherd"), more than his asceticism. Eastern Christianity regards him as a saint, and in the Julian calendar he is commemorated on August 27, his feast day.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Poemen", "biography": "rewritten"}'::jsonb),
