UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Innocent II held office as Roman Pontiff in the years 1130–1143.'::text) || jsonb_build_object('background', 'Pope Innocent II, whose birth name was Gregorio Papareschi, led the Catholic Church and governed the Papal States starting on 14 February 1130 and until he died in 1143. His election was disputed, and for his first eight years in office he had to fight for recognition against the followers of Anacletus II. King Lothair III of Germany backed him against Anacletus, and Innocent reached an agreement with him and crowned him Holy Roman emperor. Later Innocent presided at the Second Council of the Lateran.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Innocent_II", "summary": "rewritten", "background": "rewritten"}'::jsonb),
