UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Celestine II, whose birth name was Guido di Castello, led the Catholic Church and governed the Papal States between 26 September 1143 and his death on 8 March 1144.'::text) || jsonb_build_object('summary', 'Pope Celestine II held office as Roman Pontiff in the years 1143–1144.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Celestine_II", "background": "rewritten", "summary": "rewritten"}'::jsonb),
