UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Lucius II held office as Roman Pontiff in the years 1144–1145.'::text) || jsonb_build_object('background', 'Pope Lucius II, born Gherardo Caccianemici dal Orso, led the Catholic Church and ruled the Papal States starting on 9 March 1144 and until he died in 1145. Rome was in turmoil during his pontificate because of the Commune of Rome, which tried to take control of the city away from the papacy. In the Anarchy he took the side of Empress Matilda in her claim to the Kingdom of England, and his dealings with King Roger II of Sicily were strained.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Lucius_II", "summary": "rewritten", "background": "rewritten"}'::jsonb),
