UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Lucius III held office as Roman Pontiff in the years 1181–1185.'::text) || jsonb_build_object('background', 'Pope Lucius III, whose birth name was Ubaldo Allucingoli, led the Catholic Church and governed the Papal States between 1 September 1181 and his death in 1185. He came from an aristocratic family of Lucca and, before becoming pope, spent many years as a papal diplomat. His pontificate saw clashes with the Holy Roman Emperor Frederick I. Exile from Rome and the first preparations for the Third Crusade also marked it.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Lucius_III", "summary": "rewritten", "background": "rewritten"}'::jsonb),
