UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Urban III led the Catholic Church and governed the Papal States between 25 November 1185 and his death in 1187. Born in Milan, he became pope while Emperor Frederick Barbarossa and the Holy Roman Empire were locked in sharp conflict with the papacy. His short pontificate was taken up with quarrels over church jurisdiction in northern Italy and Germany, with opposition to imperial interference in the appointment of bishops, and with the continuing consequences of the 1177 Treaty of Venice.'::text) || jsonb_build_object('summary', 'Pope Urban III held office as Roman Pontiff in the years 1185–1187.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Urban_III", "background": "rewritten", "summary": "rewritten"}'::jsonb),
