UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Clement III held office as Roman Pontiff in the years 1188–1191.'::text) || jsonb_build_object('background', 'Pope Clement III, whose birth name was Paolo Scolari, led the Catholic Church and governed the Papal States between 19 December 1187 and his death in 1191. By permitting the election of magistrates he settled the dispute with the city of Rome, and so brought the papacy back to the city after six years in exile. With a depleted college of cardinals, Clement appointed thirty-one cardinals in three years, the largest number since Adrian IV. He died on 20 March 1191, and Celestine III soon succeeded him.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Clement_III", "summary": "rewritten", "background": "rewritten"}'::jsonb),
