UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Honorius III held the office of Roman Pontiff from 1216–1227.'::text) || jsonb_build_object('background', 'Born Cencio Savelli, Pope Honorius III headed the Catholic Church and governed the Papal States between 18 July 1216 and his death. He had been a canon of the Basilica di Santa Maria Maggiore and rose to several significant administrative posts, among them Camerlengo. Frederick II, then young, was placed under his tutelage in 1197. As pope he pushed forward the Fifth Crusade, planned by his predecessor, Innocent III, and again and again urged King Andrew II of Hungary and Emperor Frederick II to keep their vows to take part. He also approved the newly founded Dominican and Franciscan religious orders.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Honorius_III", "summary": "rewritten", "background": "rewritten"}'::jsonb),
