UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Innocent V held office as Roman Pontiff from 1276 to 1276.'::text) || jsonb_build_object('background', 'Pope Innocent V, whose birth name was Pierre de Tarentaise, led the Catholic Church and governed the Papal States between 21 January and 22 June 1276. He belonged to the Order of Preachers and gained a name as an able preacher. At Paris''s university he occupied a "Dominican Chair", one of two such posts, and played a key part in drafting the Order''s "program of studies". Peter of Tarentaise served as Provincial of the Dominicans'' French Province in 1269. Pope Gregory X, with whom he worked closely, appointed him Bishop of Ostia and made him a cardinal in 1273.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Innocent_V", "summary": "rewritten", "background": "rewritten"}'::jsonb),
