UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Lambertus (625-688) served as Bishop of Lyon (678-688) and as Abbot of Fontenelle Abbey. His feast day is on 14 April. His birthplace was Quernes, where Erlebert, his father, was seigneur; Robert I, Bishop of Tours, was his uncle.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Lambert_of_Lyon", "biography": "rewritten"}'::jsonb),
