UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'John of Constantinople, called John the Confessor as well, headed the Cathares Monastery in Constantinople as abbot. Byzantine Emperor Leo the Armenian pursued a policy of iconoclasm, and John came into conflict with him. He lived through torture because he defended the veneration of icons (iconodulism). Both the Eastern Orthodox Church and the Roman Catholic Church consider him a saint; the Orthodox celebrate him on 27 April, and the Catholics on 18 April.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/John_of_Constantinople", "biography": "rewritten"}'::jsonb),
