UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Valerian (377–457) was a bishop in North Africa, at Abbenza, probably Dioecesis Zabensis.(it) In 457 the Vandals, under the Arian king Geiseric, demanded the sacred vessels of his church. He refused to hand them over and was martyred. Geiseric outlawed him despite his advanced age of eighty. Valerian was driven from the city and left to perish from exposure. December 15 is the day of his feast.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Valerian_of_Abbenza", "biography": "rewritten"}'::jsonb),
