UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pope Sixtus II, also spelled Pope Xystus II, held the see of Rome as bishop from 31 August 257 until he died on 6 August 258. During the Emperor Valerian''s persecution of Christians he was put to death together with seven deacons, one of them Lawrence of Rome.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Sixtus_II", "biography": "rewritten"}'::jsonb),
