UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Samthann (Samhthann or Samthana in modernised form), an Irish folk saint, purportedly lived as a Christian nun and abbess of Early Christian Ireland. Only four female Irish saints have surviving Latin Lives, and she is one of them. She died on 19 December 739.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Samthann", "biography": "rewritten"}'::jsonb),
