UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pope Victor I, a prelate of the Catholic Church from Roman Africa, was Rome''s bishop in the late second century. Exact dates of his tenure are uncertain; one source has him become pope in 189 and die in 199. The Roman Province of Africa was his birthplace, and he was of Berber origin. Later regarded as a saint, he has a feast on 28 July, entitled "St Victor I, Pope and Martyr".'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Victor_I", "biography": "rewritten"}'::jsonb),
