UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Michael the Confessor, also called Michael of Synnada, held the post of metropolitan bishop there from 784/7 until 815. He served as Byzantium''s envoy to Harun al-Rashid and to Charlemagne. Because he opposed iconoclasm, Emperor Leo V the Armenian exiled him, and he died on 23 May 826. Both the Roman Catholic and Eastern Orthodox churches honour him as a saint, and his feast day is May 23.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Michael_of_Synnada", "biography": "rewritten"}'::jsonb),
