  AND md5(content."payload"->>'biography') = '2d38462020eed0ac87dee8e4d46b73a5';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Olga Vasilievna Evdokimova is a martyr and saint of the Russian Eastern Orthodox Church. When Soviet authorities moved to close the church of her village, Novorozhdestvenka, she defended it. The NKVD arrested and questioned her, then sent her to the Gulag, and four months after she got there she died. The Eastern Orthodox Church recognizes her as a martyr, and her memory is observed on January 28.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Olga_Vasilievna_Evdokimova", "biography": "rewritten"}'::jsonb),
