  AND md5(content."payload"->>'biography') = 'b808986dcb2ea5d14c3ae8c35eebaef1';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Theoclite, also called Theoclite the Wonderworker, was a Byzantine saint of the Eastern Orthodox tradition in the 9th century. She lived under the iconoclastic Emperor Theophilos and became known for many deeds on behalf of the poor and for her Christian life generally. The Eastern Orthodox believed that her incorrupt relics produced several miracles. Her commemoration on August 3rd carries the title of Venerable.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Theoclite_the_Wonderworker", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
