WHERE content."id" = 'cmq9m9xn51sv8g92draa3wd4a'
  AND content."slug" = 'saint-theoclite-the-wonderworker'
  AND md5(content."payload"->>'biography') = '784501d668841de2bbdfb9f3f9db1ba5';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The Christian saint and martyr Eudokia lived in the 3rd century. In Christian hagiographic accounts, Shapur I is said to have deported her, along with thousands of other Christians. She reportedly encouraged her fellow believers during the persecution and converted Persian women; she was then tortured in several ways, jailed more than once, and finally beheaded. The Eastern Orthodox Church venerates her as a saint and commemorates her on August 4. Some modern Orthodox hagiographers, however, think she may in fact be a fictional figure.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Eudokia_the_Martyr", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmq9m9yw81svbg92djso3rum3'
  AND content."slug" = 'saint-eudocia-the-martyr'
  AND md5(content."payload"->>'biography') = 'cdf809f53b932ec1dd30529a087c1d1b';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Between 9 January 1522 and his death on 14 September 1523, Pope Adrian VI, born Adriaan Florensz Boeyens, led the Catholic Church and the Papal States. He was the only Dutchman to be pope, and after him no pope came from outside Italy until 455 years later, when the Polish John Paul II was elected.'::text) || jsonb_build_object('summary', 'Pope Adrian VI held the office of Roman Pontiff from 1522–1523.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Adrian_VI", "background": "rewritten", "summary": "rewritten"}'::jsonb),
