UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Marcellus II held office as Roman Pontiff from 1555 to 1555.'::text) || jsonb_build_object('background', 'Pope Marcellus II, whose birth name was Marcello Cervini degli Spannocchi, led the Catholic Church and governed the Papal States starting on 10 April 1555 and ending with his death 22 days afterward.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Marcellus_II", "summary": "rewritten", "background": "rewritten"}'::jsonb),
