UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Paul IV, whose birth name was Gian Pietro Carafa, led the Catholic Church and the Papal States between 23 May 1555 and his death in August 1559. During his time as papal nuncio in Spain he formed an anti-Spanish outlook, which later colored his papacy. When Spain invaded part of the Papal States during his reign, he appealed for French military intervention. After the French were defeated and with Spanish troops on the outskirts of Rome, a compromise was struck between the Papacy and Spain: forces of both France and Spain withdrew from the Papal States, and from then on the Pope took a neutral position between the two.'::text) || jsonb_build_object('summary', 'Pope Paul IV held the office of Roman Pontiff from 1555–1559.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Paul_IV", "background": "rewritten", "summary": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
