UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Kyros of Constantinople held the post of Ecumenical Patriarch of Constantinople between 705 and 711. Both the Eastern Orthodox Church and the Catholic Church honour him as a saint; the Catholic Church assigned his feast to 7 January, and the Orthodox Church to 8 January (21). Emperor Justinian II installed Kyros on the patriarchal throne in 705, to replace Patriarch Callinicus I of Constantinople, who had been deposed. In December 711, shortly after Justinian II declined and finally fell, the new Emperor Philippicus removed Kyros and put Patriarch John VI of Constantinople in his place, a man who shared Philippicus'' Monothelite sympathies.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Kyros_of_Constantinople", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
