UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A Mexican layman, Manuel Morales Cervantes was killed during the Cristero War. He was an activist for the Catholic cause during the anticlerical era under President Plutarco Elías Calles; government forces captured him and executed him because he would not renounce his stance. Pope John Paul II canonized Morales on 21 May 2000, among the 25 Saints of the Cristero War.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Manuel_Morales_(martyr)", "biography": "rewritten"}'::jsonb),
