UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pedro Poveda, a Catholic priest from Spain, was an educator and humanitarian, and the founder of the Teresian Association. He carried out humanitarian and educational work for more than 30 years, until persecutors of the Christian faith executed him in 1936. He was beatified in 1993, then canonized in 2003, and his feast day is 28 July.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pedro_Poveda_Castroverde", "biography": "rewritten"}'::jsonb),
