UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Felix I, bishop of Rome as pope from 5 January 269 until he died on 30 December 274, was a native of Rome and followed Pope Dionysius. He is remembered for his theological contributions, above all an important dogmatic letter on the unity of Christ’s person. As pope, Felix I faced the heresy taught by Paul of Samosata, who rejected Christ''s divinity. Felix prompted Emperor Aurelian to step in, and Paul was removed from the bishopric of Antioch, which strengthened orthodox Christological doctrine.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Felix_I", "biography": "rewritten"}'::jsonb),
