UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'The Roman Pontiff Pope Miltiades held office from 311–314.'::text) || jsonb_build_object('background', 'Pope Miltiades, also called Melchiades the African, served as bishop of Rome from 311 until he died on 10 or 11 January 314. His pontificate coincided with the Edict of Milan (313), issued by Emperor Constantine the Great, which gave Christianity legal standing in the Roman Empire. The pope was also given the palace of Empress Fausta, on whose site the Lateran Palace would rise, serving as the papal seat and as home to the papal administration. A Lateran Council met amid the schism involving the Church of Carthage, and Miltiades there denounced rebaptizing bishops and priests who had apostatised, a practice taught by Donatus Magnus.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Miltiades", "summary": "rewritten", "background": "rewritten"}'::jsonb),
