    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmq9ml4dk29cqg92ddpnamej9'
  AND content."slug" = 'pope-miltiades'
  AND md5(content."payload"->>'summary') = 'e4751a67231bd67e08ad1da1ad182e3b' AND md5(content."payload"->>'background') = '84e11f1f7d2e69bd1570a2a7cf1535e9';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'The Roman Pontiff Pope Sylvester I held office from 314–336.'::text) || jsonb_build_object('background', 'Pope Sylvester I served as bishop of Rome. His term began on 31 January 314 and ended with his death on 31 December 335. Although little is known about his life, he held the See of Rome during a major period in Western Church history.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Sylvester_I", "summary": "rewritten", "background": "rewritten"}'::jsonb),
