UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Julius I served as bishop of Rome. His term began on 6 February 337 and ended with his death on 12 April 352. When Arian bishops removed Athanasius from his post as patriarch, Athanasius appealed to Julius, who backed him and declared the removal unjust. Julius is noted for claiming papal authority over the Arian Eastern bishops, and he is also credited with fixing December 25 as the official date of Jesus''s birth.'::text) || jsonb_build_object('summary', 'The Roman Pontiff Pope Julius I held office from 337–352.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Julius_I", "background": "rewritten", "summary": "rewritten"}'::jsonb),
