UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Damasus I, who is also called Damasus of Rome, was bishop of Rome from October 366 until he died in 384. He presided at the 382 Council of Rome, which fixed the canon, the official list of sacred scripture.'::text) || jsonb_build_object('summary', 'The Roman Pontiff Pope Damasus I held office from 366–384.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Damasus_I", "background": "rewritten", "summary": "rewritten"}'::jsonb),
