UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'The Roman Pontiff Pope Siricius held office from 384–399.'::text) || jsonb_build_object('background', 'Siricius was bishop of Rome from December 384 until he died on 26 November 399. Bishop Himerius of Tarragona sent him questions, and he answered with the Directa decretal, which set out decrees on baptism, church discipline and other topics. These are the earliest papal decretals preserved in full. Some say he was the first bishop of Rome to style himself pope.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Siricius", "summary": "rewritten", "background": "rewritten"}'::jsonb),
