UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'The Roman Pontiff Pope Innocent I held office from 402–417.'::text) || jsonb_build_object('background', 'Pope Innocent I served as bishop of Rome from 401 until he died on 12 March 417. From the start of his papacy, people regarded him as a general arbitrator of church disputes in both East and West. He upheld the privileges of the Archbishop of Thessalonica, and wrote a decretal on disciplinary questions that the Bishop of Rouen had put to him. He took the part of the exiled John Chrysostom, and on the Pelagian controversy he consulted the bishops of Africa and confirmed what the African synods had decided.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Innocent_I", "summary": "rewritten", "background": "rewritten"}'::jsonb),
