UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Zosimus, Roman Pontiff during the years 417–418.'::text) || jsonb_build_object('background', 'Pope Zosimus was Rome''s bishop from 18 March 417 until he died on 26 December 418. He played a firm role in the long-running Gaulish quarrel over whether the See of Arles had authority over that of Vienne, issuing vigorous rulings in favour of Arles without bringing the dispute to an end. His quarrelsome temperament marked every controversy he entered, whether in Gaul, in Africa or in Italy (Rome itself among them), where the clergy were deeply split when he died.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Zosimus", "summary": "rewritten", "background": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmq9ml4kj29deg92drel4vyw1'
