UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Boniface I, Roman Pontiff during the years 418–422.'::text) || jsonb_build_object('background', 'Pope Boniface I was Rome''s bishop from 28 December 418 until he died on 4 September 422. Supporters of Eulalius contested his election, and the matter was resolved only when Emperor Honorius intervened. Boniface worked to uphold church discipline and gave back certain privileges to the metropolitan sees of Narbonne and Vienne, freeing them from any subordination to the primacy of Arles. Augustine of Hippo lived in his time and dedicated some of his writings to him.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Boniface_I", "summary": "rewritten", "background": "rewritten"}'::jsonb),
