UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'The Roman Pontiff Pope Celestine I held office from 422–432.'::text) || jsonb_build_object('background', 'Pope Celestine I served as bishop of Rome. His term began on 10 September 422 and ended with his death on 27 July 432. Most of his pontificate went to fighting teachings considered heretical. When Cyril of Alexandria appealed to him, he played a key part in the condemnation of Nestorius at the Council of Ephesus, instructing Cyril to condemn Nestorius should he fail to retract his teachings. In 429 he backed the Gallic bishops in sending Germanus of Auxerre to Britain to deal with Pelagianism, and later he named Palladius a bishop, as the one to serve the Scots of Ireland as well as northern Britain.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Celestine_I", "summary": "rewritten", "background": "rewritten"}'::jsonb),
