UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Sixtus III, Roman Pontiff during the years 432–440.'::text) || jsonb_build_object('background', 'Pope Sixtus III, also known as Pope Xystus III, was Rome''s bishop from 31 July 432 until he died on 18 August 440. His accession to the papacy coincided with a time of greater building activity in the city of Rome. Both the Catholic Church and the Eastern Orthodox Church keep his feast day on 28 March.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Sixtus_III", "summary": "rewritten", "background": "rewritten"}'::jsonb),
