UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Leo I held office as Roman Pontiff in the years 440–461.'::text) || jsonb_build_object('background', 'Pope Leo I, also called Leo the Great, was the Bishop of Rome beginning 29 September 440, and his life ended on 10 November 461. The Annuario Pontificio lists three popes with the title "the Great": Leo I, Gregory I and Nicholas I. Leo is the first of these three.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Leo_I", "summary": "rewritten", "background": "rewritten"}'::jsonb),
