UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Simplicius held office as Roman Pontiff in the years 468–483.'::text) || jsonb_build_object('background', 'Pope Simplicius was bishop of Rome from 468 until he died on 10 March 483. He fought the Eutychian heresy, put an end to the custom that bishops be consecrated in December alone, and worked to lessen the damage of the Germanic invasions. In 476, during his pontificate, the Western Roman Empire fell when Odoacer removed Romulus Augustulus, the last Western Roman emperor, an event that scarcely affected how the Church administered Rome.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Simplicius", "summary": "rewritten", "background": "rewritten"}'::jsonb),
