UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Judas Cyriacus (Spanish: Quirico, Italian: Ciriaco) died ca. AD 360 and is the patron saint of Ancona in Italy. The Catholic Church keeps his feast day on 4 May.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Judas_Cyriacus", "biography": "rewritten"}'::jsonb),
