UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Guillaume-Joseph Chaminade, SM, a French Catholic priest, lived through persecution during the French Revolution. In 1817 he went on to found the Society of Mary, whose members are usually known as the Marianists. Pope John Paul II beatified him on 3 September 2000, and 22 January is his feast day.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/William_Joseph_Chaminade", "biography": "rewritten"}'::jsonb),
