  AND md5(content."payload"->>'biography') = 'f8b3541bd0be7916955f12fee316cccd';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Severus of Ravenna, Bishop of Ravenna in the 4th century, was present in 343 at the Council of Sardica. He is commemorated on February 1. His ordination as bishop came about through his personal virtue and "the sign of a dove".'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Severus_of_Ravenna", "biography": "rewritten"}'::jsonb),
