UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Briac (French) or Briag (Breton) was an Irish monk who traveled to Brittany alongside Saint Tudwal. He is commemorated on 17 December.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Briag", "biography": "rewritten"}'::jsonb),
