UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Hallvard Vebjørnsson, usually called Saint Hallvard, is Oslo''s patron saint. He is regarded as a martyr for defending an innocent thrall woman. He is honored with a religious feast day on 15 May.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Hallvard_Vebj%C3%B8rnsson", "biography": "rewritten"}'::jsonb),
