UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Landry, or Landericus, of Paris served as Bishop of Paris, and both the Roman Catholic Church and the Orthodox Church have canonized him as a saint. He constructed a hospital in honor of St. Christopher, which in time became the Hôtel-Dieu de Paris. People keep his feast day on 10 June.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Landry_of_Paris", "biography": "rewritten"}'::jsonb),
