UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Perfectus (Santo Perfecto) died on 18 April 850. He was counted among the Martyrs of Córdoba, and Saint Eulogius recorded his martyrdom in the Memoriale sanctorum.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Perfectus", "biography": "rewritten"}'::jsonb),
