UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Maxentia of Beauvais was an Irish virgin and hermit of the 5th century who was beheaded for refusing marriage. Her feast day is 20 November.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Maxentia_of_Beauvais", "biography": "rewritten"}'::jsonb),
