UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A Greek monk, Maximus the Greek, whose other names include Maximos the Greek and Maksim Grek, was active in Russia as a publicist, writer, scholar and translator. Maximos the Hagiorite and Maximus the Philosopher are further names for him. He signed himself Maximus Grecus Lakedaimon, and his family probably came from Mystras in Laconia, the region of the Peloponnese where Ancient Sparta once stood. He was canonised in 1988, and Eastern Orthodox Christians venerate him as a saint, keeping his feast on 21 January.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Maximus_the_Greek", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmq9mlqe429yrg92dhdpmsooa'
  AND content."slug" = 'saint-maximus-the-greek'
  AND md5(content."payload"->>'biography') = '345d5416ce24b72bcc5016e1b82a4f85';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The patron saint of Pisa, who is likewise patron saint of travellers, is Rainerius (c. 1115/1117 – 1160). June 17 is his feast day. Variant spellings of his name include Raynerius, Rainerius, Rainier, Raineri, Rainieri, Ranieri, Raniero, and Regnier.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Rainerius", "biography": "rewritten"}'::jsonb),
