  AND md5(content."payload"->>'biography') = 'f6a313501defd1ac390bb0e751e7e540';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The Carthusian Martyrs of London were monks of the London Charterhouse whom the English state put to death between 4 May 1535 and 20 September 1537. Execution was typically by hanging, followed by disembowelment while the victim was still alive, and quartering. Others were jailed and left to die of starvation. Two further monks, brought to the London house from Beauvale and Axholme (also Charterhouses) and subjected to the same fate, belong to the group. In all there were 18 men, and the Catholic Church has formally recognized each of them as martyrs.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Carthusian_Martyrs_of_London", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmq9mlwmy2a8kg92dn9w7k83z'
  AND content."slug" = 'saint-carthusian-martyrs-of-london'
  AND md5(content."payload"->>'biography') = '4779e449fb21fbcbbd51dfe835b11580';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pope John Paul II beatified Leonid Ivanovich Feodorov at Lviv on 27 June 2001. A Studite hieromonk in the Russian Greek Catholic Church, he was the initial Exarch of the Russian Catholic Apostolic Exarchate of Russia, and he lived through the Gulag at the Solovki prison camp.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Leonid_Feodorov", "biography": "rewritten"}'::jsonb),
