UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Zaragoza''s patron saint is Saint Valerius of Saragossa. From 290 until he died he served as that city''s bishop, and he took part in the Council of Elvira. January 29 is his feast day.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Valerius_of_Saragossa", "biography": "rewritten"}'::jsonb),
