UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Benedict II died on 8 May 685, having been bishop of Rome since 26 June 684. Benedict II''s feast is kept on 7 May.'::text) || jsonb_build_object('summary', 'Pope Benedict II held office as Roman Pontiff in the years 684–685.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Benedict_II", "background": "rewritten", "summary": "rewritten"}'::jsonb),
