UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Between 23 July 685 and his death on 2 August 686, Pope John V held the office of bishop of Rome. During the Byzantine Papacy he was the first pope consecrated without earlier imperial consent, and he began a run of ten popes in a row who were of Eastern origin. His papacy saw Rome and the Empire reconciled.'::text) || jsonb_build_object('summary', 'Pope John V held office as Roman Pontiff in the years 685–686.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_John_V", "background": "rewritten", "summary": "rewritten"}'::jsonb),
