UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Sergius I was Rome''s bishop from 15 December 687 until he died on 8 September 701; the Roman Catholic Church reveres him as a saint. When he was elected, two rivals named Paschal and Theodore were disputing which of them should be pope. His papacy was chiefly defined by his reaction to the Quinisext Council, whose canons he steadfastly refused to accept. Emperor Justinian II then ordered that Sergius be arrested, yet the people of Rome together with the Italian militia of the Ravenna exarch refused to let the exarch bring Sergius to Constantinople.'::text) || jsonb_build_object('summary', 'Pope Sergius I held office as Roman Pontiff from 687 to 701.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Sergius_I", "background": "rewritten", "summary": "rewritten"}'::jsonb),
