UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope John VI held office as Roman Pontiff in the years 701–705.'::text) || jsonb_build_object('background', 'Pope John VI, a Greek from Ephesus, was bishop of Rome beginning on 30 October 701, and his life ended on 11 January 705. He reigned in the era of the Byzantine Papacy, and his papacy brought notable breakthroughs, both military and political, on the Italian Peninsula. A vacancy of under two months followed, after which Pope John VII succeeded him. The pope''s body was laid in the tomb at Old St. Peter''s Basilica.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_John_VI", "summary": "rewritten", "background": "rewritten"}'::jsonb),
