UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope John VII, Roman Pontiff during the years 705–707.'::text) || jsonb_build_object('background', 'Pope John VII was Rome''s bishop from 1 March 705 until he died on 18 October 707. Ethnically Greek and one of the Byzantine popes, he got along better with the Lombards, who controlled a large part of the peninsula, than with Emperor Justinian II, the ruler of the remaining territory.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_John_VII", "summary": "rewritten", "background": "rewritten"}'::jsonb),
