UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Sisinnius, Roman Pontiff during the years 708–708.'::text) || jsonb_build_object('background', 'Pope Sisinnius was Rome''s bishop from 15 January 708 until he died on 4 February 708. Apart from the facts that he was a Syrian and that his father was named John, little is recorded about his early life or career. When he was elected to the papal throne he was weakened by severe gout. In the twenty days of his papacy, he consecrated a new bishop for Corsica and gave orders to strengthen the walls around Rome, the papal capital. After his death he was laid to rest in Old St. Peter''s Basilica, and Pope Constantine followed him.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Sisinnius", "summary": "rewritten", "background": "rewritten"}'::jsonb),
