UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Constantine held office as Roman Pontiff in the years 708–715.'::text) || jsonb_build_object('background', 'Between 25 March 708 and his death on 9 April 715, Pope Constantine held the office of bishop of Rome. He was one of the final popes of the Byzantine Papacy, and the most important event of his pontificate was his visit to Constantinople in 710/711, where he reached a compromise with Justinian II over the canons of the Quinisext Council known as the Trullan canons. Not until 1967 would another pope visit that city.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Constantine", "summary": "rewritten", "background": "rewritten"}'::jsonb),
