UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'The Roman Pontiff Pope Gregory II held office from 715–731.'::text) || jsonb_build_object('background', 'Pope Gregory II served as bishop of Rome. His term began on 19 May 715 and ended with his death on 11 February 731. Because the Eastern Empire''s iconoclastic controversy led him to defy Emperor Leo III the Isaurian, he opened the way for a long run of revolts, schisms and civil wars, which in the end produced the temporal power of the popes.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Gregory_II", "summary": "rewritten", "background": "rewritten"}'::jsonb),
