UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Gregory III held office as Roman Pontiff in the years 731–741.'::text) || jsonb_build_object('background', 'Between 11 February 731 and his death on 28 November 741, Pope Gregory III held the office of bishop of Rome. As in his predecessor''s time, his pontificate was troubled by Byzantine iconoclasm and by Lombard expansion; he appealed to Charles Martel for help, but in the end without success. He was the final pope to ask the Byzantine exarch of Ravenna to approve his election and the final pope of Syrian origin, and no pope born outside Europe followed him until Pope Francis was elected 1,272 years later, in 2013.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Gregory_III", "summary": "rewritten", "background": "rewritten"}'::jsonb),
