UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope-elect Stephen held office as Roman Pontiff from 752 to 752.'::text) || jsonb_build_object('background', 'Pope-elect Stephen, a Roman cardinal-priest and presbyter, was chosen to succeed Pope Zachary; the selection took place on 23 March 752. Until 1961 he was known as Pope Stephen II. As he died before his episcopal consecration, he is considered only a pope-elect, not a legitimate pope.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope-elect_Stephen", "summary": "rewritten", "background": "rewritten"}'::jsonb),
