UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Stephen II was bishop of Rome from 752 until he died in 757. His pontificate marks the dividing line in history separating the Byzantine Papacy from the Frankish Papacy. When the Lombards threatened to invade Rome, Stephen II traveled to Paris to ask Pepin the Short for help. Pepin defeated the Lombards and gave the pope a grant of land, which in time led to the founding of the Papal States.'::text) || jsonb_build_object('summary', 'Pope Stephen II held office as Roman Pontiff in the years 752–757.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Stephen_II", "background": "rewritten", "summary": "rewritten"}'::jsonb),
