UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Paul I held office as Roman Pontiff in the years 757–767.'::text) || jsonb_build_object('background', 'Between 29 May 757 and his death on 28 June 767, Pope Paul I was bishop of Rome and governed the emerging Papal States. Earlier he was a Roman deacon, whom his brother, Pope Stephen II, often used in negotiations with the Lombard kings.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Paul_I", "summary": "rewritten", "background": "rewritten"}'::jsonb),
