UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Maurinus of Cologne was a German abbot of the 9th century who is said to have died a martyr. Both the Roman-Catholic Church and the Eastern Orthodox Church recognise him as a saint. His shrine, dating to the 12th century, is in Saint Pantaleon''s Church, Cologne, and Saint Maurinus'' Church, Lützenkirchen, bears his dedication. His saint''s day is 10 June.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Maurinus_of_Cologne", "biography": "rewritten"}'::jsonb),
