UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Stephen VIII was Rome''s bishop and nominal head of the Papal States. His rule began on 14 July 939 and lasted until he died. His papacy fell within the Saeculum obscurum, an age in which the ambitious counts of Tusculum weakened papal power, and it was shaped by the struggle between King Hugh of Italy and Stephen''s patron, Alberic II of Spoleto.'::text) || jsonb_build_object('summary', 'Pope Stephen VIII was Roman Pontiff in the period 939–942.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Stephen_VIII", "background": "rewritten", "summary": "rewritten"}'::jsonb),
