UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope John XII, originally named Octavian, was Rome''s bishop and sovereign of the Papal States starting 16 December 955, and he held both roles until he died in 964. His relatives included the counts of Tusculum, a mighty Roman family that had shaped papal politics for more than fifty years. He became Pope at an age somewhere from 17 to 25. At 17 he could have been the youngest Pope ever; otherwise, the record may instead be held by Benedict IX, elected when aged between 11 and 20.'::text) || jsonb_build_object('summary', 'Pope John XII held office as Roman Pontiff from 955–964.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_John_XII", "background": "rewritten", "summary": "rewritten"}'::jsonb),
