UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Benedict V held office as Roman Pontiff from 964 to 964.'::text) || jsonb_build_object('background', 'Pope Benedict V was pope and governed the Papal States between 22 May and 23 June 964, as a rival to Leo VIII. Emperor Otto I overthrew him. His short pontificate came at the close of the Saeculum obscurum.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Benedict_V", "summary": "rewritten", "background": "rewritten"}'::jsonb),
