UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Leo VIII, a Roman prelate, laid claim to the Holy See from 963 to 964, against John XII and Benedict V, and then once more from 23 June 964 until he died. The Catholic Church today regards him as an antipope in the first span and as the legitimate pope in the second. Holy Roman Emperor Otto I appointed him, and his pontificate came later than the era called the saeculum obscurum.'::text) || jsonb_build_object('summary', 'Pope Leo VIII was Roman Pontiff in the period 964–965.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Leo_VIII", "background": "rewritten", "summary": "rewritten"}'::jsonb),
