UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope John XIII held office as Roman Pontiff from 965–972.'::text) || jsonb_build_object('background', 'From 1 October 965 until he died, Pope John XIII served as ruler of the Papal States and bishop of Rome. During his pontificate the struggle between the Roman nobility and the Holy Roman emperor, Otto I, went on, and it drew him in. Following lengthy and difficult negotiations, he managed to arrange a Byzantine marriage for Otto II, seeking thereby to give legitimacy to the claim of the Ottonians to imperial dignity. He likewise set up a church hierarchy in Poland and Bohemia.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_John_XIII", "summary": "rewritten", "background": "rewritten"}'::jsonb),
