UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Benedict VI was Rome''s bishop and sovereign over the Papal States beginning 19 January 973 until he died in 974. His short pontificate fell within the political setting of the Holy Roman Empire''s founding, at the shift from the reign of Otto I to that of Otto II, and it involved a contest for power among aristocratic Roman families, among them the Crescentii.'::text) || jsonb_build_object('summary', 'Pope Benedict VI held office as Roman Pontiff from 973–974.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Benedict_VI", "background": "rewritten", "summary": "rewritten"}'::jsonb),
