UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope John XIV was Roman Pontiff in the period 983–984.'::text) || jsonb_build_object('background', 'Born Peter Canepanova, Pope John XIV was bishop of Rome and ruled the Papal States. His reign began in December 983 and lasted until he died. Emperor Otto II proposed Canepanova for the papal throne when Pope Benedict VII died in July 983, once the abbot Maiolus of Cluny had turned the office down. Canepanova, then bishop of Pavia, was installed without any consultation of the clergy and Roman people, and no formal election confirmed it.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_John_XIV", "summary": "rewritten", "background": "rewritten"}'::jsonb),
