UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope John XV was Roman Pontiff in the period 985–996.'::text) || jsonb_build_object('background', 'Pope John XV, a Roman by birth, was bishop of Rome and ruled the Papal States. His reign began in August 985 and lasted until he died. Of all the popes, he was the first who canonized a saint. His pontificate holds the roots of the investiture controversy: a quarrel over removing Archbishop Arnulf of Reims from office strained relations between the Holy See and the Capetian kings of France.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_John_XV", "summary": "rewritten", "background": "rewritten"}'::jsonb),
