UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope John XVII was Roman Pontiff in the period 1003–1003.'::text) || jsonb_build_object('background', 'Born John Sicco, Pope John XVII was bishop of Rome and nominal head of the Papal States for roughly seven months in 1003. He was among the popes selected, and overshadowed, by the patrician John Crescentius.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_John_XVII", "summary": "rewritten", "background": "rewritten"}'::jsonb),
