UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope John XVIII was Rome''s bishop and nominal sovereign over the Papal States beginning January 1004 until he abdicated in July 1009. He held little temporal power, as his reign coincided with the contest between John Crescentius and Emperor Henry II over control of Rome. He was the final pope for centuries to keep his baptismal name, and each pope since has chosen a new papal name.'::text) || jsonb_build_object('summary', 'Pope John XVIII held office as Roman Pontiff from 1003–1009.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_John_XVIII", "background": "rewritten", "summary": "rewritten"}'::jsonb),
