UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Sergius IV was Roman Pontiff in the period 1009–1012.'::text) || jsonb_build_object('background', 'Pope Sergius IV was bishop of Rome and nominal head of the Papal States. His rule began on 31 July 1009 and lasted until he died. The patrician John Crescentius overshadowed his temporal power. It is disputed whether Sergius IV called for Muslims to be driven out of the Holy Land. The custom of a newly elected pope adopting a new name became established from his time.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Sergius_IV", "summary": "rewritten", "background": "rewritten"}'::jsonb),
