UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Donatus (called Donato of Zara as well) was a Dalmatian saint who rose to bishop and acted as diplomat on behalf of Zadar (Zara), a Dalmatian city-state. 25 February is his feast day.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Donatus_of_Zadar", "biography": "rewritten"}'::jsonb),
