UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Rabanus Maurus Magnentius (also Hrabanus or Rhabanus) was a Benedictine monk of the Franks, and also a theologian, poet, encyclopedist and military writer; he rose to be archbishop at Mainz in East Francia. He wrote the encyclopaedia De rerum naturis, along with treatises on education and grammar and Bible commentaries. He ranked among the foremost teachers and authors of the Carolingian era and was called "Praeceptor Germaniae"; in English, "the teacher of Germany". In the latest edition of the Roman Martyrology, 4 February is his feast and he is styled a Saint (''sanctus'').'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Rabanus_Maurus", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmq9mn4b92bzzg92dr1ipydlx'
