UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pope Agapetus I, bishop of Rome, took office on 13 May 535 and died on 22 April 536. Gordianus, a priest in Rome, was his father, and he possibly had family ties to two other popes, Felix III and Gregory I.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Agapetus_I", "biography": "rewritten"}'::jsonb),
