UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pope Siricius held the office of bishop of Rome from December 384 until he died on 26 November 399. Bishop Himerius of Tarragona sent him questions, and Siricius answered with the Directa decretal, which set out rulings on baptism, church discipline and other subjects. These are the earliest papal decretals preserved in full. He is sometimes described as the first bishop of Rome to style himself pope.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Siricius", "biography": "rewritten"}'::jsonb),
