UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'On 14 August 1480, 813 residents of Otranto (in Salento, Apulia, southern Italy) were killed after the city fell to Ottoman troops commanded by Gedik Ahmed Pasha. They are called the Martyrs of Otranto, or Saints Antonio Primaldo and his Companions. A traditional account says the killings followed the citizens'' refusal to convert to Islam.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Martyrs_of_Otranto", "biography": "rewritten"}'::jsonb),
