UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pope Zosimus, bishop of Rome, held office from 18 March 417 until he died on 26 December 418. He played a decided role in the long-running Gallic dispute over whether the See of Arles had jurisdiction over that of Vienne, and he ruled energetically for Arles, though he did not settle the controversy. His quarrelsome temper marked every controversy he joined, whether in Gaul, Africa, or Italy (Rome included), and at his death the Roman clergy were deeply divided.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Zosimus", "biography": "rewritten"}'::jsonb),
