  AND md5(content."payload"->>'biography') = '31e560ed81a2a911b2f094f245a1d3b7';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Fabiola, a physician, was a Roman matron of rank belonging to the noble Roman women who followed the Church Father Jerome''s influence in abandoning all earthly pleasures for the practice of Christian asceticism and works of charity. The Eastern Orthodox Church and the Roman Catholic church venerate her as a saint, and commemorate her on 27 December.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Fabiola", "biography": "rewritten"}'::jsonb),
