UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Adrian V, originally named Ottobuono de'' Fieschi, headed the Catholic Church and ruled over the Papal States beginning 11 July 1276 until he died on 18 August 1276. Pope Clement IV had sent him as an envoy to England in May 1265, where he succeeded in settling the quarrels between the barons and King Henry III of England. After Innocent V died, Adrian V was elected pope, but a natural illness took his life before he could be ordained to the priesthood.'::text) || jsonb_build_object('summary', 'Pope Adrian V held office as Roman Pontiff from 1276–1276.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Adrian_V", "background": "rewritten", "summary": "rewritten"}'::jsonb),
