UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope John XXI was Roman Pontiff in the period 1276–1277.'::text) || jsonb_build_object('background', 'Born Pedro Julião, Pope John XXI headed the Catholic Church and ruled the Papal States. His reign began on 8 September 1276 and ended with his death in May 1277. He remains the only Portuguese pope. Some identify him as Peter of Spain, the logician and herbalist; if so, he would be the only pope who was a physician.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_John_XXI", "summary": "rewritten", "background": "rewritten"}'::jsonb),
