UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Honorius IV led the Catholic Church and ruled over the Papal States beginning 2 April 1285 until he died on 3 April 1287. He was elected once Pope Martin IV had died, and the speed of the election stood out: the vote was unanimous on the first ballot. His papacy fell in a turbulent time of political strife and of conflict in Sicily, where he tried to handle delicate relations with various rulers while preserving papal authority. Throughout his pontificate he kept up his predecessor''s pro-French political policy. He is the latest pope to choose the pontifical name "Honorius" on election, taking it from his granduncle Pope Honorius III.'::text) || jsonb_build_object('summary', 'Pope Honorius IV held office as Roman Pontiff from 1285–1287.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Honorius_IV", "background": "rewritten", "summary": "rewritten"}'::jsonb),
