UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'Pope Felix III was Roman Pontiff in the period 483–492.'::text) || jsonb_build_object('background', 'Pope Felix III was bishop of Rome. His tenure began on 13 March 483 and ended with his death on 1 March 492. By rejecting the Henotikon, he is regarded as having started the Acacian schism. His commemoration falls on March 1.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Felix_III", "summary": "rewritten", "background": "rewritten"}'::jsonb),
