UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Stephen III was bishop of Rome and ruled the Papal States. His reign began on 7 August 768 and ended with his death on 24 January 772. A Benedictine monk, Stephen had served in the Lateran Palace under Pope Zachary. Rival factions fought fiercely over who should follow Pope Paul I, and amid this turmoil Stephen won election with the backing of Roman officials. He called the Lateran Council of 769, which tried to curb the nobles'' influence over papal elections and also opposed iconoclasm.'::text) || jsonb_build_object('summary', 'Pope Stephen III was Roman Pontiff in the period 768–772.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Stephen_III", "background": "rewritten", "summary": "rewritten"}'::jsonb),
