UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'The Roman Pontiff Pope Leo III held office from 796–816.'::text) || jsonb_build_object('background', 'Pope Leo III ruled as bishop of Rome and of the Papal States. His term began on 26 December 795 and ended with his death on 12 June 816.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Leo_III", "summary": "rewritten", "background": "rewritten"}'::jsonb),
