UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Pope Stephen IV was bishop of Rome and ruled the Papal States from June 816 until he died on 24 January 817. He came from a noble Roman family. At Reims, during October 816, Louis the Pious received the imperial crown from him, and Stephen convinced the new emperor to free certain Roman political prisoners in his custody. Stephen travelled back to Rome by way of Ravenna in November or so, and died the next January.'::text) || jsonb_build_object('summary', 'Pope Stephen IV was Roman Pontiff in the period 816–817.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Stephen_IV", "background": "rewritten", "summary": "rewritten"}'::jsonb),
