UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'San Teodoro, or Saint Theodore of Pavia, served as bishop of Pavia from 743 until he died. The Lombard kings exiled him several times. His feast day is May 20. He and Syrus (Siro) are patron saints of Pavia, and his body rests in the church that bears his name.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Theodore_of_Pavia", "biography": "rewritten"}'::jsonb),
