  AND content."slug" = 'saint-theodore-of-pavia'
  AND md5(content."payload"->>'biography') = 'f757c8ecbb55f88499b79ffe60eb6852';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'William Lacy, also spelled Lacey, died in 1582. An English priest and martyr of the Catholic Church, he was put to death at York on 22 August 1582 together with a fellow priest, Richard Kirkman.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/William_Lacy_(Catholic_priest)", "biography": "rewritten"}'::jsonb),
