UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pope Simplicius was bishop of Rome from 468 until he died on 10 March 483. He fought the Eutychian heresy, stopped bishops from being consecrated only in December, and tried to counter the effects of the Germanic invasions. In 476, during his pontificate, the Western Roman Empire fell when Odoacer deposed Romulus Augustulus, its last emperor, though this affected the Church''s administration of Rome very little.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Simplicius", "biography": "rewritten"}'::jsonb),
