  AND md5(content."payload"->>'biography') = '169914093065a1aa7c924e6915677848';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Born Nicola Boccasini, Pope Benedict XI led the Catholic Church and governed the Papal States. His pontificate began on 22 October 1303 and ended with his death on 7 July 1304.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Benedict_XI", "biography": "rewritten"}'::jsonb),
