  AND content."slug" = 'saint-sava-ii'
  AND md5(content."payload"->>'biography') = '2e35b08b59d7de0e82b699252a4c6b8c';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Two saints, John and Paul, lived in the Roman Empire during the fourth century. They were martyred in Rome on 26 June. Their Acts leave the exact year of martyrdom uncertain, but it took place under Julian the Apostate (361–363).'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/John_and_Paul", "biography": "rewritten"}'::jsonb),
