UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pope Nicholas I (Nicholas the Great) ruled the Papal States and served as bishop of Rome from 24 April 858 to 13 November 867, when he died. Of the three popes given the title "the Great" in the Annuario Pontificio, he is the last, the others being Leo I and Gregory I.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Nicholas_I", "biography": "rewritten"}'::jsonb),
