UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pope Boniface IV, a Benedictine, was bishop of Rome from 608 until his death on 8 May 615. Earlier he had served Pope Gregory I as a deacon and, following that mentor, treated the Lateran Palace as a monastery. During his papacy he encouraged monasticism and, with imperial permission, turned the Pantheon into a church. Then in 610 he held talks with Bishop Mellitus of London about the needs of the English Church. The Catholic Church venerates him as a saint, and his feast day for the universal Church is 8 May.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Boniface_IV", "biography": "rewritten"}'::jsonb),
