  AND content."slug" = 'saint-boniface-iv'
  AND md5(content."payload"->>'biography') = '1208ba94a4f7c5babea2cd06ec38dd70';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Anthony the Great, a Christian monk from Egypt, has been revered as a saint since his death. Various epithets set him apart from other saints called Anthony, for instance Anthony of Padua: Anthony of Egypt, Anthony the Abbot, Anthony of the Desert, Anthony the Anchorite, Anthony the Hermit, and Anthony of Thebes. Because of his significance among the Desert Fathers and for all Christian monasticism that followed, he is also called the Father of All Monks. The Eastern Orthodox and Catholic churches keep his feast day on 17 January, while the Coptic calendar marks it on Tobi 22.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Anthony_the_Great", "biography": "rewritten"}'::jsonb),
