  AND md5(content."payload"->>'biography') = '593674f4b4e63a612fbafa175885121d';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pope Adeodatus I (also Deodatus I or Deusdedit) led the church in Rome as its bishop; his tenure began on 19 October 615 and ended when he died on 8 November 618. The first priest chosen as pope since John II in 533, he is also credited with introducing lead seals (bullae) on papal documents. He is commemorated on 8 November, his feast day.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Adeodatus_I", "biography": "rewritten"}'::jsonb),
