UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Born Theophylact of Tusculum into the counts of Tusculum, a noble family, Pope Benedict VIII was Rome''s bishop and governed the Papal States. His rule began on 18 May 1012 and ended in 1024. For a medieval pope he was unusual in wielding strong authority in Rome and beyond.'::text) || jsonb_build_object('summary', 'Pope Benedict VIII was Roman Pontiff in the period 1012–1024.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Benedict_VIII", "background": "rewritten", "summary": "rewritten"}'::jsonb),
