UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('background', 'Born Roman of Tusculum, Pope John XIX was Bishop of Rome and ruled the Papal States from 1024 until he died. He came from the powerful Counts of Tusculum and followed his brother, Benedict VIII. Relations between the papacy and the Patriarchate of Constantinople worsened during John XIX''s pontificate. He backed Emperor Conrad II, and the musician Guido of Arezzo enjoyed his patronage.'::text) || jsonb_build_object('summary', 'Pope John XIX was Roman Pontiff in the period 1024–1032.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_John_XIX", "background": "rewritten", "summary": "rewritten"}'::jsonb),
