UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pope Eleutherius, also called Eleutherus, was bishop of Rome beginning c. 174; he died in 189. His pontificate is alternatively placed at 171–185 or 177–193. The Catholic Church venerates him as a saint.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Eleutherius", "biography": "rewritten"}'::jsonb),
