UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Mario Ciceri was an Italian Roman Catholic priest from Milan. His parents were farmers, and from boyhood he felt drawn to the priesthood. He studied in Bergamo and Milan. In 1924 he was ordained priest at the Duomo; his first pastoral role was at a local parish church. He became well known for his devoted care of the poor and the sick, and also worked with children and teenagers. He renewed Catholic Action in his area and personally brought teens into the movement.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Mario_Ciceri", "biography": "rewritten"}'::jsonb),
