UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Mateus Moreira, a Portuguese martyr of the Catholic Church, lived in Colonial Brazil. On March 5, 2000 he was beatified, and on October 15, 2017 he was canonized, together with the other Martyrs of Natal.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Mateus_Moreira", "biography": "rewritten"}'::jsonb),
