UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pope Leo II was Rome''s bishop. His time in office began on 17 August 682 and ended with his death on 28 June 683. He belonged to the era of the Byzantine Papacy, and a biographer of his own time called him both just and learned. The Roman Martyrology commemorates him as a saint.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Leo_II", "biography": "rewritten"}'::jsonb),
