UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Colonial Brazil''s Martyrs of Natal were Catholics, 30 in number, two of whom were priests. Dutch Calvinists led massacres in the territory''s north, and these Catholics died in them. Of the two priests, one was a Colonial Brazilian Jesuit missionary and the other was an evangelizer. The remaining victims were lay Catholics, mostly unnamed members of the Church, and a few were children.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Martyrs_of_Natal", "biography": "rewritten"}'::jsonb),
