UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Afro-Brazilian Catholic priest Francisco de Paula Victor is called the "Apostle of Charity" in Brazil, because of how charitably he treated the poor. He is the earliest black Brazilian citizen to be beatified by the Catholic Church, and the earliest former slave who became a priest to be considered for canonization.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Francisco_de_Paula_Victor", "biography": "rewritten"}'::jsonb),
