  AND md5(content."payload"->>'biography') = '475bda361d083b2014697bb3d48b50d1';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Born Anselm of Baggio, Anselm of Lucca was a bishop of Lucca, in Italy, in the Middle Ages, and a leading figure in the Investiture Controversy during the conflict in central Italy that pitted Matilda, countess of Tuscany, against Emperor Henry IV. His uncle Anselm was bishop of Lucca before him, until his election as pope under the name Alexander II, and for this reason he is at times called Anselm the Younger or Anselm II.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Anselm_of_Lucca", "biography": "rewritten"}'::jsonb),
