  AND content."slug" = 'saint-anselm-of-lucca'
  AND md5(content."payload"->>'biography') = 'f77d7c5f7111a0df2578c4db1b69f4d4';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Marko Stjepan Krizin, also called Marko Križevčanin, was a Croatian missionary, priest and professor of theology of the Roman Catholic Church. His career fell in the 17th century, when Catholicism and Calvinism were in conflict in his region, and he was put to death because of his faith. The Church has since canonized him, and he is the third Croat to receive this honor.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Marko_Krizin", "biography": "rewritten"}'::jsonb),
