  AND md5(content."payload"->>'biography') = '5640c7268c0d0635b69f563184b3ec9b';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Cedd, a monk and bishop, came from the Anglo-Saxon Kingdom of Northumbria. As an evangelist he worked among the Middle Angles and the East Saxons of England, and he was an important figure at the Synod of Whitby, which resolved major disagreements inside the English Church. Anglicanism, the Roman Catholic Church and the Orthodox Church all venerate him.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Cedd", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
