  AND md5(content."payload"->>'biography') = '53b62f49d41e8a1787932ca2a62c6713';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Cellach of Armagh, also known as Celsus or Celestinus (1080–1129), served as Archbishop of Armagh and played a major part in reforming the Irish church during the twelfth century. The Roman Catholic Church venerates him as Saint Cellach. He belonged to Clann Sínaig, a laicised ecclesiastical dynasty, yet he took holy vows and was ordained a priest, ending the irregular situation that had held since 966, in which a layman headed the Irish Church. After the Synod of Ráith Bressail, which set up a diocesan structure for Ireland, he became primate of all Ireland and its first metropolitan.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Cellach_of_Armagh", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmq9rry92016vjgwsuye00yej'
  AND content."slug" = 'saint-cellach-of-armagh'
  AND md5(content."payload"->>'biography') = '9b4e3806a240d52f3c28b0c475e87a65';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'In 13th-century Florence, seven men joined in a spiritual friendship and together started the Servite Order; they are called the Seven Holy Founders of the Servite Order. Mary, mother of Jesus, was the object of their intense devotion, and they felt she was calling them. They reported a vision that apparently came to each of them separately at the very same moment, with none aware that the rest had also seen it. They heard themselves called to "leave the world" so as to better "serve almighty God".'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Seven_Holy_Founders_of_the_Servite_Order", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmq9rrysi016yjgws45d06hm1'
