UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A Slovak Roman Catholic, Anna Kolesárová was a virgin and a martyr. In 1944 she was killed by a Soviet soldier because she resisted his attempt to rape her. Those who knew her best described a modest, simple girl who went to Mass every morning and who took over the care of the household after her mother died, when Anna was in late childhood.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Anna_Koles%C3%A1rov%C3%A1", "biography": "rewritten"}'::jsonb),
