UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The Poor Handmaids of Jesus Christ had as their foundress Mary Catherine Kasper, A.D.J.C., a German Catholic Religious Sister. Her poverty, her father''s death and her brother''s death, and the lack of any female religious orders in her region after Napoleon''s secularization all stood in the way of a vocation she had cherished for a very long time, so she became a religious sister only later in life. Her commitment to the poor and her strength of will drew notice throughout her life, and she gave herself to that work with great zeal.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Maria_Katharina_Kasper", "biography": "rewritten"}'::jsonb),
