UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A German Roman Catholic priest, Kaspar Stanggassinger was a professed member of the Redemptorists. From his childhood he leaned toward the priesthood, and he soon entered the seminary. A spiritual experience then drew him to the Redemptorist charism, so he chose to join a religious order instead of becoming a diocesan priest. Ordained to the priesthood in 1895, he quickly started teaching and supervising new seminarians, even though he wished to go to the missions in Brazil.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Kaspar_Stanggassinger", "biography": "rewritten"}'::jsonb),
