UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Ansgar (also Anskar, Saint Ansgar, Saint Anschar or Oscar) served as Archbishop of Hamburg-Bremen, in the Kingdom of the East Franks'' northern region. His journeys earned him the title "Apostle of the North", and the See of Hamburg was given the mandate for missionary work of bringing Christianity to Northern Europe.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Ansgar", "biography": "rewritten"}'::jsonb),
