UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Giovanni Battista de'' Rossi was an Italian Roman Catholic priest. When his cousin, a priest at Santa Maria in Cosmedin, died, he took over there as canon. He became a well-loved confessor, even though at first he feared that his epileptic seizures might strike in the Confessional. Shortly after being ordained, Rossi set up a hospice for homeless women, and he was known for his ministry to prisoners and the sick, to whom he gave the whole of his ecclesial mission.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Giovanni_Battista_de''_Rossi_(priest)", "biography": "rewritten"}'::jsonb),
