UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'John Theristus, OSB, was a Benedictine monk of the Byzantine tradition from Italy. He died nearly a hundred years after the Great Schism of 1054, and yet, remarkably, he is a saint of both the Catholic and the Eastern Orthodox Churches. Legends and popular belief have preserved what is known of his life.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/John_Theristus", "biography": "rewritten"}'::jsonb),
