  AND md5(content."payload"->>'biography') = '9cf9957a1e4870e2c362e0ab29508c70';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Nicholas Salos of Pskov, a Russian, was a fool for Christ (yurodivy). Tsar Ivan the Terrible, after ravaging Novgorod in a devastating campaign, decided in February 1570 to attack Pskov, suspecting its inhabitants of treason. When the city was under siege, Nicholas confronted the tsar and rebuked him for his cruelty. Ivan IV reportedly stopped the executions because of this fearless admonition, and in time pulled his forces back to Alexandrov, so the city escaped a massacre. The Eastern Orthodox Church regards him as a saint.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Nicholas_Salos_of_Pskov", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmq9rzbxp06tbjgwsx0c26tig'
