  AND md5(content."payload"->>'biography') = 'd65ebefbf283b9d7a7df45f1cafab872';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Leoluca, also called Leone Luca, Leo Luke of Corleone, or Luke of Sicily, served as abbot of the monastery on Mount Mula in Calabria, where he was a wonderworker, and he was a founder of Italo-Greek monasticism across southern Italy. The Roman Catholic church and the Eastern Orthodox one both venerate him as a saint.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Leoluca", "biography": "rewritten"}'::jsonb),
