  AND md5(content."payload"->>'biography') = '04116ec384dfd6635dc1f2438703f39c';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Cainnech of Aghaboe (515/16–600) was an Irish abbot, priest, missionary and founder of monasteries in the early medieval period. He is also called Saint Canice in Ireland, Saint Kenneth in Scotland, Saint Kenny, and in Latin Sanctus Canicus. Counted among the Twelve Apostles of Ireland, Cainnech preached the Christian faith throughout Ireland and among the Picts of Scotland. His commentary on the Gospels was long called the Glas-Choinnigh, which means the Chain of Cainnech, or Kenneth''s Lock.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Cainnech_of_Aghaboe", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
