  AND md5(content."payload"->>'biography') = 'a85b36c69dc3962afe3c2b0720e150b4';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Léonie Martin, who took the name Sister Françoise-Thérèse and is styled VHM, was a French Catholic nun of the Visitation Sisters who lived in the cloister. Her parents were Saints Louis Martin and Marie-Azélie Guérin Martin, and she was an older sister of Saint Thérèse of Lisieux. People sometimes call her Saint Thérèse''s "difficult sister".'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/L%C3%A9onie_Martin", "biography": "rewritten"}'::jsonb),
