UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Blessed Hartmann of Brixen, a German prelate in the Catholic Church, was appointed Bishop of Brixen in 1140 and held the see until he died. The Order of Saint Augustine, which had overseen his education, was one he worked with; although he did not belong to that congregation, he handled some parts of its administration. He backed Pope Alexander III in the conflict with Frederick Barbarossa, yet Barbarossa still favored him, notwithstanding Hartmann''s position on the schism.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Hartmann_of_Brixen", "biography": "rewritten"}'::jsonb),
