UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Nicholas of Flüe, a Swiss hermit and ascetic, is the patron saint of Switzerland and is at times called upon as Brother Klaus. He worked as a farmer and served as a military leader, assembly member, councillor and judge, and he was also a mystic; people respected him as a man of unblemished moral integrity. He is remembered for fasting for more than twenty years. The advice Brother Klaus gave when the Diet of Stans met (1481) helped keep war from breaking out between the Swiss cantons.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Nicholas_of_Fl%C3%BCe", "biography": "rewritten"}'::jsonb),
