UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'From 1924 until March 1930, Mariano Mullerat i Soldevila, a Spanish Roman Catholic doctor, was also the mayor of Arbeca. He studied medicine in Reus and Barcelona, married in 1922, and then he and his wife settled in Arbeca, where he ran a private medical practice. A firm Catholic traditionalist, he defended Catholic dogma against liberal interpretations; as a doctor he treated the poor without charge and would even assist them with their material needs. While mayor he helped to organize religious solemnities, and he was known as well for going after people who slandered or made blasphemous claims in public.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Mariano_Mullerat_i_Soldevila", "biography": "rewritten"}'::jsonb),
