UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'María Teresa Ferragut Roig, a Spanish Roman Catholic laywoman, was a martyr killed near Alzira, Valencia, in the anti-clerical persecutions of Republican-controlled Spain at the start of the Spanish Civil War. In 2001 Pope John Paul II beatified her as one of the group called the 233 Spanish Martyrs, who were recognized as killed in odium fidei.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Mar%C3%ADa_Teresa_Ferragut_Roig", "biography": "rewritten"}'::jsonb),
