UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Maria Troncatti, FMA was an Italian Catholic member of the Salesian Sisters of Don Bosco. She came from a farming family and joined that congregation in 1907. She served as a nurse in World War I and then took part in the Ecuador missions from 1922 until a plane crash killed her in 1969. The Church beatified Troncatti on 24 November 2012, and she was canonized on 19 October 2025.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Maria_Troncatti", "biography": "rewritten"}'::jsonb),
