UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pietro Igneo was an Italian Roman Catholic Benedictine monk of the Vallombrosians branch. He also became a cardinal, appointed Cardinal-Bishop of Albano. Though he is frequently described as belonging to the Aldobrandini house, sources do not actually attest to that familiar designation as fact. Montepiano in Tuscany was the site of the Abbey of Santa Maria, which he founded.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Peter_Igneus", "biography": "rewritten"}'::jsonb),
