UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Alberto da Bergamo, TOSD, was a Catholic farmer from Bergamo, Italy, who made profession in the Third Order of Saint Dominic. In adulthood he married a woman who disapproved of his generosity to the poor before she converted and died. In the first period of his widowhood he went on several pilgrimages to Rome and visited both Spain and Jerusalem.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Alberto_da_Bergamo", "biography": "rewritten"}'::jsonb),
