UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Matrona of Perge was a Byzantine saint, remembered for disguising herself for a time as the monk Babylos in order to get away from her husband, after she resolved to follow the First Epistle to the Corinthians, chapter 7, verse 29, which says that "those who have wives" should live "as if they had none".'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Matrona_of_Perge", "biography": "rewritten"}'::jsonb),
