UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Adomnán, or Adamnán, of Iona, who is also called Eunan, served as the abbot at Iona Abbey (r. 679–704) and was a saint, canon jurist, statesman and hagiographer. He wrote the Life of Columba, probably between 697 and 700. The work is far and away the most important surviving text from early-medieval Scotland. It is a vital source for knowledge of the Picts, and gives a glimpse of life on Iona and of the early-medieval Gaelic monk.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Adomn%C3%A1n", "biography": "rewritten"}'::jsonb),
