UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The Croatian Catholic priest Miroslav Bulešić studied in Rome, then was called back to Istria, his homeland, where during World War II, in 1943, he was ordained. He then held two parish postings, in which he spoke out vocally against communism. Through well-organized pastoral activities he revitalized his parishes, and he encouraged frequent reception of the sacraments. His criticism of communism made enemies, though, and they soon killed him.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Miroslav_Bule%C5%A1i%C4%87", "biography": "rewritten"}'::jsonb),
