UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A catacomb saint, Donatus of Muenstereifel has his relics in the Jesuit church of Bad Muenstereifel. Many people in Germany''s Rhine valley and in the Low Countries venerate him. He is patron of Buda and is invoked for protection against lightning. In the 17th century, relics of him were moved to Muenster Eifel from his original burial place, the Catacombs of Rome.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Donatus_of_Muenstereifel", "biography": "rewritten"}'::jsonb),
