UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Mercurius, a Roman soldier of Scythian descent, became a Christian saint and martyr. His birthplace was Eskentos, a city in Cappadocia, in eastern Asia Minor. Christian tradition holds that he was the soldier who slew Julian the Apostate during the Persian campaign. Egyptian Arabic speakers also knew him widely as Abu-Sayfain, Abu-Sifin or Abu-Sefein, which means "wielder of two swords" and alludes to a second sword that the Archangel Michael gave him.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Mercurius", "biography": "rewritten"}'::jsonb),
