UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Hermes was born in Greece and died as a martyr in Rome in 120. Both the Catholic Church and the Eastern Orthodox Church venerate him as a saint. He appears in the Martyrologium Hieronymianum and in the Depositio Martyrum (354). Around 600 Pope Pelagius I built a large basilica above his tomb, which Pope Adrian I later restored. The Catacomb of Sant''Ermete on the Salarian Way takes its name from him.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Hermes", "biography": "rewritten"}'::jsonb),
