UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Marcellinus of Carthage, a saint, was a Christian martyr who died in 413. Honorius, the Roman emperor, employed him as Western Roman Empire secretary of state. He corresponded with Saint Jerome and was a close friend to Augustine of Hippo, who in 413 dedicated to him the first books of The City of God, his landmark work.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Marcellinus_of_Carthage", "biography": "rewritten"}'::jsonb),
