UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Both the Greek Orthodox Church and the Roman Catholic Church honor Epenetus, or Epaenetus, as a saint. He is regarded as one of the seventy disciples, and he may also have served as the earliest Bishop of Carthage or Cartagena. In chapter 16 of the Letter to the Romans, Paul calls Epenetus "my beloved" and honors him with great distinction as the earliest person in the Province of Asia to convert.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Epenetus_of_Carthage", "biography": "rewritten"}'::jsonb),
