UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Abraham of Cratia (also spelled Krateia), a Christian monk, came from Emesa in Byzantine Syria. Of all the bishops of the see of Kratia, which lasted from its founding in the 2nd century until it was dissolved in the 12th century, Abraham was the most important.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Abraham_of_Cratia", "biography": "rewritten"}'::jsonb),
