UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Asella, who is also called Osella and Ocella, was a hermit and a virgin of Rome. Saint Jerome, who wrote about her, counted her as a disciple and friend. She came from a noble, wealthy Roman Christian family, and was perhaps the sister of Marcella, who was likewise an ascetic and a saint.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Asella", "biography": "rewritten"}'::jsonb),
