UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Andrew Bobola, SJ, a missionary and martyr from Poland, belonged to the Society of Jesus. He was called the "Apostle of Lithuania" and also the "hunter of souls". During the Khmelnytsky Uprising he was beaten and tortured until he died. Pope Pius XI canonized him in 1938.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Andrew_Bobola", "biography": "rewritten"}'::jsonb),
