UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Louis Martin and his wife Azélie-Marie "Zélie" Guérin Martin, a French Catholic couple, raised five daughters who became nuns. One was Thérèse of Lisieux, a Carmelite whom the Catholic Church canonized in 1925; another was her older sister Léonie Martin, a Visitation Sister named a Servant of God in 2015. The same year saw Louis and Zélie become the first couple ever canonized together.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Louis_Martin_and_Marie-Az%C3%A9lie_Gu%C3%A9rin", "biography": "rewritten"}'::jsonb),
