UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Rafael Guízar y Valencia, a Mexican bishop, belonged to the Roman Catholic Church and suffered persecution during the Mexican Revolution. He was appointed Bishop of Xalapa in 1919, but was expelled from his diocese and spent the rest of his life hiding in Mexico City. On 15 October 2006 Pope Benedict XVI canonized him.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Rafael_Gu%C3%ADzar_y_Valencia", "biography": "rewritten"}'::jsonb),
