UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Jesús María Echavarría Aguirre was a Mexican Roman Catholic prelate. He became founder of the Guadalupan Catechists Sisters, and was Saltillo''s bishop, serving from 1904 until he died. Devoted ardently to the Mother of God, he paid close attention to local parishes; his pastoral work centered on bettering parish conditions and easing the hardship of the poor in his diocese.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Jes%C3%BAs_Mar%C3%ADa_Echavarr%C3%ADa_Aguirre", "biography": "rewritten"}'::jsonb),
