UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Among the Forty Martyrs honored by the Catholic Church, a group from England and Wales, was Edmund Arrowsmith, SJ. The main source of information about him is an account by a contemporary eyewitness, published shortly after he died. It follows the old style of "Acts of martyrs" writing and also tells how Richard Herst, another recusant martyr of the 17th century, was executed.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Edmund_Arrowsmith", "biography": "rewritten"}'::jsonb),
