UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Francinaina Cirer Carbonell was a Spanish Roman Catholic who belonged to the Saint Vincent de Paul Sisters of Charity of Mallorca. She afterwards took the religious name Francinaina, adding the title of the Sorrowful Mother of God. Though she could not read or write, she nonetheless founded the Community of Sisters of Charity. She reportedly had angelic visions on many occasions. Beatified on 1 October 1989, she has a second attributed miracle that is now under investigation.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Francinaina_Cirer_Carbonell", "biography": "rewritten"}'::jsonb),
