UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Erminold was a Benedictine abbot. As a small child he was entrusted to Hirschau Monastery, in Würzburg, Germany. He became abbot of Lorsch in 1110, but when his election was contested he resigned and went back to Hirschau. In 1117 he was made abbot of Prüfening, where a lay brother attacked him and killed him on 7 January 1121. The assailant used a piece of timber, and the Abbot''s excessive strictness was the motive.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Erminold", "biography": "rewritten"}'::jsonb),
