UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'An Italian Catholic priest, Joseph Cafasso was an important social reformer in Turin. He counts among the so-called "Social Saints" who arose in that era. Because of his extensive work with prisoners condemned to death, he is called the "Priest of the Gallows". He was also known for severe mortifications even though his constitution was frail. Unless a doctor directed otherwise, he went without certain foods and comforts so as to live as frugally and simply as possible.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Joseph_Cafasso", "biography": "rewritten"}'::jsonb),
