UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Szymon of Lipnica, a Polish catholic priest, was a professed member of the Order of Friars Minor. He grew into a noted preacher in great demand, drawing his inspiration for preaching from Saint Bernardine of Siena, and he firmly supported popular devotions, which he labored to spread.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Szymon_of_Lipnica", "biography": "rewritten"}'::jsonb),
