UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'An Italian Roman Catholic priest, Albert of Trapani belonged to the Carmelites as a professed member. He subjected himself to severe austerities in order to become poor, following the spirit of Jesus Christ, and he went out to preach and evangelize. He was known for his healing powers and for keeping up good relations with Jews. The saint was likewise credited with ending, in 1301, the siege of Messina, in which hundreds could have died of starvation without his intervention.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Albert_of_Trapani", "biography": "rewritten"}'::jsonb),
