UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Paul of Narbonne was among the "apostles to the Gauls", who were dispatched when Decius and Gratus were consuls. Their task was to bring Christianity to Gaul, since the small Christian communities had been almost wiped out by the persecutions under Emperor Decius. Hagiographies say that, to preach the Gospel in Gaul, seven bishops were sent from Rome by Fabian: Martial went to Limoges, Austromoine to Clermont, Denis to Paris, Saturnin to Toulouse, Trophimus to Arles, Gatien to Tours, and Paul to Narbonne.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Paul_of_Narbonne", "biography": "rewritten"}'::jsonb),
