UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Paphnutius of Thebes, called too Paphnutius the Confessor, was an early Christian figure whose historical existence is doubtful. He is said to have followed Anthony the Great as a disciple, and to have served during the early fourth century as bishop of a city in Upper Thebaid. Some regard him as an important participant at the First Council of Nicaea, held in 325. The name of his see is unknown, and so is the exact date of his death.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Paphnutius_of_Thebes", "biography": "rewritten"}'::jsonb),
