UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Born Vincenzo Peis in Sardinia, Ignazio da Laconi was a Catholic professed religious who belonged to the Order of Friars Minor Capuchin. After he recovered from a serious illness, he resolved to dedicate his life to God and joined the religious life, without being ordained a priest. In Sardinia Peis was widely known for his humble manner and his care for the poor. He mixed with everyone he met and was kind to the sick. He also gained a reputation as a wonder worker, and 121 miracles were claimed for him during his lifetime.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Ignatius_of_Laconi", "biography": "rewritten"}'::jsonb),
