UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Julián of Cuenca, also called Saint Julián, was a Spanish Roman Catholic prelate. He was Bishop of Cuenca from 1196 until he died, and he also worked as a professor and preacher while remaining a simple hermit. He was made bishop once the Moors had been driven out of Cuenca. He visited the people of his diocese on pastoral rounds, feeding prisoners and supplying grain to poor farmers. Yet his longing for solitude never left him, and each year he traveled to the place where he could find the deepest silence, then returned to his episcopal duties.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Julian_of_Cuenca", "biography": "rewritten"}'::jsonb),
