UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Judoc, also called Jodoc, Joyce or Josse, was a Breton nobleman of the seventh century who is regarded as a saint. He was the son of Juthael, King of Brittany. Giving up his wealth and rank, he became a priest and spent the rest of his life alone in the forest by the coast, close to where the River Canche meets the sea.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Judoc", "biography": "rewritten"}'::jsonb),
