UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Parmenas was among the Seven Deacons chosen for service in the early Christian church, as the Acts of the Apostles records; his name is sixth on that list of seven. Tradition holds that he preached the gospel in Asia Minor, and he was martyred in 98 during the persecution under Trajan.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Parmenas", "biography": "rewritten"}'::jsonb),
