UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Calabria venerates Saint Nicodemus of Mammola as a saint. Where exactly he was born is not known, though he has been identified as coming from Ypsicron. His parents, Theophanus and Pandia, put a priest named Galato (Galatone) in charge of their son''s spiritual formation. From an early age Nicodemus felt drawn to monastic life and hoped to join the ascetics who had settled in the area called the Mercurion, set on the Pollino cliffs of Calabria.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Nicodemus_of_Mammola", "biography": "rewritten"}'::jsonb),
