UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Romanus of Condat was a fifth-century saint. When he was thirty five, he chose the life of a hermit in the Condat region. His younger brother Lupicinus came to join him, and together they headed a community of monks, among whom was Eugendus.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Romanus_of_Condat", "biography": "rewritten"}'::jsonb),
