UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Restituta, a Berber, is honoured as a saint and martyr by the Roman Catholic and Eastern Orthodox Churches. Reportedly she was born in Carthage or Teniza, and was martyred during the reign of Roman Emperor Diocletian, though exactly where and when she was martyred is not known. Sometimes she is counted among the Martyrs of Abitinae, Roman Province of Africa. This group of North Africans, who were martyred in AD 304, included Dativus and Saturninus, among others.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Restituta", "biography": "rewritten"}'::jsonb),
