UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Giuseppina Suriano was an Italian Roman Catholic and a member of the Catholic Action. She was born near Palermo to simple farmers. During her life she became a prominent and essential figure in Catholic Action, and for a short time she also worked with the Young Catholic Action movement.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Giuseppina_Suriano", "biography": "rewritten"}'::jsonb),
