UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Giulia Crostarosa, an Italian Roman Catholic nun, founded the Redemptoristines, officially named for the Most Holy Redeemer, a community of contemplative nuns. She founded it as the culmination of mystical visions, and out of devotion to the way of life those visions showed her. On becoming a professed nun she took the religious name "Maria Celeste". She also helped persuade Alphonsus Liguori to found the Redemptorists, formally the Most Holy Redeemer Congregation, whose members are missionary priests and brothers.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Giulia_Crostarosa", "biography": "rewritten"}'::jsonb),
