UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Blessed Carino Pietro of Balsamo, who is sometimes called Saint Acerinus, murdered Saint Peter of Verona, but afterwards repented and became a Dominican lay brother. The Catholic Church venerates him as a beatus.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Carino_of_Balsamo", "biography": "rewritten"}'::jsonb),
