UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A Roman Catholic priest, Alfonso Maria Fusco was the founder of a congregation of sisters named for Saint John the Baptist, also called the Baptistine Sisters. The sisters were to evangelize, educate and foster the faith among adolescents, giving special attention to the poor and abandoned.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Alfonso_Maria_Fusco", "biography": "rewritten"}'::jsonb),
