UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Alexandru Rusu was a Romanian bishop in the Greek-Catholic Church. Born in Șăulia Commune, Mureș County, as one of a priest''s twelve children, he was ordained a priest in 1910. In 1931 he was ordained Bishop of Maramureş.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Alexandru_Rusu", "biography": "rewritten"}'::jsonb),
