UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Hildegund was a Praemonstratensian abbess of noble birth, the daughter of Count Herman of Lidtberg and Countess Hedwig. She married Count Lothair of Meer, in the present-day region of North Rhine-Westphalia, Germany. The couple had three children, and one of them died before reaching adulthood.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Hildegund_(widow)", "biography": "rewritten"}'::jsonb),
