SET "payload" = content."payload" || jsonb_build_object('biography', 'Philip Evans, SJ, and John Lloyd were Welsh Catholic priests who were killed after the alleged Popish Plot. Both belong to the Forty Martyrs, the group from England and Wales.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Philip_Evans_and_John_Lloyd", "biography": "rewritten"}'::jsonb),
