UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Maria Bolognesi was an Italian Catholic. Debilitating diseases afflicted her throughout life, and by report she underwent various demonic possessions and visions. She had many visions of Jesus Christ; through him, she saw Heaven, and she herself received the stigmata.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Maria_Bolognesi", "biography": "rewritten"}'::jsonb),
