UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'From 8 June 536 until his deposition in 537, only some months before he died, Pope Silverius was bishop of Rome. He climbed fast from deacon to pope, which matched the aims of the Ostrogothic king Theodahad, who wished to place a pro-Gothic candidate on the throne just ahead of the Gothic War. The Byzantine general Belisarius later deposed him; he was tried and exiled to Palmarola, a desolate island, and there he starved to death in 537.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Silverius", "biography": "rewritten"}'::jsonb),
