  AND content."slug" = 'saint-silverius'
  AND md5(content."payload"->>'biography') = '2c382b357b37741a08a2dadd9aa31805';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Gerard, a German prelate, held the see of Toul as its Bishop from 963 until he died. A lightning bolt killed his mother, and he took this as God''s judgment on his sins and as a summons to serve the Church, which led him into the priesthood. He was already known for his piety, and although he was reluctant, he agreed to take the Toul diocese. As bishop he worked to recover all the properties under the Church''s care and to put an end to lay interference in Church affairs.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Gerard_of_Toul", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmq9x5u5u3of12fi79zulblz8'
