  AND md5(content."payload"->>'biography') = '84ec6549b0025de0a97a70a779383ab0';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Maddalena Panattieri, OP was an Italian Sister of Penance of Saint Dominic. She bore the stigmata and had visions during her life, one of them concerning the invasion of the Italian peninsula by the French. She taught catechism to children and was known for her plain way of life.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Maddalena_Panattieri", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
