  AND md5(content."payload"->>'biography') = '564bc1786e4f260285cf8327c2ccd814';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Germanicus was a youth arrested in Smyrna and martyred for his faith under the Roman Emperor Antoninus. When he was standing in the arena in front of a wild beast, the Roman proconsul begged him to deny his faith and be pardoned because he was so young. Germanicus would not apostatize; he accepted martyrdom of his own free will. He was praised for his courage in facing the beasts that killed him.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Germanicus_of_Smyrna", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmq9x5vk53of72fi7wcoyyap4'
  AND content."slug" = 'saint-germanicus-of-smyrna'
