UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'As a Christian martyr and saint, Saint Getulius receives veneration alongside Amantius (Amancius), Cerealus (Caerealis), and Primitivus. Gabii is held to be the place where they died. Tradition makes Getulius the husband of Saint Symphorosa. His name means "of the Gaetuli", a North African tribe.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Getulius", "biography": "rewritten"}'::jsonb),
