UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Giuseppe Toniolo, an Italian Catholic, worked as an economist and sociologist and was a pioneer of Christian democracy. He was a prominent political and social economist who rejected both socialism and laissez-faire capitalism. In their place he argued for an economy where social, judicial and economic forces work together in due proportion for the common good. He was among the first Catholics to champion labour unions and social reform, and his writing drew on Catholic social teaching; he described the economy as "integral" to "the operative design of God". Pope Benedict XVI beatified him in Rome on 29 April 2012.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Giuseppe_Toniolo", "biography": "rewritten"}'::jsonb),
