  AND md5(content."payload"->>'biography') = 'af417fedf329f7f468e557dbf78d2180';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Solange was a Frankish shepherdess, a Christian saint venerated only locally, and a cephalophore; devotion to her is confined to Sainte-Solange in Cher. She was patron saint of the traditional Province of Berry, which includes Cher.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Solange_of_Bourges", "biography": "rewritten"}'::jsonb),
