UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Mildrith (also Mildthryth, Mildryth and Mildred) was an Anglo-Saxon abbess who lived in the 7th and 8th centuries and led the abbey of Minster-in-Thanet in Kent. After her death she was recognized as a saint, and her remains were taken to Canterbury in 1030.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Mildrith", "biography": "rewritten"}'::jsonb),
