UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Goswin was a Benedictine abbot. He was born in 1086 in Douai, which then lay in the County of Flanders and has been French since 1668. After studying in Paris he came home to Douai and taught theology. In 1113 he joined Anchin Abbey at Pecquencourt, close to his native town, and became a Benedictine monk there. He was appointed abbot of Anchin Abbey in 1130.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Goswin_of_Anchin", "biography": "rewritten"}'::jsonb),
