UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'In Markowa, Poland, the Polish Catholic Ulma family, Józef and Wiktoria Ulma with Seven Children, lived under the Nazi German occupation in World War II. They tried to rescue Polish Jewish families during the Holocaust by concealing them inside their own house. Because of this, the parents were summarily executed together with their children on 24 March 1944.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Ulma_family", "biography": "rewritten"}'::jsonb),
