UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Grzegorz (Gregory) Bolesław Frąckowiak was a martyr of the Society of the Divine Word (SVD). On 13 June 1999 Pope John Paul II beatified him among the 108 Polish Martyrs of World War II.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Grzegorz_Boles%C5%82aw_Fr%C4%85ckowiak", "biography": "rewritten"}'::jsonb),
