UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Opportuna of Montreuil was a Benedictine nun and abbess of the Franks. Within a century after she died, Adalhelm, bishop of Séez, composed a Vita et miracula Sanctae Opportunae; he believed that he owed both his life and his see to her.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Opportuna_of_Montreuil", "biography": "rewritten"}'::jsonb),
