SET "payload" = content."payload" || jsonb_build_object('biography', 'Aquilina (281–293), a child from Byblos, was a Christian who was martyred in the third century during the reign of Emperor Diocletian.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Aquilina", "biography": "rewritten"}'::jsonb),
