UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Matronian(us), called San Matroniano in Italian, lived as a hermit in Milan. According to the record, Ambrose placed Matronian''s relics in a shrine within Milan''s church of San Nazaro Maggiore.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Matronian", "biography": "rewritten"}'::jsonb),
