UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A West Frankish prelate, Odo I was abbot of Corbie during the 850s, and from about 860 until he died in 881 he was bishop of Beauvais. As a courtier and diplomat, he undertook missions to East Francia and to the Holy See.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Odo_I_of_Beauvais", "biography": "rewritten"}'::jsonb),
