UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Richard served as Bishop of Andria in Italy, a see to which Pope Adrian IV, likewise English, had appointed him. In 1179 he took part in the Eleventh Ecumenical Council, which Pope Alexander III convened, as one of the bishops present. His time as bishop lasted until his death and ran to well over 40 years.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Richard_of_Andria", "biography": "rewritten"}'::jsonb),
