  AND md5(content."payload"->>'biography') = 'eebf32b34e58073133d602f462f36ea8';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Zdislava Berka, TOSD, was a Czech philanthropist and Dominican tertiary. She was a wife and mother, and among the first lay Dominicans. Canonized in 1995, she is honored as a saint.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Zdislava_Berka", "biography": "rewritten"}'::jsonb),
