  AND md5(content."payload"->>'biography') = '90c6735773c57af5b7e1307ebab4ab2e';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pope Caius, or Gaius, was Rome''s bishop from 17 December 283 until he died in 296. The Liber Pontificalis supplies nearly all the available information about him, and it draws on a legendary story about the martyrdom of Susanna of Rome. Legend says Caius baptized those men and women whom Tiburtius and Castulus had converted. The legend further says he hid in Rome''s catacombs and died a martyr.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Caius", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmq9x6ufs3p1c2fi7xknmkdzv'
  AND content."slug" = 'saint-caius'
