UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Orentius, Cyriacus, Firminus, Firmus, Heros, Longinus and Pharnacius are known as the Seven Brothers of Lazia, all of them martyrs. Soldiers in the Roman Army, they supposedly enlisted in Diocletian''s army at Antioch and later served in Thrace. Because of their Christian faith they were condemned, and they were martyred in the persecutions carried out by co-Emperor Maximian.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Seven_Brothers_of_Lazia", "biography": "rewritten"}'::jsonb),
