UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Wilgefortis, a female folk saint, is known above all for her large beard, and her legend arose in the 14th century. Her life story takes place in Portugal and Galicia, where she was a teenage noblewoman whose father had pledged her in marriage to a Moorish king. She had vowed virginity to block the wedding she did not want, and she prayed to be made repulsive. Her prayers were answered when she sprouted a beard, and the engagement ended. Wilgefortis'' father, in anger, had her crucified.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Wilgefortis", "biography": "rewritten"}'::jsonb),
