UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Juan de Ribera held great influence under Philip III of Spain. He pressed for severe measures against the so-called New Christians, which led to the Moriscos being expelled in 1609. His offices included Chancellor of the University of Valencia, president of the Audiencia, Commander in Chief, Latin Patriarchate of Antioch, Viceroy of Valencia, and Archbishop of Valencia. Pope John XXIII canonized him in 1960, after he had been beatified in 1796.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Juan_de_Ribera", "biography": "rewritten"}'::jsonb),
