UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Jan Franciszek Macha, a Polish Roman Catholic priest, was first turned down for ecclesial studies and spent some months studying law before a seminary accepted him. His ordination came only months before World War II began. On 1 September 1939, the day Nazi forces invaded Poland and started the war, he was sent to a parish church as vicar. Macha supported student and scout activities and worked to give material help to families whose sons and husbands had been lost to the war. Arrested in 1942, he was moved from one prison to another and finally executed by guillotine.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Jan_Franciszek_Macha", "biography": "rewritten"}'::jsonb),
