  AND md5(content."payload"->>'biography') = '610a80c3b763ff144e63037b4f5af218';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Cristobal (1514/15–1527), Antonio (1516/17–1529) as well as Juan (1516/17–1529) were three Mexican Roman Catholic teenagers of the Tlaxcaltec people, from the modern Mexican state of Tlaxcala; together they are the Martyrs of Tlaxcala. The three had given up the Nahua religion of their families and become Catholics in Mexico; missionaries from the Order of Friars Minor, who were evangelizing the area, baptized them and educated them. Because of their activism and evangelical zeal they were killed in honour killings carried out by fellow Tlaxcaltec people, among them their close relatives, who despised their new faith and regarded them as threats to their values and rituals.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Child_Martyrs_of_Tlaxcala", "biography": "rewritten"}'::jsonb),
