UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Inocencio of Mary Immaculate, CP, a Catholic priest and Passionist, was born Manuel Canoura Arnau and was killed in the Asturias revolt. Together with his companions he is known as the Martyrs of Turon. Pope John Paul II canonised him in 1999.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Inocencio_of_Mary_Immaculate", "biography": "rewritten"}'::jsonb),
