UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pope Eugene III, born Bernardo and known as Bernardo da Pisa, led the Catholic Church and ruled over the Papal States between 15 February 1145 and his death in 1153, and no Cistercian had held the papacy before him. When Edessa fell to the Muslims in 1144, he called for the Second Crusade. Pope Pius IX beatified him in 1872.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Eugene_III", "biography": "rewritten"}'::jsonb),
