UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Khalil al-Haddad, known as Jacques Ghazir Haddad, OFM Cap., was a Capuchin friar and Catholic priest from Lebanon. He founded the Franciscan Sisters of the Cross, was a noted preacher, and was also the founder of several orphanages and schools in Lebanon. Lebanon''s presidents gave him a number of honors, and ordinary people compared him with Vincent de Paul and John Bosco.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Jacques_Ghazir_Haddad", "biography": "rewritten"}'::jsonb),
