UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A French Roman Catholic anchoress, Jeanne-Marie de Maille belonged to the Third Order of Saint Francis. Her parents were nobles, and she married a nobleman, but the two had no children, since she resolved, with her husband''s permission, to remain chaste. Husband and wife lived together until he died during a conflict. After that, she took up life as an anchoress in a church, where her humility and holiness were notable. On 27 April 1871 her beatification was confirmed by Pope Pius IX.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Jeanne-Marie_de_Maille", "biography": "rewritten"}'::jsonb),
