  AND md5(content."payload"->>'biography') = '787ed8f9ffe53252edbdeb35d53a12f7';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Fintán, or Munnu, is counted among the saints of Ireland and Britain, having served in Ireland and Scotland. As founder and abbot he led the abbey at Teach-Mhunn; his bed can be visited there, and the place is a pilgrimage site. Today Taghmon lies in Leinster, the Irish province, within the County Wexford. Scotland honors him as patron saint of the Clan Campbell.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Fint%C3%A1n_of_Taghmon", "biography": "rewritten"}'::jsonb),
