UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'John of Beverley was a bishop from England, serving the kingdom of Northumbria. He held the see of Hexham, then the see of York, the foremost religious post of that region. Beverley owes its founding to him, since he built a monastery there as the first structure. Miracles were attributed to John in his lifetime and afterwards. In 1037 the Catholic Church canonised him a saint, and because this preceded the 1054 split between East and West known as the Great Schism, the Eastern Orthodox Church recognises him as a saint too.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/John_of_Beverley", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
