WHERE content."id" = 'cmq9x8bqs3pwp2fi77sinrvkj'
  AND content."slug" = 'saint-john-of-beverley'
  AND md5(content."payload"->>'biography') = '43678de6f1d6b9c89dafeb6b9977b6af';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Joseph Vaz CO, an Oratorian priest, was a missionary in Dutch Ceylon. A native of Sancoale in Portuguese Goa, he came to Ceylon during the Dutch occupation. The Dutch had taken control from the Portuguese Empire, forbidden Catholicism there, and made Calvinism the official religion.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Joseph_Vaz", "biography": "rewritten"}'::jsonb),
