  AND md5(content."payload"->>'biography') = '5aa05939bca5baff95bcd0a90bb2b584';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Between 21 January and 22 June 1276, Peter of Tarentaise (Pierre de Tarentaise) headed the Catholic Church and ruled the Papal States as Pope Innocent V. He belonged to the Order of Preachers and gained renown as an effective preacher. At the University of Paris he had one of its two "Dominican Chairs", and he played an instrumental role in preparing the Order''s "program of studies". In 1269 he was Provincial for the Dominicans'' French Province. He worked closely with Pope Gregory X, who appointed him Bishop of Ostia, and made him a cardinal in 1273.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Innocent_V", "biography": "rewritten"}'::jsonb),
