WHERE content."id" = 'cmq9x8mer3qan2fi7w4llgqn0'
  AND content."slug" = 'saint-innocent-v'
  AND md5(content."payload"->>'biography') = 'aeda16b586aca59536b79c9215cec82c';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Julian was a martyr from Sora in Lazio, Italy, though Dalmatia was his birthplace. Under Emperor Antoninus Pius, while he was en route to Campania, Roman soldiers tortured him and afterwards beheaded him at Sora. His commemoration falls on 27 January in the Roman Catholic Church and on 28 July or 11 August in the Eastern Orthodox Church. 27 January is his feast day.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Julian_of_Sora", "biography": "rewritten"}'::jsonb),
