  AND md5(content."payload"->>'biography') = 'e27f04401d4f037c26a411f633140d01';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Justus of Beauvais is a saint of the Roman Catholic Church whose story is partly legendary. Possibly a martyr of Gallo-Roman times, he had his legend tangled with the stories of other saints, Justin of Paris among them.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Justus_of_Beauvais", "biography": "rewritten"}'::jsonb),
