UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Victorinus of Camerino and his brother Severinus of Sanseverino both lived in the 6th century, each serving as a bishop and as a hermit. Both are saints.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Severinus_of_Sanseverino_and_Victorinus_of_Camerino", "biography": "rewritten"}'::jsonb),
