UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Neilos of Rossano, also known as Nilus the Younger, was a monk and abbot of the Griko people from Calabria in Italy. He established Italo-Byzantine monasticism in southern Italy as its founder. Both the Eastern Orthodox and Catholic churches venerate him as a saint, and the Roman Martyrology and the Byzantine calendar alike give his feast day as September 26.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Nilus_the_Younger", "biography": "rewritten"}'::jsonb),
