UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pope Adrian III, also called Hadrian III, was bishop of Rome and ruler of the Papal States. His pontificate began on 17 May 884 and ended with his death on 8 July 885. It lasted little more than a year, and he spent it helping the people of Italy through a difficult era of famine and war.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Adrian_III", "biography": "rewritten"}'::jsonb),
