UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Italian Catholic Amato Ronconi made profession as a member of the Secular Franciscan Order. He lived penitentially and devoted all his work to the poor by building chapels and hospitals, one of which still exists in his hometown of Rimini. The townspeople recognised his good deeds and acclaimed him a saint while he was still alive.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Amato_Ronconi", "biography": "rewritten"}'::jsonb),
