UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Proclus of Constantinople held the post of Archbishop of Constantinople from 434 until he died. He was renowned for his preaching skill and played a leading part during the Nestorian controversy. Through his contributions to Marian theology, in a time when devotion to the Virgin Mary was growing, he counts among the earliest and foremost Marian theologians. Catholic, Eastern Catholic, Eastern Orthodox and Oriental Orthodox Churches all venerate him as a saint.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Proclus_of_Constantinople", "biography": "rewritten"}'::jsonb),
