  AND md5(content."payload"->>'biography') = 'eaf1a2d7b61c42a1e78df5aac977f1b1';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'From 15 December 687 until his death on 8 September 701, Sergius I was pope, holding the office of bishop of Rome, and the Roman Catholic Church reveres him as a saint. He was elected while two rivals, Paschal and Theodore, were disputing which of them should be pope, and the Quinisext Council and his reaction to it filled most of his papacy, since he steadfastly refused to accept its canons. In response Emperor Justinian II ordered his arrest, yet the people of Rome, along with the Italian militia serving the exarch of Ravenna, would not permit the exarch to take Sergius to Constantinople.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Sergius_I", "biography": "rewritten"}'::jsonb),
