WHERE content."id" = 'cmq9x8r7e3qbb2fi720vd9xci'
  AND content."slug" = 'saint-sergius-i'
  AND md5(content."payload"->>'biography') = '7cb03382ac8c8a678184519d2de26bd3';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Carmen Elena Rendiles Martínez, SJC, who took the name María Carmen in religion and is also known by the name Maria del Monte Carmelo Rendiles, was a Venezuelan religious sister of the Catholic Church. She was the founder of a congregation, the Servants of Jesus of Caracas. She completed her novitiate in France, where she held a leadership role among the Servants of the Eucharist, and then went back to Venezuela and founded her congregation in 1965, serving as its first superior general. She was canonized on October 19, 2025. In January 2026, after the US raid on Venezuela, Pope Leo XIV asked for her intercession.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Carmen_Elena_Rendiles_Mart%C3%ADnez", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmq9x8rcx3qbe2fi7sdrsm3q4'
  AND content."slug" = 'saint-carmen-rendiles'
  AND md5(content."payload"->>'biography') = 'b6e8af6386fa2ef15bb58c6d4dbad94e';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Born Giancarlo Marchioni, Charles of Sezze was an Italian professed religious of the Order of Friars Minor. His parents wanted him to be a priest, but he became a religious against their wishes. He lived austerely, doing humble work as porter and gardener, and he was also a well-known writer. Throughout the Lazio region he was greatly respected: noble families such as the Colonna and Orsini praised him and asked for his counsel, as did popes including Innocent X and Clement IX.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Charles_of_Sezze", "biography": "rewritten"}'::jsonb),
