UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Killed in the Cristero War, David Roldán Lara was a layman from Mexico. He was an activist for the Catholic cause in the anticlerical period when Plutarco Elías Calles was President; government forces seized him, and he was put to death for refusing to give up his position. Pope John Paul II canonized Roldán on 21 May 2000, counting him among the 25 Martyrs of the Cristero War.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/David_Rold%C3%A1n_Lara", "biography": "rewritten"}'::jsonb),
