  AND md5(content."payload"->>'biography') = '613748959b2be3ab2b3c295b588b3f2e';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Maximilian of Tebessa (Theveste), or Maximilian of Numidia, is a Christian saint and martyr commemorated on 12 March. His father Fabius Victor was an official with ties to the Roman army, and Maximilian, born in AD 274, was obliged at 21 to enlist. He is regarded as the first recorded conscientious objector, though other Christians of that time are believed likewise to have refused military service and been executed.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Maximilian_of_Tebessa", "biography": "rewritten"}'::jsonb),
