  AND content."slug" = 'saint-maximilian-of-tebessa'
  AND md5(content."payload"->>'biography') = 'deef87ba3a08f9592ea4a380da7dc1a1';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'David the Dendrite is a saint of Thessaloniki. He is also called David of Thessalonika and David the tree-dweller. As a monk he joined a monastery outside Thessaloniki that honored Saints Merkourios and Theodore. Because he was renowned for sound advice, crowds kept pursuing him for words of wisdom and prayer. Wanting a quiet, contemplative life, he withdrew to an almond tree and lived there for three years.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/David_the_Dendrite", "biography": "rewritten"}'::jsonb),
