UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Tysul lived in the 5th century, before formal canonization. He is patron saint of the churches at Llandysul, in Ceredigion (Cardiganshire), and at Llandyssil, in Maldwyn (Montgomeryshire), Powys. His complete name, Tysul ap Corun ap Cunedda, means son of Corun, who was son of Cunedda. His feast day falls on 31 January.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Tysul", "biography": "rewritten"}'::jsonb),
