UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Nazarius and Celsus were two martyrs about whom almost nothing is known apart from Ambrose of Milan''s discovery of their bodies.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Nazarius_and_Celsus", "biography": "rewritten"}'::jsonb),
