UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'An Italian Franciscan missionary, Thomas of Tolentino, OFM, was martyred in Thane, India, along with his three companions, for blaspheming Muhammad. Odoric of Pordenone carried his relics to Quanzhou, China, and to Tolentino, Italy. He is venerated as a saint, and his feast day is 9 April.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Thomas_of_Tolentino", "biography": "rewritten"}'::jsonb),
