  AND md5(content."payload"->>'biography') = 'f314988aa05f70d3bb269383dd809c85';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Raymond William was born in Durban, France. He joined the Canons Regular, and in 1104 he became Bishop of Barbastro in Spain. He held that post until he died of natural causes in 1126. He consecrated Sant Climent de Taull''s church on 10 December 1123, and the church of Santa Maria de Taüll the next day.
Innocent II canonised him in 1136.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Raymond_of_Barbastro", "biography": "rewritten"}'::jsonb),
