  AND md5(content."payload"->>'biography') = '401b05fa8b9c0b50e199915b9f92cef5';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Elisabetta Canori Mora, an Italian, belonged to the Third Order of the Most Holy Trinity. Her husband was a harsh man who stayed unfaithful and abusive toward her, yet at her death she obtained his repentance, and later he was ordained a priest. During her life Mora had many spiritual experiences: she heard God''s voice, saw the Madonna and other saints in visions, and went into religious ecstasies.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Elisabeth_Canori_Mora", "biography": "rewritten"}'::jsonb),
