UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Maurus of Parentium is patron saint of Poreč/Parenzo, a city in Istria, Croatia, which the Romans called Parentium. His commemoration is on November 21.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Maurus_of_Parentium", "biography": "rewritten"}'::jsonb),
