UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Maria Vittoria De Fornari Strata was an Italian Roman Catholic nun, the foundress of the Blue Nuns, formally the Order of the Annunciation. Her marriage lasted just under a decade, and she decided against finding another spouse after a vision of the Madonna told her she should live a chaste life of motherhood. Soon afterward, as a widow, she resolved to found an order based on the Carmelite charism.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Maria_Vittoria_De_Fornari_Strata", "biography": "rewritten"}'::jsonb),
