  AND md5(content."payload"->>'biography') = '0b2c9900aa756bfaeeb261b84fead83a';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Meinrad, OSB, a German Benedictine hermit, is revered as a saint by Catholics and the Orthodox alike. People call him the "Martyr of Hospitality", and his feast day falls on 21 January.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Meinrad_of_Einsiedeln", "biography": "rewritten"}'::jsonb),
