UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Thecla of Kitzingen was an Anglo-Saxon nun and abbess of the Benedictines, and a missionary. She was one of a number of people linked to Saint Boniface and to the Anglo-Saxon mission.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Thecla_of_Kitzingen", "biography": "rewritten"}'::jsonb),
