UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Noyale, also called Noaluen, is a semi-legendary Celtic saint and virgin martyr of the 5th century. Both Brittany and Cornwall hold her in popular devotion, and in Cornwall she is remembered at Newlyn East. Legend there says that the fig tree growing out of the church''s south wall sprang from her staff, and that she was martyred at a holy well close by. She was among the many Celtic settlers who crossed to Brittany while the Anglo-Saxons were invading England.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Noyale", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmq9x9lri3qm92fi78xxzurvj'
