  AND md5(content."payload"->>'biography') = '429ce497523f8a895125a02c375e76f2';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pega, a Christian saint and the sister of St Guthlac, lived as an anchoress in Mercia, an ancient Anglo-Saxon kingdom.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pega", "biography": "rewritten"}'::jsonb),
