UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Elpidius the Cappadocian, a saint and abbot, lived in Asia Minor. By tradition he spent twenty-five years in a cave in Cappadocia, and disciples such as Eustace (Eustachio) and Ennesius (Ennesio) assembled around him.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Elpidius_the_Cappadocian", "biography": "rewritten"}'::jsonb),
