  AND md5(content."payload"->>'biography') = '277e46fa818f7e461da99378eddc1bf7';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Bartolomeo Fanti, an Italian Roman Catholic priest, belonged to the Carmelite order in Mantua. In his hometown he was the spiritual director and the rector of a religious movement, and he supervised the drawing up of its rule and statutes. He also worked as novice master for his own order, and in that role he became known as an effective preacher.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Bartolomeo_Fanti", "biography": "rewritten"}'::jsonb),
