UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Nonnosus, sometimes spelled Nonosius, was a prior of the monastery of San Silvestre on Monte Soratte, north of Rome; later he became a monk at Suppentonia, close to Civita Castellana. He lived at the same time as Saint Benedict of Nursia. Alban Butler wrote that, because information about Nonnosus has survived so sparsely, he is of no special interest in himself. No ancient martyrology lists his name.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Nonnosus", "biography": "rewritten"}'::jsonb),
