UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A Saint Ilar appears among the saints of 6th-century Wales and is probably the origin of the names of Llanilar, in Ceredigion, and of the hundred of Ilar that existed formerly. Sources differ on his feast day, offering 13, 14, or 15 January, yet neither the Anglican nor the Catholic church in Wales observes it any longer.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Ilar", "biography": "rewritten"}'::jsonb),
