UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Adrian of Nicomedia, also called Saint Adrian, served in the Herculian Guard of the Roman Emperor Galerius. He and his wife Natalia (Ναταλία) became Christians, and Adrian was then put to death as a martyr in Nicomedia, a city of Asia-Minor (Turkey). For many ages he was the foremost military saint of Northern Europe, behind only Saint George, and he is greatly revered in Flanders, Germany and northern France.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Adrian_and_Natalia_of_Nicomedia", "biography": "rewritten"}'::jsonb),
