UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Edward Poppe, a Belgian Roman Catholic priest, urged Catholics to receive the sacraments often and founded a children''s league devoted to the Eucharist. He strongly opposed Marxism, materialism and the widespread secularism of his region. Both as writer and pastor he argued for the rights of ordinary laborers. His ministry began in Ghent, but poor health made him leave.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Edward_Poppe", "biography": "rewritten"}'::jsonb),
