UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Iarlaithe mac Loga (Jarlath), a priest and scholar from Connacht in Ireland, is remembered as the founder who set up the monastic School of Tuam and the Archdiocese of Tuam, whose patron saint he is. No medieval biography of him survives; his life and cult are known from genealogies, martyrologies, the Irish Lives devoted to St Brendan of Clonfert, plus a 17th-century biography compiled by John Colgan.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Iarlaithe_mac_Loga", "biography": "rewritten"}'::jsonb),
