SET "payload" = content."payload" || jsonb_build_object('biography', 'The Catholic Church venerates Saints Ferreolus and Ferrutio as martyrs and saints. They are honored in particular at Besançon, whose patron saints they are.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Ferreolus_and_Ferrutio", "biography": "rewritten"}'::jsonb),
