UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Marta Anna Wiecka, DC, was a Polish Catholic who belonged to Saint Vincent de Paul''s Daughters of Charity. On taking her vows she took the name Maria, and she nursed in hospitals in Poland and Ukraine. After a miracle was credited to her intercession, Wiecka was beatified on 24 May 2008. Presiding for Pope Benedict XVI was Cardinal Tarcisio Bertone.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Marta_Anna_Wiecka", "biography": "rewritten"}'::jsonb),
