UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'John Duns Scotus was a university professor, philosopher and theologian, a Catholic priest and Franciscan friar from Scotland. He ranks among the foremost philosopher-theologians of Western Christendom in the late medieval period, alongside Thomas Aquinas, Bonaventure and William of Ockham.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Duns_Scotus", "biography": "rewritten"}'::jsonb),
