UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The Martyrs of Gorkum were 19 Dutch Catholic clerics, both secular and religious. Militant Dutch Calvinists hanged them in the town of Brielle on 9 July 1572, amid the religious wars of the 16th century. They died in the Dutch Revolt against Spanish rule, in particular, which grew into the Eighty Years'' War.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Martyrs_of_Gorkum", "biography": "rewritten"}'::jsonb),
