UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Edward Grzymała was a Polish Roman Catholic priest. Sachsenhausen, a Nazi concentration camp, held him prisoner, and he died at the camp in Dachau. Pope John Paul II beatified him in 1999. He is included in the group titled 108 Martyrs of World War II.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Edward_Grzyma%C5%82a", "biography": "rewritten"}'::jsonb),
