UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A Hispano-Roman Christian cleric, Augurius of Tarragona (Saint Augurius) is also cited as Augurinus. He served as a deacon and was martyred along with the bishop Fructuosus and another deacon, Eulogius. He was burned alive in Tarraco''s amphitheater during a persecution ordered by the emperors Valerian and Galerius of Rome. They were possibly the earliest martyrs for whom Spanish Christian history has any documentation.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Augurius_of_Tarragona", "biography": "rewritten"}'::jsonb),
