UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Benedict Daswa was a South African teacher and school principal. His parents named him "Samuel" when he began school, and he took the name "Benedict" when he converted to Catholicism. He was killed by a local mob after he declined to contribute money toward anti–Christian superstition.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Benedict_Daswa", "biography": "rewritten"}'::jsonb),
