UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The Benedictine abbess Wivina lived from 1103 to 1168. A native of Oisy, France, she turned down every marriage proposal and at age 23 settled as a hermit near Brussels, at Groot-Bijgaarden. Later she took land offered by Count Godfrey of Brabant, built a monastery there, and served as its first abbess.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Wivina_(abbess)", "biography": "rewritten"}'::jsonb),
