UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A religious sister from Italy in the Consolata Missionaries, Irene Stefani (IMC) was given the religious name Irene at her investiture. Her assignment was the mission in Kenya, where bubonic plague killed her in 1930. In 2015 Cardinal Polycarp Pengo beatified her on behalf of Pope Francis.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Irene_Stefani", "biography": "rewritten"}'::jsonb),
