UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Richard the Pilgrim, an English nobleman, is a Christian saint, also named Richard of Wessex. He was married to Wuna of Wessex, and their children were the West Saxon saints Willibald, Winnibald, and Walpurga. When he took his family on pilgrimage to the Holy Land, he died on the way at Lucca, where the church of Saint Fridianus received his burial.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Richard_the_Pilgrim", "biography": "rewritten"}'::jsonb),
