UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Hieu was an Irish abbess of the 7th century who carried out her work in Northumbria. As foundress she established abbeys at Hartlepool, and at Healaugh in Yorkshire England. She was the earliest of Northumbria''s saintly recluses, and the first woman known to have governed a double monastery.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Hieu_(abbess)", "biography": "rewritten"}'::jsonb),
