UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Johannes Ludovicus Paquay, who also bore the name Valentinus, was a Belgian priest of the Roman Catholic Church and belonged, as a professed member, to the Order of Friars Minor. He held a number of leadership posts in the house where he lived and was a well-liked confessor and a well-known preacher. He was also known for his devotion to the Eucharist and to the Sacred Heart, which he spread among the faithful and among his confreres alike.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Johannes_Ludovicus_Paquay", "biography": "rewritten"}'::jsonb),
