UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Bertin, also called Saint Bertin the Great, was a Frankish abbot whose monastery in Saint-Omer was afterward renamed the Abbey of Saint Bertin in his honour. The Catholic and Orthodox Churches venerate him as a saint. Word of his learning and holiness spread so widely that within a short time over 150 monks were living under his rule. Some of these were St. Winnoc and three companions; they arrived from Brittany, became part of Bertin''s community, and helped with the conversions. The Morini region became almost entirely Christianized.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Bertin", "biography": "rewritten"}'::jsonb),
