UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Adrian journeyed from Batanea to Caesarea Palaestina, and there he was martyred along with Saint Eubulus. Adrian''s commemoration is on 5 March, and Eubulus is commemorated on 7 March.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Adrian_of_Batanea", "biography": "rewritten"}'::jsonb),
