UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Gaudentius served as bishop of Novara, and he is counted as the city''s first. Tradition holds that his family at Ivrea was pagan, and that Eusebius of Vercelli led him to Christianity. According to some sources, Eusebius ordained him a priest and then sent him to Novara, to assist a Christian priest there named Laurence (Laurentius).'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Gaudentius_of_Novara", "biography": "rewritten"}'::jsonb),
