UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Klymentiy Sheptytsky, MSU, a Ukrainian Catholic prelate, was also known as Klymentiy of Univ. In the Ukrainian Greek Catholic Church he was archimandrite of the Studite Monks, and he was also Russian Catholic Apostolic Exarch of Great Russia and Siberia. He was arrested, and he died in Russia''s Vladimir Central Prison as a political prisoner held by the Soviet Union. He was beatified in 2001. The State of Israel named him Righteous Among the Nations because he saved the lives of Jews during the Holocaust in Ukraine.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Klymentiy_Sheptytsky", "biography": "rewritten"}'::jsonb),
