UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Anthony, John, and Eustathius are martyrs and saints of the Eastern Orthodox Church. The horologion places their feast day on 14 April, and every year on 13 July they are also commemorated at Vilnius, at the monastery dedicated to the Holy Spirit. In Eastern Orthodoxy they are honored with the 4th Tone Troparion and the 3rd Tone Kontakion.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Anthony%2C_John%2C_and_Eustathius", "biography": "rewritten"}'::jsonb),
