  AND md5(content."payload"->>'biography') = '5d16ddf51846bc852cbef63010a883a6';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Nicholas Owen, S.J., was an English Jesuit lay brother, and he was the chief builder of priest holes while Queen Elizabeth I and then James I ruled England. From 1588 he made many such hiding places inside the homes and other buildings of English Catholics, until his final arrest in 1606. At that arrest, prison officials in the Tower of London tortured him to death. The Catholic Church honours him as a martyr, and Pope Paul VI canonized him in 1970.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Nicholas_Owen_(Jesuit)", "biography": "rewritten"}'::jsonb),
