WHERE content."id" = 'cmq9xcalm3s4c2fi7izt0xuhl'
  AND content."slug" = 'saint-nicholas-owen'
  AND md5(content."payload"->>'biography') = 'a150e8fa5b68f5357ff7583af7ea5847';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Tegulus is venerated among the men of the legendary Theban Legion, whom Maurice led during the 3rd century. His cult is centered at Ivrea. 
His veneration in fact began as the 10th century was ending. In the episcopate of Warmondus (Varmondo), Tegulus''s relics were found in a sepulcher a short distance from Ivrea. They were moved inside the city walls to the cathedral of Ivrea and set in the chapel of San Giacomo. Later they were moved again, with the relics of Bessus, into the chapel of the Santissimo Sacramento.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Tegulus", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmq9xcnmu3se92fi7cf64pl79'
  AND content."slug" = 'saint-tegulus'
