UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pope Vitalian, bishop of Rome, held that office from 30 July 657 until his death in 672. Throughout his pontificate Constantinople''s imperial government and the papacy disputed over Monothelitism, which Rome condemned. Vitalian sought a settlement, and his dealings with Emperor Constans II, who came to Rome to visit him and presented him with gifts, were conciliatory. During his pontificate the Archbishopric of Ravenna also broke away from papal authority.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Vitalian", "biography": "rewritten"}'::jsonb),
