UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Andrea Franchi, OP, was an Italian Catholic of the Order of Preachers. From 1382 until 1400 he held the see of Pistoia as bishop. He was a well-known preacher and evangelist, deeply devoted to the poor in his diocese. Confirmation of his cultus meant Pope Benedict XV was able in 1921 to confirm Franchi''s beatification.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Andrea_Franchi", "biography": "rewritten"}'::jsonb),
