UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A French Catholic religious sister, Anne-Marie Rivier was foundress of the religious order Sisters of the Presentation of Mary. Education was her focus, and she opened a school shortly before the French Revolution began, during which the school was confiscated. When the revolution ended she was able to return to teaching, and she set up this order to provide schooling for orphans and for other children who needed it.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Anne-Marie_Rivier", "biography": "rewritten"}'::jsonb),
