UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Manuel González García, a Spanish bishop in the Roman Catholic Church, was Bishop of Palencia from 1935 until he died. As founder he started the Eucharistic Missionaries of Nazareth, and he also set up the Disciples of Saint John along with the Children of Reparation. Because of his intense devotion to the Eucharist he came to be called the "Bishop of the Tabernacle"; he made spreading that devotion his aim and urged people to receive the Eucharist often.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Manuel_Gonz%C3%A1lez_Garc%C3%ADa_(bishop)", "biography": "rewritten"}'::jsonb),
