UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Augustine Fangi, a Dominican friar and Catholic priest, was Italian. People of his time widely regarded him as a miracle worker. He served as prior of several monasteries of his Order and sought to bring back and keep the Rule of Saint Dominic faithfully observed. In 1878 he was beatified.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Augustine_Fangi", "biography": "rewritten"}'::jsonb),
