UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Simón de Rojas, a priest from Spain, belonged to the Trinitarian Order. Because he was devoted to the Blessed Virgin Mary, he is called the "Apostle of the Ave Maria". Talented in many ways, he was a theologian and spiritual writer, and he befriended and supported the poor.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Sim%C3%B3n_de_Rojas", "biography": "rewritten"}'::jsonb),
