UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Feodor Poskochin, who became the Russian Orthodox monk Therapont of Belozersk (also called Therapont of Mozhaysk), is credited with founding two houses: the Ferapontov Monastery in Northern Russia, which now lies near Kirillov in Vologda Oblast, and the Luzhetsky Monastery at Mozhaysk, near Moscow. The Russian Orthodox Church venerates Therapont as a saint.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Therapont_of_Belozersk", "biography": "rewritten"}'::jsonb),
