  AND md5(content."payload"->>'biography') = '8700dc72b50bc851051f14d9b51f22d7';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The Synaxaire Arabe-Jacobite, or Jacobite Arab Synaxarium, is a volume with biographies of several saints, used by the Syriac Orthodox Church. In 1904 René Basset issued its first publication, a French version printed in the Patrologia Orientalis. Do not confuse it with the Coptic Synaxarium, since some hagiographies noted look identical and both use the Egyptian Calendar. Variants have been found containing extra Nubian Church material, though only fragmentary. Among these saints are Abadios, who was a Christian martyr. Bilgai in Egypt was his birthplace; a soldier of native birth in the army, he professed faith in Jesus Christ at Khalakhis under Diocletian''s reign. He was martyred when thrown into a rock. January 20 is his feast day. Another Christian martyr, Abakuh, was born in the Al Fayyum region of Egypt, at Bamujeh. As a zealous Christian he was martyred for Christianity together with eight companions. January 23 is his feast day; the Synaxaire Arabe-Jacobite refers to him.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Synaxaire_Arabe-Jacobite", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmq9xdgw13sr32fi7keq0hxzk'
  AND content."slug" = 'saint-abadios'
  AND md5(content."payload"->>'biography') = 'fd2f0fed46a7c07d5ca8502c8490ce0a';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Benedict of Nursia had Placidus as a disciple. The son of the patrician Tertullus, he was brought to Benedict at Sublaqueum (Subiaco) as a child and offered to God, as the Rule of St. Benedict allows in its chapter 69 (oblate).'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Placidus", "biography": "rewritten"}'::jsonb),
