UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Urbicius, a French monk, is now a Catholic saint. Saracens took him captive, but he got away and lived as a hermit in the Aragon part of the Pyrenees. He is remembered on 15 December, and the Sanctuary of San Úrbez, Huesca, takes its name from him.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Urbicius_(monk)", "biography": "rewritten"}'::jsonb),
