UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Antoine Chevrier, TOSF, was a French Catholic priest who belonged to the Third Order of Saint Francis. He established the Institute of the Prado, which comprises a women''s branch, the Sisters of Prado, and a clerical branch, Institute of the Priests of Prado. He gave his whole life and pastoral work to serving the poor and to educating poor children and people living on the margins.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Antoine_Chevrier", "biography": "rewritten"}'::jsonb),
