UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Lazër Shantoja was an Albanian blessed who worked as a publicist, poet, and satirist. He translated Goethe, Schiller and Leopardi into Albanian and was Albania''s first Esperantist. As a Catholic priest he was among the first arrested by the communist government, and he was the first Albanian priest to die before a firing squad. In 2016 the Catholic Church recognized him as a martyr, one of the Martyrs of Albania.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Laz%C3%ABr_Shantoja", "biography": "rewritten"}'::jsonb),
