UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Andrés Hibernón Real was a Spanish Roman Catholic professed religious of the Order of Friars Minor. His parents were nobles who had become poor, and he was robbed while trying to raise money for them. The experience led him to rethink his attitude toward material and spiritual goods, and he entered religious life as a lay brother in order to nurture his spiritual side.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Andr%C3%A9s_Hibern%C3%B3n_Real", "biography": "rewritten"}'::jsonb),
