UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'According to the Hebrew Bible, Elisha was an Israelite prophet who worked wonders. English writers usually spell his name Elisha, following the Hebrew, while other forms are Eliseus (Greek and Latin), Ełishe (Yeghishe/Elisha) (Armenian), Alyasa (Arabic), and Elyasa or Elyesa (Turkish). The Quran,[6:86][38:48] and the New Testament also mention him, and Judaism, Christianity and Islam all venerate him as a prophet, while writings of the Bahá''í Faith mention him by name.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Elisha", "biography": "rewritten"}'::jsonb),
