UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Francisco de Jesus Marto and Jacinta de Jesus Marto were a brother and sister. Their home was the small hamlet of Aljustrel near Fátima, Portugal. Lúcia dos Santos (1907–2005), who was their cousin, joined them in reportedly seeing the Angel of Peace three times in 1916 and the Blessed Virgin Mary several times at Cova da Iria in 1917. As a result the Virgin Mary received the title Our Lady of Fátima, and the Sanctuary of Fátima grew into a leading centre of Catholic pilgrimage worldwide.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Francisco_and_Jacinta_Marto", "biography": "rewritten"}'::jsonb),
