UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Theodard of Maastricht, a bishop of Maastricht-Liège in what is now the Netherlands, lived in the 7th century. He was killed while travelling to protest against Frankish nobles who were plundering his diocese, and for that reason he is regarded as a martyr. He is commemorated on 10 September. His successor Lambert of Maastricht was his nephew, which makes Theodard the brother or brother-in-law of Robert II, Lord Chancellor of France.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Theodard_of_Maastricht", "biography": "rewritten"}'::jsonb),
