UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'John Stone, OSA, was an English Augustinian friar and a doctor of theology from Canterbury. He was executed, probably in December 1539. Pope Paul VI canonized him in 1970, and he is a member of the group titled Forty Martyrs of England and Wales.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/John_Stone_(martyr)", "biography": "rewritten"}'::jsonb),
