UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Dominik Trčka, a Czech priest, took the religious name Metod. A Redemptorist (Congregation of the Most Holy Redeemer), he began with parish missions, then extended his ministry to Greek Catholics. Eastern Rite Catholics often felt neglected and badly in need of pastoral help, and Trčka gladly met that need, making real and serious progress in the care he offered those people.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Dominik_Tr%C4%8Dka", "biography": "rewritten"}'::jsonb),
