UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A Spanish Roman Catholic professed religious, Nazaria Ignacia March Mesa took the name Nazaria of Saint Teresa of Jesus in religion and was the Missionaries of the Crusade''s founder. After immigrating from Spain to Mexico, Mesa joined a religious order, which had her minister in Bolivia, where she lived for most of her life. After leaving her own order she moved to Argentina, where she later died. She spent short periods back in Spain spreading the order she had founded.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Nazaria_Ignacia_March_Mesa", "biography": "rewritten"}'::jsonb),
