UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Marie-Louise-Élisabeth de Lamoignon de Molé de Champlâtreux, known in religion as Saint-Louis, was a professed religious of the Roman Catholic Church in France. In 1803 she established Sisters of Charity of Saint Louis, and so became its founder. She devoted herself to educating poor girls and abandoned girls in her region, although her love for the poor had already been noted during her marriage. Her husband, a politician, also supported this until his execution in the French Revolution. That period brought her great turmoil, and she lost two of her five children.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Marie-Louise-%C3%89lisabeth_de_Lamoignon_de_Mol%C3%A9_de_Champl%C3%A2treux", "biography": "rewritten"}'::jsonb),
