UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The Catholic and Eastern Orthodox churches both venerate Severus of Barcelona as a saint. His legend holds that he served as bishop of Barcelona and died a martyr in AD 304 when Diocletian persecuted the Christians. 
The particulars of what he did and how he died are uncertain, and their historical reliability is questionable.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Severus_of_Barcelona", "biography": "rewritten"}'::jsonb),
