UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Jakob Griesinger, a German, was a professed religious in the Order of Preachers (Roman Catholic) who had earlier been a soldier. In the Italian province of Campania he was in the duke''s service as a soldier, but he came to feel disillusioned with that life. A sudden call to religious life followed, and he gave the rest of his days to it.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Jakob_Griesinger", "biography": "rewritten"}'::jsonb),
