UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Annemund held the office of archbishop in Lyon''s archdiocese, and is also named Annemundus, Aunemundus, Ennemond and Chamond. Wilfrid of York counted him a friend, and he advised Clovis II as a councillor. His death is dated to 657 by some and 658 by others. He receives veneration as a saint within the Catholic Church.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Annemund", "biography": "rewritten"}'::jsonb),
