UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Jan Beyzym, a Polish Jesuit priest of the Catholic Church, spent a period after his ordination teaching in Jesuit boarding schools. He later left Poland to work among lepers in Madagascar, and he stayed there until he died.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Jan_Beyzym", "biography": "rewritten"}'::jsonb),
