UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Juan Grande Román, OH, a Spanish Catholic, belonged to the Brothers Hospitallers of Saint John of God. He took the name "John the Sinner" and, in 1600, died of the plague after caring for those stricken by it.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Juan_Grande_Rom%C3%A1n", "biography": "rewritten"}'::jsonb),
