UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Euphrasia Eluvathingal, a Carmelite nun from India, belonged to the Syro-Malabar Church, an Eastern Catholic Church in Kerala. She is said to have seen a vision of the Holy Family, after which the illness that had long afflicted her came to an end. Pope Francis canonised her in Vatican City on 23 November 2014. St. John the Baptist''s beheading is celebrated on 29 August, so St. Euphrasia''s feast is observed a day later, on 30 August.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Euphrasia_Eluvathingal", "biography": "rewritten"}'::jsonb),
