UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Fructus was an eighth-century hermit from Castile who is venerated as a saint. According to Christian tradition he had two siblings, Valentine (Valentín) and Engratia (Engracia), and the three lived as hermits on a mountain near Sepúlveda. Engratia is not to be mistaken for the Portuguese martyr of the same name from the 4th century.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Fructus", "biography": "rewritten"}'::jsonb),
