UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Fidela Oller Angelats, a Spanish religious sister belonging to Hermanas de Sant Josep o Vetlladores, was martyred during the Spanish Civil War, shot together with others beside a road at Xeresa. She was beatified in Girona Cathedral on 5 September 2015.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Fidela_Oller_Angelats", "biography": "rewritten"}'::jsonb),
