UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Agnes of Rome was an adolescent Roman Christian put to death in the 4th century on account of her faith. The Catholic Church, the Oriental Orthodox Church, the Eastern Orthodox Church, the Anglican Communion and Lutheran Churches all venerate her as a virgin martyr and a saint. Her name appears in the Canon of the Mass among those of a few virgin martyrs, and she was one of many Christians martyred under the Roman emperor Diocletian.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Agnes_of_Rome", "biography": "rewritten"}'::jsonb),
