UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Isabel Cristina Mrad Campos was a Catholic laywoman from Brazil. She worked in her parish as a Vincentian, though she never became a formal member of the movement. She gave her free time to her faith and was often found at Eucharistic adoration and at Mass. She hoped to take up medicine and become a pediatrician in order to care for underprivileged children, but she was murdered in her apartment following an attempted rape.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Isabel_Cristina", "biography": "rewritten"}'::jsonb),
