  AND md5(content."payload"->>'biography') = 'f955de3cea5d8a47d559d34be20deec7';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Juan de Castillo, a Spaniard, was a Jesuit priest and missionary, honored by the Catholic Church as a martyr and saint. He was among the earliest workers in the Jesuit reductions of Paraguay.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Juan_de_Castillo_(Jesuit)", "biography": "rewritten"}'::jsonb),
