UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'An Italian Roman Catholic priest, Tommaso da Cori (born Francesco Antonio Placidi) was professed as a Friar Minor of the Franciscan Order, and he spent much of his religious life as a hermit. His preaching made him well known across the region around his hermitage, and it earned him the name "Apostle of the Sublacense".'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Tommaso_da_Cori", "biography": "rewritten"}'::jsonb),
