UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Venerated in the Kingdom of Mercia, Saint Edith of Polesworth was an abbess of Anglo-Saxon England. Tradition connects her with Polesworth Abbey in Warwickshire and with Tamworth, Staffordshire, a royal centre. She is widely revered as a saint, yet her historical identity and the period when she was active (floruit) are uncertain.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Edith_of_Polesworth", "biography": "rewritten"}'::jsonb),
