UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Calminius, or Calmin, established three French abbeys during the 6th or 7th centuries AD. They were Laguenne Abbey, Monastier-Saint-Chaffre abbey, and Mozac Abbey (in Puy-de-Dôme). His Saint''s day falls on August 19.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Calminius", "biography": "rewritten"}'::jsonb),
