UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Mar Shimun Bar Sabbae, a Persian, was Bishop of Seleucia-Ctesiphon and, until he died, the effective leader of the Church of the East. He served as bishop in the Sasanian Empire while Shapur II was persecuting Christians, and he was executed with many of his followers. Various Christian communions revere him as a saint.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Shemon_bar_Sabbae", "biography": "rewritten"}'::jsonb),
