UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Acacius, or Aqaq, was Amida''s bishop (in Mesopotamia) between 400 and 425, in the time of the Eastern Roman Emperor Theodosius II. None of his writings survive, but Socrates Scholasticus records his life in his Church History, in the 7th book''s 21st chapter, describing him as freeing thousands of slaves.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Acacius_of_Amida", "biography": "rewritten"}'::jsonb),
