UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A martyr of Spain, Saint Cucuphas has a feast day of 25 July, though in some regions it is observed on 27 July so as not to clash with the major feast day of Santiago, Spain''s patron saint. His name is said to be Phoenician in origin and to mean "he who jokes" and "he who likes to joke."'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Cucuphas", "biography": "rewritten"}'::jsonb),
