UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Nicanor appears in the Acts of the Apostles as a member of the Seven Deacons of the church of the early Christians. The Catholic Church and also the Eastern Orthodox Church venerate him as martyr, deacon, and apostle of the Seventy.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Nicanor_the_Deacon", "biography": "rewritten"}'::jsonb),
