UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A nun living at Nisibis in the Roman Empire, Phebronia of Nisibis (also called Phebronia of Sebapte) was persecuted during the time of Diocletian. He promised her freedom on condition that she renounce her faith and wed his nephew Lysimachus, a man already inclining toward Christianity. Febronia refused; she was tortured, mutilated and put to death. Lysimachus watched her suffer and became a convert.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Febronia_of_Nisibis", "biography": "rewritten"}'::jsonb),
