UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Emmelia of Caesarea was born between the late third and early fourth century, at a time when Christianity was spreading more widely and posing a challenge to Rome''s pagan government.
She married Basil the Elder and had nine or ten children, among them Basil of Caesarea, Macrina the Younger, Peter of Sebaste, Gregory of Nyssa, and Naucratius.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Emmelia_of_Caesarea", "biography": "rewritten"}'::jsonb),
