UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Félicité Pricet numbered among the French Catholic martyrs of Angers, killed in the massacres of the War in the Vendée for backing the rebels who opposed the monarchy in the French Revolution. Pope John Paul II beatified her in 1984, and her Feast Day falls on 18 January.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/F%C3%A9licit%C3%A9_Pricet", "biography": "rewritten"}'::jsonb),
