UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Gerontissa Gavrielia was a nun of the Greek Orthodox Church, noted for caring for the poor and the sick. She was a qualified physiotherapist and the second woman admitted to a Greek university, and at the age of 60 she took up her religious calling. Another name for her is Gabriela of the Ascetic of Love, and she is a saint. On 3 October 2023 she was canonized by the Ecumenical Patriarchate of Constantinople, through its Holy synod.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Gerontissa_Gavrielia", "biography": "rewritten"}'::jsonb),
