UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Carolina Santocanale, an Italian nun of the Roman Catholic Church, took the name "Maria of Jesus" and set up a congregation named Capuchin Sisters of the Immaculata of Lourdes. Santocanale gave her life and work to the ill and the poor, and her care for them made her widely known. She likewise belonged to the Secular Franciscan Order.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Carolina_Santocanale", "biography": "rewritten"}'::jsonb),
