UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Sigo, an abbot from Burgundy, lived in the sixth century. The Roman Catholic Church and the Orthodox Church both honor him as a saint, and he is reputed to be the founder of Saint-Seine Abbey. Both churches keep his feast day on September 19.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Sigo", "biography": "rewritten"}'::jsonb),
