UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A Capuchin friar from Poland and a Roman Catholic priest, Florian Stępniak is counted among the 108 World War II Martyrs. In 1931 he entered the Order of Friars Minor Capuchin. The Gestapo arrested him while he was pursuing theological studies at the Catholic University of Lublin; he was sent first to Sachsenhausen and then to Dachau, where he was later killed with gas.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Florian_St%C4%99pniak", "biography": "rewritten"}'::jsonb),
