UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Fleur of Issendolus, who is also called Fleur of Beaulieu, Sainte Fleur, Saint Flora or Flora of Beaulieu, was a French Hospitaller nun. She lived at Hôpital-Beaulieu in Issendolus, which lay in the former province of Quercy. The Catholic Church venerates her as a saint and keeps her feast on 5 October.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Flora_of_Beaulieu", "biography": "rewritten"}'::jsonb),
