SET "payload" = content."payload" || jsonb_build_object('biography', 'Mariana Navarro de Guevara, whose full name was Mariana Navarro de Guevara Romero, was a Spanish Roman Catholic nun of the Mercedarian Tertiaries. On entering, she received a religious name, Mariana of Jesus, and became known for penance and for stressing devotion to the Eucharist. She is at times called the "Lily of Madrid".'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Mariana_Navarro_de_Guevara", "biography": "rewritten"}'::jsonb),
