UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saints Alphius, Philadelphus and Cyrinus were martyrs honoured within southern Italy''s Byzantine traditions. The three brothers came from Vaste, in the Otranto diocese, and died together with their mother, Benedicta, while Decius was persecuting Christians, ca 251 AD. The accounts of their martyrdoms are traditional, later set down in the Acta of Saint Alphius, a Benedictine work.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Alphius%2C_Philadelphus_and_Cyrinus", "biography": "rewritten"}'::jsonb),
