UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Guillaume de Donjeon, a French prelate of the Roman Catholic Church, was Archbishop of Bourges from 1200 until he died. Before entering the Order of Grandmont he held canonries at Soissons and Paris, and some time afterward he joined the Cistercians. Austere practices marked his life, such as going without meat and wearing a hair shirt.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/William_of_Donjeon", "biography": "rewritten"}'::jsonb),
