UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Rolando Maria Rivi was an Italian Roman Catholic seminarian, known as a studious and devout young man who loved Jesus Christ deeply, as shown by his frequent confession and reception of the Eucharist. Friendly to everyone, he proudly wore his cassock to declare that he belonged to Christ and to his church. Communist partisans, claiming he had spied for the Italian Social Republic, murdered him in odium fidei in Modena near the end of World War II, because he was studying to become a priest.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Rolando_Rivi", "biography": "rewritten"}'::jsonb),
