UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Plato the Studite, also called Plato of Sakkoudion, started out as a minor Byzantine official and then became a monk in 759. He declined both the metropolitan see of Nicomedia and the headship of a Constantinople monastery. In 783 he instead established the monastery of Sakkoudion, located in Bithynia on Mount Olympus, and served as its first abbot. Along with his nephew Theodore Stoudites, he is remembered for supporting the veneration of icons during the Byzantine Iconoclasm and for taking part in the Second Council of Nicaea, as well as for steadfastly opposing Emperor Constantine VI''s second marriage, to Plato''s own niece Theodote. The Church canonized him; April 4 is his feast day.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Plato_of_Sakkoudion", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmq9xggpb3ulh2fi76ly105b0'
