UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Luigi Beltrame Quattrocchi and Maria Corsini-Beltrame Quattrocchi were Italian Catholic laypeople, a married couple, who in 2001 became the first couple beatified together. Pope John Paul II said that they led an ordinary life, but did so in an extraordinary manner. They are commemorated on 25 November, which was their wedding anniversary.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Luigi_Beltrame_Quattrocchi_and_Maria_Corsini", "biography": "rewritten"}'::jsonb),
