UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Among the Twelve Apostles of Ireland was Ciarán of Saigir, called as well Ciarán mac Luaigne or Saint Kieran. He is regarded as the first saint born in Ireland, though the legend that he came before Saint Patrick is doubtful. He was the bishop at Saighir (Seir-Kieran), and the diocese of Ossory, which succeeded it, still has him as patron saint.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Ciar%C3%A1n_of_Saigir", "biography": "rewritten"}'::jsonb),
