UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Anthimus of Rome is a Christian saint, known to Italians as Sant''Antimo. Legend makes up most of what is told of his life. Bithynia is said to have been his birthplace. He was a Christian priest, and under the Emperors Diocletian and Maximian he was jailed because of his beliefs. His feast day is May 11.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Anthimus_of_Rome", "biography": "rewritten"}'::jsonb),
