UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Francesco Fogolla, called Fu Zhujiao in Chinese, was a missionary prelate from Italy, belonging to the Franciscans, formally the Order of Friars Minor. He was named titular bishop of Bageis on 28 June 1898, and also coadjutor bishop for Northern Shanxi in China. He died on 9 July 1900 in the Taiyuan Massacre, which took place during the Boxer Rebellion. The Catholic Church counts him a martyr and venerates him as a saint.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Francis_Fogolla", "biography": "rewritten"}'::jsonb),
