UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Arthur "Francis" Bell, OFM was an English Franciscan friar. During the English Civil War a court acting under Parliament''s authority convicted him of being a Catholic priest, and he was put to death at Tyburn in London. Pope John Paul II beatified Bell on 22 November 1987.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Arthur_Bell_(martyr)", "biography": "rewritten"}'::jsonb),
