UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A Dominican nun, Margaret of Hungary (OP) was the daughter of Maria Laskarina and King Béla IV of Hungary. Her sisters included Kinga of Poland (Kunegunda) and Yolanda of Poland, both older, and on her father''s side she was a niece of the renowned Elizabeth of Hungary. An elder sister who bore the same name had died before Margaret''s birth.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Margaret_of_Hungary_(saint)", "biography": "rewritten"}'::jsonb),
