UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Chrysogonus died as an early Christian martyr. Holy tradition says that he served the Roman army as a knight. Roman emperor Diocletian proposed making him prefect of a province if he renounced Christianity; Chrysogonus refused and was put to death in the persecution.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Chrysogonus", "biography": "rewritten"}'::jsonb),
