UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Richardis, who also bears the names Richgard, Richardis of Swabia and, in French, Richarde de Souabe, was empress of the Carolingian Empire through her marriage to Charles the Fat. Her piety was widely known, and she served as the first abbess of Andlau. Her husband repudiated her; later she was held up as a Christian model for devotion and for just rule. In 1049 she was canonised.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Richardis", "biography": "rewritten"}'::jsonb),
