UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A Jewish martyr, the woman with seven sons appears in 2 Maccabees 7, a deuterocanonical book, and 4 Maccabees expands her story. King Antiochus IV Epiphanes began a persecution of Judaism, and she and her seven sons were seized in it. As part of that campaign they were commanded to eat pork, which would break Jewish law. Again and again they refused. Antiochus tortured the sons and killed them one at a time while their unflinching, stout-hearted mother looked on, and in the end he killed her too.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Woman_with_seven_sons", "biography": "rewritten"}'::jsonb),
