UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Rictius Varus held the post of Vicarius in Roman Gaul toward the close of the 3rd century, about when the Diocletianic Persecution took place. A prefect, Rixius Varus, is often mentioned in the Roman Martyrology, and he is said to have been the persecutor of hundreds of Christians. Christian hagiography says he later repented and himself died a Christian martyr, and both the Eastern Orthodox and Roman Catholic Churches regard him as a Saint, with a feast day of July 6.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Rictius_Varus", "biography": "rewritten"}'::jsonb),
