UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Julia of Corsica, a virgin and martyr venerated as a saint, also bears the names Julia of Carthage and, much less often, Julia of Nonza. She most probably died in AD 439 or afterwards. Together with Devota she is a patron saint of Corsica in the Catholic Church; the church declared Julia a patroness of Corsica on 5 August 1809 and Devota on 14 March 1820. Both suffered martyrdom under Roman rule in pre-Christian Corsica. In the Western liturgical calendar Julia''s feast day is 23 May, while in the East it is 16 July.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Julia_of_Corsica", "biography": "rewritten"}'::jsonb),
