UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Giovanni da Penna belonged to the Order of Friars Minor as a professed member and was an Italian Roman Catholic priest. In 1213 he became a Franciscan after listening to a sermon by Fra Filippo, a disciple of Francis of Assisi. For more than two decades he lived in France, supervising the founding of Franciscan houses, and then went back to the Italian peninsula, where he passed the rest of his life in quiet, cloistered retirement.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Giovanni_da_Penna", "biography": "rewritten"}'::jsonb),
