UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Macrina the Younger was a consecrated virgin of the early Church. Her brothers were Peter of Sebaste, Naucratius, Gregory of Nyssa and Basil the Great, and she was their elder sister. In his work entitled Life of Macrina, Gregory of Nyssa describes her holiness and asceticism across her life. Macrina led a chaste, humble life, and spent her time in prayer and in giving her younger brother Peter a spiritual education.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Macrina_the_Younger", "biography": "rewritten"}'::jsonb),
