UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Gemma Umberta Maria Galgani, also called Gemma of Lucca, was a mystic from Italy whom the Catholic Church canonized as a saint in 1940. Because she imitated the Passion of Christ so deeply, she has been named the "daughter of the Passion". The Passionists (Passion of Jesus Congregation) hold her in special veneration.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Gemma_Galgani", "biography": "rewritten"}'::jsonb),
