UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A medieval folk saint, Veronus of Lembeek is honored in Lembeek, the town he made his home, which lies close to Halle and to the Belgian language boundary. Tradition says that he chose a humble life even though he was a great-grandson of Charlemagne, and that he won a name for holiness before dying on 31 January 863.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Veronus_of_Lembeek", "biography": "rewritten"}'::jsonb),
