UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Catherine of Genoa, an Italian saint and mystic, was noted for her work with the sick and the poor, and is remembered for several writings that describe both this work and her mystical experiences. She came from the noble Fieschi family and devoted most of her life and her resources to the sick, especially during the plague that devastated Genoa in 1497 and 1501. Her death occurred in Genoa in 1510.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Catherine_of_Genoa", "biography": "rewritten"}'::jsonb),
