UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Lorcán Ua Tuathail, called Laurence O''Toole in English and Laurent d''Eu in French, served as Archbishop of Dublin when the Normans invaded Ireland. He was a prominent figure in the 12th-century Irish Church Reform Movement, and he acted as a mediator between the parties both during and after the invasion. Pope Honorius III canonised him in 1225.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Lorc%C3%A1n_Ua_Tuathail", "biography": "rewritten"}'::jsonb),
