UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Dorothea of Caesarea is a virgin martyr of the 4th century who was put to death at Caesarea Mazaca. Very little evidence survives that she truly existed, or for her acta. She is described as a martyr of the Diocletianic Persecution in its late phase, even though she died after Diocletian himself had resigned.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Dorothea_of_Caesarea", "biography": "rewritten"}'::jsonb),
