UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Zofia Radziwiłł, known too as Zofia of Słuck, is an Orthodox Christian saint from Poland and Lithuania. Last of her line, the Olelkowicz–Słucki family, which ruled as princes of Slutsk and Kopyl, she traced her descent from Lithuanian Grand Duke Algirdas. The Orthodox Church canonized her in 1983. A church in Minsk, dedicated to St. Sophia of Slutsk, is named in her honour.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Zofia_of_S%C5%82uck", "biography": "rewritten"}'::jsonb),
