UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A Byzantine Greek theologian and cleric of the Eastern Orthodox Church in the late Byzantine period, Gregory Palamas was first a monk on Mount Athos, then archbishop of Thessalonica. He is renowned for defending hesychast spirituality, the difference between the essence of God and his energies, and the uncreated nature of the light of the Transfiguration. His teaching developed through three major controversies: (1) from 1336 to 1341 with the Italo-Greek Barlaam, (2) from 1341 to 1347 with the monk Gregory Akindynos, and (3) from 1348 to 1355 with the philosopher Gregoras. His theological contributions are at times called Palamism, and his followers Palamites.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Gregory_Palamas", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmq9xjxmc3vw12fi79n5okfq2'
  AND content."slug" = 'saint-gregory-palamas'
  AND md5(content."payload"->>'biography') = '15425ecdd4a3087ffe49d9b3ba2329cb';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Between 1535 and 1679, a group of Catholic men and women, both lay and religious, were executed for treason and related offences under assorted laws that Parliament enacted during the English Reformation. They are known as the Forty Martyrs of England and Wales, or Cuthbert Mayne and Thirty-Nine Companion Martyrs. The earliest on the list are Carthusian monks who refused in 1535 to accept the Act of Supremacy of Henry VIII, and the latest are seminary priests caught up in 1679 in the Popish Plot against Charles II, a conspiracy that was alleged. Show trials produced many of the death sentences, and some victims had no trial at all.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Forty_Martyrs_of_England_and_Wales", "biography": "rewritten"}'::jsonb),
