UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Saturninus of Cagliari is honored as Cagliari''s patron saint. Christian tradition holds that he was a martyr of the city, put to death there on the orders of the governor Barbarus. The legend says he was beheaded because he would not sacrifice to Jupiter during Diocletian''s persecutions of Christians.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saturninus_of_Cagliari", "biography": "rewritten"}'::jsonb),
