UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The 108 Martyrs of World War II, also called the 108 Blessed Polish Martyrs, were Polish Catholics killed by the German Nazis during World War II. They are commemorated liturgically on 12 June. Pope John Paul II beatified the 108 in Warsaw on 13 June 1999. The group includes 11 lay people, 3 bishops, 79 priests, 7 religious men and 8 religious women. Two parishes bear the martyrs'' name, one in Powiercie in Koło County and the other in Malbork.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/108_Martyrs_of_World_War_II", "biography": "rewritten"}'::jsonb),
