UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Tanguy of Locmazhé, called Sant Tangi in Breton, came from Gerber and was a Breton monk. At Le Conquet he established the abbaye de Saint Matthieu, and he lies buried at Locmazhé (Finistère). His feast is kept on 19 November, the day after that of Aude de Trémazan, his sister, or alternatively on 12 March, when his spiritual father, Saint Pol Aurélien, is also celebrated.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Tanguy", "biography": "rewritten"}'::jsonb),
