UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Among the early Irish monastic saints, Brendan of Clonfert counts among the Twelve Apostles of Ireland. Other names for him include Brendan the Navigator, Brendan the Voyager, Brendan the Anchorite, and Brendan the Bold, and in Irish he is Naomh Bréanainn or Naomh Breandán. His chief renown rests on a legendary voyage in search of the "Isle of the Blessed", at times called "Saint Brendan’s Island". The account of that journey is preserved in the immram Navigatio Sancti Brendani Abbatis.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Brendan_the_Navigator", "biography": "rewritten"}'::jsonb),
