UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pietro Geremia, an Italian Roman Catholic priest, was a professed member of the Order of Preachers. Born in Palermo, he lived for a long time in Bologna, where he underwent a radical conversion, and in Fiesole, where he was admitted to the Dominicans. He then went back to Palermo, where he became a celebrated and much sought-after preacher and miracle worker.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pietro_Geremia", "biography": "rewritten"}'::jsonb),
