UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Eugenia of Alsace, venerated as a Christian saint, served from 721 to 735 as the second abbess of Hohenburg Abbey in Alsace. She was the niece of Saint Odile and the sister of Saint Attalus. Her feast day is 16 September, the day in 735 when she died of natural causes at Hohenburg.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Eugenia_of_Alsace", "biography": "rewritten"}'::jsonb),
