UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Anthusa of Constantinople, usually called Saint Anthusa of Constantinople and, among the Orthodox, Saint Anthousa the Younger, is venerated as a saint by both the Eastern Orthodox Church and the Catholic Church. The Orthodox keep her feast on 12 and 18 April, and the Catholic Church keeps it on 18 April. Catholics regard her as patroness of convents and abbeys. Her father was the Byzantine Emperor Constantine V.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Anthusa_of_Constantinople", "biography": "rewritten"}'::jsonb),
