UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Romanos the Melodist, a Byzantine hymnographer and composer, is an important early figure in Byzantine musical history. Active in the sixth century, he is known as "the Pindar of rhythmic poetry", although the oldest manuscripts of his works date from centuries later. No composer of the Kontakion in his day surpassed him.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Romanos_the_Melodist", "biography": "rewritten"}'::jsonb),
