UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Sagar, also known as Sagaris, died as a martyr in the early Christian church. He is supposed to have been a disciple of St. Paul, and he is known to have been Bishop of Laodicea, Phrygia. His martyrdom took place under Emperor Marcus Aurelius. Polycrates cited Sagar because he was a quartodeciman.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Sagar_of_Laodicea", "biography": "rewritten"}'::jsonb),
