UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Aurelianus held the see of Arles as archbishop from 546 to 551, after Auxanius and Caesarius of Arles. Sacerdos, his father, was Archbishop of Lyon, and his cousin Nicetius took over from that father in the Lyon see. Aurelianus died in Lyon on 16 June 551 and lies buried at the church of Saint-Nizier. The wording of his epitaph survives.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Aurelianus_of_Arles", "biography": "rewritten"}'::jsonb),
