UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Theodosius of Kiev, also known as Theodosius of the Caves, was a saint of the 11th century. He introduced cenobitic monasticism to Kievan Rus'' and co-founded the Kiev Caves Lavra with Anthony of Kiev. Nestor the Chronicler composed a hagiography of Theodosius in the twelfth century.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Theodosius_of_Kiev", "biography": "rewritten"}'::jsonb),
