UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Bartholomew of Braga was Portuguese and Catholic; born Bartolomeu Fernandes, he took the name Bartolomeu dos Mártires in religion. He was a religious, a professed member of the Order of Preachers, and Archbishop Emeritus of Braga. He took part in the Council of Trent, where he also worked with Charles Borromeo. In Braga he set up a number of hospitals and hospices, and he published works on subjects ranging from the catechism to other topics.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Bartholomew_of_Braga", "biography": "rewritten"}'::jsonb),
