UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'In 304, under Emperor Diocletian, 49 Christians known as the Martyrs of Abitinae were found guilty of holding Sunday worship in defiance of the law at Abitinae, a Roman town in the province of Africa. Although the town is commonly called Abitina, the Annuario Pontificio gives it as Abitinae. Saint Augustine of Hippo used the plural Abitinae in his De baptismo, written in 400 or 401.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Martyrs_of_Abitinae", "biography": "rewritten"}'::jsonb),
