UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The Gospel of John says Mary of Clopas stood among the women at Jesus''s crucifixion and brought supplies for his funeral. Whether Mary was Clopas''s daughter or wife is ambiguous in the Greek wording Mary of Clopas, though exegesis has commonly favoured reading "wife of Clopas". Clopas was identified by Hegesippus as Joseph''s brother. The Catholic Church''s latest official Roman Martyrology edition commemorates her on April 24, together with Salome.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Mary_of_Clopas", "biography": "rewritten"}'::jsonb),
