UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Paolo Manna was an Italian Roman Catholic priest, a member of PIME (the Pontifical Institute for Foreign Missions), and founder of the Pontifical Missionary Union. He served as a missionary in Burma and was even Superior General for PIME. Much of his life went to fostering the missions along with the evangelic and apostolic zeal attached to them; to that end he founded newspapers and movements supporting this charismatic apostolate. Several leadership roles in PIME were also his, and from that standing he engaged further with prospective missionaries.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Paolo_Manna", "biography": "rewritten"}'::jsonb),
