UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Morwenna gave her name to Morwenstow, a village and civil parish in the north of Cornwall, UK, and is its patron saint. The name is believed to be cognate with the Welsh word morwyn, meaning "maiden". It is also used as a given name in Wales and Brittany, and is said to be formed from "Mor" and "Gwenn", which mean "White sea" in Welsh and in Breton alike.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Morwenna", "biography": "rewritten"}'::jsonb),
