UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Goeznovius, or Goueznou, was born in Cornwall and became Bishop of Léon in Brittany. People around Brest and in the diocese of Léon venerate him as a saint. His Legenda says that, like many fellow countrymen, he crossed to the continent after the Anglo-Saxon invasions and so contributed to establishing the Brittonic settlement in Armorica, which grew into Brittany. Each 25 October his feast day is kept.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Goeznovius", "biography": "rewritten"}'::jsonb),
