UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Born João de Menezes da Silva, Amadeus of Portugal was a Portuguese nobleman. He first became a Hieronymite monk, then left that religious order to be a friar in the Franciscan Order. He afterward worked to reform the Franciscans and founded a separate branch of the Friars Minor that took his name. The Pope later suppressed this branch (1568) so that it could be merged into one large family of Friars Minor Observants.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Amadeus_of_Portugal", "biography": "rewritten"}'::jsonb),
