UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Lazarus, surnamed Zographos, was a Christian saint of Byzantium in the 9th century, also called Lazarus the Painter or Lazarus the Iconographer. His birth, in Armenia, was on November 17, 810, and he lived both ahead of and throughout the second period of Byzantine Iconoclasm. He holds the distinction of being the first saint canonized specifically as an iconographer. Saint Catherine of Bologna later followed him.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Lazarus_Zographos", "biography": "rewritten"}'::jsonb),
