UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pedro de Arbués, also called Peter of Arbués, was a priest from Spain and a professed Augustinian canon in the Roman Catholic Church. He held office in the Spanish Inquisition until Jews and conversos assassinated him in 1485 in La Seo Cathedral in Zaragoza. Popular acclaim quickly gave rise to his veneration. His death greatly helped Inquisitor-General Tomás de Torquemada in his campaign against heretics and crypto-Jews. He was canonized on 29 June 1867.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pedro_de_Arbu%C3%A9s", "biography": "rewritten"}'::jsonb),
