UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Felicitas of Rome (anglicized as Felicity) is a saint counted among the Christian martyrs. Beyond her name, the one certain fact about her is that she was buried on a 23 November in the Maximus cemetery along the Via Salaria. A legend, though, makes her the mother of the seven martyrs commemorated on 10 July. The Eastern Orthodox Church marks their martyrdom on 25 January.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Felicitas_of_Rome", "biography": "rewritten"}'::jsonb),
