UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The Roman Catholic Church beatified Chiara Badano, an Italian woman. She was nine when she joined the Focolare Movement, whose founder, Chiara Lubich, gave her the nickname "Luce" ("light"). Doctors diagnosed osteogenic sarcoma, a painful bone cancer, when she was 16, and she died of it on October 7, 1990, two years after the illness began. The Roman sanctuary of Our Lady of Divine Love hosted her beatification on September 25, 2010. Her feast day is October 29.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Chiara_Badano", "biography": "rewritten"}'::jsonb),
