UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Elizabeth of the Trinity, OCD, born Élisabeth Catez, was a French Discalced Carmelite, mystic, and spiritual writer. She was noted for her deep spiritual growth as a Carmelite, and also for dark periods when people around her saw her religious calling as uncertain. Even so, she was recognized for persevering in seeking the will of God and for giving her life to the Carmelite charism.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Elizabeth_of_the_Trinity", "biography": "rewritten"}'::jsonb),
