UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Tradition says that Saint Eutropius of Saintes, venerated as the first bishop of that French city, was of royal descent, either Roman or Persian. He was sent to evangelize Gaul as a companion of Saint Denis, sent either by Pope Fabian in the 250s or by Saint Clement back in the 1st century.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Eutropius_of_Saintes", "biography": "rewritten"}'::jsonb),
