UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Giacomo Bianconi was an Italian Roman Catholic priest, professed in the Order of Preachers. A native of Umbria, he entered the order as an adolescent and devoted his pastoral work to his flock; on one notable occasion he helped refugees when Frederick II sacked the region in 1248. He also fought heresies and succeeded in converting a leading figure among those promoting them. He was further marked by a life of extreme poverty that exceeded Dominican standards.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Giacomo_Bianconi", "biography": "rewritten"}'::jsonb),
