UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Christians venerate Saint Caprasius of Agen as a saint and martyr from the fourth century. In the fifth century, relics linked to him were found at Agen in south-west France. Legends from the 14th century call him the first bishop of Agen, yet as Alban Butler notes, the sole evidence for his existence is that a church was dedicated to him in the 6th century.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Caprasius_of_Agen", "biography": "rewritten"}'::jsonb),
