UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Narcisa de Jesús Martillo Morán, from Ecuador, was a virgin and a tertiary of the Dominicans in the Roman Catholic Church. She was known for giving to charity and for strict devotion to Jesus Christ, leading a chaste, austere life given to prayer and penance. Her commitment to prayer and to bodily mortification was strong, and it moved her to join the Third Order of Saint Dominic. She did so in Patrocínio (Peru), and died there on 8 December 1869. She was beatified on 25 October 1992.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Narcisa_de_Jes%C3%BAs", "biography": "rewritten"}'::jsonb),
