  AND md5(content."payload"->>'biography') = '3e57b9eb66dfd633d60878d5b2b58f0f';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pietro of Pappacarbone was an Italian saint who served as abbot and as bishop. He headed the abbey of La Trinità della Cava, which stands at Cava de'' Tirreni. A native of Salerno, he had earlier been a monk of Cava, serving under Leo I of Cava. From 1062 to 1068 he lived at Cluny, and in 1079 he was made bishop of Policastro.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pietro_of_Pappacarbone", "biography": "rewritten"}'::jsonb),
