UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Shushanik, also called Shushanika or Vardandukht, was an Armenian Christian woman whom her husband Varsken tortured to death in the town of Tsurtavi, Georgia. She was killed for insisting on her right to profess Christianity, and so she is counted a martyr. Jacob’s hagiographic work, written by her confessor, tells of her martyrdom and is the earliest surviving piece of Georgian language literature. It describes Shushanik''s long resistance to isolation, imprisonment, cruelty and torture.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Shushanik", "biography": "rewritten"}'::jsonb),
