UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Nicholas Bunkerd Kitbamrung was a Thai Catholic priest. He studied for nearly twenty years before ordination, after which he began pastoral work as assistant to two pastors in different Thai provinces. He soon gained a reputation as a catechist, teaching catechesis to Salesian seminarians and the Thai language to Salesian priests. In 1941 officials in Thailand accused him of espionage and of collaborating with the French and jailed him, and in 1944 he died of tuberculosis after long mistreatment.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Nicholas_Bunkerd_Kitbamrung", "biography": "rewritten"}'::jsonb),
