UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Adela of Pfalzel, at times named Adula or Adolana, was a noblewoman of the Franks, an abbess, and a Catholic saint. According to some sources, she was the daughter of Dagobert II and the sister of Saint Irmina of Oeren. She was married to a man called Alberic, and after his death joined the Pfalzel monastery of the Benedictines, near Trier, of which she may have been the founder and first abbess. She died at Pfalzel in 735. The Orthodox Church keeps her feast day on December 24, and the Catholic Church on January 3.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Adela_of_Pfalzel", "biography": "rewritten"}'::jsonb),
