UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Arcangelo Canetoli, an Italian Roman Catholic priest, was a canon regular at Santa Maria di Reno. His parents and brothers were killed in Bologna in a political feud, but he survived the massacre, and soon afterward entered religious life. There he gained such renown that he repeatedly refused the offered posts of Archbishop of Bologna and Archbishop of Florence.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Arcangelo_Canetoli", "biography": "rewritten"}'::jsonb),
