UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Albertina Berkenbrock, a Brazilian Catholic girl, was killed in 1931 "in defensum castitatis" when she resisted her attacker''s attempts to rape her. Both sides of her family were of German descent, and the family farm was where she worked. A devoutly religious girl, she attended Mass often and taught catechism to other children.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Albertina_Berkenbrock", "biography": "rewritten"}'::jsonb),
