UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Antoninus of Pamiers, an early Christian missionary and martyr, is known as the "Apostle of the Rouergue". Because he is frequently confused with other venerated Antonini, sources date his life variously, to the first, the second, the fourth, or the fifth century. He is revered today as the patron saint of Pamiers, of Palencia, and of Medina del Campo. Doubt surrounds both his historicity and his exact identity.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Antoninus_of_Pamiers", "biography": "rewritten"}'::jsonb),
