UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Living as a hermit during the era of King Liutprand of the Lombards, Saint Baudolino dwelt at Forum Fulvii, a locality along the lower Tanaro river in the north-west of Italy. It is said that he came from a noble family, but gave his entire fortune to the poor and then moved into a wretched hut near the river. Alessandria, the neighbouring city, honors him as its patron saint, and keeps his feast on the Sunday following 10 November.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Baudolino", "biography": "rewritten"}'::jsonb),
