UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Catellus of Castellamare was bishop of Castellamare di Stabia, and Saint Antoninus of Sorrento was a close friend of his. According to tradition, Antoninus fled the Lombard invasions and made for Campania, ending up at Castellammare di Stabia. Catellus was bishop there, but he wanted to become a hermit, so he resigned as bishop and handed the duty of serving as the town''s bishop to Antoninus. Catellus retired to Monte Aureo.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Catellus_of_Castellammare", "biography": "rewritten"}'::jsonb),
