UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Odile of Alsace, also called Odilia and Ottilia, was born c. 662 and died c. 720 at Mont Sainte-Odile. Both the Roman Catholic Church and the Eastern Orthodox Church honor her as a saint. She is patroness of Alsace, the region, and of good eyesight.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Odile_of_Alsace", "biography": "rewritten"}'::jsonb),
