UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Bartolo da San Gimignano, an Italian Roman Catholic priest, belonged to the Third Order of Saint Francis. Born to nobles near Siena, he ran away from home to become a priest, escaping his father''s wrath. He looked after poor people in the streets, using his income to give them alms and ease their suffering. Working among the poor, he caught a disease, and it eventually caused his death.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Bartolo_da_San_Gimignano", "biography": "rewritten"}'::jsonb),
