UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Born in 1268, Clare of Montefalco (also called Saint Clare of the Cross) died August 18, 1308. An Augustinian nun and abbess, she had earlier belonged to the Third Order of St. Francis. On December 8, 1881, Pope Leo XIII canonized her.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Clare_of_Montefalco", "biography": "rewritten"}'::jsonb),
