UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Aquilinus, a Frankish bishop and hermit, was born in Bayeux. He had served as a warrior under Clovis II and married at Chartres in 660. He then settled in Évreux with his wife, and the two of them looked after the poor and sick of the town. In 670 he was appointed bishop of the city, yet Aquilinus chose the hermit''s life instead. His feast day: 19 October.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Aquilinus_of_%C3%89vreux", "biography": "rewritten"}'::jsonb),
