UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Austrebertha lived in France during the Middle Ages as a nun. She took the veil at a very young age; at Port Monastery in the Ponthieu she entered religious life. She later became abbess of the foundation at Pavilly, and died there aged 74 at the start of the eighth century. Both the Catholic and the Eastern Orthodox Churches venerate her as a saint. Her feast day is February 10.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Austrebertha", "biography": "rewritten"}'::jsonb),
