UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Francisco de Paula Castelló Aleu was a Spanish Roman Catholic who was killed in the Spanish Civil War after being falsely accused of fascism. He was known for being devout and outgoing, and was an activist in Christian movements, Catholic Action among them. He made friends through these movements, and met his fiancée in one of them, though his death ended their planned marriage. For a time he worked as a chemist, before being conscripted into military service just before the civil war began.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Francesc_de_Paula_Castell%C3%B3_Aleu", "biography": "rewritten"}'::jsonb),
