UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Laura of Cordoba, born in Córdoba, was a Spanish Christian of the 9th century, when Spain was under Muslim rule. After her husband died she became a nun at Cuteclara, where she was eventually made abbess. Saint Eulogius of Córdoba relates that Muslims took her captive and martyred her by scalding, lowering her into a vat of pitch that was boiling. Her feast falls on 19 October, and she is counted among the Martyrs of Córdoba.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Laura", "biography": "rewritten"}'::jsonb),
