UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Portuguese mystic and victim soul Alexandrina Maria da Costa, whom people best know as Blessed Alexandrina of Balazar, was born and died in Balazar and belonged to the Association of Salesian Cooperators. Pope John Paul II declared her blessed on 25 April 2004, saying that love for Christ was the secret of her holiness.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Alexandrina_of_Balazar", "biography": "rewritten"}'::jsonb),
