UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Albinus of Angers, known in English as Saint Albin, was a French abbot and bishop. He was born at Vannes in Brittany, into a noble family of Gallo-Roman descent. As a monk, he became Abbot of Tintillac from 504 A.D., and his reputation grew over the twenty-five years of his abbacy. In 529 he was chosen Bishop of Angers, though he did not want the office.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Albinus_of_Angers", "biography": "rewritten"}'::jsonb),
