UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A Portuguese princess of the House of Aviz, Joanna of Portugal OP had King Afonso V of Portugal as her father and Queen Isabel of Coimbra, his first wife, as her mother. In 1471 she acted as regent while her father was away. She entered the Dominican Order as a cloistered nun in 1475. The Catholic Church venerates her as ''Blessed'' and keeps her feast on May 12; in Portugal she is widely called Holy Princess Joan.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Joanna%2C_Princess_of_Portugal", "biography": "rewritten"}'::jsonb),
