UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Susanna of Rome was a Christian who died as a martyr in the Diocletianic Persecution. Her surviving hagiography, composed between about 450 and 500 AD, has no historical value; the family relations it attributes to her are wholly fictitious. A real martyr called Susanna is probably behind the literary invention.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Susanna_of_Rome", "biography": "rewritten"}'::jsonb),
