UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The Martyrs of Albania were a group of 38 people killed under Albania''s Communist regime between 1945 and 1974, a time when the government enforced state atheism. They were born at different times between 1874 and 1935; Albanians and Italians were among them, along with one German. All but four of them lived the religious life as priests or religious, and they worked as missionaries or educators; a great many had spent their years of schooling and formation in cities of Italy and Austria.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Martyrs_of_Albania", "biography": "rewritten"}'::jsonb),
