UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Mary Euphrasia Pelletier, RGS, was a French religious sister whose religious name was Mary of Saint Euphrasia; she was born Rose Virginie Pelletier. As foundress of the Sisters of the Good Shepherd, she also served as its first superior general.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Mary_Euphrasia_Pelletier", "biography": "rewritten"}'::jsonb),
