WHERE content."id" = 'cmqa5g3fh029s5krppltlqkws'
  AND content."slug" = 'saint-abakuh'
  AND md5(content."payload"->>'biography') = 'fd2f0fed46a7c07d5ca8502c8490ce0a';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Emmeram of Regensburg, a bishop and martyr, was born in Poitiers, Aquitaine. After hearing of idolatry in Bavaria, he went to Ratisbon (Regensburg), some time after 649, and presented himself at the court of Theodo I, who was Duke of Bavaria. He is supposed to have journeyed up the Loire, through the Black Forest, and then along the Danube to Regensburg. Theodo received him at court, where Emmeram spent three years in missionary work and won a name for piety. He died circa 652, and his tomb is in St. Emmeram''s, in Regensburg, Germany. The Catholic Calendar of saints marks his feast day on September 22.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Emmeram_of_Regensburg", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmqa5g3kg029v5krpqhg6qkdl'
