  AND md5(content."payload"->>'biography') = 'ca18954b6abaf36fe6a4b14200666ec7';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Álvaro of Córdoba, OP, lived c.1350–c.1430. He was a Spanish Dominican friar, and the Catholic Church venerates him. A native of Zamora, he entered, in 1368, the Order of Preachers, then went on to preach across Spain and Italy.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/%C3%81lvaro_of_C%C3%B3rdoba_(Dominican)", "biography": "rewritten"}'::jsonb),
