UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Founded in Paris, France, in 1856, the Society of Helpers is a women''s Roman Catholic religious congregation, once styled Helpers of the Holy Souls. It aims to help the souls in Purgatory by serving the needy of the world. In Europe the Sisters put "A.P." after their names, while in English-speaking countries they alternatively use "H.H.S".'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Society_of_the_Helpers_of_the_Holy_Souls", "biography": "rewritten"}'::jsonb),
