UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Osgyth, a Mercian noblewoman and prioress, has been honoured as an English saint from the 8th century, beginning soon after she died. The main place that remembers her is St Osyth, a village near Colchester in Essex. Her name is also spelled Sythe, Othith or Ositha. Of noble birth, she became a nun and established a priory near Chich, later renamed in her honour.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Osgyth", "biography": "rewritten"}'::jsonb),
