UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Lambert of Maastricht, usually called Saint Lambert, held the see of Maastricht-Liège (Tongeren) as bishop from about 670 until he died. He criticized Pepin for his relationship with Alpaida, described as a mistress or a bigamous wife, who was Charles Martel''s mother. The bishop was killed amid political upheaval, as rival families competed for influence while the Carolingians were replacing the Merovingian dynasty. September 17 is his feast day.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Lambert_of_Maastricht", "biography": "rewritten"}'::jsonb),
