UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Alypius of Thagaste held the see of Thagaste as bishop in 394. A friend of Augustine of Hippo throughout his life, he shared in Augustine''s conversion and in his Christian life. He is credited with assisting in the founding of Augustine''s monastery in Africa. Nearly everything we know of him comes from Augustine''s autobiographical Confessions.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Alypius_of_Thagaste", "biography": "rewritten"}'::jsonb),
