UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Alèthe de Montbard (also Aleth or Alette, and called Alix or Alice) lived from 1070 to 1107. She is a saint, and Saint Bernard of Clairvaux was her son. 4 April is her feast day. The Greek name "Alethea" ("truth" or "reality") has Alèthe as a variant.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Al%C3%A8the_de_Montbard", "biography": "rewritten"}'::jsonb),
