UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'In Augusta Emerita, capital city of Lusitania, a young Roman Christian named Eulalia of Mérida was martyred when Diocletian persecuted Christians. Some views date her death to the time of Trajan Decius. Scholars debate whether she is identical with Saint Eulalia of Barcelona, who has a similar story. Until James, son of Zebedee, was proclaimed, she was invoked to protect Christian soldiers during the Reconquista, and she was patron of Spain''s territories while they were taking shape.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Eulalia_of_M%C3%A9rida", "biography": "rewritten"}'::jsonb),
