UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'André Abellon, O.P., was a French Catholic priest of the Order of Preachers. After he heard Vincent Ferrer preach, he became a Dominican, having first studied art. He won fame as a preacher and confessor, and became prominent through caring for plague victims at Aix-en-Provence in 1445. Some of the works of this noted artist and painter are still preserved today.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Andr%C3%A9_Abellon", "biography": "rewritten"}'::jsonb),
