UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Luca Antonio Falcone, who took the name Angelo in religious life, was an Italian priest of the Roman Catholic Church, professed as a Franciscan in the Order of Friars Minor Capuchin at Cosenza. His path into religious life was difficult, since he entered and left the order several times, and his first few sermons drew few listeners. He later became a noted preacher in southern Italian cities including Catanzaro and Salerno. He came to be styled the "Angel of Peace" as well as the "Apostle of the South".'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Luca_Antonio_Falcone", "biography": "rewritten"}'::jsonb),
