UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Vidal, a third-century saint of the Catholic Church, was born at Complutum during the period of Roman rule over the Iberian peninsula (3rd century). His father was Natal the Confessor, a resident of Rome under Pope Zephyrinus, and his family was notable. Felipe de la Gándara also related that Marcellus of León was a brother of Vidal. According to tradition, as recorded by Braulio of Zaragoza, Marta de Astorga was Vidal''s sister or half-sister, even though her martyrdom took place in 250 AD, among other differences.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Vidal_(martyr)", "biography": "rewritten"}'::jsonb),
