  AND md5(content."payload"->>'biography') = '382b0ebdc57196330deb4ba213bc861e';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Venerated as Saint Aurea of Paris, Aurea was, in the seventh century, abbess of Saint Martial in Paris, when Dagobert I and Clovis II reigned. Prior to the 1054 Great East-West Schism her feast day was 4 October everywhere, and the Orthodox Church still keeps that date. Post-Schism Catholics are not recognised as saints by the Orthodox Church. Catholics moved her feast to 5 October after they began venerating St Francis of Assisi.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Aurea_of_Paris", "biography": "rewritten"}'::jsonb),
