UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Finbar (also Finbarr, Finnbar or Finnbarr; Fionnbharra in Irish, often shortened to Barra) served as Bishop of Cork and as abbot of a monastery on the site of today''s city of Cork, Ireland. The city and the diocese of Cork both have him as their patron saint, and 25 September is his feast day.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Finbar_of_Cork", "biography": "rewritten"}'::jsonb),
