UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A Christian saint, Justina of Padua is a patroness of Padua, and her feast day is October 7. From her earliest years she was devoted to religion, and she took the vow of perpetual virginity. Brought before the prefect Maximian, she stood firm against every attack. The prefect had her killed with a sword.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Justina_of_Padua", "biography": "rewritten"}'::jsonb),
