UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Marguerite d''Youville, SGM was a widow from French Canada and the founder of the Sisters of Charity of Montreal, popularly called the "Grey Nuns". Pope John Paul II canonized her in 1990, making her the first Canadian-born person declared a saint.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Marie-Marguerite_d''Youville", "biography": "rewritten"}'::jsonb),
