UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Claudius of Besançon, a saint sometimes known as Claude the Thaumaturge, held the roles of priest, monk, abbot, and bishop. Born in Franche-Comté, he was ordained a priest at Besançon and afterwards became a monk. In the Catholic Encyclopedia, Georges Goyau wrote that the biography of St. Claudius, Abbot of Condat, is much debated. Henry Wace, an Anglican, claimed that "inventors of legends" have, around this saint, compiled "a vast farrago of improbabilities."'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Claudius_of_Besan%C3%A7on", "biography": "rewritten"}'::jsonb),
