UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Swithun Wells, an English Roman Catholic martyr, was put to death under Elizabeth I. A country gentleman who had once worked as a schoolmaster, he and his family gave shelter to priests being hunted by the authorities. He frequently organized their passage between one safehouse and another. His house in Gray''s Inn Lane had a reputation for welcoming recusants.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Swithun_Wells", "biography": "rewritten"}'::jsonb),
