SET "payload" = content."payload" || jsonb_build_object('biography', 'Polydore Plasden (1563–1591) belonged to the Catholic Forty Martyrs of England and Wales. Born in London, he pursued his priestly studies at Rheims and Rome. He was ordained in 1586 and, shortly afterward, dispatched back to England.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Polydore_Plasden", "biography": "rewritten"}'::jsonb),
