UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The Italian Dominican priest and martyr Anthony Neyrot (OP) was seized by Barbary corsairs in 1458, and in return for improved treatment he gave up Catholicism. A few months afterward he heard that his mentor, Antoninus of Florence, had died, and this led him to rethink what he had done. He was then put to death for rejecting Islam.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Anthony_Neyrot", "biography": "rewritten"}'::jsonb),
