UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Ælfflæd (654–714) had King Oswiu of Northumbria and Eanflæd as her parents. From 680, when her kinswoman Hilda died, she served as abbess of Whitby Abbey, whose community of nuns was noted for medical skill; at first she ruled together with her mother and afterward alone.
Ælfflæd was especially noted for surgical skill and for attending to patients personally, just as Hilda, who was known for individualized medical care, had been.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/%C3%86lffl%C3%A6d_of_Whitby", "biography": "rewritten"}'::jsonb),
