UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Senán mac Geircinn was a Christian minister in Ireland who lived in Munster. Irish tradition holds him in high regard as the founder of Inis Cathaigh and the patron of the Uí Fhidgeinte as well as the Corco Baiscinn. He counts among the Twelve Apostles of Ireland.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Sen%C3%A1n_mac_Geirrcinn", "biography": "rewritten"}'::jsonb),
