UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Ælfthryth, a princess of Mercia, saint, virgin, and recluse, honored by both the Catholic Church and the Antiochian Orthodox Church, goes by several other names too: Alfreda, Alfritha, Aelfnryth, or Etheldritha. Her father was King Offa of Mercia, and her mother was his consort, Cynethryth.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/%C3%86lfthryth_of_Crowland", "biography": "rewritten"}'::jsonb),
