UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Luke of Steiris, also called Luke, Luke the Younger, Luke of Hellas and Luke the Wonder-worker, was a saint from Byzantium in the tenth century AD. He lived in Greece, in the provinces known as the themes of Hellas and Peloponnese, and founded the Monastery of Hosios Loukas, which stands on Mount Helicon''s slopes between Delphi and Levadia, near the Gulf of Corinth shore in Boeotia, Greece. He ranks among the first saints reported to have levitated while praying.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Luke_of_Steiris", "biography": "rewritten"}'::jsonb),
