UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Brendan of Birr was an early Irish monastic saint of the 6th century, first a monk and later an abbot. He is called "Saint Brendan the Elder" so that he is not mistaken for his friend and contemporary Brendan the Navigator of Clonfert. A friend and disciple of Columba, he was counted among the Twelve Apostles of Ireland.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Brendan_of_Birr", "biography": "rewritten"}'::jsonb),
