UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Petrus Norbertus Donders was a Dutch Roman Catholic priest and a Redemptorist. His missions were located in Surinam, a Dutch colony, beginning in the capital Paramaribo. He is best known for his labors at Batavia, a leper colony, and in its surroundings, and he died there in 1887. In 1982 he was beatified and given the title ''Apostle of the Indians and Lepers''. A Dutch child healed of bone cancer in 1929 supplied the miracle his beatification required.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Peter_Donders", "biography": "rewritten"}'::jsonb),
