  AND md5(content."payload"->>'biography') = 'bd55be6a638d1fb23fb1a3c61eaae7be';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Hyacintha Mariscotti, T.O.R., also called Hyacintha of Mariscotti, was a religious sister from Italy, belonging to the Third Order Regular of St. Francis. Born to a noble family in 1585 at Vignanello, a town of the Province of Viterbo, she died in Viterbo on 30 January 1640; people noted how deep her spiritual gifts ran. The Catholic Church honors her as a saint.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Hyacintha_Mariscotti", "biography": "rewritten"}'::jsonb),
