UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Born Francesco Pontillo, Egidio Maria of Saint Joseph was a professed religious from Italy who belonged to the Order of Friars Minor. Because he lacked a proper education, Pontillo became a Franciscan brother and not an ordained priest, and he gave himself to looking after the poor and sick in the cities of southern Italy, for example Taranto and Naples, and there people called him the "Consoler of Naples".'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Egidio_Maria_of_Saint_Joseph", "biography": "rewritten"}'::jsonb),
