UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Itta of Metz, OSB, was married to Pepin of Landen, who was Mayor of the Palace in the Kingdom of Austrasia. When he died, Itta established the Abbey of Nivelles, a double monastery housing both monks and nuns, and became a Benedictine there together with her daughter, Gertrude of Nivelles. The Roman Catholic Church honors both as saints.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Itta_of_Metz", "biography": "rewritten"}'::jsonb),
