UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Giovanni Pelingotto, an Italian Roman Catholic and a member of the Secular Franciscan Order, came from Urbino and lived as an almsgiver and hermit. He worked in his father''s business until he left it and gave as much in alms as he could to the less fortunate around him. This brought him into contact with the Franciscans, and that opened him to a deeper service of God and the poor.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Giovanni_Pelingotto", "biography": "rewritten"}'::jsonb),
