UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Bartolomeo Cerveri, OP was an Italian Catholic priest of the Order of Preachers. He worked as inquisitor for Piedmont and Liguria, was aware of threats to his life, and was killed in Cuneo by a small band of heretics. Pope Pius IX beatified him in 1853.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Bartolomeo_Cerveri", "biography": "rewritten"}'::jsonb),
