UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Rafaela Ybarra Arambarri de Vilallonga, a Spanish Roman Catholic widow, is the founder of Sisters of the Holy Guardian Angels. She belonged to the upper class of Bilbao, and she and her husband José Vilallonga had seven children.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Rafaela_Ybarra_de_Vilallonga", "biography": "rewritten"}'::jsonb),
