UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Anne of Saint Bartholomew was a Spanish Discalced Carmelite and a companion of Teresa of Ávila, and she founded new monasteries in France as well as the Low Countries. She at times clashed with her superiors while founding convents and serving as a prioress. Later she made her home in the Spanish Netherlands, where she opened a house and stayed until she died in 1626. She was beatified in 1917 by Pope Benedict XV.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Anne_of_Saint_Bartholomew", "biography": "rewritten"}'::jsonb),
