UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Gregorio Celli, an Italian Roman Catholic priest, was a professed member of the Augustinians, the Order of Saint Augustine. He lived in Rimini with that order until he resolved to spend his remaining years in deep contemplation, and so went to the hills of the region and lived in a cave close to the Franciscans based there. One claim says that his order expelled him and that he became a Franciscan, but nothing supports this.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Gregorio_Celli", "biography": "rewritten"}'::jsonb),
