UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Celine Chludzińska Borzęcka, a Roman Catholic professed religious, was co-foundress of the Sisters of the Resurrection; her daughter Jadwiga Borzęcka founded it with her. She longed for religious life but, obeying her parents, married and had four children, two of whom died in infancy. When her husband died, she chose the spiritual path with her daughter beside her and started a life in community in Rome.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Celine_Borzecka", "biography": "rewritten"}'::jsonb),
