UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Hemma of Gurk, called Emma of Gurk as well, was a Fürstin (princess), a noblewoman, and the founder of numerous churches and monasteries within the Duchy of Carinthia. Beatified on 21 November 1287, she was canonised by Pope Pius XI on 5 January 1938. Her burial at Gurk Cathedral dates from 1174. Her feast day is 27 June. She is venerated as a saint in the Catholic Church as well as the Eastern Orthodox Church, and she is patroness of the present Austrian state of Carinthia.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Hemma_of_Gurk", "biography": "rewritten"}'::jsonb),
