UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Tryphine, a Breton saint, is semi-legendary, and her life is often thought to underlie the tale of Bluebeard. Across Brittany people widely revere her as patron of sick children and of those whose birth is overdue. Her legend probably comes from a real person, the wife of Conomor, an early Breton ruler.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Tryphine", "biography": "rewritten"}'::jsonb),
