UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Agathangelus of Rome was a martyr in the reign of emperor Diocletian. A Roman deacon, he was a disciple of Clement of Ancyra. He met Clement while Clement was imprisoned in Rome, then travelled back to Ancyra with him, and both men were beheaded there. His feast day, shared with Clement, is January 23 by the Gregorian calendar and February 5 by the Julian calendar, which some Eastern Orthodox countries use.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Agathangelus_of_Rome", "biography": "rewritten"}'::jsonb),
