UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Galgano Guidotti was a Catholic saint of Tuscany, born at Chiusdino in what is now the province of Siena, Italy. His mother was named Dionigia; his father''s name first shows up in a 16th-century document, which is when the surname Guidotti was assigned. He is associated with the Sword in the Stone relic near the Abbey of San Galgano''s ruins outside Siena.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Galgano_Guidotti", "biography": "rewritten"}'::jsonb),
