UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The Church of the East counts Saint Mari [ܡܳܐܪܝ̣] among its saints. He was originally named Palut [ܦܳܠܘ̣ܛ]; other forms of his name are Mares and Maris [Μαρις]. Thaddeus of Edessa ("Addai" is another name for him) converted him, and he is said to have had Mar Aggai as his spiritual director. People venerate him as the Apostle of Persia.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Mari_of_Edessa", "biography": "rewritten"}'::jsonb),
