UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Louis Aleman, a French Roman Catholic cardinal, was a professed member of the Canons Regular of Saint John Baptist, which is now suppressed. He was Archbishop of Arles from 1423 until 1440, the year he resigned, and he gave up the cardinalate as well. On 19 December 1449 he was restored as a cardinal, serving as Protopriest and regaining his titular church.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Louis_Aleman", "biography": "rewritten"}'::jsonb),
