UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A legendary child of medieval Spain, Dominguito del Val is said to have been a choirboy murdered in a ritual by Jews in Zaragoza (Saragossa). He features in one of the earliest blood libel stories in Spanish history, a kind of tale that became more prominent during the 12th and 13th centuries and helped fuel antisemitism in late medieval Spain. The legend holds that the Jews of Zaragoza murdered Dominguito in a ritual.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Dominguito_del_Val", "biography": "rewritten"}'::jsonb),
