UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Augustin Kažotić was a prelate from Croatia serving the Catholic Church, and a professed member of the Order of Preachers. He held the see of Zagreb as bishop from 1303 to 1322, and the see of Lucera from 1322 until he died. A humanist and orator, he studied in Paris, then went back to his homeland, where he took up missionary work and preaching in what is now Bosnia and Herzegovina. He was among the first humanist figures to emerge in southern Croatia.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Augustin_Ka%C5%BEoti%C4%87", "biography": "rewritten"}'::jsonb),
