UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Valerie of Limoges, tied to the Roman period, is a legendary figure: a Christian martyr and cephalophore. Her cult was very important in medieval Limousin, France. She has long been an important subject in Christian art, from the Middle Ages onward, and in porcelain figurines made over several centuries.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Valerie_of_Limoges", "biography": "rewritten"}'::jsonb),
