UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Dionysius Exiguus was a monk of the Eastern Roman Empire in the 6th century, born in Scythia Minor and working in Rome. He belonged to a community of Scythian monks centred in Tomis, the chief city of Scythia Minor. He is chiefly remembered as the originator of Anno Domini (AD) dating, the system that numbers years in the Gregorian calendar as well as in the Julian calendar once Christianised. His computus for calculating the date of Easter was taken up by nearly all churches.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Dionysius_Exiguus", "biography": "rewritten"}'::jsonb),
