UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The Catholic Church venerates Adjutor as a saint. He is credited as the patron of Vernon, France, and of boaters, swimmers and those who drown. His birth took place on July 24, 1073, in Vernon, France; during the First Crusade he was made a knight. Accounts differ about why he is the patron of boaters. In one common version, Muslims captured Adjutor during the First Crusade and tried to make him give up his faith; he refused and avoided persecution by swimming away, swimming all the way back to France. He then entered the Abbey of Trion, where he was a recluse; he died on April 30.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Adjutor", "biography": "rewritten"}'::jsonb),
