UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Agatha Lin (林昭) was a Chinese saint and martyr, born in 1817 at Qinglong in Guizhou province, southwest China. A headmistress and catechist, she was among the first to bring the Gospel to the Miao. For her faith she was beheaded on January 28, 1858. Pope Pius X beatified her on May 2, 1909, and she was canonized in 2000. Her feast day falls on February 18.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Agatha_Lin", "biography": "rewritten"}'::jsonb),
