UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The Roman Catholic Church venerates Saint Latuinus as a saint. He is regarded as the earliest bishop of Sées, serving in the 5th century, between 400 and 440 AD. Louis Duchesne, as the Catholic Encyclopedia reports, believed that the episcopal catalogue of Séez, known through certain compilations of the sixth century, cannot be relied upon for any period before 900.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Latuinus", "biography": "rewritten"}'::jsonb),
