UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Giuseppe Oddi, though not a priest, was an Italian professed religious of the Roman Catholic Church in the Franciscan Order of Friars Minor Capuchin. After his adolescence he felt drawn to religious life, and he resolved to become a Franciscan on seeing the example of Mariano da Roccacasale. When he took his vows he received the religious name "Diego da Vallinfreda".
Oddi and Mariano da Roccacasale were both beatified on 3 October 1999, in a ceremony led by Pope John Paul II.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Giuseppe_Oddi", "biography": "rewritten"}'::jsonb),
