UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Julius and Aaron were two Christian saints of Romano-British background, martyred about the third century AD. Apart from Saint Alban, they are the only Christian martyrs from Roman Britain known by name. Most historians locate their martyrdom at Caerleon, though Chester and Leicester have also been proposed. Their feast day was once kept on 1 July; today the Roman Catholic and Anglican Churches observe it on 20 June, together with Alban.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Julius_and_Aaron", "biography": "rewritten"}'::jsonb),
