UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Domenico Lentini was an Italian Roman Catholic priest, ordained in 1794, who spent his whole life as a parish priest in his native Potenza. There he encouraged Eucharistic devotion and labored alongside the area''s poor. He also advanced education and evangelization, frequently taught catechism and literature to his parishioners, and was always ready to hear penitents'' confessions.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Domenico_Lentini", "biography": "rewritten"}'::jsonb),
