UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The Carmel of Compiègne in France gave the Church 16 martyrs: 11 Discalced Carmelite nuns, two externs and three lay sisters. Near the close of the Reign of Terror, on 17 July 1794, the guillotine executed them at the spot in Paris now called Place de la Nation. The Catholic Church venerates them as martyr saints. Maximilien Robespierre was himself executed ten days after they died, which brought the Reign of Terror to an end. Their story inspired a novella and a motion picture, as well as a television movie and the opera Dialogues of the Carmelites by the French composer Francis Poulenc.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Martyrs_of_Compi%C3%A8gne", "biography": "rewritten"}'::jsonb),
