UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Donnán of Eigg was a priest of Gaelic origin, probably from Ireland, who tried to carry the Christian faith to the Picts in the northwest of Scotland during the Early Middle Ages. Eigg, an island in the Inner Hebrides, is where he was killed, and he is its patron saint.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Donn%C3%A1n_of_Eigg", "biography": "rewritten"}'::jsonb),
