UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Jænberht was a medieval monk who later became abbot of St Augustine''s Abbey, Canterbury, and was appointed Archbishop of Canterbury in 765. His relationship with King Offa of Mercia as archbishop was difficult; at one point Offa seized lands belonging to the archbishopric. Some of the bishoprics Canterbury supervised were moved by 787 to the newly created Archbishopric of Lichfield, though whether Jænberht ever accepted its legitimacy is unclear. Apart from the Lichfield matter, he also chaired church councils held in England. After his death in 792 he came to be regarded as a saint.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/J%C3%A6nberht", "biography": "rewritten"}'::jsonb),
