UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The bishop of Susa in Iran was Abdas; he is described by Socrates of Constantinople as "bishop of Persia". He had destroyed a Zoroastrian fire temple, and when he refused to rebuild it, shah Yazdegerd I ordered his execution.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Abdas_of_Susa", "biography": "rewritten"}'::jsonb),
