UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The Catholic Church and the Eastern Orthodox Church recognize Abdon and Sennen as Christian martyrs; early calendars and martyrologies variously give their names as Abdo, Abdus, and Sennes, Sennis, Zennen. Their feast day is 30 July, and some places have also honoured them on 20 March and on the first Sunday of May.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Abdon_and_Sennen", "biography": "rewritten"}'::jsonb),
