UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Nikodim Tismanski, a Christian monk, scribe and translator, was the founder of three monasteries (one in Serbia, two in Romania). His other names include Nicodemus the Sanctified, Nikodim Osvećeni, Nikodim Vratnenski, Nikodim Grčić, and, in Romanian, Nicodim de la Tismana. Serbian medieval history recalls him for passing on hesychastic monastic traditions, and for taking part in the 1375 diplomatic and ecclesiastical mission to Constantinople. He followed St. Gregory of Sinai. The Eastern Orthodox Church sanctified him in 1767, commemorating him on 26 December; the Romanian Orthodox Church also glorified him, in 1955.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Nicodemus_of_Tismana", "biography": "rewritten"}'::jsonb),
