UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A saint of the Roman Catholic Church, Galdino della Sala (Galdinus or Galdimus) came from Milan in northern Italy. Raised to cardinal in 1165, he was Archbishop of Milan from 1166 until he died in 1176. He gave firm backing to Pope Alexander III, and to Milan and its Lombard neighbours, in the shared, parallel struggles they waged against Antipope Victor IV, whom Holy Roman Emperor Frederick I Barbarossa supported.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Galdino", "biography": "rewritten"}'::jsonb),
