UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Gregory the Illuminator was founder of the Armenian Apostolic Church and its first official leader. In the early fourth century he led Armenia from Zoroastrianism to Christianity, so that Armenia became the first state to take Christianity as its official religion. The Armenian Apostolic Church venerates him as a saint, as do some other churches.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Gregory_the_Illuminator", "biography": "rewritten"}'::jsonb),
