UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Erik (also Eric IX or Erik Jedvardsson) ruled Sweden as king from c. 1156 until 1160, when he died. The Roman Martyrology of the Catholic Church lists him among saints commemorated on 18 May. As founder of the House of Erik, he began a dynasty; from c. 1156 to 1250 it governed Sweden, though not continuously.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Erik", "biography": "rewritten"}'::jsonb),
