UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Giuseppe Girotti, OP, an Italian Dominican priest, was a scholar of the Bible and a professor of theology. In World War II he helped Jewish people during the Nazi Holocaust. Arrested in 1944, he was passed from one prison to another and finally held at Dachau, a concentration camp, where he formed friendships with Josef Beran and Carlo Manziana.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Giuseppe_Girotti", "biography": "rewritten"}'::jsonb),
