UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Gregory of Autun, who is also named Gregory of Langres, was a prelate of Gallo-Roman background. He was born around 446 and was count at Autun, in Saone-et-Loire. Once a widower, towards 500 he became bishop of Langres, an office he held from 506 until his death in 539. The Eastern Orthodox Church counts Gregory as a Saint and keeps his feast day on 4 January.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Gregory_of_Langres", "biography": "rewritten"}'::jsonb),
