UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Guillaume Courtet, O.P. (1589–1637), came from France and was a Dominican friar, a Catholic priest and a missionary. He was among the first Frenchmen to go to Japan. Three days of unbroken torture preceded his death as a martyr in Nagasaki, where the Tokugawa Shogunate had him beheaded on Michaelmas Day 1637. Pope John Paul II canonised him in 1987, counting him among the 16 Martyrs of Japan. On September 28th he is celebrated among the 16, and on November 6th among the Thomasian Martyrs.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Guillaume_Courtet", "biography": "rewritten"}'::jsonb),
