  AND md5(content."payload"->>'biography') = '70381ce8c363c1aee68381e26bcede9e';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Guillaume Pinchon, a French Catholic prelate, was appointed in 1220 as Bishop of Saint-Brieuc, a post he held to the end of his life. He championed the poor and defended the Church''s rights and privileges against secular intervention, though that cause brought about his exile from the diocese. Not long afterward he came back and set about building a new cathedral, which was still being built when he died.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/William_Pinchon", "biography": "rewritten"}'::jsonb),
