UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Bruno is the name under which Bruno of Cologne is venerated. He was the founder of the Carthusians and personally established the first two communities of the order. He taught with great renown at Reims, and he later became a close counsellor to Pope Urban II, who had once been his pupil. His feast is on 6 October.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Bruno_of_Cologne", "biography": "rewritten"}'::jsonb),
