UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A deacon, confessor and martyr from 4th-century Syria, Abibus of Edessa went by other names too: Abibus the New, Habib the Deacon and Saint Habibus the Martyr. The Martyrdom of Habib the Deacon says he was executed at Edessa by burning under Roman Emperor Licinius. Catholic, Eastern Orthodox and Oriental Orthodox Churches alike venerate him as a saint.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Abibus_of_Edessa", "biography": "rewritten"}'::jsonb),
