UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Alban is venerated as the earliest recorded Christian martyr of Britain, and so is regarded as its protomartyr. He is one of three martyrs from Roman Britain named in early records, the others being the saints Julius and Aaron. Tradition holds that he was beheaded at Verulamium in the 3rd or 4th century, and he has been honored there since ancient times.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Alban", "biography": "rewritten"}'::jsonb),
