UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'An Italian chronicler and the archbishop of Genoa, Jacobus de Voragine (OP) wrote, or more precisely compiled, the Golden Legend, a gathering of legendary accounts of the lives of the major saints of the medieval church, which ranked among the most widely read religious books of the Middle Ages.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Jacobus_de_Voragine", "biography": "rewritten"}'::jsonb),
