UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Honorina was a virgin martyr of the 3rd century from northern Gallo-Roman France; the Catholic and Eastern Orthodox Churches venerate her as a saint. According to belief, she died in the opening years of the 4th century amid Diocletian''s persecutions. Beyond her reputed martyrdom for keeping her Christian faith, her life is almost wholly unknown.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Honorina", "biography": "rewritten"}'::jsonb),
