UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Simpert, an abbot, bishop, and confessor at the end of the 8th century and start of the 9th, was supposedly a nephew of Charlemagne. He studied in Alsace, at Murbach Abbey, where he received the Benedictine habit and was chosen as abbot. Charlemagne made him bishop of Augsburg in 778. He strengthened and secured the jurisdiction of his diocese, and he lived in turn at Neuburg an der Donau, Staffelsee Abbey, and Augsburg.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Simpert", "biography": "rewritten"}'::jsonb),
