UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Hydulphe, also spelled Hydulphus, Hidulphe or Hidulf, a Frankish saint, is commonly known as Hydulphe of Lobbes, in French Hydulphe de Lobbes. He assisted Saint Landelin in establishing Lobbes Abbey, Crespin Abbey, and Aulne Abbey.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Hidulf_of_Lobbes", "biography": "rewritten"}'::jsonb),
