UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Jean-Baptiste Fouque, a French Roman Catholic priest, cared for the poor while serving his parish in Marseille, and was known for wanting to build a large hospital that would be free to them. In 1921 he accomplished this, and looked after the elderly and infirm there. He was also known for ministering to displaced people in World War I and for his dedication to evangelization.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Jean-Baptiste_Fouque", "biography": "rewritten"}'::jsonb),
