UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Sabas (439–532) was a saint, grazer, priest and monk, a Greek from Cappadocia, known in Church usage as Saint Sabas or Sabbas the Sanctified. Born in Cappadocia, he spent most of his life in Palaestina Prima. The saint''s name is rooted in סַבָּא (Sabbāʾ), an Imperial Aramaic word for "old man". A founder of several convents, he is best known for the one called Mar Saba, in Palestine.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Sabbas_the_Sanctified", "biography": "rewritten"}'::jsonb),
