UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Lanfranc, born in Italy, was an English churchman, monk and scholar. He went to Normandy and became a Benedictine monk at Bec. In turn he was prior of Bec Abbey, abbot of St Stephen''s Abbey at Caen in Normandy, and, after William the Conqueror''s conquest of England, Archbishop of Canterbury. He is also called Lanfranc of Pavia, Lanfranc of Bec, and Lanfranc of Canterbury. His contemporaries ranked him as their generation''s greatest theologian.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Lanfranc", "biography": "rewritten"}'::jsonb),
