UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The Spanish missionary José de Anchieta y Díaz de Clavijo, SJ, worked in the Portuguese colony of Brazil during the latter half of the 16th century. He had great influence on Brazilian history during the first century after Europeans reached it, and was one of the founders of both São Paulo (1554) and Rio de Janeiro (1565). Born in the Canary Islands, he was the first playwright, first grammarian and first poet from there, and is regarded as the father of Brazilian literature.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Joseph_of_Anchieta", "biography": "rewritten"}'::jsonb),
