UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Vincent Ferrer, OP, a Dominican friar from Valencia, won renown as a preacher, missionary and logician. He first backed Antipope Benedict XIII during the Western Schism, and afterwards journeyed through Western Europe and the British Isles to preach. Some sources credit his sermons with bringing 25,000 Jews to Catholicism, while others say they included support for coercion, for instance turning synagogues into churches by force. He was canonized in 1455.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Vincent_Ferrer", "biography": "rewritten"}'::jsonb),
