UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'From 516 until his death, Sigismund was King of the Burgundians. His parents were king Gundobad and Caretene, and he succeeded his father in 516. Clovis''s sons defeated Sigismund and his brother Godomar in battle, and Godomar fled. Chlodomer, King of Orléans, captured Sigismund and held him prisoner. Afterward Sigismund was executed, along with his wife and children. Godomar then gathered the Burgundian army again and won his kingdom back.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Sigismund_of_Burgundy", "biography": "rewritten"}'::jsonb),
