UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Vincent of Saragossa served as a deacon in the Church of Zaragoza. He is regarded as the Protomartyr of Spain, and Lisbon, Algarve and Valencia all claim him as patron saint. Born at Huesca, he was martyred around 304 under the Emperor Diocletian. The Catholic Church, the Anglican Communion, and the Eastern Orthodox Church keep his feast day on 22 January, and the Eastern Orthodox Church also commemorates him on 11 November.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Vincent_of_Saragossa", "biography": "rewritten"}'::jsonb),
