UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Raymond of Penyafort, a Catalan Dominican friar, was a canon lawyer. He put together the Decretals of Gregory IX, a body of canonical legislation that stayed central to Church law until it was abrogated by the 1917 Code of Canon Law. Pope Clement VIII canonized him in 1601, and canon lawyers count him as their patron saint.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Raymond_of_Pe%C3%B1afort", "biography": "rewritten"}'::jsonb),
