UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Justus of Lyon, the 13th Bishop of Lyon, took over from Verissimus around the middle of the 4th century. He was named bishop of the city about 350. The Catholic and Orthodox Churches both venerate him as a saint, and his feast day falls on 2 September. Because Lyon was the capital of Gaul, Justus was one of the participants at the Council of Valence of 374, which concerned the religious discipline of clergy and faithful. In later life he became a hermit.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Justus_of_Lyon", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
