WHERE content."id" = 'cmqa7diqm1as65krplyn3hioi'
  AND content."slug" = 'saint-just-of-lyon'
  AND md5(content."payload"->>'biography') = '8da166e40ae3d25840d2cf91950534ce';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A priest from Spain, John of Ávila was also a preacher, a scholastic author and a religious mystic. The Catholic Church has declared him a saint and a Doctor of the Church. Because of his wide-ranging ministry across Andalusia, he is known as the "Apostle of Andalusia".'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/John_of_%C3%81vila", "biography": "rewritten"}'::jsonb),
