SET "payload" = content."payload" || jsonb_build_object('biography', 'Italian Roman Catholic priest Giovanni Battista Righi belonged, as a professed member, to the Order of Friars Minor. People knew him for his ascetic life, his preaching, and his ability to heal.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/John_Righi", "biography": "rewritten"}'::jsonb),
