UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Bernardine of Feltre, a Friar Minor and missionary, was a native of Feltre, Italy, and he died at Pavia. He is associated with the monti di pietà: together with Michele Carcano he reorganized them and, in a certain sense, was their founder. The Order of Friars Minor keeps the feast of Blessed Bernardino on 28 September.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Bernardine_of_Feltre", "biography": "rewritten"}'::jsonb),
