UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Landry of Soignies (also Landric or Landericus), commonly called Saint Landry of Metz, was a Frankish saint: a Roman Catholic Bishop of Metz and a Benedictine abbot of Haumont and Soignies. Saint Waltrude and Madelgaire were his parents.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Landry_of_Soignies", "biography": "rewritten"}'::jsonb),
