UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Beatus of Lungern, also called Beatus of Beatenberg and Beatus of Thun, was a monk and hermit of the early Christian era, venerated as a saint. His legend places his death in the 2nd century, but his story has probably been merged with those of other saints of the same name, particularly Beatus of Vendôme, and with an Abbot Beatus who in 810 received a charter from Charlemagne confirming that Irish monks would administer Honau Abbey.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Beatus_of_Lungern", "biography": "rewritten"}'::jsonb),
