UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Born Shukrallah Maloyan, Ignatius Maloyan (ICPB) was an Armenian Catholic prelate, serving from 1911 until 1915 as Archbishop of Mardin. Because he repeatedly refused to convert to Islam, Ottoman gendarmes tortured and killed him during the Armenian genocide, in Diyarbekir Vilayet under Mehmed Reshid. Pope John Paul II beatified him in 2001 as a martyr. Pope Francis then gave his approval, in 2025, to a plan for canonizing him, and Maloyan was canonized on October 19, 2025.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Ignatius_Maloyan", "biography": "rewritten"}'::jsonb),
