UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A virgin and nun, Columba of Spain was born in Córdoba, Spain. Muslim rulers in Spain martyred her around 853 amid a persecution of Christians. She is one of the Martyrs of Córdoba and is venerated as a saint by the Catholic Church, which keeps her feast day on September 17. Her cult probably combined two virgin martyrs: Columba of Sens, a French martyr of the third century, and Colomba of Spain.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Columba_of_Spain", "biography": "rewritten"}'::jsonb),
