UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Elias, a bishop, served as Patriarch of Jerusalem from 494; in 516 Byzantine Emperor Anastasius I deposed him for supporting the Council of Chalcedon''s decrees. Elias was Arab by birth and had received his education in a monastery in Egypt. Together with Flavian II of Antioch, he successfully defended, at the Synod of Sidon (512), the dyophysite Christological doctrine that the Council of Chalcedon had proclaimed. The Eastern Orthodox Church commemorates Elias, along with Flavian II of Antioch, on July 20, and the Roman Martyrology on July 4.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Elias_I_of_Jerusalem", "biography": "rewritten"}'::jsonb),
