UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Narnus is honored as Bergamo''s first bishop, and is a saint. According to Christian tradition, St. Barnabas consecrated him to that office during the Apostolic Age, though Narnus most likely lived later. The earliest source to mention him dates from the 13th century and was composed by a friar, Branca da Gandino, who regards Narnus as a bishop of Bergamo under Diocletian in the fourth century.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Narnus", "biography": "rewritten"}'::jsonb),
