UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Among the Martyrs of Uganda, Saint Kizito, also called Kizito Omuto, was the youngest to be killed by King Mwanga II of Buganda. Charles Lwanga, then leader of Uganda''s Christian community, baptized him at Munyonyo on 25/26 May 1886. On 3 June 1886 he was burned alive in Namugongo. Pope Paul VI canonized him in Rome on 18 October 1964. His feast day is June 3, and children and primary schools look to him as their patron saint.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Kizito", "biography": "rewritten"}'::jsonb),
