UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Kea was a British saint of the late 5th century who came from the Hen Ogledd, meaning the lands in present-day southern Scotland and northern England where Brythonic was spoken. Tradition holds that he worked mainly in Cornwall, Devon and Brittany, and devotion to him flourished there, as well as across Wales and the West Country. Fili or Filius, the dedicatee of the parish church of Philleigh, likely hailed from Wales, and he is said to have accompanied Kea.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Kea", "biography": "rewritten"}'::jsonb),
