UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Ludan, known also as Ludain or Luden, was a pilgrim from Scotland who traveled to Jerusalem. Returning, he died at Scherkirchen, close to the city of Strasbourg, France, and as he died the bells of a church nearby began to ring.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Ludan", "biography": "rewritten"}'::jsonb),
