UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Rivoare, who is also called Saint Riware, Saint Riwall, Riware, Rivoal, Rioual or Rivoaré, numbers among Armorica''s semi-legendary Breton saints. He is commemorated on 19 September.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Rivoare", "biography": "rewritten"}'::jsonb),
