UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Other names for Tremorus of Brittany are Trémeur, Treveur, and Tromeur; he died as a child in the sixth century and is venerated as a martyr by the Roman Catholic Church. His mother had him baptized in defiance of his stepfather. He received the baptismal name Gildas, after Gildas the Wise, and was given the title Trech-meur to tell him apart from the older Gildas. Count Conmore, his stepfather, murdered him while he studied at the monastery of Carhaix in Brittany, because Conmore hated Christianity. His mother was Triphina (Triphena); after her son''s murder she withdrew to a convent. Gildas the Wise had been his teacher.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Tremorus_of_Brittany", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
