UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Ninnoc or Ninnog of Breton, known also as Nenooc, Nennoca, Nennocha, Ninnoc, Ninnocha, and Gwengustle, was an abbess of the early medieval period. She was born in Wales and died in Brittany. What is known of her life and work comes from the text of Vita Sanctae Ninnocae, kept in the Cartulary of Quimperlé.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Ninnoc", "biography": "rewritten"}'::jsonb),
