UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Thomais of Lesvos, also called Saint Thomais, was a saint and a Byzantine woman from Lesvos. As a married laywoman who reached holiness through ordinary daily life she is an unusual case. The Eastern Orthodox Church venerates her as a saint, with her feast day on 3 January.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Thomais_of_Lesbos", "biography": "rewritten"}'::jsonb),
