SET "payload" = content."payload" || jsonb_build_object('biography', 'Christian saint Ulphia of Amiens receives particular veneration at Amiens, and her feast day falls on January 31.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Ulphia", "biography": "rewritten"}'::jsonb),
