UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'King Liuvigild ruled the Visigothic Kingdom, which covered the Iberian Peninsula and southern France, and his son was Saint Hermenegild (also Ermengild). In 579 Hermenegild quarrelled with his father, and he rose in revolt the next year. During the revolt he went from Arianism to Catholicism. Defeated in 584, he was exiled. Later his death came to be celebrated as martyrdom, an outcome shaped by Pope Gregory I''s Dialogues, where Gregory portrayed him as a "Catholic martyr" rebelling in the face of "the tyranny of an Arian father."'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Hermenegild", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
