  AND md5(content."payload"->>'biography') = '8a6de00b6bd4016657004d44f8c329f8';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Adalbert I of Ostrevent, a Frankish nobleman of the 7th century, was a courtier of King Clovis II of France. The Church recognizes him as a saint, with commemorations on 2 February, and likewise on 2 May.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Adalbard", "biography": "rewritten"}'::jsonb),
