  AND md5(content."payload"->>'biography') = 'd0bf0183528571d04380157204cedf65';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'From 888 until his death, Adalgar served as the third archbishop of Bremen, and he is venerated as Saint Adalgar. The Roman Catholic and Eastern Orthodox Churches both revere him as a saint, with his feast day on 29 April.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Adalgar", "biography": "rewritten"}'::jsonb),
