UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Tradition holds that St. Sidonius followed St. Maximinus of Aix as Archbishop of Aix. Tradition also identifies him as a blind man whom Jesus healed. Many take this to be the man born blind whom Jesus cures in John 9, though that healed man is more usually linked with St. Celidonius, Protobishop of Nîmes. His name, Sidonius, translates literally as "from Sidon", which suggests he may have belonged to the Syro-Phoenician crowd mentioned at Mark 7:24 and Matthew 15:21 as following Jesus.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Sidonius_of_Aix", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
