WHERE content."id" = 'cmqa7gzpo1cpc5krp17ehbujr'
  AND content."slug" = 'saint-sidoine-d-aix'
  AND md5(content."payload"->>'biography') = 'e0bc41192eaa002cdec4cf790c72d6e6';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Leopold III, called Leopold the Good, held the title Margrave of Austria from 1095 until his death in 1136; he belonged to the House of Babenberg. Canonized on 6 January 1485, he became patron saint of Austria and of Lower Austria, Upper Austria and Vienna. 15 November is his feast day.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Leopold_III%2C_Margrave_of_Austria", "biography": "rewritten"}'::jsonb),
