UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Dominic Loricatus, O.S.B. Cam., was an Italian monk. He was born in Luceolis, a village close to Cantiano. His father wanted social advancement and paid a bribe so that Dominic would be ordained a priest while still a child. On learning of this, Dominic resolved to lead a life of penance. He lived as a hermit in woodland by S. Emiliano abbey, at Congiuntoli, and in 1040 he became a Camaldolese monk at Fonte Avellana monastery.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Dominic_Loricatus", "biography": "rewritten"}'::jsonb),
