UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Aristides the Athenian, a Greek Christian author of the 2nd century, is chiefly known for writing the Apology of Aristides. The Catholic Church keeps his feast day on August 31, and the Eastern Orthodox Church on September 13.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Aristides_of_Athens", "biography": "rewritten"}'::jsonb),
