UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'In the third century Saint Acathius served as bishop of Melitene, though some sources occasionally make him bishop of Antioch. Melitene, the capital city of the Roman Province known as Second Armenia, was his see.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Acathius_I_of_Melitene", "biography": "rewritten"}'::jsonb),
