UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Brothers who were both Byzantine Christian theologians and missionaries, Cyril and Methodius earned the title "Apostles to the Slavs" through their evangelization of the Early Slavs.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Cyril_and_Methodius", "biography": "rewritten"}'::jsonb),
