UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Stanislaus of Szczepanów, a Polish Catholic prelate, was Bishop of Kraków and met his martyrdom at the hands of the Polish King Bolesław II the Bold. Poland counts him as its patron saint.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Stanislaus_of_Szczepan%C3%B3w", "biography": "rewritten"}'::jsonb),
