UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Teobaldo Roggeri, an Italian Roman Catholic, was a shoemaker and porter who came from the Ligurian province. He became known for living simply and for devoting himself to what the poor in the Diocese of Alba needed.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Teobaldo_Roggeri", "biography": "rewritten"}'::jsonb),
