UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Thierry, also called Theodoric of Mont d''Hor, followed Saint Remigius as his disciple and later became abbot at Saint-Thierry Abbey, near Reims, France; he was born on 9 March and died in 533.
He is commemorated on 1 July.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Theodoric_of_Mont_d''Hor", "biography": "rewritten"}'::jsonb),
