UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Born Giacomo Capocci, James of Viterbo was an Italian Roman Catholic, an Augustinian friar and Scholastic theologian who went on to become Archbishop of Naples.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/James_of_Viterbo", "biography": "rewritten"}'::jsonb),
