WHERE content."id" = 'cmqa7hkm21d0x5krpt2sfnwu7'
  AND content."slug" = 'saint-penitent-thief'
  AND md5(content."payload"->>'biography') = 'be3bd58ac975879fe255d2ff48d5eae1';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A mythical Christian saint of Armorica, Saint Urielle (also called Eurielle, Curielle or Arielle) received veneration in the Celtic region of Brittany.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Urielle", "biography": "rewritten"}'::jsonb),
