UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Ursicinus of Cahors, also Urcis or Saint Urcsicinus, was bishop of Cahors, in office from the early 580s to about 595, when he died. His feast day is December 13. Before that he was chancellor to queen Ultragotha, who was married to Childebert I, king of Paris, and Maurilio, the bishop of Cahors then, picked him as his successor.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Ursicinus_of_Cahors", "biography": "rewritten"}'::jsonb),
