UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A prelate of the Roman Catholic Church from Italy and a professed friar of the Order of Friars Minor Capuchin, Giacinto Bonaventura Longhin took the name Andrea di Campodarsego as a religious. He held the office of Bishop of Treviso from 1904 until he died. After his ordination he held several leadership posts in his order, including teaching in Udine and serving as its Provincial Minister. He formed a close friendship with Giuseppe Melchiorre Sarto, Cardinal Patriarch of Venice. When Sarto became Pope Pius X in 1903, he named his old friend Longhin to head the vacant episcopal see of Treviso.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Giacinto_Longhin", "biography": "rewritten"}'::jsonb),
