UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Colomba Matylda Gabriel, whose religious name was Janina, was a professed religious, Ukrainian and Roman Catholic. She was founder of an order, the Benedictine Sisters of Charity. Gabriel was educated in Lviv by the Order of Saint Benedict, later becoming a Benedictine herself while teaching at her old school, until in 1900 she was forced to move to Rome, where she established her order and also joined a Benedictine branch there.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Colomba_Gabriel", "biography": "rewritten"}'::jsonb),
