UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Cono was a Benedictine monk born in Diano (Italy) at the end of the 12th century. He entered the Benedictine Monastery of S.Maria di Cadossa near Montesano sulla Marcellana as a monk. In the first years of the 13th century he died at a very young age, already thought of as holy. His relics were brought back to Diano in 1261, after the Cadossa monastery closed, and there he is venerated as patron saint.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Conus", "biography": "rewritten"}'::jsonb),
