UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Wincenty Kadłubek, a professed Cistercian and Polish Catholic prelate, was Bishop of Kraków from 1208 until he resigned in 1218. As bishop he set out to reform the diocesan priests so that they would be holy, to energize the faithful and to encourage them to take a greater part in the affairs of the Church. He was far more than a bishop. Among Poland''s foremost scholars, he flourished in the twelfth and thirteenth centuries, and he was a lawyer, historian, church reformer, monk and magister as well, and the father of Polish national identity and culture.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Wincenty_Kad%C5%82ubek", "biography": "rewritten"}'::jsonb),
