UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Constantius is venerated as one of the members of the legendary Theban Legion. His cult, like those of Chiaffredo at Crissolo, Bessus at Val Soana, Tegulus at Ivrea, Magnus at Castelmagno, and Dalmatius at Borgo San Dalmazzo, was tied to that of the Theban Legion in order to give a sense of antiquity to a local saint of whom nothing was truly known.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Constantius_(Theban_Legion)", "biography": "rewritten"}'::jsonb),
