UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A Christian saint called Damian was once listed in the Roman Martyrology on 12 February, but the 2004 revision of the Martyrology dropped the entry. Apparently, at some point two early martyrs were confused with one another: a soldier who was put to death in Alexandria or Roman Africa, and another man whose relics turned up in the catacomb of Callixtus. Those catacomb relics were afterwards translated to Salamanca.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Damian_(martyrs%2C_February_12)", "biography": "rewritten"}'::jsonb),
