UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Æbbe, who was also called Tabbs, was an Anglian noblewoman and abbess. Her father was Æthelfrith, who ruled Bernicia as king from c. 593 to 616. She established monasteries at Ebchester and at St Abb''s Head, near Coldingham in Scotland.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/%C3%86bbe_of_Coldingham", "biography": "rewritten"}'::jsonb),
