UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Edoardo Giuseppe Rosaz, an Italian Roman Catholic prelate, was Bishop of Susa from 1877 until he died. The Franciscan Mission Sisters of Susa owe their origin to him as their founder. John Bosco proposed him for appointment as a bishop. As a bishop his apostolic zeal grew still stronger: he looked after abandoned people on the peripheries and supported the work of many different religious orders.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Edoardo_Giuseppe_Rosaz", "biography": "rewritten"}'::jsonb),
