UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Helladius (also Eladio or Elladio) was an archbishop of Toledo. Descended from a noble Visigothic family of Spain, he first held major court offices, yet the monastic life appealed to him, and at the Agali monastery he made his vows. He rose to be that house''s abbot and afterward the archbishop. The Roman Martyrology gives 18 February as his feast.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Helladius_of_Toledo", "biography": "rewritten"}'::jsonb),
