UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Elena Aiello, an Italian religious sister, established the Minim Sisters of the Passion of Our Lord Jesus Christ, and so is its founder. She entered a congregation, Sisters of the Most Precious Blood, yet serious ill health forced her to leave. Her condition soon confined her to her home, where she began to experience visions of Jesus Christ, of the Blessed Virgin Mary, and of saints, among them Francis of Paola. Her beatification took place on 14 September 2011.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Elena_Aiello", "biography": "rewritten"}'::jsonb),
