UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Amadeus IX, called the Happy, ruled as Duke of Savoy between 1465 and 1472. He was noted for his piety, his charity and his gentle character. The Catholic Church venerates him and keeps his liturgical feast on 30 March, and Pope Innocent XI beatified him in 1677.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Amadeus_IX%2C_Duke_of_Savoy", "biography": "rewritten"}'::jsonb),
