UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Felix of Nola, a Christian priest, served in Nola, a town close to Naples, Italy. He sold his possessions and gave the money to the poor, but during the persecution under Roman Emperor Decius he was arrested and tortured for his faith. He was once thought to have died a martyr''s death in the persecution of Decius or Valerian, yet the General Roman Calendar now lists him as a Confessor of the Faith, one who lived through the torture.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Felix_of_Nola", "biography": "rewritten"}'::jsonb),
