UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Ferdinando Maria Baccilieri, an Italian priest of the Roman Catholic Church, was a professed Secular Servite. He was also the founder of a religious congregation for women, called Sisters Servants of Mary of Galeazza. He gained wide recognition for turning a troubled parish into one full of faith, and in the Bolognese parish his good work and effort led to his appointment as its parochial vicar.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Ferdinando_Maria_Baccilieri", "biography": "rewritten"}'::jsonb),
