UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'At Padua during the Middle Ages a cultus was kept for a saint named Fidentius Armenus, whom some call Fidentius of Padua. 16 November is his feast day. Nothing is known about him. Tradition dates him to the second century and counts him a martyr. A late hagiographic account claims he was killed in 168, the seventh year of the reign of Marcus Aurelius. From his nickname one may infer that he was Armenian.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Fidentius_Armenus", "biography": "rewritten"}'::jsonb),
