UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'An Italian Passionist seminarian, Gabriel of Our Lady of Sorrows came from a family of professionals, but he set aside plans for a secular career and entered the Passionist congregation. Life in the monastery held nothing extraordinary for him, though he observed the congregation''s rule perfectly and was known for deep devotion to the Virgin Mary''s sorrows. At 23 he died of tuberculosis at Isola del Gran Sasso, in Teramo province. Pope Benedict XV canonized him in 1920.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Gabriel_of_Our_Lady_of_Sorrows", "biography": "rewritten"}'::jsonb),
