  AND md5(content."payload"->>'biography') = '085573499a1f340d90817bcb0ceebb1b';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Firmina is an Italian saint of the Roman Catholic Church, a virgin martyr. Civitavecchia has her as its patroness saint, and Amelia Cathedral carries her dedication.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Firmina", "biography": "rewritten"}'::jsonb),
