UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The Catholic Church venerates Saint Flavian of Ricina as a martyr and bishop. According to tradition, he was bishop of Helvia Ricina (Macerata) in the 3rd century and was martyred on November 24. Devotion to him is ancient and widespread across the Marche and Umbria, where many churches and abbeys bear his name, yet the historical record of his life is confined to a few details and traditions.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Flavian_of_Ricina", "biography": "rewritten"}'::jsonb),
