UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Fulk, an English pilgrim, was beatified because he selflessly helped plague victims, even at risk to himself. Sometime in the 12th century, while on his way to Rome, he halted at Santopadre (also called Castrofuli) in southern Italy to aid those stricken by plague. He died of the disease, was beatified, and became Castrofuli''s patron saint. Approval of his cult came in 1572; May 22 is his feast day.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Fulk", "biography": "rewritten"}'::jsonb),
