  AND md5(content."payload"->>'biography') = '402a58473bd473f6a3bf44544c3f1442';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The Catholic Church venerates Fortunatus of Casei as a saint. According to tradition he belonged to the Theban Legion and was therefore martyred at Agaunum. Until 1746 his relics were kept in Rome, in Pope Callixtus I''s catacombs; then Cardinal Guadagni, the Roman vicar under Benedict XIV, exhumed them again and put them on display at Santa Maria in Via Lata, a collegiate church in Rome. How the relics came to Rome from the Swiss Alps, where the saint is supposed to have died, is unclear.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Fortunatus_of_Casei", "biography": "rewritten"}'::jsonb),
