UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Fortunatus of Naples was a Christian bishop of the 4th century and is the earliest historically attested bishop of Naples, since he was among the recipients of a letter from participants of the Arian Council of Philippopolis, held in the 340s. Tradition holds that he strongly opposed Arianism. His time as bishop is traditionally placed from 347 to 359.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Fortunatus_of_Naples", "biography": "rewritten"}'::jsonb),
