UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Francesco Maria Greco, an Italian Roman Catholic priest, served in the Archdiocese of Cosenza. In 1894 he founded, with Raffaela De Vincentis, the Little Workers of the Sacred Hearts. Greco worked in Cosenza as a pastor and a professor, and he started a catechetical school as well as a hospital service for the poor.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Francesco_Maria_Greco", "biography": "rewritten"}'::jsonb),
