UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Francesco Spinelli, an Italian Roman Catholic priest, was founder of Sisters Adorers of the Blessed Sacrament. He was a close contemporary of Geltrude Comensoli and of Luigi Maria Palazzolo. He had earlier worked with Comensoli, and together they founded a religious institute in Bergamo, but a dispute among its members led Spinelli to withdraw from its work and depart.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Francesco_Spinelli", "biography": "rewritten"}'::jsonb),
