UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Giovanni Giovenale Ancina, an Italian Roman Catholic prelate, was Bishop of Saluzzo and a professed Oratorian. He was also a scholar, a composer of music, and a celebrated orator. For about twenty years before becoming a bishop he served the Oratorians as a simple priest. He tried for five months to avoid the episcopal appointment, but finally yielded to Pope Clement VIII and accepted it. Some months afterwards he entered his diocese, where he gained renown for his charitable work among the poor and for his efforts to put the Council of Trent''s reforms into fuller practice.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/John_Juvenal_Ancina", "biography": "rewritten"}'::jsonb),
