UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Giovanni Saziari, who is also called John Saziari or Joannes Saziari, was a Roman Catholic farmer from Italy''s Province of Pesaro and Urbino. He belonged to the Secular Franciscan Order. During his life he was known for his gifts of healing, and although he was married he stayed celibate and had no children.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Giovanni_Saziari", "biography": "rewritten"}'::jsonb),
