UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Giulia della Rena, an Italian Roman Catholic, was a professed member of the third order branch of the Order of Saint Augustine. She lost her parents in her late childhood and found work in Florence as a maid, where before long she joined the Augustinian tertiaries. Because of Florence''s poor economic and political climate, the religious went back to Certaldo, where she became best known for saving a child from a burning building.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Giulia_della_Rena", "biography": "rewritten"}'::jsonb),
