UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Inés de Benigánim, whose religious name was Josefa María of Saint Agnes and who was born Josefa Teresa Albiñana Gomar, was a Spanish nun of the Discalced Augustinians. She was noted for deep spiritual and theological insight and for the harsh austerities she practiced throughout her life. Her beatification took place in Saint Peter''s Basilica in 1888.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/In%C3%A9s_de_Benig%C3%A1nim", "biography": "rewritten"}'::jsonb),
