UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Waningus held the rank of Merovingian count and served as a royal official in the time of Clotaire III. He helped Wandrille found Fontenelle Abbey and afterward founded Fécamp Abbey. He is regarded as a Christian saint.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Waningus", "biography": "rewritten"}'::jsonb),
