UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Known as Cosma de Carbognano, Gomidas Keumurdjian served as a married priest in the Armenian Apostolic Church before converting to the Armenian Catholic Church. The Armenian Apostolic Patriarch of Constantinople pressed for his prosecution, and Ter Gomidas was brought before an Islamic court, where the Qadi condemned him to death, accusing him of betraying the Ottoman Sultan and of secretly baptizing Muslims. He was offered a complete pardon and instant release if he would convert to Islam, but he refused again and again, and was beheaded in public in the Samatya quarter of Istanbul. The Catholic Church regards him as a martyr, and since 1929 he has been honored with the title Blessed.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Gomidas_Keumurdjian", "biography": "rewritten"}'::jsonb),
