WHERE content."id" = 'cmqa7lu2d1f7r5krpm7nsuvfb'
  AND content."slug" = 'saint-gomidas-keumurdjian'
  AND md5(content."payload"->>'biography') = '149c725655826c1897e129893b295072';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Blessed Hemming of Turku, a Swedish Roman Catholic bishop (1290–1366), headed the see of Turku from 1338 until he died in 1366. Sweden was his birthplace, but he moved to Finland once appointed bishop. His firm commitment to what the faithful needed educationally and spiritually made him well loved in the diocese. Saint Bridget of Sweden was a close friend of his, and during his studies the future Pope Clement VI was among his classmates.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Hemming_of_Turku", "biography": "rewritten"}'::jsonb),
