UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Ferdinando Santamaria, known as Grimoaldo of the Purification, was an Italian Roman Catholic who studied for the priesthood as a Passionist. As a boy he served at the altar and encountered the Passionist charism, and he spoke early of a leaning toward the religious life. He did not enter until 1899, when his father at last approved of his vocation, and he professed his vows in 1900. His studies went on, now aimed at ordination, but meningitis killed him before he could reach that goal.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Grimoaldo_of_the_Purification", "biography": "rewritten"}'::jsonb),
