UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Isidore the Laborer, whose birth name was Isidro de Merlo y Quintana, was a Mozarab farmworker in medieval Madrid; he is also called Isidore the Farmer. He was noted for his piety, shown toward the poor and toward animals. Catholics venerate him as a patron saint of farmers, of Madrid, of El Gobernador, Jalisco; Condiro Jalisco, La Ceiba, Honduras; and of Tocoa, Honduras. His feast day is observed on 15 May.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Isidore_the_Laborer", "biography": "rewritten"}'::jsonb),
