UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A Franciscan friar and missionary explorer, Odoric of Pordenone came from Friuli in northeastern Italy. He traveled through India, Sumatra, Java and China, and stayed three years at the imperial capital, Khanbaliq. Having been away for more than ten years, he came home and dictated an account of what he had seen and experienced, called the Relatio, which points out many cultural, religious and social oddities he met in Asia.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Odoric_of_Pordenone", "biography": "rewritten"}'::jsonb),
