UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A Spanish Jesuit priest, Francis Borgia was descended from both Pope Alexander VI and King Ferdinand II of Aragon, who were his great-grandfathers. He held the titles of Duke of Gandía and grandee of Spain. When his wife died, Borgia gave up his titles and became a priest of the Society of Jesus, where he later served as third superior general. Pope Clement X canonized him on 20 June 1670.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Francis_Borgia", "biography": "rewritten"}'::jsonb),
