UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The Hieromartyrs of Cherson were several bishops of the early 4th century who were martyred at Cherson, which then lay within Taurica (Crimea), in the Bosporan Kingdom. Their martyrdom took place when Tiberius Julius Rhadamsades was Roman client king, in the Diocletian persecution (303–313). The Orthodox church commemorates them on March 7.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Hieromartyrs_of_Cherson", "biography": "rewritten"}'::jsonb),
