UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Reverianus of Autun was a bishop of Autun and martyr of the 3rd century. The Roman Catholic Church venerates him as a saint. Tradition holds that he was of Italian origin and that Pope Felix I sent him to bring the gospel to the Aedui, a Gallic people in Gallia Lugdunensis; he is regarded as the "apostle of the Morvan".'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Reverianus", "biography": "rewritten"}'::jsonb),
