UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Several Christian traditions venerate Nicodemus, a figure of the New Testament, as a saint. He appears as a Pharisee and Sanhedrin member who feels drawn to listen to the teachings of Jesus. As with Lazarus, the synoptic Gospels never mention him. Only John does, giving him over half of Chapter 3 and a few verses in Chapter 7, then naming him finally in Chapter 19.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Nicodemus", "biography": "rewritten"}'::jsonb),
