UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Eleven Catholic saints, known as the Martyrs of Damascus, were killed as martyrs while praying in a Franciscan-run parish in Damascus; Druze attackers killed them in the civil strife of 1860 in Mount Lebanon and Damascus. They are the Massabki Brothers together with Manuel Ruiz Lopez and Companions. Three Maronite Catholics from Damascus (in modern Syria), sons of Nehme Massabki, were the Massabki Brothers. Franciscans made up the other eight martyrs, among them Emmanuel Ruiz: seven were Spanish and one Austrian.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Martyrs_of_Damascus", "biography": "rewritten"}'::jsonb),
