UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Esțfān Nehmé was a professed religious of the Lebanese Maronite Order, from Lebanon. During World War I he eased the suffering of many by handing out food to people struck by famine, and he was known for an intense devotion toward the Mother of God. He labored in the fields belonging to his convent and to other monasteries, and for a short time he also did construction work. Other monasteries, valuing his spiritual insight and his diligence, sought to have him live among them, and he became well known.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Stephen_Nehm%C3%A9", "biography": "rewritten"}'::jsonb),
