UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Born Athanasios Karslidis, Saint George of Drama was a monk of the Greek Orthodox Church with Caucasian origins. The Eastern Orthodox Church venerates him as a saint, and he is connected to the Greek and also the Georgian Orthodox traditions. He had a reputation for spiritual guidance and an ascetic lifestyle. Karslidis died in Greece on 4 November 1959, aged 58. His grave is behind the katholikon of the Ascension Monastery, where he spent thirty years in service.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/George_of_Drama", "biography": "rewritten"}'::jsonb),
