UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Maximus of Évreux, known locally as Saint Mauxe, is venerated as a saint by both the Catholic Church and the Eastern Orthodox Church. Legend holds that he was Évreux''s second bishop and died as a martyr at Acquigny together with his brother, who served as his deacon. The brother is named Venerandus (Vénérand) or Victorinus.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Maximus_of_%C3%89vreux", "biography": "rewritten"}'::jsonb),
