UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Shtjefën Kurti, an Albanian Roman Catholic priest, was killed amid communist persecution. His priesthood fell in an unsettled era for Albania, when communist repression enforced state atheism and brought in strict rules that prevented clerics from doing their duties. Because he went on serving as a priest whenever needed, he was arrested, accused of colluding with spies. His last arrest followed an allegation that he had secretly baptized a child, something the regime forbade. A death sentence was passed on him, and he was executed by firing squad.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Shtjef%C3%ABn_Kurti", "biography": "rewritten"}'::jsonb),
