UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Waldebert (also called Gaubert, Valbert or Walbert) was a count of the Franks, ruling Guines, Ponthieu and Saint-Pol. He became abbot of Luxeuil and was eventually canonized as a saint of both the Roman Catholic Church and the Eastern Orthodox Church. As several of his relatives did, he protected the Church, gave it gifts of land and founded monasteries. Faro was his brother.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Waldebert", "biography": "rewritten"}'::jsonb),
