UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Valère de Langres, or Saint Valère, was archdeacon of Langres. Vandals under a man called Chrocus seized him, beat him and beheaded him on 22 October 411, either at Port-sur-Saône or at Port-Saint Pierre, a spot on the Saône River that today belongs to the municipality, or commune, of Heuilley-sur-Saône.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Val%C3%A8re_de_Langres", "biography": "rewritten"}'::jsonb),
