UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Francisco Martín Fernández de Posadas, a Spaniard, was a Roman Catholic priest. He had professed vows in the Order of Preachers. He gained renown as a preacher and a sought-after confessor, and was praised as a second Vincent Ferrer. At the outset, fellow Dominicans treated him with violent dislike and mockery before admitting him to the order.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Francisco_Mart%C3%ADn_Fern%C3%A1ndez_de_Posadas", "biography": "rewritten"}'::jsonb),
