UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Gerard of Potenza, known too as Gerard La Porta, was bishop of Potenza, which today is the provincial capital of Basilicata, a region of Southern Italy. He held the see for eight years, until he died in 1119. The Catholic Church later recognised him as a saint. Each year on 29 May, in keeping with local myth and folklore, the town honours him with the Parade of the Turks.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Gerard_of_Potenza", "biography": "rewritten"}'::jsonb),
