UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Giovannangelo Porro, an Italian Roman Catholic hermit and priest from the Milanese area, took vows among the Servites. He was born into a noble family and was ordained a priest once his father had died. He lived as a hermit in convents in places including Florence and Milan, devoting himself until his death to interior meditation and self-mortification.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Giovannangelo_Porro", "biography": "rewritten"}'::jsonb),
