UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Luigi Novarese, an Italian Roman Catholic priest, was co-founder of both the Apostolate of the Suffering and the Silent Workers of the Cross. He further set up the Marian Priest League, as well as his Brothers and Sisters of the Sick, and he built several homes for ill and disabled people. He worked in the Secretariat of State until he left that post to work with the Italian Episcopal Conference, to spend more time with the ill, and to attend to the work of his orders.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Luigi_Novarese", "biography": "rewritten"}'::jsonb),
