UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Neot, an English monk, was born during the ninth century''s first half and lived at Glastonbury Abbey. Preferring to keep his devotions private, he later withdrew to a secluded life in Cornwall, close to the village that is now named St Neot. The monks admired him for his wisdom and religious commitment. He travelled to Rome and met the Pope, who instructed him to set up a monastery in Cornwall.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Neot_(monk)", "biography": "rewritten"}'::jsonb),
