UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A Polish Roman Catholic priest, Władysław Bukowiński ministered in the Karaganda diocese in Kazakhstan. In Poland during World War II he served and became well known among his parishioners for his calm and his intelligence. He sought to meet the conflict with Jesus Christ''s love and the Gospel''s message. He was arrested several times and spent a period as a prisoner in a Soviet gulag. After his release he carried out a long mission in Kazakhstan.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/W%C5%82adys%C5%82aw_Bukowi%C5%84ski", "biography": "rewritten"}'::jsonb),
