UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Constantine of Murom, called Saint Constantine the Blessed, descended directly from Vladimir I of Kiev and was a son of Prince Svyatoslav of Chernigov. Some identify him with Yaroslav Sviatoslavich, who was prince of Chernigov (1123–1127), yet it is uncertain whether they were the same man.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Constantine_of_Murom", "biography": "rewritten"}'::jsonb),
