UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'In China''s Boxer Rebellion, Saint Marie-Hermine of Jesus, a French nun and Mother Superior, lost her life; her canonisation came in 2000. Together with six other nuns she traveled to China to establish a small hospital and to run an orphanage, but they were eventually killed because of their link with foreign interference. Pope John Paul II canonised her on 1 October 2000 together with the group called the Martyr Saints of China.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Marie-Hermine_of_Jesus", "biography": "rewritten"}'::jsonb),
