UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Joseph of Cupertino, OFM Conv., was an Italian friar of the Conventual Franciscans, honored as a saint and Christian mystic. Traditional Franciscan accounts describe him as "remarkably unclever". Throughout his life he experienced miraculous levitation and ecstatic visions, and these made him a target of scorn.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Joseph_of_Cupertino", "biography": "rewritten"}'::jsonb),
