UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Longinus is the name traditionally given to the unnamed Roman soldier who pierced Jesus''s side with a lance; medieval and some modern Christian traditions describe him as having become a Christian. The name first occurs in the apocryphal Gospel of Nicodemus. Catholic Christianity calls the lance the "Holy Lance" (lancea), and the Gospel of John relates the episode as part of the Crucifixion. The wound is said to have made the final one among the Five Holy Wounds of Christ.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Longinus", "biography": "rewritten"}'::jsonb),
