UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A French Roman Catholic priest, Louis-Édouard Cestac co-founded the Serviteurs de Marie together with his sister Marie-Louise-Élise. He was devoted to the poor and visited them often, hoping to understand them and learn how best to meet their material and spiritual needs. Poor and destitute girls worried him in particular, so he resolved to give them a stable environment. With his sister''s help, he founded a religious order dedicated to caring for them.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Louis-%C3%89douard_Cestac", "biography": "rewritten"}'::jsonb),
