UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'John the Warrior, also known as John the Soldier, is a martyr and saint of the Catholic Church. Born in the 4th century, he spent his life in the Byzantine Empire until his death. Julian the Apostate forced him to fight as a warrior against Christianity; John was caught helping those in need or defending Christians, was put in prison and waited there for his death sentence. After the emperor died in a war, however, John the Warrior was set free.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/John_the_Warrior", "biography": "rewritten"}'::jsonb),
