UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Venantius of Camerino is patron saint of Camerino, Italy, and of Raiano, Italy. Christian tradition says he was 15 years old when he was tortured and then martyred by beheading at Camerino in the persecutions under Decius. He died alongside 10 other Christians who were martyred too, among them Leontius, bishop of Camerino, and the priest Porphyrius, who was Venantius'' tutor.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Venantius_of_Camerino", "biography": "rewritten"}'::jsonb),
