UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Giuseppina Catanea, OCD, was an Italian Catholic and a professed member of the Discalced Carmelites, taking Maria Giuseppina of Jesus Crucified as her religious name. Her parents were nobles from the Marquises Grimaldi, and in childhood she was noted for her close attention to the hardships of the poor. This concern deepened after she made her profession as a Carmelite in 1932; she held leadership positions even though her failing health eventually caused her death.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Giuseppina_Catanea", "biography": "rewritten"}'::jsonb),
