UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Sigfrid of Sweden
(Swedish: Sigfrid, Latin: Sigafridus, Old Norse: Sigurðr, Old English: Sigefrið/Sigeferð) was a missionary-bishop in Scandinavia in the 11th century''s first half. He was English by origin. Late medieval king-lists and hagiography credit Saint Sigfrid with baptizing Olof Skötkonung, the first firmly Christian monarch of Sweden. He most likely reached Sweden shortly after the year 1000 and carried out wide-ranging missions in Götaland and Svealand. After returning to England he was based for some years after 1014 in Trondheim, Norway, but once Olaf Haraldsson was defeated his position there could not be maintained.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Sigfrid_of_Sweden", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmqadhjfr37msjhj28y388fow'
  AND content."slug" = 'saint-sigfrid-of-sweden'
  AND md5(content."payload"->>'biography') = '9393a8636ae5d661fd6187a931b1a614';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Máel Ruba was an Irish saint who carried out his work in Scotland. A native of Bangor, County Down, Ireland, he became a monk and established the monastery of Applecross in Ross, which ranks among the best documented early Christian monasteries of present-day Scotland. His name also appears as Máelrubai, Maol Rubha (MoRubha/MaRuibhe) or Malruibhe, and is at times latinised as Rufus.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/M%C3%A1el_Ruba", "biography": "rewritten"}'::jsonb),
