  AND md5(content."payload"->>'biography') = '08bb1216e2b308e85a41c7dc65c763fd';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'An Italian religious sister, Saint Maria Chiara Nanetti (Mary Clare) was killed in China, for her faith, amid the Boxer Rebellion, and she was canonised in 2000. Pope John Paul II canonised her on 1 October 2000 together with the group called the Martyr Saints of China.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Maria_Chiara_Nanetti", "biography": "rewritten"}'::jsonb),
