UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Knud (Canute Lavard) was a Danish prince who later became the first Duke of Schleswig. He was likewise the earliest border prince who was a vassal of both Denmark and Germany, a position leading toward Southern Jutland''s historical double status. His cousin Magnus the Strong, who viewed him as a rival for the Danish throne, killed him. Canute Lavard was canonized in 1170.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Canute_Lavard", "biography": "rewritten"}'::jsonb),
