UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Rose Venerini, or Rosa Venerini, was a saint and virgin of the Roman Catholic Church from Italy, and she founded Italy''s earliest public schools for girls as well as for young women. The Vatican document issued for her 2006 canonization says that soon "a moral improvement could be noted" among the young, "wherever a new school sprang up". After she died, her confraternity of teachers was raised to a religious congregation, the Religious Teachers Venerini. Its members ministered to Italian immigrants in Switzerland and the U.S., opened the earliest day care centers in the U.S. Northeast, and have labored across the globe. May 7 is her feast day.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Rose_Venerini", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
