UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Barbara Maix, ICM, an Austrian Catholic religious sister, took the name Maria Barbara of the Most Holy Trinity in religion. In Brazil she founded a community known as the Immaculate Heart of Mary Sisters. Maix gave her life to proper care for the poor and the sick, and she placed particular stress on recognizing the dignity of women.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Barbara_Maix", "biography": "rewritten"}'::jsonb),
