UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Elisabeth of Schönau, a German Benedictine, was a visionary. She was abbess of the abbey at Schönau in the Duchy of Nassau. She reportedly had many religious visions, and as a result powerful men as distant as France and England came seeking her.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Elisabeth_of_Sch%C3%B6nau", "biography": "rewritten"}'::jsonb),
