UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pollio of Cybalae, whose name is also given as Pullio of Cybalae, receives veneration as a Christian martyr, possibly put to death for his faith during the persecutions under Emperor Diocletian. He may have been a lector, it is thought, in Cybalae, a city of the Roman province of Pannonia, and in that role he may have had ties to the imperial dynasty. The Synaxarium of Constantinople and the Hieronymian Martyrology both mention him.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pollio_of_Cybalae", "biography": "rewritten"}'::jsonb),
