UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Verena of Zurzach, or Saint Verena, lived as a hermit and consecrated virgin of the early Christian era. The Eastern Orthodox Church, the Roman Catholic Church and the Oriental Orthodox Churches all venerate her as a saint. Switzerland honors her especially: her cult is attested from at least the 5th century at Bad Zurzach, which is reported to be where she was buried. 1 September is her feast.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Verena_of_Zurzach", "biography": "rewritten"}'::jsonb),
