UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Lorenzo Salvi, known as Lorenzo Maria of Saint Francis Xavier, was a Roman Catholic priest from Italy, professed in the Passionists. While studying before his ordination, Salvi made friends with Gaspar del Bufalo and with Bartolomeo Alberto Cappellari, a future pope. Anti-clerical laws of Napoleon Bonaparte drove him out of the Passionist house, but he returned once it was safe, in order to preach and to make known the Child Jesus''s charism.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Lorenzo_Maria_of_Saint_Francis_Xavier", "biography": "rewritten"}'::jsonb),
