  AND md5(content."payload"->>'biography') = '98976b8e7aa63bcfe9c5ce0e001eaf5e';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Adrian of Nicomedia, or Saint Adrian, served as a Herculian Guard under the Roman Emperor Galerius. He and his wife Natalia (Ναταλία) became Christians, and he was then martyred in Nicomedia, in Asia-Minor (Turkey). For many ages Adrian was the foremost military saint of Northern Europe, ranking just behind Saint George, and he is widely revered in Flanders, Germany and northern France.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Adrian_and_Natalia_of_Nicomedia", "biography": "rewritten"}'::jsonb),
