UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'John Eudes, CIM, a French Catholic priest, was the founder of two institutes. One was Our Lady of Charity, an order he began in 1641; the other, in 1643, was the Congregation of Jesus and Mary, whose members are called Eudists. Up to 1643 he also belonged, as a professed member, to the Oratory of Jesus.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/John_Eudes", "biography": "rewritten"}'::jsonb),
