UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Born Maria Droste zu Vischering, Mary of the Divine Heart was a noblewoman from Germany who became a religious sister in the Good Shepherd Catholic Congregation of Our Lady of Charity. Her chief claim to remembrance is her influence on Pope Leo XIII, whom she persuaded to consecrate the world solemnly to the Sacred Heart of Jesus. Describing that solemn consecration, Pope Leo XIII said it was "the greatest act of my pontificate".'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Mary_of_the_Divine_Heart", "biography": "rewritten"}'::jsonb),
