UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Sophie-Thérèse de Soubiran La Louvière, a French Roman Catholic nun, established the Sisters of Marie-Auxiliatrice. In 1877, once she had become a nun, she took the name Marie of the Sacred Heart. In French her name is pronounced [maʁi teʁɛz d subiʁã la luvjɛʁ].'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Sophie-Th%C3%A9r%C3%A8se_de_Soubiran_La_Louvi%C3%A8re", "biography": "rewritten"}'::jsonb),
