UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Henry was a clergyman from medieval England. In 1153 he travelled to Sweden with Cardinal Nicholas Breakspeare, and he was most likely intended to become the new Archbishop of Uppsala. Yet Sweden''s own church province could not be set up until 1164, after the civil war, so Henry would instead have been dispatched to Finland to organize its Church, where Christians had been present for two centuries already.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Henry_(bishop_of_Finland)", "biography": "rewritten"}'::jsonb),
