UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Teneu is a legendary Christian saint, venerated in medieval Glasgow in Scotland. By tradition she was a princess of the ancient Brittonic kingdom of Gododdin in the sixth century. Her son, Saint Mungo, was the founder of Glas Ghu, the city now called Glasgow, and an apostle to the Britons in Strathclyde. The city regards her and Mungo as co-patrons. St Enoch Square in Glasgow allegedly marks where a medieval chapel dedicated to her stood, at or close to her grave. Every year on 18 July she is commemorated.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Teneu", "biography": "rewritten"}'::jsonb),
