UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Triduana, known too as Trodline, Tredwell, and (in Norse) Trøllhaena, was an early Christian woman linked with a number of places in Scotland. The time when she lived is unknown, though it was probably sometime from the 4th to the 8th century AD.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Triduana", "biography": "rewritten"}'::jsonb),
