UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Olivia of Palermo (born in Palermo, 448; died in Tunis, 10 June 463, although another tradition places her life in the late 9th century AD under the Muslim Emirate of Sicily) was a Christian virgin-martyr. Since the Middle Ages the people of Palermo, Sicily, have venerated her as one of their local patron saints, as have the Sicilian towns of Monte San Giuliano, Termini Imerese, Alcamo, Pettineo and Cefalù.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Olivia_of_Palermo", "biography": "rewritten"}'::jsonb),
