UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Fintán, or Munnu, is counted among the saints of Ireland and Britain, and he served in both Ireland and Scotland. He was the founder and abbot of Teach-Mhunn Abbey, where visitors can see his bed and make pilgrimage; the site, Taghmon, now lies in County Wexford, in Leinster province, Ireland. Scotland venerates him as patron saint of Clan Campbell.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Fint%C3%A1n_of_Taghmon", "biography": "rewritten"}'::jsonb),
