UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Marie of the Incarnation, a French Ursuline nun, was a missionary, mystic, educator, and writer. She helped start the first institution in North America dedicated to educating girls, and she founded the Ursuline monastery of Quebec. Among the leading mystical authors of seventeenth-century French Catholicism, she left many autobiographical, spiritual, and epistolary writings. She also produced catechetical and linguistic texts written in various Indigenous tongues of New France.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Marie_of_the_Incarnation_(Ursuline)", "biography": "rewritten"}'::jsonb),
