UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Christina the Astonishing (known also as Christina Mirabilis) was born in Brustem, Belgium, and was a Christian holy woman. She is chiefly known for the legend that she rose from the dead during her own funeral mass, and for numerous other miracles said to have occurred while she was alive. Thomas of Cantimpré composed a hagiography of her using the testimony of people who had known her, and through it she became known outside Sint-Truiden.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Christina_the_Astonishing", "biography": "rewritten"}'::jsonb),
