UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Rosa Maria Sgorbati, known as Leonella Sgorbati, was a religious sister from Italy in the Consolata Missionaries, and she did mission work in Kenya and Somalia. Not long after Pope Benedict XVI gave the Regensburg lecture, she was killed in Somalia, after more than thirty years of work on that continent. Nursing, and the training of those hoping to become nurses, took most of her attention, and she also cared for the children in a children''s hospital where she was a frequent visitor.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Leonella_Sgorbati", "biography": "rewritten"}'::jsonb),
