UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Joan Elizabeth Lucy Bichier des Âges, usually called Elizabeth Bichier, was a French religious sister. In 1807 she and Andrew Fournet founded the Sisters of the Cross, also called Sisters of St. Andrew. This religious congregation, based in the Diocese of Poitiers, looked after the poor and taught the children of the countryside. She also helped inspire the founding of Betharram''s community of priests devoted to missionary service, named the Sacred Heart of Jesus Congregation. The Catholic Church has declared her a saint.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Joan_Elizabeth_Bichier_des_%C3%82ges", "biography": "rewritten"}'::jsonb),
