UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Benedict Joseph Labre, TOSF, a French Franciscan tertiary, is a Catholic saint. His family, who lived near Arras, France, were well-to-do. He tried a monastic lifestyle but then chose to be a pilgrim, living by begging as he journeyed to the majority of Europe''s major shrines. Labre is the patron saint of the homeless.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Benedict_Joseph_Labre", "biography": "rewritten"}'::jsonb),
