UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Bona of Pisa was a Third order Augustinian nun who guided travellers on pilgrimages. Pope John XXIII canonized her as a saint of the Catholic Church in 1962. She is regarded as the patron saint of Pisa, and among travellers more particularly of couriers, guides, pilgrims, and flight attendants.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Bona_of_Pisa", "biography": "rewritten"}'::jsonb),
