UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Eluned, who also goes by Aled and other names, was a virgin martyr of the 5th or 6th century from the region of present-day Breconshire. George Phillips, in his Catholic Encyclopedia entry, describes her as both "Luned of the Mabinogion" and "Lynette of Tennyson''s Gareth and Lynette."'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Eluned", "biography": "rewritten"}'::jsonb),
