UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Óengus of Tallaght, or else Óengus the Culdee, is the name by which Óengus mac Óengobann became better known; he served as an Irish bishop and reformer and was a writer too. He was at his height in the opening quarter of the 9th century. He is considered to have composed the Félire Óengusso, and perhaps the Martyrology of Tallaght.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/%C3%93engus_of_Tallaght", "biography": "rewritten"}'::jsonb),
