UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Angela Truszkowska, a Polish religious sister, was beatified by the Roman Catholic Church. She was the foundress of the Sisters of Saint Felix of Cantalice, a Third Order Regular of Saint Francis of Assisi, and shaped one of the earliest active-contemplative communities. Close to a century and a half later, that community numbered over 1,800 sisters on four continents, working in many different ministries.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Angela_Truszkowska", "biography": "rewritten"}'::jsonb),
