UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A French Catholic professed religious, Marie-Madeleine Postel (born Julie Françoise-Catherine Postel) was the founder of the congregation known as the Sisters of Christian Schools. She also belonged to the Third Order of Saint Francis. After the French Revolution she worked as a schoolteacher, overseeing the education of about 300 children. During the Revolution she used her school, by then disbanded, to shelter fugitive priests, though doing so put her own life at great risk.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Marie-Madeleine_Postel", "biography": "rewritten"}'::jsonb),
