UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Marie Deluil-Martiny (Marie of Jesus in religion) was a French Catholic religious sister; she was founder of a congregation, Daughters of the Heart of Jesus. In 1884 the convent''s gardener murdered her. Pope John Paul II beatified her in 1989.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Marie_Deluil-Martiny", "biography": "rewritten"}'::jsonb),
