UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Alicja Jadwiga Kotowska, a Polish religious sister, led the Resurrectionist convent in Wejherowo from 1934 until 1939. On 24 October 1939 the Gestapo arrested her while she was at prayer, and on 11 November she was murdered with more than 300 other Poles and Jews, in a killing that belonged to the Piaśnica massacres. Witnesses said they saw her comforting Jewish children as they were being transported. In 1999 the Roman Catholic Church beatified her among 108 Martyrs of World War II.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Alicja_Kotowska", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmqadk4ds39rojhj2vf6dr8nl'
  AND content."slug" = 'saint-alicja-kotowska'
  AND md5(content."payload"->>'biography') = 'ea9ed8ffa3d987c15e5db7b21c94fdb3';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Bolesława Maria Lament, a religious sister from Poland, was the founder of a community, Missionary Sisters of the Holy Family. She began as a seamstress and soon entered a religious congregation, but doubts about her vocation led her to leave shortly before her profession. She went back to sewing and, with two of her sisters, supported their siblings and widowed mother. When her brother, a seminarian, died, she was moved to return to religious life, and Honorat Koźmiński encouraged her to do so. She later founded a congregation that quickly grew and brought her to Russia, though the revolution there forced her to leave during World War I. Pope John Paul II beatified Lament in 1991 during a visit to Poland.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Boles%C5%82awa_Lament", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmqadk67o39rxjhj2zzmhesj8'
  AND content."slug" = 'saint-boles-awa-lament'
  AND md5(content."payload"->>'biography') = '22fbd788f7f070608d5b577960774b62';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Erhard of Regensburg served in the 7th century as bishop of that city. A Merovingian diploma of 684 mentions an Abbot Erhard of Ebersheimmunster, and he is identified with that man. Ancient documents also give his name as Erard and Herhard.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Erhard_of_Regensburg", "biography": "rewritten"}'::jsonb),
