UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A Spanish professed religious, Vicenta María López y Vicuña was the founder of the order called Religious of Mary Immaculate. It was devoted to serving "working girls", meaning young women in domestic employment. She held that care was due to housemaids and other domestic servants, and she paid special attention to girls who suffered abuse.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Vicenta_Mar%C3%ADa_L%C3%B3pez_i_Vicu%C3%B1a", "biography": "rewritten"}'::jsonb),
