  AND md5(content."payload"->>'biography') = '0759f666e8b346c7e3ec5660bd7cb467';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Blaesilla (364–384), also spelled Blesilla, was a Roman widow and a disciple of Jerome. Her family was a wealthy senatorial one in Rome. She was the eldest of Paula of Rome''s daughters and the sister of Eustochium, both of whom belonged to a group of wealthy Christian women following Jerome''s teachings. Widowed at 18, Blaesilla at first enjoyed her freedom, but a fever that threatened her life made her "a changed woman", turning to harsh asceticism and practicing fasting as a spiritual discipline. The fasts weakened her dramatically, and within four months she died, aged 20.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Blaesilla", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmqadk9eb39scjhj2vpo8pqp2'
  AND content."slug" = 'saint-blaesilla'
  AND md5(content."payload"->>'biography') = '393d12f82d8bb647a87d3d4ecf73ecab';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Bavo of Ghent is a saint of both the Roman Catholic and Eastern Orthodox churches. Under the guidance of Saint Amand, he gave up a dissolute life and became a missionary.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Bavo_of_Ghent", "biography": "rewritten"}'::jsonb),
