UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Victor and Corona, both saints, were Christian martyrs. Victor, a Roman soldier, suffered torture and death, and Corona was killed because she comforted him. She is invoked as a patron for matters involving money. She had no historical connection to pandemics or disease, although people have invoked her against the coronavirus pandemic.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Victor_and_Corona", "biography": "rewritten"}'::jsonb),
