UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'José Ramón Miguel Agustín Pro Juárez, also called Blessed Miguel Pro, SJ, was a Mexican Jesuit priest. He was executed while Plutarco Elías Calles was president, after being falsely accused of a bombing and of an attempt to assassinate Álvaro Obregón, a former president of Mexico.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Miguel_Pro", "biography": "rewritten"}'::jsonb),
