UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Ia of Cornwall was a martyr and evangelist of the 5th or 6th centuries who lived in the region of St Ives, Cornwall. Tradition says she was an Irish princess and the sister of Erc of Slane.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Ia_of_Cornwall", "biography": "rewritten"}'::jsonb),
