UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Philomena, also styled Philomena of Rome, was a virgin martyr of Greek origin. Her remains came to light on 24–25 May 1802 inside the Catacomb of Priscilla, where the tomb was closed by three tiles bearing the inscription Pax Tecum Filumena. This was read as showing that her name was Filumena, which in English becomes Philomena. She is called "The Wonderworker", and babies, infants, and youth have her as their patron saint.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Philomena", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
