UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Nicholas of Tolentino, OSA, an Italian Catholic mystic, goes by the title "Patron of Holy Souls" and is invoked as an intercessor for the souls in Purgatory, above all during Lent and in November. A member of the Augustinians, he is honored with weekly devotions for the suffering souls in Augustinian churches, as well as those of the Discalced Augustinians. All Souls'' Day, November 2, is especially meaningful to his devotees. He was canonized in 1446.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Nicholas_of_Tolentino", "biography": "rewritten"}'::jsonb),
