UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Ammon, Amun, Ammonas, Amoun (Ἀμοῦν), or Ammonius the Hermit lived in the 4th century as a Christian ascetic and was the founder of one of the best-known monastic communities in Egypt. He was later declared a saint. Among the ascetics of the Nitrian Desert he was one of the most revered, and Athanasius of Alexandria refers to Amun in his biography of Anthony the Great.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Amun", "biography": "rewritten"}'::jsonb),
