UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Anastasius of Antioch was a Christian convert and a martyr. He died during the Diocletianic Persecution, together with Anthony, Julian, Celsus and Marcionilla. Supposedly, Saint Julian of Antioch raised him from the dead, and that is why he converted. His memorial falls on 9 January. He is counted among the 140 Colonnade saints adorning St. Peter''s Square, and his relics are interred in Serbia, at the Ravanica Monastery.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Anastasius_of_Antioch_(martyr)", "biography": "rewritten"}'::jsonb),
