UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Alfredo Cremonesi, an Italian Roman Catholic priest, belonged to the Pontifical Institute for Foreign Missions. After studying in Crema and Milan, he traveled by boat from Genoa to Naples and then on to the Burmese missions. He vowed never to come back to the Italian mainland, and he spent the rest of his life among the Burmese people in mountain villages, in spite of great hardships. When the Japanese occupied the country during World War II, he was also held as their prisoner.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Alfredo_Cremonesi", "biography": "rewritten"}'::jsonb),
