UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Branwalator, also called Branwalader or Breward, was a British saint whose relics rested at Milton Abbas in Dorset and at Branscombe in Devon. He is thought to have come from Brittany, and the parish of Saint Brélade in Jersey takes its name from him; "Brelade" is a corrupted form of "Branwalader". Other forms of his name are Branuvelladurus, Brélade and, in French, Broladre.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Branwalator", "biography": "rewritten"}'::jsonb),
