UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Andrew of Crete was an ardent iconophile. His execution, in Constantinople''s Forum Bovis, was ordered by Emperor Constantine V and took place during the Byzantine Iconoclasm, in the year 766 or 767. The Catholic and Eastern Orthodox churches regard him as a martyr, and his feast day is October 17. A monastery dedicated to him, St Andrew in Krisei in Constantinople, is now the Koca Mustafa Pasha Mosque in Istanbul. 
Modern sources note that, as with many iconophile Saints who lived under the iconoclastic period, the figure of Andrew of Crete is unverified.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Andrew_of_Crete_(martyr)", "biography": "rewritten"}'::jsonb),
