UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'In 597 AD the Gregorian mission set out to Christianize the Anglo-Saxons, leading them away from their native Anglo-Saxon paganism. Honorius, a member of it, later became Archbishop of Canterbury. He consecrated the earliest bishop of Rochester who was a native Englishman, and he also helped Felix''s missionary efforts among the East Anglians. Honorius outlived all the other Gregorian missionaries.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Honorius_of_Canterbury", "biography": "rewritten"}'::jsonb),
