UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Hegesippus, also called Hegesippus the Nazarene, wrote as a Christian in the early Church. Though his name is Greek, perhaps he was a convert from Jewish background; he certainly wrote against Marcion and against the Gnostic heresies.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Hegesippus_(chronicler)", "biography": "rewritten"}'::jsonb),
