UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Catholic catechist and liturgist Carlos Manuel Cecilio Rodríguez Santiago was nicknamed "Blessed Charlie". Pope John Paul II beatified him on April 29, 2001. He holds the distinction of being the earliest Puerto Rican, and the earliest Caribbean-born layperson, ever to be beatified.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Carlos_Manuel_Rodr%C3%ADguez_Santiago", "biography": "rewritten"}'::jsonb),
