UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'From 668 to 690, Theodore of Tarsus served as Archbishop of Canterbury. He was raised in Tarsus but escaped to Constantinople once the Persian Empire had taken Tarsus and other cities. After a period of study there, he moved to Rome, and Pope Vitalian later ordered him installed as Archbishop of Canterbury. Two 8th-century texts record accounts of his life. He is chiefly remembered for reforming the English Church and for founding a school at Canterbury.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Theodore_of_Tarsus", "biography": "rewritten"}'::jsonb),
