UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'As founder, Vincent Pallotti, SAC, an Italian Catholic cleric, established the Society of the Catholic Apostolate, which later took the name Pious Society of Missions. Its original name came back into use in 1947. His remains lie in Onda, in the Church of San Salvatore. Regarded as the forerunner of Catholic Action, he has a feast day on 22 January.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Vincent_Pallotti", "biography": "rewritten"}'::jsonb),
