UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Maternus, also called Maternus II, is the first known bishop of Cologne. He is also reported to have been Trier''s third bishop and the founder of the diocese of Tongeren. The Catholic and Eastern Orthodox churches venerate him as a saint. The Basilica of Saint Maternus in Walcourt, Belgium, is allegedly his foundation.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Maternus_of_Cologne", "biography": "rewritten"}'::jsonb),
