UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saturnin of Toulouse was one of those "Apostles to the Gauls" who were dispatched in 250–251, when Decius and Gratus were consuls, to Christianise Gaul once Emperor Decius''s persecutions had nearly wiped out the small Christian communities. Fabian sent seven bishops from Rome to preach the Gospel in Gaul: Martial to Limoges, Austromoine to Clermont, Denis to Paris, Saturnin to Toulouse, Paul to Narbonne, Trophimus to Arles, and Gatien to Tours. 29 November is his feast day.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saturnin", "biography": "rewritten"}'::jsonb),
