UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Under the laws of Elizabeth I, Cuthbert Mayne, an English Catholic priest, was put to death. He was the first martyr among the seminary priests who had trained on the Continent. He was beatified in 1886, and in 1970 canonised as part of the group called Forty Martyrs of England and Wales.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Cuthbert_Mayne", "biography": "rewritten"}'::jsonb),
