UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'André-Hubert Fournet, a French Roman Catholic priest, was co-founder, along with Jeanne-Elisabeth Bichier des Ages, of the Sisters of St. Andrew, also called the Daughters of the Holy Cross. In childhood he disdained religion, yet an uncle''s shining influence and example led him to the priesthood. He was arrested briefly during the French Revolution for declining the oath, and in 1792 he fled France; he returned some time afterwards, when he met Bichier.
In 1926 he was beatified by Pope Pius XI, and a short while later, in 1933, canonized by him.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Andr%C3%A9-Hubert_Fournet", "biography": "rewritten"}'::jsonb),
