UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Born Biagio Arrighi, Theophilus of Corte was a priest from Italy, a Roman Catholic and a professed member of the Order of Friars Minor. Arrighi gained renown for preaching and evangelization and worked as a reformer, setting up Franciscan houses in northern Italian cities and throughout Corsica, the island of his birth. People knew him for a cheerful demeanor and eagerness to help others, as well as a tireless commitment to silence and solitude, which he urged his fellow friars to practice so they might commune better with God.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Theophilus_of_Corte", "biography": "rewritten"}'::jsonb),
