UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Wendreda (also called Wendreth) was a nun, healer, and saint of Anglo-Saxon England, perhaps living in the 7th century. She is uncertainly reported to have been the daughter of the Christian king Anna of East Anglia; if so, she was a sister of the better-known saints Ely''s abbess Etheldreda, Minster-in-Sheppey''s abbess Sexburgha, and Faremoutiers'' abbess Ethelburga, and a half-sister of Sæthryth, likewise an abbess at Faremoutiers.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Wendreda", "biography": "rewritten"}'::jsonb),
