UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Arsenius the Deacon, an anchorite in Egypt who had earlier been a Roman imperial tutor, is sometimes called Arsenius the Great, Arsenius the Roman, or Arsenius of Scetis and Turah. Among the Desert Fathers he ranks as one of the most highly regarded, and his teachings had a major influence on how asceticism and the contemplative life developed.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Arsenius_the_Great", "biography": "rewritten"}'::jsonb),
