UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Antoni Julian Nowowiejski was a bishop of Płock from Poland (1908–1941), titular archbishop of Silyum, historian, honorary citizen of Płock, and first secretary of the Polish Episcopal Conference (1918–1919). On 28 May 1941 he died at German hands in the Soldau concentration camp, close to Działdowo. In 1999 Pope John Paul II beatified him among 108 Martyrs of World War II.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Antoni_Julian_Nowowiejski", "biography": "rewritten"}'::jsonb),
