UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A noble Frankish poet, Angilbert, Count of Ponthieu, studied under Alcuin and served Charlemagne as secretary and diplomat, as well as being his son-in-law. As a pre-Congregation saint he is venerated, and he is commemorated each 18 February, his death day.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Angilbert", "biography": "rewritten"}'::jsonb),
