UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Maria Schininà, a Roman Catholic nun from Italy, was the founder in 1889 of the Sacred Heart of Jesus Sisters congregation. Her religious name combined Maria with "of the Sacred Heart of Jesus". Her teenage years showed no special spiritual focus, but her father''s death and her brother''s marriage triggered a sudden inner conversion, and she began reaching out to and working with the ill and the poor. In 1885 she started laying the foundations of the religious congregation she established in 1889.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Maria_Schinin%C3%A0", "biography": "rewritten"}'::jsonb),
