  AND md5(content."payload"->>'biography') = 'b5ae11e04c8cc4fb261b9124b893967d';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Lazarus of Bethany is a New Testament figure whom Jesus restores to life four days after he died, as the Gospel of John tells. He served as Marseilles'' first bishop. This resurrection counts among the miracles of Jesus. The Eastern Orthodox Church venerates Lazarus as Righteous Lazarus, the Four-Days Dead. What happened later in his life is told differently by the Eastern Orthodox and Catholic traditions.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Lazarus_of_Bethany", "biography": "rewritten"}'::jsonb),
