UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Benjamin, a deacon, was martyred in Persia around 424. His execution came during a forty-year persecution of Christians that spanned the reigns of two Persian kings. The first was Isdegerd I, who died in 421. Varanes V, Isdegerd''s son and successor, was the second, and he pursued the persecution so furiously that Christians suffered the cruelest tortures.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Benjamin_the_Deacon_and_Martyr", "biography": "rewritten"}'::jsonb),
