UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'José María of Manila, a Criollo Catholic priest, belonged to the Order of Friars Minor Capuchin as a friar. He was martyred early in the Spanish Civil War. The Roman Catholic Church has declared him blessed, making him the third Filipino to receive that honor.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Jos%C3%A9_Mar%C3%ADa_of_Manila", "biography": "rewritten"}'::jsonb),
