UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Margaret Ball (1515–1584) held a prominent place in Irish society of the 16th century. Despite being the widow of a man who had been Lord Mayor of Dublin, she was arrested for holding to the Catholic faith, and she died from deprivation while held in a dungeon at Dublin Castle. The Catholic Church declared her a martyr for the faith and beatified her in 1992, among 17 Irish Catholic Martyrs beatified together.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Margaret_Ball", "biography": "rewritten"}'::jsonb),
