UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'According to the Kentish royal legend, Saints Æthelred and Æthelberht were princes belonging to the Kingdom of Kent, murdered around AD 669 and afterward honored as saints and martyrs. Their story is a key part of the legend of Saint Mildrith, since tradition holds that the monastery of Minster in Thanet was established to atone for the crime.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/%C3%86thelred_and_%C3%86thelberht", "biography": "rewritten"}'::jsonb),
