UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Eustace White was a Catholic priest. On account of his service he stood trial in December 1591 and was then hanged, drawn and quartered; the execution took place on 10 December 1591 at Tyburn, and a second priest and three laymen suffered it alongside him. In 1970 Pope Paul VI canonised him, and he belongs to the group called Forty Martyrs of England and Wales.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Eustace_White", "biography": "rewritten"}'::jsonb),
