  AND md5(content."payload"->>'biography') = 'ee23be9885020a78227a93afad51d49c';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Falco, sometimes called Falco of Maastricht or of Tongeren, is traditionally held to have been bishop of Maastricht from 495 to 512. The Roman Catholic Church venerates him too as a saint.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Falco_of_Maastricht", "biography": "rewritten"}'::jsonb),
