UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Luigi Giovanni Orione, an Italian priest, worked to meet the social needs of his country during the upheavals of the late 19th century. For that purpose he established a religious institute for men. The Catholic Church has declared him a saint.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Luigi_Orione", "biography": "rewritten"}'::jsonb),
