UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Paulinus of Trier, bishop of that city, backed St. Athanasius the Great in his fight against Arianism. In 353, at the Synod of Arles, the Arians went after him, and Emperor Constantius II effectively singled him out, so he was exiled to Phrygia. Five years later he died in exile, yet in 395 his remains came back to Trier. His tomb lies in the crypt of St. Paulinus'' Church in Trier, which was rededicated to him.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Paulinus_of_Trier", "biography": "rewritten"}'::jsonb),
