UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Paisius of Hilendar, also written Paìsiy Hilendàrski, was a clergyman of the Bulgarian Orthodox Church who played a central part in the Bulgarian National Revival. He is best known as the writer of Istoriya Slavyanobolgarskaya, which was the earliest major modern Bulgarian history; it won wide fame and was copied and spread across the Bulgarian lands. Overall it stands third among modern works of Bulgarian history, after History of Bulgaria by Petar Bogdan Bakshev (1667) and the one by Blasius Kleiner (1761). He is regarded as the forefather of that Revival.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Paisius_of_Hilendar", "biography": "rewritten"}'::jsonb),
