WHERE content."id" = 'cmqadqvhd3caojhj2lc8zxiir'
  AND content."slug" = 'saint-paisius-of-hilendar'
  AND md5(content."payload"->>'biography') = 'a372090ae4a49bfe92f841c2c0461d2a';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Beatus of Liébana, a monk and theologian, wrote the Commentary on the Apocalypse, which is largely a compilation of earlier authorities'' opinions on the Apocalypse of John, the biblical Book of Revelation. Its influence was local, chiefly on the Iberian Peninsula, until about the 13th century. Today it is recalled mostly for its 27 surviving manuscript copies, richly illustrated with often spectacular miniatures that rank as outstanding monuments of Mozarabic art. The Morgan Beatus and Saint-Sever Beatus are examples; they are discussed further in the article on the book. Unusually for a Christian theological work, Beatus evidently meant it to be illustrated from the start. Credit for the original designs, and possibly the painting, of the earliest illustrations goes to him, although they have not survived.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Beatus_of_Li%C3%A9bana", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmqadqvtg3carjhj27s9h3vkc'
  AND content."slug" = 'saint-beatus-of-liebana'
  AND md5(content."payload"->>'biography') = 'e246249e84ffd204b192f263b3630887';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Popularly called Padre Hurtado, Alberto Hurtado, SJ, was a Chilean priest of the Jesuit order, as well as a lawyer, social worker, and writer, with Basque ancestry. In 1944 he established the Hogar de Cristo foundation.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Alberto_Hurtado", "biography": "rewritten"}'::jsonb),
