UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The best-known Bishop of Caithness, and the founder of Dornoch Cathedral, was Gilbert de Moravia, who later became known as Saint Gilbert of Dornoch (also Gilbert of Caithness). His name may suggest that he belonged to the Lords of Duffus, a semi-Gaelicized family of Flemish origin. While Gilbert was bishop, the family brought the Earldom of Sutherland into being under William de Moravia (the 1st Earl of Sutherland), possibly a cousin of Gilbert.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Gilbert_de_Moravia", "biography": "rewritten"}'::jsonb),
