WHERE content."id" = 'cmqadqyjp3caxjhj2juizye6f'
  AND content."slug" = 'saint-gilbert-de-moravia'
  AND md5(content."payload"->>'biography') = '57f87c10cd107f57ed4cd237b3beefb0';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Leontius of Monemvasia, also called Saint Leontius of Achaia, was an Eastern Orthodox Saint. He was born in 1377 in Monemvasia and in the 15th century lived as an ascetic in the northern Peloponnese region.
The main source for his life is his first biographer, whom some scholars identify as the Byzantine philosopher and Ecumenical Patriarch of Constantinople, Gennadius Scholarius.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Leontius_of_Monemvasia", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmqadqyr43cb0jhj2zj0qffvc'
  AND content."slug" = 'saint-leontius-of-monemvasia'
  AND md5(content."payload"->>'biography') = '446c9bce8393fa3afb0eed3ebbefc019';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Æthelflæd of Romsey was an abbess of Romsey Abbey in the late tenth century. Little is clear about who she was, although later stories described her as a nobleman''s daughter from the tenth century. Her feast day is 23rd October. A record exists, though a doubtful one, of a sainted daughter named Æthelflæd born to King Edward the Elder, which is probably a mix-up with Æthelflæd of Romsey.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/%C3%86thelfl%C3%A6d_of_Romsey", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmqadqywo3cb3jhj2h27e5pcb'
  AND content."slug" = 'saint-ethelfleda-of-romsey'
  AND md5(content."payload"->>'biography') = '1f05f9b38a70de584c9f21991cae4411';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Gobnait, who is also called Gobnat, Mo Gobnat, Abigail, or Deborah, was an early medieval female Irish saint. Her church, Móin Mór (later named Bairnech), stood at Ballyvourney, a village in County Cork, Ireland. The Múscraige are linked with her, and both her church and her convent lay on the boundary between the Múscraige Mittine and the Eóganacht Locha Léin. Her feast day falls on February 11.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Gobnait", "biography": "rewritten"}'::jsonb),
