SET "payload" = content."payload" || jsonb_build_object('biography', 'A noble Persian lady, known as Golindouch, Golindukht, Golindokht, or Dolindokht, embraced Christianity and took the name Maria. She is a saint and a martyr.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Golinduch", "biography": "rewritten"}'::jsonb),
