UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Servatius held the office of bishop of Tongeren. He is patron saint of Schijndel and Grimbergen, both towns, and of the city of Maastricht. He is counted among the Ice Saints, whose feasts come in the middle of May, and his own is on 13 May.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Servatius_of_Tongeren", "biography": "rewritten"}'::jsonb),
