UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Jurgis Matulaitis-Matulevičius was a Catholic prelate of the Latin Church. He held the see of Vilnius as bishop from late 1918 until resigning in 1925. He was also the founder of two congregations: Handmaids of Jesus in the Eucharist, and Sisters of the Immaculate Conception. From 1911 to his death he was the Marian Fathers'' Superior-General. When the Russian authorities had banned every religious order, he laboured secretly to bring the Marian Fathers back to life, and he even gave up his teaching position so as to devote himself more fully to that secret revival. A well-known teacher and spiritual director, he established further branches of the order in places far from Russian authorities, including Switzerland and the United States.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Jurgis_Matulaitis-Matulevi%C4%8Dius", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmqadr65g3cl2jhj26kcjypvg'
