  AND md5(content."payload"->>'biography') = 'f1bde62b151c0f970158040209f746c0';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Charles Lwanga, a Ugandan who converted to the Catholic Church, was martyred along with his companions. The Catholic Church reveres him as a saint, as does the Anglican Communion.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Charles_Lwanga", "biography": "rewritten"}'::jsonb),
