UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Suitbert (also Suidbert, Suitbertus, Swithbert, or Swidbert) was a native of Northumbria, England, born in the seventh century. He went with Willibrord on the Anglo-Saxon mission.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Suitbert_of_Kaiserswerth", "biography": "rewritten"}'::jsonb),
