UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Corbinian, a Frankish bishop, lived for fourteen years as a hermit near Chartres and then travelled as a pilgrim to Rome. After that pilgrimage, Pope Gregory II dispatched him to Bavaria. He objected to Duke Grimoald of Bavaria marrying Biltrudis, the widow of the duke''s brother, and as a result he spent a period in exile. His feast day falls on 8 September, and the translation of his relics is commemorated on 20 November.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Corbinian", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmqadr6th3clbjhj2bam7tru6'
  AND content."slug" = 'saint-corbinian'
  AND md5(content."payload"->>'biography') = 'a0e2ced2f73b3acdd203d9d007f4b9b8';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Peter Julian Eymard, a French Catholic priest and saint, was the founder of two religious institutes: for men, the Congregation of the Blessed Sacrament, and for women, the Servants of the Blessed Sacrament.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Peter_Julian_Eymard", "biography": "rewritten"}'::jsonb),
