UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Virgil, spelled also Vergil, Vergilius, Virgilius, Feirgil or Fearghal, was an early astronomer and an Irish priest. Around 745 he left Ireland meaning to go to the Holy Land, but like many fellow Irishmen he ended up settling in Francia. He served as abbot of Aghaboe, then as bishop of Ossory, and afterward as bishop of Salzburg. He earned the names "the geometer" and "the Apostle of Carinthia".'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Virgil_of_Salzburg", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
