UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A Polish priest, Honorat Koźmiński (born Florentyn Wacław Jan Stefan Koźmiński) was a professed member of the Order of Friars Minor Capuchin, and he founded sixteen religious congregations. He first worked as a teacher. He then revived the clandestine religious orders suppressed by the Russian Empire while it occupied Poland. In this work he cooperated with many people, and he promoted the Third Order of Saint Francis among the people.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Honorat_Ko%C5%BAmi%C5%84ski", "biography": "rewritten"}'::jsonb),
