UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Caterina Cittadini, a Roman Catholic religious from Bergamo in Italy, founded the Ursuline Sisters of Saint Jerome Emiliani. The congregation devoted itself to educating girls in Bergamo and nearby areas, and it has since spread beyond Italy. Cittadini lost her parents in childhood and grew in faith among the other children of an orphanage with strong spiritual guidance. She founded her order partly out of devotion to Saint Jerome Emiliani and to the Blessed Mother.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Caterina_Cittadini", "biography": "rewritten"}'::jsonb),
