UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Crispina, a virgin and martyr of Africa, suffered during the persecution under Diocletian. She was born in Thagora, a town of the Roman province of Numidia in North Africa, in what is now Taoura, Algeria. She was beheaded at Theveste, also in Numidia.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Crispina", "biography": "rewritten"}'::jsonb),
