UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Catholics venerate Saint Magnus of Trani, also called Magnus of Anagni, Magnus Episcopus or Magnus of Fabrateria Vetus, as the patron of Anagni, in Lazio''s Province of Frosinone, a role he shares with his apprentice Saint Secundina. Legend also links him with Rome''s church of Santi Michele e Magno, whence a skull and arm were taken to St. Peter''s Basilica. Louisville, Kentucky has venerated the saint since 1901, when a set of relics from Anagni, including a skull, was sent to St. Martin of Tours Catholic Church there.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Magnus_of_Trani", "biography": "rewritten"}'::jsonb),
