UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Jan Sarkander was a Polish-Czech Roman Catholic priest. He married briefly and was widowed, after which he took up the path to the priesthood and actively defended Catholicism amid anti-Catholic sentiment and conflict. False accusations led to his arrest, intended to silence him. He would not yield to his tormenters; they tortured him for about a month, and then he died.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Jan_Sarkander", "biography": "rewritten"}'::jsonb),
