UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Born Francisco Tomás de San Juan Bautista Márquez y Sánchez, Leopold of Alpandeire was a Spanish Capuchin friar who lived mostly in Granada. Residents there continue to remember him and celebrate him as exemplifying virtue and a Christian life. Devotion to him has spread considerably across southern Spain, and he was beatified in September 2010.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Leopold_of_Alpandeire", "biography": "rewritten"}'::jsonb),
