UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Gildard (Gildardus, Gildaredus), also called Godard or Godardus, held the bishopric of Rouen between 488 and 525. The Roman Catholic Church venerates him as a saint, and Sarum Rite missals describe him as a confessor. He has a close connection with Medard, whom tradition took to be his brother.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Gildard", "biography": "rewritten"}'::jsonb),
