UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Maria Costanza Panas, born Agnese Pacifica Panas, was a Capuchin Poor Clare from Italy. She was educated in cities of northern Italy and then worked as a teacher. Only a short time after her teaching career did she decide to become a nun; because her parents and uncle opposed the wish, she entered a convent in secret. There she was novice mistress and twice served as abbess, and despite several severe illnesses in the late 1950s she even won election to an important religious council.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Maria_Costanza_Panas", "biography": "rewritten"}'::jsonb),
