UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'An English saint, Edith belonged as a nun to the community at Wilton Abbey. Her father was Edgar, King of England, and her mother Saint Wulfthryth. It is possible that her parents were married and that Edgar had abducted Wulfthryth out of Wilton Abbey, but Wulfthryth went back to Wilton with Edith while the girl was an infant, and the marriage was dissolved. Mother and daughter lived out their days at Wilton.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Edith_of_Wilton", "biography": "rewritten"}'::jsonb),
