UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Eleven Catholic saints, the Martyrs of Damascus, were killed by Druze while praying in a Franciscan-run parish in Damascus, amid the civil conflict of 1860 that struck Mount Lebanon and Damascus. They are made up of The Massabki Brothers and Manuel Ruiz Lopez and Companions. The Massabki Brothers, sons of Nehme Massabki, were three Maronite Catholics from Damascus, which lies in present-day Syria. The Franciscans were Emmanuel Ruiz and seven other martyrs; of these eight, seven came from Spain and one from Austria.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Martyrs_of_Damascus", "biography": "rewritten"}'::jsonb),
