UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Junian was a Christian hermit of the 5th century at the place later called Saint-Junien in his honor. Tradition holds that he was born in 486, in the reign of Clovis I, to the Count of Cambrai. By the same tradition, he and Saint Leonard were baptized together.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Junian_of_Saint-Junien", "biography": "rewritten"}'::jsonb),
