UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Rafael Arnáiz Barón, OCSO, a Spanish Trappist conventual oblate, also bore the religious name María Rafael. After beginning architecture studies in Madrid, he chose to give them up for the religious life. Type 1 diabetes and a summons to active military service repeatedly broke into that life, yet neither weakened his religious call. He coped with his diabetes as well as he could, living reflectively and writing about spiritual subjects in his letters.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Rafael_Arnaiz_Bar%C3%B3n", "biography": "rewritten"}'::jsonb),
