UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Benedetta Bianchi Porro, from Romagna, was an Italian Roman Catholic. Polio struck her in her teenage years and severely affected her health, yet Porro pursued a career in medicine and excelled as a student. Her illness progressed so aggressively, however, that she had to abandon those medical ambitions. Hoping for improvement she underwent multiple surgeries; these failed to relieve her problems, and her health deteriorated rapidly.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Benedetta_Bianchi_Porro", "biography": "rewritten"}'::jsonb),
