UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Christians put to death in Rome in 64 during Nero''s persecution are known as the Church of Rome''s First Martyrs. Both Tacitus and, among other writers, Pope Clement I record the event. The Roman Catholic Church marks them with an optional memorial on 30 June, and the Orthodox Church also keeps 30 June for them in its liturgical calendar, as Western saints from before the East-West Schism of 1054.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/First_Martyrs_of_the_Church_of_Rome", "biography": "rewritten"}'::jsonb),
