UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Aredius, also called Yrieix, Abbé d''Attanum and Arède d''Atane, served Theudebert I, king of Austrasia, as chancellor and later became Abbot of Attane. There he established a monastery that, after his death, was renamed in his honour as Saint-Yrieix. Where it stood, the town came to be called Saint-Yrieix-la-Perche, and several other French communes also bear the name Saint-Yrieix because of him.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Aredius", "biography": "rewritten"}'::jsonb),
