UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Johann Nepomuk von Tschiderer zu Gleifheim, a Roman Catholic prelate from Austria and Italy, was Bishop of Trent from 1834 until he died. His parents were Austrian, but because he came into the world in Bolzano, a town in Italy, he was regarded as Austro-Italian.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Johann_Nepomuk_von_Tschiderer_zu_Gleifheim", "biography": "rewritten"}'::jsonb),
