UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Paschasius Radbertus (785–865), a Carolingian theologian, was abbot at Corbie, a Picardy monastery. The queen regent Bathilde founded it in 657 or 660, settling there a community of monks drawn from Luxeuil Abbey. His best-known and most influential work, written around 831, explains the nature of the Eucharist and is titled De Corpore et Sanguine Domini. Pope Gregory VII canonized him in 1073. He is commemorated on 26 April.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Paschasius_Radbertus", "biography": "rewritten"}'::jsonb),
