UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Epiphanius of Pavia (438–496), who came to be venerated as Saint Epiphanius of Pavia, served as Bishop of Pavia from 466 to his death in 496. He had also been a lector, subdeacon and deacon.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Epiphanius_of_Pavia", "biography": "rewritten"}'::jsonb),
