UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Matěj Pavlík, later Gorazd of Prague, led, as hierarch, the Orthodox Church that was revived in Czechoslovakia after World War I. In World War II, the assassins of Reinhard Heydrich, an SS-Obergruppenfuhrer nicknamed The Hangman of Prague, found refuge with him; he had hidden them in the Prague cathedral of Saints Cyril and Methodius. When the Schutzstaffel discovered them in the cathedral crypt, Gorazd accepted full responsibility for protecting them, hoping to lessen Nazi reprisals against his congregation. That act made his execution certain, and so his martyrdom, in the reprisals that came next. His feast day is 4 September (NC) or, by the Old Calendar, 22 August (OC).'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Gorazd_Pavl%C3%ADk", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmqadtswm3efyjhj2op1amhjm'
  AND content."slug" = 'saint-gorazd'
