  AND md5(content."payload"->>'biography') = '2f2bfc51efc7da3a0247cf197b46ea64';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Jacques Berthieu, SJ, was a Jesuit priest from France who worked as a missionary in Madagascar. His murder occurred in 1896, amid the Menalamba rebellion. Of the martyrs of Madagascar, he was the first to be beatified. Pope Benedict XVI canonized him in 2012.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Jacques_Berthieu", "biography": "rewritten"}'::jsonb),
