UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Euphrosyne of Alexandria, who is also called Euphrosynē, was a saint from Egypt. She dressed as a man to be admitted to a monastery, where she lived as an ascetic for 38 years. The Greek Orthodox Church and Byzantine Rite Catholics keep her feast day on September 25, the Episcopal Church on September 27, and the Roman Catholic Church on January 16.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Euphrosyne_of_Alexandria", "biography": "rewritten"}'::jsonb),
