  AND md5(content."payload"->>'biography') = 'b9a488e8259b60a534441cb73460c23b';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Berhtwald was England''s ninth Archbishop of Canterbury, and Theodore of Tarsus came before him. With Berhtwald starts the first unbroken run of native-born Archbishops of Canterbury. Earlier archbishops had been Anglo-Saxon too, but none of them followed one another in office until Tatwine succeeded Berhtwald.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Berhtwald", "biography": "rewritten"}'::jsonb),
