UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Margareta Ebner, a German professed religious, was a member of the Dominican Nuns. She began in 1311 to have a sequence of spiritual visions, during which Jesus Christ conveyed messages to her; at her spiritual director''s insistence she wrote these down in letters and a journal. For much of her religious life, Pope John XXII and Holy Roman Emperor Louis the Bavarian were locked in bitter conflict, and she and her convent stood loyally with Louis.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Margareta_Ebner", "biography": "rewritten"}'::jsonb),
