UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Oliver Plunkett (Irish: Oilibhéar Pluincéid), whose surname is also spelled Plunket, was born on 1 November 1625 and died on 1 July 1681. He was the Catholic Archbishop of Armagh, Primate of All Ireland, and last victim of the Popish Plot. The Church beatified him in 1920, then canonised him in 1975, which made him the first new Irish saint in nearly seven hundred years.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Oliver_Plunkett", "biography": "rewritten"}'::jsonb),
