UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pietro I Orseolo OSBCam, who is also called Peter Urseulus (928–987), served as Doge of Venice from 976 to 978. He gave up the office and slipped away at midnight to become a monk, and afterward joined the Camaldolese Hermits of Mount Corona. Both the Eastern Orthodox Church and the Roman Catholic Church venerate him as a saint.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pietro_I_Orseolo", "biography": "rewritten"}'::jsonb),
