UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Aldhelm, who wrote and studied Latin poetry, served as Abbot of Malmesbury Abbey and then Bishop of Sherborne. He was born some time before the mid-point of the 7th century. Tradition makes him the son of Kenten, a member of the royal house of Wessex. His early biographer Faritius claims he was the brother of King Ine, which he certainly was not. Aldhelm was venerated as a saint following his death, and his feast day falls on the anniversary of it, 25 May.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Aldhelm", "biography": "rewritten"}'::jsonb),
