UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Born Pacificus Ramati, Pacificus da Ceredano was an Italian Roman Catholic priest who had professed vows in the Order of Friars Minor. On 7 July 1745 Pope Benedict XIV confirmed the "cultus" paid to him and beatified him.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pacificus_of_Ceredano", "biography": "rewritten"}'::jsonb),
