WHERE content."id" = 'cmqadvex23fo3jhj2qx3kucvy'
  AND content."slug" = 'saint-wilfrid'
  AND md5(content."payload"->>'biography') = '3bcabd79c840d8893ecfd124bf19c6d7';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Livinus, also called Livinus of Ghent, lived from c. 580 to 12 November 657. He worked as an apostle in Flanders and in Brabant. Catholic tradition venerates him as a saint and martyr, most particularly at the Saint Bavo Chapel, Ghent. 12 November is his feast day.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Livinus", "biography": "rewritten"}'::jsonb),
