UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Simon Stock, OCarm, an English Catholic priest and saint of the 13th century, served as an early prior within the Carmelite Order. Tradition holds that the Blessed Virgin Mary appeared to him and presented him with the Brown Scapular. People''s devotion to him is typically linked to their devotion toward Our Lady of Mount Carmel.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Simon_Stock", "biography": "rewritten"}'::jsonb),
