SET "payload" = content."payload" || jsonb_build_object('biography', 'Pompeius of Pavia served as bishop of that city. Some believe he may have suffered in the Roman persecutions, though no list records him as a martyr.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pompeius_of_Pavia", "biography": "rewritten"}'::jsonb),
