SET "payload" = content."payload" || jsonb_build_object('biography', 'Giuseppe Benedetto Cottolengo (Joseph Benedict Cottolengo) is counted among the saints by the Roman Catholic Church. He was founder of an institution named Little House of Divine Providence.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Giuseppe_Benedetto_Cottolengo", "biography": "rewritten"}'::jsonb),
