UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'José Gregorio Hernández Cisneros, O.F.S., was a physician from Venezuela and an active member of the Franciscan Third Order, formally the Third Order of Saint Francis. He was born in Isnotú, Trujillo State, and became a very celebrated doctor, even more so after he died. He was known for numerous acts of charity toward the poor of his society and for a devoted life of faith. Pope Francis beatified him in 2021 for the Catholic Church and approved his canonization in early 2025. Pope Leo XIV canonized him on 19 October 2025, making him among the first two Venezuelans so recognized by the Catholic Church.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Jos%C3%A9_Gregorio_Hern%C3%A1ndez", "biography": "rewritten"}'::jsonb),
