UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'According to records, Venerable John the Hermit took up an ascetic life while still young. He was born in Armenia in the fourth century, and his mother Juliana was a devout Eastern Orthodox Christian. John was a spiritual son of St. Pharmutius, who instructed him for a time. In the end John sought deeper solitude and settled at the bottom of a dry well. Pharmutius brought him bread there each day, and sacred tradition says an angel supplied that bread.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/John_the_Hermit_(Armenian)", "biography": "rewritten"}'::jsonb),
