UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Vissarion of the Agathonos, born Andreas Korkoliakos, was a monk of the Greek Orthodox Church and a Saint at the Agathonos Monastery near Lamia in Central Greece. He took monastic vows in his teens, and people who knew him thought of him as a cleric of unusually kind heart and humanitarian spirit.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Vissarion_of_the_Agathonos", "biography": "rewritten"}'::jsonb),
