UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Berard of Carbio was a Franciscan friar of the thirteenth century who was put to death in Morocco for trying to spread Christianity. Along with Peter, Otho, Accursius, and Adjutus, his companions, he is venerated as a Catholic saint, and the group is regarded as the Franciscan Protomartyrs. The king twice expelled them from his realm, but each time they came back and went on preaching against Islam. Finally, out of anger and frustration, the king had them beheaded.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Berard_of_Carbio", "biography": "rewritten"}'::jsonb),
