UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Magneric of Trier, a Frank, served as bishop of Trier and is honored as a saint by both the Catholic and Orthodox Churches; his feast day falls on July 25. His was among the earliest Germanic names borne by a bishop. Gregory of Tours counted him as a friend and admirer and mentions him in his History of the Franks. Magneric ordained his disciple St Géry, who became bishop of Cambrai-Arras when King Childebert II came to the throne. Venantius Fortunatus portrayed him as a virtuous and charitable man, calling him an "ornament of bishops".'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Magneric_of_Trier", "biography": "rewritten"}'::jsonb),
