UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A Spanish Catholic prelate, Florentino Asensio Barroso administered the Diocese of Barbastro as Apostolic Administrator. Earlier, as a priest, he was chaplain both to the Servants of Jesus and to the Little Sisters of the Poor. In 1935 he was made a bishop, and in 1936, amid the Spanish Civil War, he was killed.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Florentino_Asensio_Barroso", "biography": "rewritten"}'::jsonb),
