UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Bernardino Realino, a Roman Catholic priest from Italy, was a professed member of the Jesuits, and he spent his whole career in the regions of Naples and Lecce. He first practised law and held several municipal offices, until he felt called to the Jesuit life and was ordained to the priesthood in Naples. Because of his dedication to the poor and his skill as a preacher, he is often called the "Apostle of Lecce".'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Bernardino_Realino", "biography": "rewritten"}'::jsonb),
