UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Siblings Francisco de Jesus Marto and Jacinta de Jesus Marto lived in Aljustrel, a little hamlet by Fátima, Portugal. Along with Lúcia dos Santos (1907–2005), their cousin, they reportedly saw the Angel of Peace appear three times in 1916 and the Blessed Virgin Mary appear several times at Cova da Iria in 1917. These events gave the Virgin Mary the title Our Lady of Fátima, and the Sanctuary of Fátima grew into a leading center of Catholic pilgrimage worldwide.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Francisco_and_Jacinta_Marto", "biography": "rewritten"}'::jsonb),
