UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Melchor Chyliński, whose name as a religious was Rafał, was a Polish priest of the Roman Catholic Church. He professed vows as a member of the Order of Friars Minor Conventual. Though he began as a soldier, he chose to become a priest instead, joined the Franciscans, and professed his vows before being ordained. He was known as well for preaching in a plain style and for generously helping the poor by giving out clothing and food.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Melchor_Chyli%C5%84ski", "biography": "rewritten"}'::jsonb),
