UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Josef Mayr-Nusser was an Italian Roman Catholic who headed the Bolzano division''s Saint Vincent de Paul Conference as its President, and who belonged to Catholic Action. He is best remembered for declining to swear the Hitler oath once he had been drafted as a Nazi soldier. At the Dachau concentration camp he was sentenced to death. His own death came in 1945, on the journey to the camp. The title "Martyr of the First Commandment" is his.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Josef_Mayr-Nusser", "biography": "rewritten"}'::jsonb),
