UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Magnus of Oderzo, an Italian saint of the 7th century, is remembered for founding some of the first churches in Venice. As Bishop of Oderzo, he went to Venice in 638 to escape the Lombard invasion of Italy. In Venice he established the churches of Santi Apostoli, San Pietro di Castello, Santa Maria Formosa, Santa Giustina, San Giovanni in Bragora, San Zaccaria, San Salvador and Angelo San Raffaele.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Magnus_of_Oderzo", "biography": "rewritten"}'::jsonb),
