UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The Blessed Martyrs of Drina were nuns, who had professed vows in the Daughters of Divine Charity and lost their lives in World War II. On 15 December 1941 four of them died by leaping out of a window in Goražde, reportedly so that Chetniks would not rape them. Chetniks killed the fifth sister the next week, in Sjetlina. Pope Benedict XVI declared the five nuns martyrs and beatified them on 24 September 2011.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Blessed_Martyrs_of_Drina", "biography": "rewritten"}'::jsonb),
