UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The Catholic Church venerates Saint Castor of Karden; he lived in the 4th century as a priest and hermit. Maximinus of Trier took him as a pupil around 345 AD and ordained him a priest. Castor, like his teacher, may have originated in the Aquitaine region. After his ordination he settled as a hermit at Karden on the Moselle with several companions; there they gave themselves to an ascetic life and formed a small religious community.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Castor_of_Karden", "biography": "rewritten"}'::jsonb),
