UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'From 846 Eberhard was Frankish Duke of Friuli. His name also appears as Everard, Evrard, Erhard, or Eberard, and in Latinized forms as Everardus, Eberardus, or Eberhardus; he himself spelled it "Evvrardus". In his lifetime he was a significant political, military, and cultural figure of the Carolingian Empire. He owned a large library, commissioned Latin literary works from Lupus Servatus as well as Sedulius Scottus, and corresponded with Gottschalk, Rabanus Maurus, and Hincmar, who were theologians and church leaders.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Eberhard_of_Friuli", "biography": "rewritten"}'::jsonb),
