UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Darío Acosta Zurita was a Mexican Roman Catholic priest who served in Veracruz, where he lived and died. Having at first been turned away, he later began his priestly studies and gained a reputation for athleticism as a seminarian. He was ordained in 1931 by Bishop Rafael Guízar Valencia. Three months afterward gunmen burst into the cathedral to enforce the so-called Tejeda Law, and they shot him dead.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Dar%C3%ADo_Acosta_Zurita", "biography": "rewritten"}'::jsonb),
