UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Elisabetta Sanna, T.O.S.F., an Italian Roman Catholic from Codrongianos in the Province of Sassari, took an active part in the Union of the Catholic Apostolate and in the Third Order of Saint Francis. Within the Union, Vincent Pallotti was her friend and compatriot. Smallpox left Sanna largely disabled, and further illnesses kept her from going back to her hometown after she set out on a pilgrimage. She was therefore obliged to settle in Rome, where she later died.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Elisabetta_Sanna", "biography": "rewritten"}'::jsonb),
