UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Francisca Cualladó Baixauli, a Spanish Catholic seamstress, was born in Molino de San Isidro, in the ward of Ruzafa, Valencia. Firing-squad executioners shot her in 1936, amid the Spanish Civil War, at Benifaió''s Torre Espioca. The Catholic Church regards her as a martyr, and Pope John Paul II beatified her on 11 March 2001. September 19 is the day of her feast.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Francisca_Cuallad%C3%B3_Baixauli", "biography": "rewritten"}'::jsonb),
