UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Guadalupe Ortiz de Landázuri Fernández de Heredia, a professor and Catholic from Spain, was a member of Opus Dei. After meeting its founder Josemaría Escrivá in 1944, she joined, ranking among the earliest women to do so. She had a hand in starting Opus Dei in Mexico, and she also worked directly with Escrivá in Rome. She died in 1975 of a serious heart condition.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Guadalupe_Ortiz_de_Land%C3%A1zuri_Fern%C3%A1ndez_de_Heredia", "biography": "rewritten"}'::jsonb),
