UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Endelient was a saint of Cornwall who lived in the 5th and 6th century. Belief holds that she was a daughter of King Brychan of Wales born in South Wales, who journeyed to North Cornwall, joining her siblings in the work of converting the locals to Christianity. According to legend, King Arthur was her godfather, and she was a hermit at Trentinney, sustained by the milk of a cow. Her memory lives on at St Endellion, whose church and village carry her name, Endellion being the Anglicised form of it. Her feast day falls on 29 April.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Endelient", "biography": "rewritten"}'::jsonb),
