  AND md5(content."payload"->>'biography') = '46cd4306d71595cb4781a7023e88c34c';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Eata, also called Eata of Lindisfarne, served as Bishop of Hexham from 678 to 681 and then as Bishop of Lindisfarne, from a date before 681 to 685. After being translated back to Hexham, he remained there until he died in 685 or 686. Eata was Northumbria''s first native bishop of Lindisfarne.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Eata_of_Hexham", "biography": "rewritten"}'::jsonb),
