UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Ursicinus of Brescia, an Italian saint, was bishop of Brescia in Lombardy. In 347, the year he died, he attended the Council of Sardica; his shrine may still be viewed. His feast day is 1 December.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Ursicinus_of_Brescia", "biography": "rewritten"}'::jsonb),
