UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Józef and Wiktoria Ulma with Seven Children, known as the Ulma family, were a Polish Catholic family of Markowa, Poland. During the Nazi German occupation in World War II they tried to save Polish Jewish families from the Holocaust by sheltering them in their own home. For this, the couple and the children were put to death without trial on 24 March 1944.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Ulma_family", "biography": "rewritten"}'::jsonb),
