UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Juventius, whose name is also spelled Eventius, Iventius, or Inventius, served as bishop of Pavia in the 4th century for 39 years. Saint Hermagoras sent him, with Syrus of Pavia, to evangelize Pavia, where they established a bishopric. Syrus afterward became the first bishop of Pavia.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Juventius_of_Pavia", "biography": "rewritten"}'::jsonb),
