  AND content."slug" = 'saint-peter-of-rates'
  AND md5(content."payload"->>'biography') = 'e733c1532f6352a711807068abefd720';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Małgorzata Szewczyk, known in religion as Łucja, was a Polish religious sister. As foundress she established the Seraphic Sisters, officially the Sorrowful Mother of God''s Daughters, and she also belonged to the Third Order of Saint Francis. She devoted her life to nursing the ill, and for that purpose spent a long time in Israel and Palestine. She then returned to her native Poland, where she worked closely with Honorat Kozminski. To help the poor and needy she looked after elderly women in her apartments and went into hospitals and onto the streets to give charitable help to those who required it.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Ma%C5%82gorzata_Szewczyk", "biography": "rewritten"}'::jsonb),
