UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Euthymius of Tarnovo held the office of Patriarch of Bulgaria from 1375 to 1393. He is counted among the most significant figures of medieval Bulgaria, and as the last leader of the Bulgarian Orthodox Church within the Second Bulgarian Empire. Arguably the most esteemed of all Bulgarian patriarchs, he supported hesychasm, and his authority carried weight throughout the Eastern Orthodox world of his time.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Euthymius_of_Tarnovo", "biography": "rewritten"}'::jsonb),
