UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Ursus served as bishop of Ravenna in the late 4th century and is venerated as a saint by the Eastern Orthodox Church and the Roman Catholic church. His feast day is observed on 13 April.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Ursus_of_Ravenna", "biography": "rewritten"}'::jsonb),
