UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Raphael of Saint Joseph Kalinowski, a Polish Carmelite and social activist, took part in the January Uprising. The Catholic Church counts him a saint. His time in the Imperial Russian Army came before his conversion; he fought in Lithuania during the January Uprising and was exiled to Siberia.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Raphael_Kalinowski", "biography": "rewritten"}'::jsonb),
