UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Louis Bertrand, OP, a Spanish Dominican friar, preached in South America in the 16th century and is called the "Apostle to the Americas". The Catholic Church venerates him as a saint.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Louis_Bertrand_(saint)", "biography": "rewritten"}'::jsonb),
