UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The Catholic and Eastern Orthodox Churches venerate Phocas, sometimes called Phocas the Gardener, as a martyr and saint. The man of the legend may combine three men of the same name: Phocas of Antioch, Phocas the Gardener, and Phocas, Bishop of Sinope.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Phocas", "biography": "rewritten"}'::jsonb),
