UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Giuseppe Allamano, IMC, an Italian Catholic priest, was the founder of two institutes, the Consolata Missionaries (IMC) for men and the Consolata Missionary Sisters for women. As rector of the Santuario della Consolata, he turned the shrine into a wellspring of renewal for the faithful''s spiritual lives. He was beatified in 1990, then canonized on 20 October 2024.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Giuseppe_Allamano", "biography": "rewritten"}'::jsonb),
