  AND md5(content."payload"->>'biography') = '73ea62679f4464acd5dfab7f49eee288';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Narcissus of Jerusalem served as an early patriarch of Jerusalem. Both the Western and Eastern Churches venerate him as a saint. The Roman Catholic Church celebrates his feast day on October 29; in the Eastern Orthodox Church it falls on August 7.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Narcissus_of_Jerusalem", "biography": "rewritten"}'::jsonb),
