UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Jacob of Serugh, who is also named Jacob of Sarug or Mar Jacob, ranks among the greatest poets and theologians in the Syriac Christian tradition, behind only Ephrem the Syrian and level with Narsai. For most of his life he was a church official in Suruç, in present-day Turkey, and in 519, close to the end of his life, he was made a bishop. He was a Miaphysite, though a moderate one when set beside his contemporaries.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Jacob_of_Serugh", "biography": "rewritten"}'::jsonb),
