  AND md5(content."payload"->>'biography') = 'eb9b0aea089073627120bc6e7a29a04f';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Blessed María Pilar López de Maturana Ortiz de Zárate (religious name Margarita María) was Spanish, a Roman Catholic professed religious and founder of the Bérriz Mercedarian Missionaries. She made several international journeys to serve in the missions, since her order often undertook such trips, even though a serious ulcer that developed into stomach cancer afflicted her; still she kept promoting the charism of the missions.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Mar%C3%ADa_Pilar_L%C3%B3pez_de_Maturana_Ortiz_de_Z%C3%A1rate", "biography": "rewritten"}'::jsonb),
