UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Eugenia is remembered as a martyr of the early Church in Rome. Her feast day is December 25 for the Roman Catholic Church; December 24 for the Eastern Catholic Churches and the Eastern Orthodox Church; and January 23 for the Armenian Apostolic Church.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Eugenia_of_Rome", "biography": "rewritten"}'::jsonb),
