UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pomponius, Bishop of Naples, was noted for resisting Arianism. While Pomponius headed his see, Theodoric the Great held sway over most of the Italian Peninsula. Theodoric was an Arian, yet Pomponius did not waver in his convictions.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pomponius_of_Naples", "biography": "rewritten"}'::jsonb),
