UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Engelmar Unzeitig, born Hubert Unzeitig, was a German Roman Catholic priest. He died in the Dachau Concentration Camp in World War II, having been charged with being a priest. Engelmar was the religious name he assumed on admission to the Missionary Order of Mariannhill, where he became a professed member. People came to call him the "Angel of Dachau".'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Engelmar_Unzeitig", "biography": "rewritten"}'::jsonb),
