  AND md5(content."payload"->>'biography') = '65ae6c68a40d5996146bf7ff55be9645';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'An Italian nun, Blessed Bruna Pellesi (called Maria Rosa of Jesus) belonged to the Franciscan Missionary Sisters of Christ. She worked as an educator in places including Sassuolo until tuberculosis struck her. She was then sent to several sanatoriums to recover, and she died in her convent at the end of her life.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Bruna_Pellesi", "biography": "rewritten"}'::jsonb),
