  AND md5(content."payload"->>'biography') = 'cac69e6aa82e5860545ef9056bfd09d6';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Fiacre is the name of three Irish saints; the best known is Fiacre of Breuil, a seventh-century priest, abbot, hermit and gardener famed for his holiness and his skill at curing illnesses. He left his native Ireland for France, where he built himself a hermitage with a vegetable and herb garden, an oratory and a hospice for travellers. He is patron saint of gardeners and hemorrhoids.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Fiacre", "biography": "rewritten"}'::jsonb),
