UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Born Domenico Michele Giovan Battista, Pompilio Maria Pirrotti was an Italian Roman Catholic priest who professed vows with the Piarists. Across the Kingdom of Naples he worked as teacher and preacher. Detractors criticized him widely, and at the King''s order he was promptly expelled from the kingdom, but public pressure later brought about his readmission.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pompilio_Maria_Pirrotti", "biography": "rewritten"}'::jsonb),
