UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Gabriel Lalemant, a French Jesuit missionary, went to New France in 1646. Mohawk warriors killed him at St. Ignace amid a war pitting the Huron against nations of the Iroquois Confederacy. He counts among the eight Canadian Martyrs.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Gabriel_Lalemant", "biography": "rewritten"}'::jsonb),
