UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Genesius of Rome, a legendary Christian saint, was formerly a comedian and actor in plays that ridiculed Christianity. The legend says that while he was on stage in a play mocking baptism, something happened to him that converted him. He declared his new faith aloud and firmly would not renounce it, even when Diocletian, the emperor, commanded him to.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Genesius_of_Rome", "biography": "rewritten"}'::jsonb),
