UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Herculanus of Perugia served as bishop of Perugia. The Catholic Church canonized him, and he is acknowledged as the city''s patron saint. His principal feast is on November 7, and a second feast is kept on March 1. Pope Gregory the Great reports in his Dialogues that Herculanus was martyred in 549, when Totila, king of the Ostrogoths, took Perugia.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Herculanus_of_Perugia", "biography": "rewritten"}'::jsonb),
