UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Crescens is a figure mentioned in the New Testament. Tradition counts him among the 72 disciples whom Jesus sent out in Luke 10. He worked as a missionary in Galatia and was a companion of Paul. His name, ''Crescens'', comes from the Latin present-active participle of crescere and means ''increasing''.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Crescens", "biography": "rewritten"}'::jsonb),
