UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'In the fifth century Petronius held the office of bishop of Bologna, and he is one of the city''s patron saints. He came from a noble Roman family, converted to Christianity, and was later made a priest. While bishop of Bologna he had the Church of Santo Stefano built.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Petronius_of_Bologna", "biography": "rewritten"}'::jsonb),
