UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Felix of Cantalice, OFMCap, was a 16th-century Italian Capuchin friar. Pope Clement XI canonized him in 1712, making him the first Capuchin friar to become a saint. Until the age of twenty-eight he labored as a shepherd and farmhand. As a Capuchin he was assigned to beg alms on behalf of the friars, and Brother Felix was so successful at it that he could widen his collections to help the poor.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Felix_of_Cantalice", "biography": "rewritten"}'::jsonb),
