UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Nilus of Sora, a Russian Orthodox monk, spiritual writer and theologian, established the Sora Hermitage. He is chiefly remembered as the founder of the non-possessors (nestyazhateli), a current within the Russian Orthodox Church that opposed the owning of land by the Church. He is venerated as a saint by the Russian Orthodox Church, which keeps his feast on 7 May, the anniversary of his repose.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Nilus_of_Sora", "biography": "rewritten"}'::jsonb),
