UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Andrew of Phú Yên bears the title "Protomartyr of Vietnam." He was baptized in 1641 and served Jesuit missionaries devotedly, and for that reason he was arrested in the persecution of Christians that began in 1644. He would not abjure the faith, and he was executed at Kẻ Chàm. Pope John Paul II beatified Andrew on March 5, 2000, and his feast day is 26 July.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Andrew_of_Ph%C3%BA_Y%C3%AAn", "biography": "rewritten"}'::jsonb),
