UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Józef Bilczewski, a Polish Roman Catholic prelate, was Archbishop of Lviv from 1900 until he died. After completing two doctorates himself, he taught theology and dogmatics at the college in Lviv. His learning and culture became well known, and for that reason Emperor Franz Joseph I put him forward to lead the Lviv archdiocese. Pope Leo XIII appointed him archbishop, and he gave priority to many pastoral initiatives meant to renew people''s faith, as well as to ecumenical cooperation with other denominations.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/J%C3%B3zef_Bilczewski", "biography": "rewritten"}'::jsonb),
