UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Our Lady of Guadalupe is also called the Virgin of Guadalupe and La Virgen Morena. This title of the Blessed Virgin Mary is linked to four Marian apparitions to Juan Diego, as well as one to Juan Bernardino, his uncle, said to have occurred in December 1531, while the Mexican territories belonged to the Spanish Empire.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Our_Lady_of_Guadalupe", "biography": "rewritten"}'::jsonb),
