UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'John Paul I served as pope, heading the Catholic Church and governing Vatican City. His pontificate began on 26 August 1978 and ended with his death 33 days later, which makes it one of the shortest in papal history and produced the first year since 1605 with three popes. No Italian-born pope has come after him; the line of Italian popes had started in 1523 with Clement VII. He was both the first pope born in the 20th century and the final pope whose death occurred in that century.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_John_Paul_I", "biography": "rewritten"}'::jsonb),
