UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The seventy disciples, called the seventy apostles in the Eastern Christian traditions, were early emissaries of Jesus who are mentioned in the Gospel of Luke. Depending on the manuscript, their number is given as either 70 or 72.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Seventy_disciples", "biography": "rewritten"}'::jsonb),
