UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pope Leo I, called Leo the Great, led the church in Rome as its bishop, beginning on 29 September 440 and ending at his death on 10 November 461. Of the three Popes whom the Annuario Pontificio lists with the title "the Great", he is the first; the other two are Popes Gregory I and Nicholas I.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Leo_I", "biography": "rewritten"}'::jsonb),
