UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Known as James the Great, he was among the Twelve Apostles of Jesus. The New Testament presents him as the first apostle to be martyred and the second to die, with only Judas Iscariot dying earlier. He is patron saint of Spain, and tradition holds that his remains, as they are believed to be, rest at Santiago de Compostela, in Galicia, Spain.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/James_the_Great", "biography": "rewritten"}'::jsonb),
