UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'According to the New Testament, John the Apostle was among the Twelve Apostles of Jesus. He is also called Saint John the Beloved and, in Eastern Orthodox Christianity, Saint John the Theologian. He is usually listed as the youngest apostle, and his parents were Zebedee and Salome. James, his brother, was likewise one of the Twelve Apostles. The Church Fathers equate him with John the Evangelist, John of Patmos, John the Elder, and the Beloved Disciple. They also hold that he outlived the other apostles and was the only one who died a natural death, although modern scholars disagree about whether these claims are true.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/John_the_Apostle", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
