UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Peter Canisius, a Dutch Jesuit priest, was noted for his vigorous defense of Catholicism during the Protestant Reformation, in Germany, Austria, Bohemia, Moravia, Switzerland and the British Isles. He headed the Jesuits'' efforts in Germany, and the revival of the Catholic Church there is in large part credited to that work. The Catholic Church venerates him as a saint and a Doctor of the Church.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Peter_Canisius", "biography": "rewritten"}'::jsonb),
