  AND md5(content."payload"->>'biography') = '48baf16f01d0a6096716d384e080d570';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'As the 19th Patriarch of Alexandria, Alexander I of Alexandria faced several issues confronting the Church of his day during his patriarchate. They were when Easter should be dated, what Meletius of Lycopolis was doing, and, most substantial of all, Arianism. At the First Council of Nicaea he led the opposition to Arianism. He also mentored Athanasius of Alexandria, who succeeded him and became one of the Church Fathers. The Coptic Orthodox Church regards him as a Pope; the Catholic Church does not.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Alexander_I_of_Alexandria", "biography": "rewritten"}'::jsonb),
