  AND md5(content."payload"->>'biography') = 'd52c5452c6101b04e5302a57673f845f';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Venantius Honorius Clementianus Fortunatus, called Saint Venantius Fortunatus, composed Latin poetry and hymns at the Merovingian Court. He also served as a Christian bishop, and people have venerated him from the Middle Ages onward.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Venantius_Fortunatus", "biography": "rewritten"}'::jsonb),
