UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Rupert of Salzburg served as Bishop of Worms, became Salzburg''s first bishop, and was abbot of St. Peter''s Abbey there. He lived in the days of the Frankish king Childebert III. Roman Catholics and Eastern Orthodox Christians venerate him as a saint. He is also the patron saint of Salzburg, the Austrian state.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Rupert_of_Salzburg", "biography": "rewritten"}'::jsonb),
