  AND md5(content."payload"->>'biography') = 'f3b71b48dee053894141c8724a650a89';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Joel is a prophet of the Bible, placed second among the Twelve Minor Prophets. The Book of Joel names him as its author, and presents itself as belonging to the early Assyrian period. Scholars, however, consider the book to have been completed in the Ptolemaic period, citing its use of earlier texts and its outlook on Yahweh and the nations.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Joel_(prophet)", "biography": "rewritten"}'::jsonb),
