UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Charles de Foucauld was born Charles Eugène, a vicomte, of the Foucauld de Pontbriand family, and took the name Charles of Jesus in religion. He was a French hermit, monk and Catholic priest who made his home among the Tuareg people of the Sahara in Algeria, and he was also an explorer, geographer and ethnographer. Earlier, before becoming a Trappist monk, he had been a soldier with the 2nd Hussar Regiment. Bedouin bandits murdered him in 1916. Several religious congregations were founded out of inspiration drawn from his example and writings. He was canonized in 2022.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Charles_de_Foucauld", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
