WHERE content."id" = 'cmqagbdrj4nzyjhj21d1582x5'
  AND content."slug" = 'saint-charles-de-foucauld'
  AND md5(content."payload"->>'biography') = '86126cd8d94ca71e4ec95dea1c5b512f';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'John of Damascus, or John Damascene, was a Christian monk, a priest, a hymnographer, and an apologist whose birth name was Yūḥana ibn Manṣūr ibn Sarjūn. Damascus was where he was born and raised, around AD 675 or AD 676. The exact date and place of his death are unknown, but tradition says that on 4 December AD 749 he died at Mar Saba, his monastery near Jerusalem. He was a polymath who took an interest in law, theology, philosophy, and music and contributed to them, and he received the by-name Chrysorroas. His writings set out the Christian faith, and he composed hymns that are still sung in the liturgy of Eastern Christianity around the world and also in western Lutheranism at Easter.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/John_of_Damascus", "biography": "rewritten"}'::jsonb),
