UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Hedwig of Silesia belonged to the Bavarian comital House of Andechs. She became Duchess of Silesia in 1201 and of Greater Poland in 1231, and was High Duchess consort of Poland between 1232 and 1238. Pope Clement IV canonized her in 1267 for the Catholic Church.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Hedwig_of_Silesia", "biography": "rewritten"}'::jsonb),
