UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Hugh of Châteauneuf, who is also called Hugh of Grenoble, was Bishop of Grenoble from 1080 until he died. He supported the Gregorian reform and stood against the Archbishop of Vienne, who later became Pope Callixtus II.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Hugh_of_Ch%C3%A2teauneuf", "biography": "rewritten"}'::jsonb),
