UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pope Leo IX held the see of Rome as bishop and governed the Papal States starting 12 February 1049 until he died in 1054. Historians count him among the most important popes of the Middle Ages, and he played a key part in bringing about the Great Schism of 1054, regarded as the turning point at which the Catholic Church and the Eastern Orthodox Church formally parted ways.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Leo_IX", "biography": "rewritten"}'::jsonb),
