UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Peter Regalado y de la Constanilla, O.F.M. Conv., called Peter of Valladolid in his lifetime, was a Friar Minor from Spain and a Catholic priest. He was a well-known itinerant preacher and a major reformer of his Order. The Catholic Church has declared him a saint.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Peter_de_Regalado", "biography": "rewritten"}'::jsonb),
