UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Albertus Magnus, called Saint Albert the Great, Albert of Swabia, Albert von Bollstadt, or Albert of Cologne as well, was a German friar of the Dominicans, a philosopher, scientist, and bishop. Among medieval philosophers and thinkers he is counted as one of the greatest.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Albertus_Magnus", "biography": "rewritten"}'::jsonb),
