UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'From Christmas 972 until he died, Wolfgang of Regensburg served as bishop of Regensburg in Bavaria, and he is a saint of both the Catholic and Eastern Orthodox churches. Together with Conrad of Constance and Ulrich of Augsburg, he ranks among the 10th century''s three leading German saints. As his life drew to a close, Wolfgang retired as a hermit to a secluded place in Upper Austria''s Salzkammergut region. Shortly after he died, many churches adopted him as their patron saint, and several towns took his name.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Wolfgang_of_Regensburg", "biography": "rewritten"}'::jsonb),
