UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A German Catholic priest, Bernhard Lichtenberg spoke out forcefully against the Nazi regime''s persecution of Jews, along with other marginalized groups, in the Holocaust. His open denunciation of the government''s policies, among other places from the pulpit of Berlin''s St. Hedwig’s Cathedral, made him a lasting symbol of religious liberty. Though fear and repression were widespread, Lichtenberg publicly demanded justice and humane treatment for Jewish citizens, highlighting the moral duties of religious leaders under totalitarian regimes.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Bernhard_Lichtenberg", "biography": "rewritten"}'::jsonb),
