  AND md5(content."payload"->>'biography') = 'ef0c0e34941e27913f47260354de42b5';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'In 1066 Benno was named Bishop of Meissen. He had been venerated since the 13th century and was canonized in 1523. He accomplished a great deal for his diocese, through reforms in the Church on the Hildebrandine model and through material improvements. Throughout the Late Middle Ages, his native Saxony venerated him.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Benno_of_Meissen", "biography": "rewritten"}'::jsonb),
