UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'From 945 to 957 Olga governed Kievan Rus'' as regent on behalf of her son Sviatoslav. At her baptism she received the name Elenа. She is remembered for conquering the Drevlians, the tribe responsible for the killing of her husband Igor. Although it was her grandson Vladimir who embraced the faith and established it as the state religion, Olga was the first ruler to receive baptism.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Olga_of_Kiev", "biography": "rewritten"}'::jsonb),
