UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'In the West she is known as Margaret of Antioch, while the East calls her Saint Marina the Great Martyr. Western Christianity honors her as a saint on 20 July; the Eastern Orthodox Church does so on 30th of July, and the Coptic Orthodox Church on Epip 23 and Hathor 23. According to tradition she was a teenager in the 4th century who was tortured and beheaded for refusing to renounce Christianity and surrender her virginity to a Roman official. She had a reputation for pledging extremely powerful indulgences to people who wrote down her life, read it, or invoked her intercession, and these undoubtedly helped her cult to spread. In Roman Catholic tradition, Margaret counts among the Fourteen Holy Helpers.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Margaret_the_Virgin", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
