  AND md5(content."payload"->>'biography') = '29c533928c8d3b576069a83c5e3fd92a';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Piran or Pyran, who died c. 480, was a Cornish abbot and saint of the 5th century, possibly of Irish origin. Tin-miners regard him as their patron saint, and he is generally considered the patron saint of Cornwall too, though Michael and Petroc have some claim to that title as well.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Piran", "biography": "rewritten"}'::jsonb),
