UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A monk from Anglo-Saxon England, Saint Eskil was held in particular veneration in the province of Södermanland, Sweden, at the end of the 11th century. He was the founder of the earliest diocese covering the area around Lake Mälaren, which is now the Diocese of Strängnäs. He is patron saint of both Södermanland and the Diocese of Strängnäs.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Eskil", "biography": "rewritten"}'::jsonb),
