UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Maron, also known as Maroun or Maro, was a Syriac Christian hermit monk who lived in the 4th century in the Taurus Mountains. After he died, his followers founded a religious Christian movement that came to be called the Maronite Church. That church holds full communion with both the Holy See and the Catholic Church. The modern Maronites are the religious community that developed out of this movement.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Maron", "biography": "rewritten"}'::jsonb),
