UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'John Vianney, a Catholic priest from France who belonged to the Third Order of Mary, is often called the Curé d''Ars. The Church canonized him a saint in 1925. At his parish in Ars, France, his priestly and pastoral labors radically transformed the community and the surrounding area spiritually. Catholics point to his saintly life, mortification, steady ministry of the sacrament of confession, and passionate devotion to the Blessed Virgin Mary. The patron saint of parish priests, he is commemorated on 4 August.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/John_Vianney", "biography": "rewritten"}'::jsonb),
