UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Elisabetta Picenardi was an Italian tertiary in the Servite Order, and is also known as Elisabeth of Mantua. She was born in Mantua to a noble family. Though pressed to marry a nobleman, she refused and chose the religious path together with her sister.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Elisabetta_Picenardi", "biography": "rewritten"}'::jsonb),
