UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'An Italian Catholic nun of the Carmelites, Teodora Fracasso (OCD) took the religious name Elia di San Clemente. For a time in Saint Dominic''s Third Order she was named "Agnes". Her wish to become a nun began in childhood: in 1911 Thérèse of Lisieux, in a vision, told her that she would be a nun. A decade afterward this was fulfilled, when she joined the convent in Bari, her native city, where she remained for the rest of her life.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Teodora_Fracasso", "biography": "rewritten"}'::jsonb),
