  AND content."slug" = 'saint-elia-di-san-clemente'
  AND md5(content."payload"->>'biography') = '3ad84d9b3a4dba6eaf25e14bf798e1cd';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saints Peter and Fevronia of Murom, born David Yuryevich and Euphrosyne, were a Russian prince and his princess consort in the Principality of Murom. Among the best-known Russian saints and wonderworkers honored in the Russian Orthodox Church, they were canonized by Metropolitan Macarius of Moscow, and their feast day, kept every year, is 8 July [O.S. 25 June].'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Peter_and_Fevronia_of_Murom", "biography": "rewritten"}'::jsonb),
