UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Clotilde Micheli, an Italian Roman Catholic professed religious, founded the Sisters of Angels. When that order was established and she made her profession in it, she was named Maria Serafina of the Sacred Heart, in religion. Earlier she had belonged to another religious order, in which she was given the name Maria Annunziata, but she gave that name up on leaving the order.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Clotilde_Micheli", "biography": "rewritten"}'::jsonb),
