UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Born Livia Pietrantoni, Agostina Pietrantoni was an Italian religious sister in the Sisters of Divine Charity. She nursed at the Santo Spirito hospital in Rome, caring for the sick in a tuberculosis ward, until a patient killed her in 1894. Her canonisation took place in Saint Peter''s Square on 18 April 1999.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Agostina_Livia_Pietrantoni", "biography": "rewritten"}'::jsonb),
