UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A Christian, Irene of Tomar died a martyr for her faith in Visigothic Portugal. To keep her safe, her parents placed her in a convent school and hired a private tutor. She left home only to attend Mass or to pray at Saint Peter''s sanctuary. Her legend may well contain not much beyond this.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Irene_of_Tomar", "biography": "rewritten"}'::jsonb),
