UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Paula Montal Fornés, a Spanish Roman Catholic professed religious, established the Sisters of the Pious Schools and is regarded as their foundress. She devoted her religious career to teaching in Barcelona, where she opened schools for the local people. When her father died she was ten, and she had to help her mother bring up her siblings; once that was done she could follow her religious inclinations. Together with a close friend she started a series of schools, and then gave formal shape to her plan for a religious congregation centered on education and on opening further schools across the country.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Paula_Montal_Forn%C3%A9s", "biography": "rewritten"}'::jsonb),
