UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A German noblewoman and abbess, Blessed Gertrude of Aldenberg had as parents Louis IV, Landgrave of Thuringia, and Elizabeth of Hungary. She joined the Premonstratensian canonesses regular at Aldenberg Abbey, close to Wetzlar in the Diocese of Trier, and spent much of her life as the community''s abbess. Beatified in 1728, she has her feast on August 13.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Gertrude_of_Aldenberg", "biography": "rewritten"}'::jsonb),
