UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'An early Christian Virgin martyr, Bibiana of Rome has a basilica named for her, Santa Bibiana. The oldest mention of her in an authentic historical authority is in the Liber Pontificalis. Its entry on Pope Simplicius (468–483) says that he "consecrated a basilica" for "the holy martyr Bibiana", a church that held her body and stood near the "palatium Licinianum".'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Bibiana_of_Rome", "biography": "rewritten"}'::jsonb),
