UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Marie-Alphonsine Danil Ghattas, OP, was a Palestinian Catholic nun. She started the Dominican Sisters of the Most Holy Rosary of Jerusalem, which was the first religious congregation of Palestinians. Archbishop Angelo Amato beatified her in 2009, acting for Pope Benedict XVI. Pope Francis acknowledged, on 6 December 2014, a miracle credited to her intercession, as her canonization required. The canonization date was made public on 14 February 2015, and it was on 17 May 2015 that she was canonized.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Marie-Alphonsine_Danil_Ghattas", "biography": "rewritten"}'::jsonb),
