UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Irmgardis (Saint Irmgard of Süchteln) lived in the Middle Ages and is a saint; she ruled as sovereign Countess of Aspel (Germany) between 1013 and 1085. Her relics rest in a sarcophagus within the altar of Cologne Cathedral.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Irmgardis", "biography": "rewritten"}'::jsonb),
