UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Quadratus of Athens, an early Christian apologist, is counted by tradition among the Seventy Disciples and as a follower of the Apostles. His best-known act was an apology he presented to Emperor Hadrian when Hadrian visited Athens, around 124–125 CE. The apology defended the Christian faith against its critics and pointed to the miracles of Jesus, whose impact he saw as enduring.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Quadratus_of_Athens", "biography": "rewritten"}'::jsonb),
