UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A German Roman Catholic professed religious, Maria Luise Merkert was a co-foundress, with others, of the Sisters of Saint Elizabeth. She devoted herself to people in need, the poor and the sick, together with her older sister, until that sister died suddenly, as did her other companions. Merkert was then left to establish and sustain the order by herself, and she was its first Superior General from 1859 to her death.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Maria_Merkert", "biography": "rewritten"}'::jsonb),
