UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'An Irish saint of the 7th century, Flannán mac Toirrdelbaig was the son of Toirdhealbhach of Dál gCais, an Irish chieftain. He joined the monastery of Mo Lua at Killaloe, where he is believed to have become an Abbot. People remember him as a great preacher. On a pilgrimage to Rome, he was consecrated by Pope John IV as the first Bishop of Killaloe, and he is that diocese''s Patron Saint. He preached in the Hebrides as well. His feast day is 18 December.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Flann%C3%A1n", "biography": "rewritten"}'::jsonb),
