UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Titus Brandsma, a Dutch Carmelite priest, taught philosophy as a professor. He strongly opposed Nazi ideology and publicly denounced it repeatedly before World War II. Imprisoned in the Dachau concentration camp, he was murdered there in 1942.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Titus_Brandsma", "biography": "rewritten"}'::jsonb),
