UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Jerome''s Universal Chronicle found its first continuator in Prosper of Aquitaine (called Prosper Tiro as well), a Christian writer who had been a disciple of Augustine of Hippo. He is especially tied to an axiom of later date, ''lex orandi, lex credendi, lex vivendi'', which may be rendered ''the law of our prayer [or the things we pray] is the law of our belief, which is the law of our life''.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Prosper_of_Aquitaine", "biography": "rewritten"}'::jsonb),
