SET "payload" = content."payload" || jsonb_build_object('biography', 'Mary Frances of the Five Wounds, TOSF,, was an Italian Third Order Franciscan, and the Catholic Church honours her as a saint.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Mary_Frances_of_the_Five_Wounds", "biography": "rewritten"}'::jsonb),
