UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Catholic tradition holds that Saint Amaro (Amarus the Pilgrim) was a sailor and abbot, and legend claims he crossed the Atlantic Ocean, reaching an earthly paradise. Two historical figures may have inspired this legend. One was a French penitent bearing the same name, who in the thirteenth century went on pilgrimage to Santiago de Compostela. Coming back, he settled in Burgos, where he founded a leper hospital.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Amaro", "biography": "rewritten"}'::jsonb),
