UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Clelia Barbieri, an Italian Catholic, was founder of the Little Sisters dedicated to the Mother of Sorrows. She died at only twenty-three, and for that reason she is considered the youngest person ever to found a religious congregation of the Catholic church. In her adolescence she turned down married life, despite pressure, and chose to devote herself to the needs of others. For a time she worked as an educator, and by joining a religious movement she became a prominent figure in her village.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Clelia_Barbieri", "biography": "rewritten"}'::jsonb),
