UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Catherine of Bologna was an Italian Poor Clare who also worked as a writer, teacher, mystic and artist, and who is a saint. She is patron saint of artists and invoked against temptations. Her native Bologna venerated her for almost three centuries before Pope Clement XI formally canonized her in 1712. Her feast day falls on 9 March.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Catherine_of_Bologna", "biography": "rewritten"}'::jsonb),
