UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A Catholic saint, Mariana of Jesus de Paredes was the first person from the territory of present-day Ecuador to be canonized. A recluse, she is said to have offered her own life for the salvation of her city. Pope Pius IX beatified her in 1853, and Pope Pius XII canonized her in 1950. She is the patroness of Ecuador, and her relics rest in Quito, in the Society of Jesus church. Her feast day is May 26, though the Franciscan Order keeps it on May 28.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Mariana_de_Jes%C3%BAs_de_Paredes", "biography": "rewritten"}'::jsonb),
