  AND md5(content."payload"->>'biography') = '47c9940364db38bb7e22572497e37851';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A scholar and theologian, Ildefonsus (also Ildephonsus) was Metropolitan Archbishop of Toledo during the last ten years of his life. In Gothic his name was Hildefuns. The Ethiopian Orthodox Tewahedo Church knows him as Dexius, from the Ge''ez rendering of legends concerning his life.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Ildefonsus", "biography": "rewritten"}'::jsonb),
