UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Ambrogio Traversari (Ambrose of Camaldoli) was an Italian theologian and monk, and a leading champion of the papacy''s cause during the 15th century. The Camaldolese Order honors him as a saint.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Ambrose_Traversari", "biography": "rewritten"}'::jsonb),
