UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Maria Crocifissa Di Rosa, an Italian Roman Catholic professed religious, was born Paola Francesca Di Rosa and was founder of the Ancelle della carità, established in 1839. She began at her father''s spinning mill, where, with his encouragement, she looked after the needs of the women workers, both spiritual and material, and gathered several women who joined their efforts to care for the poor; this became the foundation of her religious congregation. In her apostolate she gave priority to caring for the ill in hospitals and for soldiers heading to the front.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Maria_Crocifissa_di_Rosa", "biography": "rewritten"}'::jsonb),
