  AND md5(content."payload"->>'biography') = 'e24a75dbf4c0bf7996510ba6c55563b9';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Born Manuela, María Soledad Torres y Acosta was a professed religious and Roman Catholic from Spain who became the founder of a congregation, the Servants of Mary. She and her order devoted their apostolic work to nursing the sick and the poor wherever they were active. From childhood Torres wished to enter religious life, and after the Dominicans declined her because of her frail constitution, she joined a priest''s newly formed group of women. A series of struggles then put her in a troubled position of leadership, and she was removed from it and reinstated twice.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Maria_Soledad_Torres_y_Acosta", "biography": "rewritten"}'::jsonb),
