UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Marie of Saint Ignatius was the name in religion of Claudine Thévenet (RJM), a Catholic woman religious from France. She was the founder of that community, the Religious of Jesus and Mary.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Claudine_Th%C3%A9venet", "biography": "rewritten"}'::jsonb),
