UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Born Cesare Silvestrelli, Bernardo Maria di Gesù was an Italian Roman Catholic priest who professed vows as a Passionist. For a short time he was a novice under a different religious name, but poor health forced him to leave; even so, he went on training and living with the Passionists. After his ordination he rejoined the order and held a number of leadership posts in it. He was compared to Saint Paul of the Cross, and Pope Leo XIII and Pope Pius X both thought highly of him.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Bernard_Mary_of_Jesus", "biography": "rewritten"}'::jsonb),
