UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Odo, a bishop of Urgell, was remembered for looking after the poor. He was of the lineage of the Pallars Sobirà counts. Santa Maria de Gerri monastery holds his grave. His successor proclaimed him a saint in 1133, and he is venerated as one now. The town of La Seu d''Urgell counts Odo as one of its patron saints, and July 7 is his feast day.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Ot_of_Urgell", "biography": "rewritten"}'::jsonb),
