UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Rimbert held the office of archbishop of Hamburg-Bremen from 865 until he died in 888; that see lay in the northern Kingdom of East Frankia. He is best known for authoring the Vita Ansgari, the life of Saint Ansgar, which was among the most widely read hagiographies of the middle ages.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Rimbert", "biography": "rewritten"}'::jsonb),
