UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Paulinus, a Roman missionary, was the first Bishop of York. Pope Gregory I sent the Gregorian mission in 601 to Christianize the Anglo-Saxons, turning them from the Anglo-Saxon paganism that was native to them. Paulinus belonged to it, and by 604 he was in England, having come with the second missionary group. Records of Paulinus''s activities during the next twenty years are scarce.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Paulinus_of_York", "biography": "rewritten"}'::jsonb),
