UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Philip the Evangelist is mentioned several times in Acts, which says he was one of the Seven appointed to look after the poor of the Christian community at Jerusalem. In Samaria he preached and worked miracles. Along the road running from Jerusalem down to Gaza he met an Ethiopian man, a eunuch, and baptised him, an event that tradition regards as the beginning of the Ethiopian Church. Afterward Philip made his home at Caesarea Maritima, together with his four daughters, who prophesied, and Paul the Apostle visited him there.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Philip_the_Evangelist", "biography": "rewritten"}'::jsonb),
