UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Clement Mary Hofbauer, a Moravian, was first a hermit and afterwards a priest of the Redemptorist congregation. The congregation had been founded in Italy, and he was the one who established it north of the Alps, which is why he is regarded as a co-founder. In a turbulent era in Europe that left thousands in destitution, he was widely known for devoting his whole life to the care of the poor. He worked among the Polish people until he was expelled, after which he settled in Austria.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Clement_Mary_Hofbauer", "biography": "rewritten"}'::jsonb),
