UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Balbina of Rome, called the mythical Balbina and sometimes Saint Balbina or Balbina the Virgin, has long been honored as a virgin martyr, and the Catholic Church counts her a saint. The Catholic Encyclopaedia makes plain that the account handed down appears to be fable and not history.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Balbina_of_Rome", "biography": "rewritten"}'::jsonb),
