UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Jacques-Désiré Laval, a French Roman Catholic priest, worked in the missions in Mauritius as a professed member of the Spiritans. His untiring work for the poor and sick earned him the name "Apostle of Mauritius". The people entrusted to him were for the most part uneducated former slaves, and Laval taught them as well. His medical skill won him distinction across the region, because it enabled him to care for those with illnesses that became worse especially during epidemics.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Jacques-D%C3%A9sir%C3%A9_Laval", "biography": "rewritten"}'::jsonb),
