UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Helladius of Auxerre held the see of Auxerre as bishop for thirty years, from 357 until he died. He converted St. Amator to Christianity, ordained him a deacon and tonsured him, which is the earliest instance of ecclesiastical tonsure noted in the religious history of France.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Helladius_of_Auxerre", "biography": "rewritten"}'::jsonb),
