UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Crispoldus is venerated as a Christian martyr of the 1st century. Bettona, in Umbria, has him as its patron saint, and he is said to have been that city''s first bishop, though Nocera and Foligno dioceses also include his name in their lists of bishops.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Crispoldus", "biography": "rewritten"}'::jsonb),
