UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Bega is an Irish saint of the medieval period who is linked to Northumbria and honored chiefly in the town of St Bees. Her Life says she was an Irish princess who escaped to Northumbria to avoid an arranged marriage with a Viking prince. She lived as an anchoress and became famous for her piety. A number of churches in England bear her dedication, and St Bees still celebrates her feast day.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Bega", "biography": "rewritten"}'::jsonb),
