UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Julian and Basilissa, a married couple, are venerated as saints by the Roman Catholic Church and the Eastern Orthodox Church. They died as Christian martyrs, in Antioch or, more likely, in Antinoe, under Diocletian in the early fourth century. The Roman Martyrology gives the date as 6 January, while the Greek Menaea gives 8 January.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Julian_and_Basilissa", "biography": "rewritten"}'::jsonb),
