UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Antonio Maria Gianelli was an Italian Roman Catholic prelate, Bishop of Bobbio from 1837 until he died. He was also founder of the Missionaries of Saint Alphonsus and of Figlie di Nostra Signora del Giardino. Gianelli devoted himself to his people''s educational needs and tended to their spiritual and material needs too; he stood ready to help the sick and the poor, and evangelization was central to his episcopal mission. He also preached missions and gained renown for charisma and eloquence.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Antonio_Maria_Gianelli", "biography": "rewritten"}'::jsonb),
