UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'An Icelandic Catholic bishop, Jón Ögmundsson (or Ögmundarson) is called John of Hólar too, and St. Jón Ögmundarson or Ögmundsson. When Iceland''s second diocese, Hólar, was established in the north of the country in 1106, Jón was named its first bishop, and he held that post until he died.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/J%C3%B3n_%C3%96gmundsson", "biography": "rewritten"}'::jsonb),
