UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Ursus of Solothurn was a Roman Christian of the 3rd century. The Eastern Orthodox Church, the Coptic church and the Roman Catholic church all venerate him as a saint. From very early on he was linked with the Theban Legion. The Roman Martyrology lists him, commemorating him on 30 September together with St. Victor of Solothurn.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Ursus_of_Solothurn", "biography": "rewritten"}'::jsonb),
