UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'An English Jesuit priest and martyr, Edmund Campion, SJ, was arrested by priest hunters while he carried out a clandestine ministry in England, then officially Anglican. After a conviction for high treason, he suffered hanging, drawing and quartering at Tyburn. Pope Leo XIII beatified him in 1886, and Pope Paul VI canonised him in 1970 among the Forty Martyrs from England and Wales. His feast day falls on 1 December.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Edmund_Campion", "biography": "rewritten"}'::jsonb),
