UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'María Emilia Riquelme y Zayas, a Spanish Roman Catholic religious sister, was the founder of a congregation, the Misioneras del Santísimo Sacramento y María Inmaculada. Her father was an officer who was posted to various barracks around the country, so she moved from place to place as a child. Throughout this time she attended boarding schools, where she improved her French and her art. When her schooling ended she was drawn to religious life, and after her father died she intended to enter a convent. Poor health forced her to abandon that plan, and instead she started a congregation of her own with several like-minded women, whose apostolate centered on the poor. The congregation later expanded across Spain and into other countries, among them Portugal and Bolivia.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Mar%C3%ADa_Emilia_Riquelme_y_Zayas", "biography": "rewritten"}'::jsonb),
