UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Demetrius I was the 12th Bishop and Patriarch of Alexandria. Sextus Julius Africanus, who came to Alexandria while Demetrius was bishop, dates his accession, as eleventh bishop after Mark, to the tenth year of the Roman Emperor Commodus, while Eusebius of Caesarea dates it to the tenth year of Septimius Severus.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Demetrius_I_of_Alexandria", "biography": "rewritten"}'::jsonb),
