UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Victor Emilio Moscoso y Cárdenas, an Ecuadorian Roman Catholic priest, was a professed member of the Jesuits. From 1892 he taught at the COPEM college in Riobamba, and he was slain there during the Liberal Revolution, which had begun in 1895. A noted philosopher, he gave his students lessons in rhetoric and grammar as a professor, and he held the post of the college''s rector from 1893 until he was assassinated.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Victor_Emilio_Moscoso_C%C3%A1rdenas", "biography": "rewritten"}'::jsonb),
