UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Arcangelo Tadini was an Italian Roman Catholic priest, ordained in 1870. He founded a religious congregation devoted to the poor and ill, using the Industrial Revolution as a chance to assist women with employment and schooling. A lame leg, the result of an accident during his seminary studies for the priesthood, left him disabled. He began several parish projects, plus a fund giving relief to the elderly and the sick.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Arcangelo_Tadini", "biography": "rewritten"}'::jsonb),
