UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Paul Aurelian was a Welshman of the 6th century who became the See of Léon''s first bishop and is counted among Brittany''s seven founder saints. He supposedly died in 575 and is rumoured to have reached the age of 140, having been helped in his work by three coadjutors in succession. This suggests that several men named Paul have been conflated. Gilbert Hunter Doble considered it possible that he was Saint Paulinus of Wales.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Paul_Aurelian", "biography": "rewritten"}'::jsonb),
