UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Peter Fourier, a French canon regular, is honored as a saint by the Roman Catholic Church. He declined offers of high office, and for many years was the pastor in Mattaincourt, a village in the Vosges. He strongly favored free education and helped establish a religious congregation of canonesses regular, devoted to caring for poor children; for this work he developed a new pedagogy.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Peter_Fourier", "biography": "rewritten"}'::jsonb),
