UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'János Brenner, O.Cist, was a Hungarian Catholic priest belonging to the Cistercian Order. His studies for the priesthood took place while communist authorities were persecuting religious orders. He became a threat to them because he was so successful as a youth chaplain, and they came to suspect that he criticized their regime. For that reason hired men murdered him, stabbing him 32 times and wounding his head severely with canes. He was thrown into a ditch in the woods and died shortly afterward. He was beatified on 1 May 2018 in Szombathely.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/J%C3%A1nos_Brenner", "biography": "rewritten"}'::jsonb),
