UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Almost nothing is known about the life of Saint Arsatius, also called Arsacius. Reportedly he was a bishop of Milan, living either about 400 or during the 6th century; he may also have been a martyr, though evidence is lacking. His traditional tie to Milan has led some to suppose him a disciple of Saint Ambrose, who likewise was Bishop of Milan, but again nothing supports it.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Arsatius", "biography": "rewritten"}'::jsonb),
