UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Ibar mac Lugna, a name that also appears as Iberius or Ivor, belonged to the early Irish church as a bishop and saint; he is patron of Beggerin Island. He is sometimes said to have belonged to the "Quattuor sanctissimi Episcopi", who are said to have come before Saint Patrick in Ireland, though they may only have been his contemporaries. His feast day falls on 23 April.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Ibar_of_Beggerin", "biography": "rewritten"}'::jsonb),
