UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Gregory V of Constantinople, born Georgios Angelopoulos, held the office of Ecumenical Patriarch of Constantinople during three periods: 1797–1798, 1806–1808 and 1818–1821. He carried out much restoration of St George''s Patriarchal Cathedral, which a fire had badly damaged in 1738.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Gregory_V_of_Constantinople", "biography": "rewritten"}'::jsonb),
