UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Isaac the Confessor, also called Isaacius or Isaakios, was a Christian monk revered as a saint and confessor. He established the Dalmatian Monastery in Constantinople and was thus its founder. He is at times called Isaac the Dalmatian, though he did not come from Dalmatia; the name comes from the monastery he founded.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Isaac_of_Dalmatia", "biography": "rewritten"}'::jsonb),
