UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Cloud, better known as Clodoald, was a Merovingian prince; he was a son of Chlodomer and grandson of Clovis I. He chose to give up a royal life, and became both hermit and monk. He discovered a hill on the Seine, two leagues downstream from Paris, at a place called Novigentum. There, living among fishermen and farmers, he spent his days alone and in prayer; he built a church there and dedicated it to Martin of Tours.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Clodoald", "biography": "rewritten"}'::jsonb),
