UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pavel Peter Gojdič, OSBM, a Rusyn Basilian monk, was Eparch of Prešov in the Slovak Greek Catholic Church. After the Czechoslovak coup d''état of 1948, the StB, the communist regime''s secret police in Czechoslovakia, arrested him, and he was jailed on a charge of high treason. He was promised that he would be freed at once if he accepted the post of Orthodox patriarch in Czechoslovakia, yet he died in 1960 at Leopoldov Prison, a prisoner of conscience.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pavel_Peter_Gojdi%C4%8D", "biography": "rewritten"}'::jsonb),
