UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Jean de Brébeuf, a French Jesuit missionary, went to New France (Canada) in 1625. For the rest of his life he worked mainly among the Huron, apart from a few years in France between 1629 and 1633. He learned the customs and the language of the Huron and wrote at length about both, to help other missionaries.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Jean_de_Br%C3%A9beuf", "biography": "rewritten"}'::jsonb),
