UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Paul and his companions were martyrs of the Dominican Order. Paul, Hungarian by birth, later studied law at the University of Bologna, where St. Dominic won him over to the order of Friars Preachers. He afterwards went back to his native Hungary to found the Dominican Order there. The group met strong hostility, particularly from the Cumans, in Wallachia, where the local people slaughtered them.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Paul_and_Ninety_Companions", "biography": "rewritten"}'::jsonb),
