UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Auxerre honors Peregrine (Peregrinus) as its first bishop, who built its first cathedral. According to a strong local tradition, he was a Roman priest whom Pope Sixtus II appointed to evangelize the area, at the request of resident Christians of that region of Gaul. He preached at Marseille and Lyon, and he converted most of Auxerre''s inhabitants to Christianity.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Peregrine_of_Auxerre", "biography": "rewritten"}'::jsonb),
