UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Justo Takayama Ukon (ジュスト高山右近), originally named Takayama Hikogorō (高山彦五郎) and also called Dom Justo Takayama, lived in the Sengoku period, an era marked by widespread anti-Catholic feeling. He was a daimyō and samurai in Japan, and a Catholic.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Justo_Takayama", "biography": "rewritten"}'::jsonb),
