UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Stefan Wincenty Frelichowski was a Polish Roman Catholic priest. During his ecclesial education he took part in the scouts and several other groups, and he kept strong ties with them after being ordained a priest. Soon after World War II began he was arrested, and the Gestapo moved him between several concentration camps and finally to Dachau, where disease killed him.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Stefan_Wincenty_Frelichowski", "biography": "rewritten"}'::jsonb),
