UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Mellonius (229-314) was a Bishop of Rotomagus in the early 4th century, in the Roman province called Secunda Provincia Lugdunensis. The only source for him is a ''Life'' written in the 17th century and of little historical value, so it is uncertain whether he really existed.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Mellonius", "biography": "rewritten"}'::jsonb),
