  AND md5(content."payload"->>'biography') = '3509d6666625d2f909f5a57b1a9c9214';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Lindalva Justo de Oliveira, DC, a Brazilian Catholic, was a sister in the congregation of Saint Vincent de Paul known as Daughters of Charity. Her post was Dom Pedro II Home, a facility for the elderly. A man obsessed with her killed her there in 1993, stabbing her 44 times once she turned down his advances.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Lindalva_Justo_de_Oliveira", "biography": "rewritten"}'::jsonb),
