UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Silvestro Guzzolini, an Italian Catholic priest, was the founder of the Silvestrini. He was a canon in Osimo, but after he respectfully criticized his bishop''s improper behavior, he withdrew to a hermitage before the bishop could remove him from his post. Staying there, he resolved to found a religious congregation, and after a dream of Benedict of Nursia he modeled it on the Order of Saint Benedict. Pope Innocent IV gave the order papal approval, and it then spread widely through the cities of Italy.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Sylvester_Gozzolini", "biography": "rewritten"}'::jsonb),
