UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'William Ireland, from Lincolnshire, was an English Jesuit and martyr who had false charges of plotting the murder of King Charles II brought against him during the Popish Plot hysteria, and he went to his execution on 24 January 1679. Pope Pius XI beatified him in 1929, and his feast day, 24 January, falls on the day he died.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/William_Ireland_(Jesuit)", "biography": "rewritten"}'::jsonb),
