UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Bartolo Longo (TOSD), an Italian lawyer, was once a Satanic priest. He came back to the Catholic faith, became a Dominican tertiary, and gave his whole life to the rosary and to the Virgin Mary. In time he received a papal knighthood of the Holy Sepulchre of Jerusalem (Equestrian Order). Pope Leo XIV canonized him on 19 October 2025.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Bartolo_Longo", "biography": "rewritten"}'::jsonb),
