UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The Annuario Pontificio gives Pius I''s tenure as bishop of Rome as c. 140 to c. 154, while other dates listed for him are 142 or 146 at the start and 157 or 161 at the end, respectively. During his papacy he is thought to have opposed the Valentinians as well as the Gnostics. The Catholic Church regards him as a saint, and his feast day is 11 July, although it is unclear whether he died as a martyr.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Pius_I", "biography": "rewritten"}'::jsonb),
