UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Otto Neururer, an Austrian Roman Catholic priest, was the first priest to lose his life in a Nazi concentration camp. After finishing his priestly training at Brixen, he taught and served as pastor in various cities, and in 1932 settled in Götzens near Innsbruck. In 1938 he was arrested for trying to persuade a girl not to marry a man of questionable morals. He was sent to Dachau and then transferred to Buchenwald, where he was hanged upside down and nailed to a tree, practically crucified, and died. Rather than screaming, he prayed in silence while "crucified". After 36 hours of being left there, he was killed by Martin Sommer, a Nazi guard. He was later beatified.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Otto_Neururer", "biography": "rewritten"}'::jsonb),
