WHERE content."id" = 'cmqcohfuu2mduza01lpk6k7ds'
  AND content."slug" = 'saint-otto-neururer'
  AND md5(content."payload"->>'biography') = '62a3ccbbf6d83f92f23d41a7f5110647';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Jakob Gapp, an Austrian Roman Catholic priest, was a professed member of the Marianists. He was a soldier at first, posted to the Italian front in World War I, when his religious convictions mattered little to him. He returned from a prisoner of war camp holding socialist views, and these soon put him in touch with the Marianists, the order he later joined. After his studies and ordination, Austria gave him a teaching assignment, and there he became notable as a fierce opponent of the Nazi regime; he considered Nazism a warped political tool for creating division, and one incompatible with the faith.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Jakob_Gapp", "biography": "rewritten"}'::jsonb),
