  AND md5(content."payload"->>'biography') = '57123660ddc5611bc03d4e84d7480812';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A Russian surgeon and spiritual writer, Valentin Felixovich Voyno-Yasenetsky is today called Luke of Simferopol, Saint Luke the Blessed Surgeon, or Saint Luke of Crimea. He was also a bishop in the Russian Orthodox Church, and from May 1946 until he died he was archbishop of Simferopol and Crimea. In 1946 he received the Stalin Prize in medicine.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Luke_Voyno-Yasenetsky", "biography": "rewritten"}'::jsonb),
