UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Blessed Jacinto Vera Durán, a Roman Catholic prelate from Uruguay, was Montevideo''s first bishop. As an energetic minister in Uruguay, he saw his work to renew the priesthood, along with other church initiatives, set him against the Uruguayan government. This conflict led to his exile; from October 1862 to August 1863 he lived in Buenos Aires, until a political change in Uruguay allowed him to come back. The warm popularity shown at his welcome lasted for the rest of his life, thanks to his intense and long missionary labour throughout the diocese of Montevideo, whose bishop he became when it was created in 1878. In 1895 a neighborhood of Montevideo was given his name.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Jacinto_Vera", "biography": "rewritten"}'::jsonb),
