UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'An Italian Catholic Discalced Carmelite, Marianna Fontanella, OCD, is also called Mary of the Angels or Maria degli Angeli. As a child she studied with the Cistercians, and she joined the Discalced Carmelites although her mother and siblings protested. Before long she was a noted abbess and prioress, and she opened a new convent in 1703, supervising its establishment herself.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Marianna_Fontanella", "biography": "rewritten"}'::jsonb),
