SET "payload" = content."payload" || jsonb_build_object('biography', 'Pope Linus was bishop of Rome from c. 68 until he died in 80. He is usually counted as the second bishop of Rome, following Saint Peter. He was canonized, as were all the early popes.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Linus", "biography": "rewritten"}'::jsonb),
