UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Nicholas Tavelic, O.F.M., a Croatian who became a Friar Minor, priest and missionary, headed a group of friars. They suffered martyrdom in Jerusalem on November 14, 1391. Friars from Italy and France were among his companions, and all were beatified together. The Catholic Church has since declared all four members of the group saints, so Tavelic is the first Croatian to be canonized.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Nicholas_Tavelic", "biography": "rewritten"}'::jsonb),
