UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Daniel Jules Alexis Brottier, C.S.Sp., was a French Roman Catholic priest of the Congregation of the Holy Spirit (Spiritans). He received the Croix de Guerre, as well as the Légion d''honneur, for his work as a chaplain in World War I, carried out missionary work in Senegal, and ran an orphanage at Auteuil, a Paris suburb. In 1983 he was declared venerable, and Pope John Paul II beatified him on 25 November 1984.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Daniel_Brottier", "biography": "rewritten"}'::jsonb),
