UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Dryhthelm, also called Drithelm or Drythelm, was a monk linked to the monastery of Melrose and is known from Bede''s Historia Ecclesiastica gentis Anglorum. Bede writes that before he became a religious, he and his family lived in Northumbria, in a district "which is called Incuneningum". Some modern scholars believe Incuneningum means Cunninghame, which is now part of Ayrshire.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Dryhthelm", "biography": "rewritten"}'::jsonb),
