UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'From 1043 until 1066 Gottschalk (also spelled Godescalc) ruled as prince of the Obotrite confederacy and founded, in the mid-11th century, a kingdom of Polabian Slavs on the Elbe. His life''s aim seems to have been to unite the scattered Slavic tribes in one realm and to see it become Christian.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Gottschalk_(Obotrite_prince)", "biography": "rewritten"}'::jsonb),
