UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A Benedictine nun at Chelles, France, Elizabeth Rose established the Sainte-Marie-du-Rozoy convent, close to Courtenay, Loiret, France, and was its first abbess. In later life she withdrew to live as an anchoress inside a hollow oak tree.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Elizabeth_Rose_(nun)", "biography": "rewritten"}'::jsonb),
