UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'His strong charitable outreach earned Angelo Paoli, O.Carm, an Italian Catholic priest of the Carmelite Order, the title "father of the poor", and while living in Rome he received praise from several cardinals and other prelates. Praise also came from Cardinal Giuseppe Maria Tomasi, his friend, and from Popes Innocent XII and Clement XI, each of whom offered to make him a cardinal, an honor he declined.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Angelo_Paoli", "biography": "rewritten"}'::jsonb),
