UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Nikolaus Gross, a German layman of the Roman Catholic Church, was a trade unionist. He started out in skilled crafts, then followed his father into coal mining and joined various trade union and political movements. Before marrying he settled on a career as a journalist. When World War II came he became a resistance fighter in the Third Reich, notable for his nonviolent rhetoric and method of opposing Adolf Hitler. Although he took no part in the attempt on Hitler''s life, he was among those implicated and arrested over it.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Nikolaus_Gross", "biography": "rewritten"}'::jsonb),
