UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Mildgyth was the last-born daughter of King Merewalh of Mercia and Saint Eormenburh. Her elder sisters were Saint Mildburh of Wenlock and Saint Mildrith. People have compared the three sisters to the three theological virtues, with Mildburh standing for faith, Mildgyth for hope, and Mildrith for charity.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Mildgyth", "biography": "rewritten"}'::jsonb),
