UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Julian of Antioch was a Christian martyr and saint of the 4th century. He also goes by the names Julian of Tarsus, Julian of Anazarbus, Julian of Cilicia and Julian the Martyr. People sometimes mistake him for the St Julian who was martyred together with his wife Basilissa.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Julian_of_Antioch", "biography": "rewritten"}'::jsonb),
