UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'In the New Testament, Epaphroditus appears as a messenger dispatched from the Philippian church to help the Apostle Paul. The Eastern Orthodox Church and the Roman Catholic Church honor him as a saint, and as the first Bishop of Philippi, of Andriaca, and the first Bishop of Terracina, Italy. Evidence that these were all one and the same man is slight.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Epaphroditus", "biography": "rewritten"}'::jsonb),
