UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Martial of Limoges was the first bishop of Limoges. His name also appears as Marcial, Martialis and Marcialis, and he bears the titles "the Apostle of the Gauls" and "the Apostle of Aquitaine." He is venerated as a Christian saint and is regarded as canonized Pre-Congregation; his feast day is 30 June.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Martial", "biography": "rewritten"}'::jsonb),
