UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Mirin, born around the year 565, is also called Merinus, Merryn, Meadhrán and Mirren of Benchor. He is the patron saint of Paisley in Renfrewshire, Scotland, and also of the Roman Catholic diocese there. Founder of a religious community that grew into Paisley Abbey, he has a shrine there that became a centre of pilgrimage.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Mirin", "biography": "rewritten"}'::jsonb),
