UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The Catholic Church venerates Saint Quirinus of Tivoli as a martyr and saint, and his cult has its center at Tivoli. He may be identical with Quirinus of Sescia, whose relics were taken from Pannonia to Rome and perhaps on to Tivoli, which would account for a cult of Saint Quirinus there. On this reading, the relics of Quirinus of Sescia were reportedly moved to the Apennine Peninsula at the time of the Hun invasion.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Quirinus_of_Tivoli", "biography": "rewritten"}'::jsonb),
