UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Severus of Antioch, also known as the Crown of Syrians or Severus of Gaza, held the patriarchate of Antioch and headed the Syriac Orthodox Church. His tenure began in 512 and ended with his death in 538. The Oriental Orthodox Church venerates him as a saint. The Syriac Orthodox Church keeps his feast day on 29 September, and the Coptic Orthodox Church keeps it on 8 February.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Severus_of_Antioch", "biography": "rewritten"}'::jsonb),
