UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Rani Maria Vattalil, FCC, was a social worker and an Indian Catholic religious sister. She belonged to the Franciscan Clarists and worked in the Diocese of Indore. A Syro-Malabar Eastern Catholic, Vattalil devoted herself to catechetical formation and teaching in various parts of the region. Her outspokenness on social justice led to her murder at the hands of people opposed to her assistance to the poor.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Mariam_Vattalil", "biography": "rewritten"}'::jsonb),
