UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Ceolwulf reigned as King of Northumbria from 729 to 737, apart from a short interval around 731 or 732 during which he was deposed and soon returned to power. In the end he abdicated and became a monk at the monastery at Lindisfarne. To him Bede dedicated the Historia ecclesiastica gentis Anglorum, calling him the "most glorious king".'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Ceolwulf_of_Northumbria", "biography": "rewritten"}'::jsonb),
