UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Sigiramnus, also called Saint Cyran, was a 7th-century abbot and confessor. Of noble birth in Berry, he was educated at Tours and afterwards entered the royal court of Clothaire II. There he held the post of cup-bearer, yet he always wore a hair-shirt beneath his clothing and gave himself to prayer.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Sigiramnus", "biography": "rewritten"}'::jsonb),
