UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'John de Britto, SJ, a Portuguese Jesuit missionary and evangelist, is frequently called "the Portuguese St. Francis Xavier" by Indian Catholics. He has also been named "the John the Baptist of India."'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/John_de_Britto", "biography": "rewritten"}'::jsonb),
