UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Karolina Gerhardinger, a religious sister of the Roman Catholic Church in Germany, founded the order known as the School Sisters of Notre Dame. She worked as an educator in Bavaria until her order was established; it offered the poor a free education and soon spread across Europe.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Karolina_Gerhardinger", "biography": "rewritten"}'::jsonb),
