UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Rufus and Zosimus were Christian martyrs of the 2nd century, honored by Roman Catholics and also by Eastern Orthodox churches. Residents of Antioch, they were put to death together with Ignatius of Antioch when the Roman emperor Trajan was persecuting Christians. Beasts in the Roman arena killed them two days ahead of Ignatius, who met the same end. Their feast day falls on December 18.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Rufus_and_Zosimus", "biography": "rewritten"}'::jsonb),
