UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Werner of Oberwesel was a boy of 16 whose death, never explained, was blamed on Jews and set off revenge killings of Jews throughout Europe. He came to be venerated as a Christian saint, with a memorial day on 19 April.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Werner_of_Oberwesel", "biography": "rewritten"}'::jsonb),
