UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Paulinus II of Aquileia, a priest, theologian and poet, ranked among the foremost scholars of the Carolingian Renaissance. He held the office of Patriarch of Aquileia, in what is today northeastern Italy, from 787 until he died. He took part in several synods that opposed Spanish Adoptionism and that advanced reforms as well as inserting the Filioque in the Nicene Creed. Paulinus also saw to the Christianisation, carried out peacefully, of the alpine Slavs and of the Avars living within the Aquileian patriarchate''s territory, and for this reason he is called the apostle of the Slovenes as well.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Paulinus_II_of_Aquileia", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmqcpudut3ms9za0166prbdpu'
