  AND md5(content."payload"->>'biography') = '609992c5c79a091a460990460002d34c';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The first abbot of Clonmacnoise, Saint Ciarán, was supposedly born Ciarán mac an tSaeir and was numbered among the Twelve Apostles of Ireland. Ciarán the Younger is a name sometimes used for him, setting him apart from Saint Ciarán the Elder, a 5th-century bishop of Osraige. Many variant spellings of his name exist, among them Ceran, Kieran, Kyran, Queran and Queranus.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Ciar%C3%A1n_of_Clonmacnoise", "biography": "rewritten"}'::jsonb),
