  AND md5(content."payload"->>'biography') = '39bc8d36eace710833ce4ac3264bf756';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Expeditus, also called Expedite, was reportedly a Roman centurion in Armenia. Because he converted to Christianity he met his martyrdom in what is now Turkey, around April 303. Regarded as patron saint of urgent causes, Expeditus is likewise called the saint of time, and on 19 April the Catholic Church commemorated him.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Expeditus", "biography": "rewritten"}'::jsonb),
