UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Maria Ludovica De Angelis, an Italian religious sister, joined a congregation called Daughters of Our Lady of Mercy, which Maria Giuseppa Rossello had established. She received the religious name Maria Ludovica when she was invested in it. After serving at first in Italy, she went to Argentina and devoted herself to children and to the children''s hospital in La Plata, where she died in 1962. In 2004 she was beatified by Pope John Paul II.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Maria_Ludovica_De_Angelis", "biography": "rewritten"}'::jsonb),
