UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The Thomasian Martyrs, 17 in all, include 3 Dominican bishops, 12 Dominican priests and 1 Franciscan priest. Each served as an administrator, professor, or student at Manila''s University of Santo Tomas. The Catholic Church venerates them as martyrs, and popes over the 20th and 21st centuries declared them saints and blesseds. All laid down their lives for their Christian faith, in Japan, in Vietnam, and, during the 20th century, in Spain amid the Spanish Civil War. Lorenzo Ruiz de Manila was one of the lay companions who accompanied the Thomasian Martyrs of Japan. November 6 is the day on which their feast is kept each year.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Thomasian_Martyrs", "biography": "rewritten"}'::jsonb),
