UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Adelaide, Abbess of Vilich, also called Adelheid, was abbess of Vilich and of Cologne''s St. Maria im Kapitol. Some regarded her as a saint, and miracles are attributed to her. Her ancestry went back to Henry the Fowler, a German king. Her parents had founded the convent at Vilich, where she later became abbess.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Adelaide%2C_Abbess_of_Vilich", "biography": "rewritten"}'::jsonb),
