UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The Seven Sleepers, called the Seven Sleepers of Ephesus by Christians and Aṣḥāb al-Kahf in Islam, are both a Christian legend of late antiquity and a Qur''anic Islamic story. It tells of a band of young men who took refuge in a cave about the year 250 AD to escape the Roman persecutions of Christians, and who came out many years afterward. The Qur''anic account is found in Sura 18 (18:9–26).'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Seven_Sleepers", "biography": "rewritten"}'::jsonb),
