  AND md5(content."payload"->>'biography') = '23afad95d159ea4c37aa02c96b48297a';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Anna, called Anna the Prophetess, is a woman named in the Gospel of Luke, which describes her as an aged woman from the Tribe of Asher who prophesied concerning Jesus at Jerusalem''s Temple. She is found in Luke 2:36–38, in the account of Jesus'' presentation at the Temple.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Anna_the_Prophetess", "biography": "rewritten"}'::jsonb),
