UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Traditionally honored as co-patron saint of Navarre, Spain, Firmin, a martyr and holy man, was born in the middle of the 3rd century, which means his death may be linked to the Diocletianic Persecution (303).'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Fermin", "biography": "rewritten"}'::jsonb),
