UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Rose of Viterbo, TOSF, was born in Viterbo, at that time a disputed commune of the Papal States. As a young woman she lived out her short life as a recluse and spoke openly in favor of the papacy. Her life was otherwise ordinary, but she later became known for mystical gifts of prophecy and for miraculous powers. The Catholic Church honours her as a saint.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Rose_of_Viterbo", "biography": "rewritten"}'::jsonb),
