WHERE content."id" = 'cmqosvgpim7ggwoqjzrbfzcpl'
  AND content."slug" = 'saint-rose-of-viterbo'
  AND md5(content."payload"->>'biography') = '8baa4b3013554c4d65c1ece76012443f';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Joseph Barsabbas appears in the Acts of the Apostles as one of two men put forward to fill the office of apostle once Judas Iscariot had lost it by betraying Jesus and dying by suicide. When lots were cast, Barsabbas was not the one selected; the lot went to St. Matthias, who was added to the remaining eleven apostles. In Acts 1:21–26 (D–R), verses 21 and 22 say that the replacement must be one of the men who had accompanied the apostles all through the Lord Jesus''s ministry, from the baptism of John until his ascension, so as to be a witness of his resurrection. In verse 23 two men are appointed: Joseph, called Barsabas and surnamed Justus, and Matthias. In verses 24 and 25 they pray, asking the Lord, who knows every heart, to reveal which of the two he has chosen to take the place in this ministry and apostleship that Judas forfeited by transgression in order to go to his own place. Verse 26 relates that lots were drawn for them, that Matthias received the lot, and that he joined the eleven apostles in their number.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Joseph_Barsabbas", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmqovrmuqoilqwoqj5s5wsaie'
  AND content."slug" = 'saint-joseph-barsabbas'
  AND md5(content."payload"->>'biography') = '918c47bc568bbc66eed83c4ce92cea7d';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'James the Just, also called brother of the Lord (or by a variant of the name James), is described in the New Testament as a brother of Jesus. Paul the Apostle knew him personally, and James headed the Church of Jerusalem as its first leader. Josephus reports that he was martyred in 62 AD, stoned to death at the command of High Priest Ananus ben Ananus, whereas Hegesippus dates his death to 69 AD and says that scribes and Pharisees threw him from the pinnacle of the Temple and then beat him to death with a club. James, Joses, Simon, and Judas are named as brothers of Jesus, along with two or more sisters who are not named.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/James%2C_brother_of_Jesus", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmqpt0z2ih9h2woqjrklbmiye'
  AND content."slug" = 'saint-james-the-just'
