UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Born Ivan Sanin, Joseph Volotsky (also called Joseph of Volotsk or of Volokolamsk) was a leading Russian theologian and an early advocate of tsarist autocracy. Amid the controversy with the non-possessors, he headed the party that defended the owning of land by monasteries. The Russian Orthodox Church regards him as a saint and keeps his memory on September 9 and October 18. He is the patron of businessmen.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Joseph_Volotsky", "biography": "rewritten"}'::jsonb),
