UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The Canadian Martyrs, also known as the North American Martyrs, numbered eight Jesuit missionaries who came from Sainte-Marie among the Hurons. On several dates in the mid-17th century they were ritually tortured and killed, in what is now southern Ontario in Canada and in upstate New York, amid warfare between the Mohawk and the Wendat (Huron), both Iroquioan tribes. The Catholic Church has since canonized them and venerates them as martyrs.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Canadian_Martyrs", "biography": "rewritten"}'::jsonb),
