UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Henry II, also called Saint Henry, Obl. S. B., became Holy Roman Emperor in 1014 and was the final ruler of the Ottonian line, dying without an heir in 1024. He was appointed Duke of Bavaria in 995. When his second cousin, Emperor Otto III, suddenly died in 1002, Henry was made King of the Romans; in 1004 he became King of Italy, and Pope Benedict VIII crowned him emperor in 1014.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Henry_II%2C_Holy_Roman_Emperor", "biography": "rewritten"}'::jsonb),
