UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The Christian saint Hubert of Liège became Liège''s first bishop in 708 A.D. Hunters, mathematicians, opticians and metalworkers count him among their patron saints. He bore the title "Apostle of the Ardennes", and until the early 20th century people called on him against rabies, using the traditional Saint Hubert''s Key.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Hubert_of_Li%C3%A8ge", "biography": "rewritten"}'::jsonb),
