UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Jan Bula was a Roman Catholic priest from Czechia who administered the parish of Rokytnice nad Rokytnou. He was among those put to death by the communist regime in judicial murders connected with the Babice case. The Catholic Church honors him as a blessed martyr, and his memorial, shared with Václav Drbola, falls each year on June 17.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Jan_Bula", "biography": "rewritten"}'::jsonb),
