UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Cecilia Cesarini (1203–1290), also called Caecilia, was a Dominican nun. One description calls her "a high-spirited young Roman". Her family, the Cesarini, was a well-established house of the minor nobility. Nobody knows what led her to enter religious life.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Cecilia_Cesarini", "biography": "rewritten"}'::jsonb),
