UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Wenceslaus I, also spelled Wenceslas I and called Václav the Good, was Prince (kníže) of Bohemia. His rule began in 921 and lasted until his death, probably in 935. Legend says his younger brother, Boleslaus the Cruel, had him assassinated.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Wenceslaus_I%2C_Duke_of_Bohemia", "biography": "rewritten"}'::jsonb),
