UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pierre-François Jamet, a French Roman Catholic priest, would not swear allegiance when the Revolution in France demanded an oath. Because he rebuilt the declining Sisters of the Good Saviour, he is also named its "Second Founder". The Legion of Honor was conferred on him in 1827 for his service as a priest.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pierre-Fran%C3%A7ois_Jamet", "biography": "rewritten"}'::jsonb),
