UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Eugenia Picco, an Italian Roman Catholic, joined, as a professed religious, a congregation called Little Daughters of the Sacred Hearts of Jesus and Mary. At her solemn profession she took the new name "Anna Eugenia", and she held a range of leadership roles until she died. She was known for her deep concern for the suffering of the poor and her firm devotion to the Eucharist.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Maria_Angela_Picco", "biography": "rewritten"}'::jsonb),
