UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Antonio Fatati, an Italian Catholic bishop, held the see of Ancona e Umana beginning 3 November 1463 and kept it until he died. He also served as a bishop in Teramo and Siena, and in Siena he assisted Cardinal Francesco Todeschini Piccolomini as an assistant bishop. His work and his important posts in the Papal States, which included treasurer and canon among others, also earned him the favor of several popes.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Antonio_Fatati", "biography": "rewritten"}'::jsonb),
