  AND md5(content."payload"->>'biography') = '1f2ba551c6cdc061db54ce1991e8a672';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Gontrand, who is also called Gontran, Gontram, Guntram, Gunthram, Gunthchramn and Guntramnus, ruled as king over Orléans between AD 561 and AD 592. He was a son of Chlothar I and Ingunda, the third eldest and the second eldest to survive. When his father died in 561 he became king over a quarter of the Frankish realm and set his capital at Orléans. His name "Gontrand" means "War Raven".'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Guntram", "biography": "rewritten"}'::jsonb),
