UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Sigebert III ruled Austrasia as a Merovingian king from 633 until he died around 656. Because the mayor of the palace actually governed the kingdom for his whole reign, he is described as the earliest Merovingian roi fainéant, meaning "do-nothing king". Still, Sigebert led a devout Christian life and was later made a saint, and both the Roman Catholic Church and the Eastern Orthodox Church remember him as Saint Sigebert of Austrasia.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Sigebert_III", "biography": "rewritten"}'::jsonb),
