UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Philip Howard, an English nobleman and the 13th Earl of Arundel, was canonised in 1970 by Pope Paul VI, who counted him among the England and Wales Forty Martyrs. He lived chiefly under Queen Elizabeth I, and the accusations against him were that he was a Roman Catholic, that he left England without permission and that he took part in Jesuit plots. For these he was imprisoned in the Tower of London in 1585. He remained there for ten years and died of dysentery.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Philip_Howard%2C_13th_Earl_of_Arundel", "biography": "rewritten"}'::jsonb),
