UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Alfonsa Clerici, from Italy, was a religious sister in a congregation called Sisters of the Most Precious Blood. Maria Matilde Bucchi founded that same congregation.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Alfonsa_Clerici", "biography": "rewritten"}'::jsonb),
