UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Blessed Alfonso Navarrete, also called Alfonso Navarrete-Benito and sometimes latinised as Alphonsus, was a nobleman from Spain who became a Dominican friar, a Catholic priest and a missionary. He worked in the Philippines (1598–1610) and then in Japan (1611–death), amid the persecutions of Christians in early Tokugawa Japan, under the Shogunate of Hidetada. His social work won praise, and he has been nicknamed the Vincent de Paul of Japan; at some point he served as Master of the Order of Preachers there. On 1 June 1617 he was beheaded in the Ōmura Domain, by order of the Daimyo Ōmura Sumiyori.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Alfonso_Navarrete", "biography": "rewritten"}'::jsonb),
