SET "payload" = content."payload" || jsonb_build_object('biography', 'A young boy of Trent, a city in the Prince-Bishopric of Trent, vanished and died, and these events were turned into a weapon: a blood libel against the Jewish community in his city. He is known as Simon of Trent, and also as Saint Simon of Trent.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Simon_of_Trent", "biography": "rewritten"}'::jsonb),
