UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Victoria was a martyr in Córdoba, in Hispania. She was martyred in the Diocletianic Persecution together with her brother Acisclus, and St. Eulogius wrote of them. Victoria and Acisclus are regarded as the first saints of Cordoba, and their feast is on 17 November. Whether Victoria really existed is historically doubtful, yet both martyrs received honor in Mozarabic liturgical rites.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Victoria_of_C%C3%B3rdoba", "biography": "rewritten"}'::jsonb),
