UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Altmann was Bishop of Passau from 1065 until he died. He was a significant figure in the Gregorian reforms and a founder and reformer of monasteries. He is venerated as a saint. No formal canonization process took place, but the Catholic Church regards him as a saint and commemorates him on August 8.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Altmann_(bishop_of_Passau)", "biography": "rewritten"}'::jsonb),
