UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'María Beatriz del Rosario Arroyo y Pidal (17 February 1884 – 14 June 1957), who as a religious took the name María Rosario of the Visitation, was a Filipino nun. She was founder of the congregation known as Dominican Sisters of the Most Holy Rosary of the Philippines.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Mar%C3%ADa_Beatriz_del_Rosario_Arroyo", "biography": "rewritten"}'::jsonb),
