UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Józef Sebastian Pelczar, a Polish Roman Catholic bishop, was co-founder, with Ludwika Szczęsna, of a congregation: the Sister Servants of the Most Sacred Heart of Jesus, in 1894. He held several episcopal offices, among them that of Bishop of Przemyśl.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/J%C3%B3zef_Sebastian_Pelczar", "biography": "rewritten"}'::jsonb),
