UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Francis Xavier Seelos, C.Ss.R., a German Redemptorist missionary, laboured in the United States, chiefly in parishes for immigrant communities on the American frontier. Towards the end of his life he went to New Orleans to minister to those stricken in a yellow fever outbreak. He caught the disease himself and died of its complications.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Francis_Xavier_Seelos", "biography": "rewritten"}'::jsonb),
