UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Leobinus, a saint, was a hermit, abbot, and bishop. He came from a peasant family and became a hermit and then a monk of Micy Abbey, after which he was ordained a priest. Next he was chosen abbot of Brou, and in 544 he succeeded Etherius as Bishop of Chartres, with the approval of king Childebert I.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Leobinus", "biography": "rewritten"}'::jsonb),
