UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Clemente Marchisio, an Italian Roman Catholic priest, served as a parish priest within the Archdiocese of Turin. After serving as an assistant priest, he travelled to cities around Italy, since word of his mission and holiness was spreading. Out of evangelical and devotional zeal he founded Daughters of Saint Joseph of Rivalba, a congregation meant to answer the religious needs of women. Saint Joseph and the Eucharist were the order''s special emphasis.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Clemente_Marchisio", "biography": "rewritten"}'::jsonb),
