WHERE content."id" = 'cmtt448wj037nblnybuetb9d0'
  AND content."slug" = 'saint-renatus-of-angers'
  AND md5(content."payload"->>'biography') = 'bffe019a0a770505cf4a4fe06665bd63';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'José María Gran Cirera, a Spanish Catholic priest who served in Guatemala, was a missionary belonging to the Missionaries of the Sacred Heart. He was a martyr, a casualty of the Guatemalan Civil War, and is a Blessed of the Catholic Church.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Jos%C3%A9_Mar%C3%ADa_Gran_Cirera", "biography": "rewritten"}'::jsonb),
