UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Anthony of Weert, a Franciscan friar and priest, was martyred in the course of the Dutch Revolt. Eighteen other men died as martyrs with him, and together they are called the Martyrs of Gorkum.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Anthony_of_Weert", "biography": "rewritten"}'::jsonb),
