SET "payload" = content."payload" || jsonb_build_object('biography', 'Stanisław Kostka Streich, a Polish Roman Catholic priest, was killed by a communist assassin while celebrating Holy Mass. He is venerated as a martyr by the Catholic Church.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Stanis%C5%82aw_Kostka_Streich", "biography": "rewritten"}'::jsonb),
