UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Simon Mchedlidze, a Georgian clergyman, educator, and journalist, was a leading figure in the educational and church life of Western Georgia. Soviet authorities executed him in the repressions that came after the August Uprising of 1924. In 1995 the Georgian Orthodox Church canonized him as a martyr.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Simon_Mchedlidze", "biography": "rewritten"}'::jsonb),
