UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pope John XXIII led the Catholic Church and ruled Vatican City. His term began on 28 October 1958 and ended with his death on 3 June 1963.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_John_XXIII", "biography": "rewritten"}'::jsonb),
