  AND md5(content."payload"->>'biography') = 'd5e8bf18de5e8ed9681c0d1b1524a911';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The last Habsburg-Lorraine ruler of Austria-Hungary, Charles I and IV held the thrones of Austria (as Emperor) and Hungary (as King), together with the remaining Habsburg lands, between November 1916 and the end of the monarchy in November 1918. His parents were Archduke Otto of Austria and Princess Maria Josepha of Saxony. After the 1914 assassination of Archduke Franz Ferdinand of Austria, his uncle, Charles stood next in line, as heir presumptive, to Emperor Franz Joseph. Princess Zita of Bourbon-Parma became his wife in 1911.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Charles_I_of_Austria", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmtt4daub06kbblnyydqcf7wl'
  AND content."slug" = 'saint-charles-i-of-austria'
  AND md5(content."payload"->>'biography') = '381f032d28b58936be41ec3ddc12565a';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Jadwiga, who also went by Hedwig, ruled the Kingdom of Poland as queen and was its last hereditary monarch. To underline that she reigned in her own right, she was crowned "King", and her reign ran from 16 October 1384 until she died. She was born in Buda, youngest daughter of Elizabeth of Bosnia and Louis I of Hungary. She belonged to the Capetian House of Anjou, and her ancestors included Polish Piasts.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Jadwiga_of_Poland", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmtt4db8j06keblny3zdv8a6j'
