  AND md5(content."payload"->>'biography') = '626c22a9a000c53dcf4bd5468c584de6';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'An Italian Dominican friar and painter of the early Florentine Renaissance, Fra Giovanni da Fiesole came to be called, after his death, Fra Angelico, or in Italian Beato Angelico.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Fra_Angelico", "biography": "rewritten"}'::jsonb),
