UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Cunigunde of Luxembourg, OSB (in Latin Cunegundis or Kinigundis, and also spelled Cunegundes, Cunegunda or Cunegonda), became Empress of the Holy Roman Empire through her marriage to Holy Roman Emperor Henry II, and after his death in 1024 she acted as interim regent. A saint, she is patroness of Luxembourg, and her feast day falls on 3 March.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Cunigunde_of_Luxembourg", "biography": "rewritten"}'::jsonb),
