  AND md5(content."payload"->>'biography') = '975b64d11c86560d0598ecefcc32b273';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('summary', 'This Catholic devotion to the Most Chaste Heart of Joseph honors Saint Joseph as "the just man" and "a man of singular virtue."'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Chaste_Heart_of_Joseph", "summary": "rewritten", "background": "wikipedia", "practiceInstructions": "wikipedia"}'::jsonb),
