UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('practiceInstructions', 'According to the doctrine of the Immaculate Conception, the Virgin Mary was without original sin from the instant she was conceived. Among the Catholic Church''s dogmas about Mary there are four, and this is one of them. Medieval theologians debated it, and Pope Pius IX did not define it as a dogma until 1854, in the papal bull Ineffabilis Deus. The Immaculate Conception concerns Mary''s freedom from original sin; her freedom from personal sin had already been affirmed, without dogmatic definition, by the Council of Trent (1545 to 1563).'::text) || jsonb_build_object('background', 'According to the doctrine of the Immaculate Conception, the Virgin Mary was without original sin from the instant she was conceived. Among the Catholic Church''s dogmas about Mary there are four, and this is one of them. Medieval theologians debated it, and Pope Pius IX did not define it as a dogma until 1854, in the papal bull Ineffabilis Deus. The Immaculate Conception concerns Mary''s freedom from original sin; her freedom from personal sin had already been affirmed, without dogmatic definition, by the Council of Trent (1545 to 1563).'::text) || jsonb_build_object('summary', 'According to the doctrine of the Immaculate Conception, the Virgin Mary was without original sin from the instant she was conceived. Among the Catholic Church''s dogmas about Mary there are four, and this is one of them.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Immaculate_Conception", "practiceInstructions": "rewritten", "background": "rewritten", "summary": "rewritten"}'::jsonb),
