UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('origin', 'The Catholic title Our Lady of the Turning Eyes for the Blessed Virgin Mary is tied to a moving and weeping statue at Rottweil, which lies in modern Baden-Württemberg, Germany. Visitors travel there from Alsace, Lake Constance and Switzerland, as well as other regions.'::text) || jsonb_build_object('summary', 'The Catholic title Our Lady of the Turning Eyes for the Blessed Virgin Mary is tied to a moving and weeping statue at Rottweil, which lies in modern Baden-Württemberg, Germany. Visitors travel there from Alsace, Lake Constance and Switzerland, as well as other regions.'::text) || jsonb_build_object('theologicalSignificance', 'The Catholic title Our Lady of the Turning Eyes for the Blessed Virgin Mary is tied to a moving and weeping statue at Rottweil, which lies in modern Baden-Württemberg, Germany. Visitors travel there from Alsace, Lake Constance and Switzerland, as well as other regions.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Our_Lady_of_the_Turning_Eyes", "origin": "rewritten", "summary": "rewritten", "theologicalSignificance": "rewritten"}'::jsonb),
