UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Egino, a native of Augsburg in Bavaria, Germany, was a Camaldolese abbot who took part in many of the disputes of his time. Sts. Ulric and Afra abbey received him as a child, and he later became its abbot, but he was expelled after backing Pope Callistus II against Emperor Henry V in a dispute. He lived at St. Blaise Abbey, came back to Augsburg in 1106, and took up the office of abbot again in 1109. He fled to Rome in 1120 because he opposed Bishop Hermann, a practitioner of simony according to Udalschalk (an associate of Egino and a monk of the abbey). Two years later he returned to Augsburg; he died in Pisa.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Egino", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmttlasuo00h24kuk6kwd2k7y'
  AND content."slug" = 'saint-egino'
  AND md5(content."payload"->>'biography') = '8d2d1cd081989fd4dc68fee3699ee74b';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pope Agatho, bishop of Rome, held office between 27 June 678 and his death on 10 January 681. Wilfrid of York, displaced from his see when Theodore of Canterbury ordered the archdiocese divided, appealed to him, and Agatho heard the case. The Sixth Ecumenical Council, called to address monothelitism, met during Agatho''s time in office. The Eastern Orthodox Church and the Catholic Church both venerate him as a saint. He is said to have lived longer than any other pope.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Agatho", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
