  AND content."slug" = 'saint-agatho'
  AND md5(content."payload"->>'biography') = '6450abbdb6e47e6604f46cb219244d0b';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Siméon-François Berneux, a French Catholic missionary in Asia belonging to the Paris Foreign Missions Society, was canonized as a saint. He was put to death in 1866 at Saenamteo, Seoul, Korea, during the anti-Christian purges. The French campaign against Korea launched that same year was provoked by his death, and it led Korea to strengthen its existing policy of isolationism.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Sim%C3%A9on-Fran%C3%A7ois_Berneux", "biography": "rewritten"}'::jsonb),
