  AND md5(content."payload"->>'biography') = '97c527389fe8586a62637e6c934d678a';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Italian medical doctor Riccardo Pampuri, OH – born Erminio Filippo Pampuri – was a World War I veteran and a professed member of the Hospitaller order of Saint John of God, whose members are called Brothers Hospitallers. In the Great War he served as a field doctor at the front, and after being discharged in 1920 he could return to his studies and shortly afterwards open his own practice, where he treated the poor free of charge. He entered the Third Order of Saint Francis under the name "Antonio" at the time he founded the Band of Pius X and dedicated it to poor people''s medical care. Later he became a professed religious, because he could not disregard the call, and he ran a free dental clinic for his order in Brescia.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Richard_Pampuri", "biography": "rewritten"}'::jsonb),
