UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Simeon Stylites, or Symeon the Stylite, became famous as a Syrian Christian ascetic who spent 36 years on a pillar near Aleppo. Other stylites afterward imitated his example. The Catholic Church, the Oriental Orthodox Churches, and the Eastern Orthodox Church all venerate Simeon as a saint. To set him apart from Simeon Stylites the Younger, Simeon Stylites III and Symeon Stylites of Lesbos, he is formally called Simeon Stylites the Elder.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Simeon_Stylites", "biography": "rewritten"}'::jsonb),
