UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Brynolf Algotsson, a Swedish Catholic prelate and theologian, held the position of Bishop of Skara from 1278 until he died. He came from a noble line and studied for almost two decades at the college in Paris. Back in his homeland he served as a dean and canon, and was afterward nominated bishop. He worked diligently to reform how the schools taught and to reorganize his see as a whole. Briefly forced into exile, he was nonetheless able to resume his work once he returned.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Brynolf_Algotsson", "biography": "rewritten"}'::jsonb),
