UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pierre-René Rogue, CM was a French Catholic priest of the Congregation of the Mission. He ministered in Vannes, where he was recognized as a man devoted to the faith. He declined to swear allegiance to the revolutionary French government, and was killed for it. Because he was small in stature, the people of Vannes called him "the wee priest". He was beatified in 1934.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pierre-Ren%C3%A9_Rogue", "biography": "rewritten"}'::jsonb),
