UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Benedetta Cambiagio Frassinello, an Italian Roman Catholic professed religious, was a founder: she began the Benedictine Sisters of Providence. In 1816 she married in order to satisfy her parents, but she and her husband agreed to live chastely, and each followed a call to religious life; she entered the Ursulines in Capriolo at Brescia. Later the two came together again, setting out to found schools where girls could be educated, and they returned to Genoa. There in 1838 she founded her order, drawing on the Benedictine charism.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Benedetta_Cambiagio_Frassinello", "biography": "rewritten"}'::jsonb),
