UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'An Italian Roman Catholic professed religious, Bartolomea Capitanio established, together with Vincenza Gerosa, the Sisters of Charity of Lovere, and she is counted as its co-foundress. Her life was rather short, and she gave it to meeting the schooling needs of children and of the poor. For most of it she worked as a teacher, with her order serving as the vehicle for this aim.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Bartolomea_Capitanio", "biography": "rewritten"}'::jsonb),
