UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'In the Fourth Century Abadiu of Antinoe held the office of bishop there. He is commemorated as a saint by the Coptic Orthodox Church, and he is said to have been killed during a theological dispute with the Arians. Hippolyte Delehaye makes reference to him in Les Martyrs d''Égypte. His feast day is 26 December.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Abadiu_of_Antinoe", "biography": "rewritten"}'::jsonb),
