UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Luigi Versiglia, S.D.B., was an Italian Catholic prelate and a professed member of the Salesians of Don Bosco. He was the first apostolic vicar of Shaoguan, serving from 1920 until he was murdered. Earlier he had been a novice master, known for strict austerities and discipline yet also for the warm, compassionate way he looked after poor and defenceless people. In 1906 he headed the first Salesian expedition to China, where he stayed until his death, serving the people in many capacities, including as a gardener and barber.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Luigi_Versiglia", "biography": "rewritten"}'::jsonb),
