UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Gerardo Cagnoli was an Italian Roman Catholic and a professed religious of the Order of Friars Minor. He set out on a lengthy pilgrimage southward, passing through Rome and Naples, then settled in Trapani and afterwards spent a long period as a hermit on the slopes of Mount Etna. Later he joined the Franciscans and lived in two of their convents in Sicily, where he gained a reputation for working miracles; people also regarded his humble, simple, childlike character as a sign of his holiness.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Gerardo_Cagnoli", "biography": "rewritten"}'::jsonb),
