UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Benedict Menni, OH, born Angelo Ercole Menni Figini, was an Italian Roman Catholic priest who professed vows as a member of the Hospitaller Brothers of Saint John of God. He went on to found a women''s religious congregation whose ministry was based on that of his own order. It is called Sisters Hospitaller of the Sacred Heart of Jesus.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Benedict_Menni", "biography": "rewritten"}'::jsonb),
