UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Giuseppe Benedetto Dusmet, born Giuseppe Dusmet, was an Italian Roman Catholic cardinal and Archbishop of Catania from 1867 until he died. He made his profession in the Order of Saint Benedict and took "Benedetto" as his religious name. Before joining the Benedictines he studied under them, and he later served as a professor, as well as prior and abbot. After he became a bishop he distinguished himself during cholera epidemics by caring for the sick, and he stayed a firm advocate for his archdiocese''s poor. Still a Benedictine, he continued to wear the Benedictine habit rather than the red regalia of a cardinal.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Giuseppe_Benedetto_Dusmet", "biography": "rewritten"}'::jsonb),
