UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The Wexford Martyrs were Matthew Lambert, Robert Meyler, Edward Cheevers and Patrick Cavanagh. They were found guilty of high treason in 1581 for helping James Eustace, 3rd Viscount Baltinglass, escape; for likewise smuggling a Jesuit, other Catholic priests and some laymen from Irish soil; and for refusing the Oath of Supremacy, which named Elizabeth I of England as Supreme Governor of the Church in her realms. They were hanged, drawn and quartered at Wexford, Ireland, on 5 July 1581. Pope John Paul II beatified them in 1992.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Wexford_Martyrs", "biography": "rewritten"}'::jsonb),
