UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Toribio Romo González, known as Saint Toribio Romo, was a Catholic priest and martyr from Mexico who was killed during the Cristero War, in the persecutions aimed against the clergy. Pope John Paul II beatified him and later canonized him along with another 24 saints and martyrs of that war. He is widely venerated in Mexico and by Mexican immigrants, above all because of reports that he miraculously appears to migrants attempting to cross the border between Mexico and the United States.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Toribio_Romo", "biography": "rewritten"}'::jsonb),
