UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'From 14 March 1800 until August 1823, when he died, Pope Pius VII led the Catholic Church. He ruled the Papal States between June 1800 and 17 May 1809, and once more from 1814 until his death. Chiaramonti belonged to the Order of Saint Benedict as a monk, and he was also a noted theologian and bishop.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Pius_VII", "biography": "rewritten"}'::jsonb),
