UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Barbora of Žagarė was a laywoman and Roman Catholic from Žagarė, in what was then the Grand Duchy of Lithuania. Oral history says she stood out for her Christian virtues and died young in unclear circumstances. Reportedly her body did not decay, which drew many local people to follow her devotedly, and many miracles are attributed to her. The Diocese of Šiauliai opened her beatification process in 2005 and named her a Servant of God.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Barbora_%C5%BDagariet%C4%97", "biography": "rewritten"}'::jsonb),
