UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Alfredo Verzosa y Florentín became the fourth native Filipino raised to the office of bishop in the Catholic Church. He was also the first bishop from Northern Luzon and the first Ilocano bishop. Together with others he founded the congregation called Missionary Catechists of the Sacred Heart (MCSH), whose work is education and administration within the church, with catechesis a particular focus. Pope Benedict XVI declared him a Servant of God, and the cause for his beatification is underway.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Alfredo_Verzosa", "biography": "rewritten"}'::jsonb),
