  AND md5(content."payload"->>'biography') = '6d8b5043c69260ae013fac21981d0bad';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Founder and abbot of the St.Cyriacus monastery at Clermont-Ferrand, Abraham of Clermont died c. 479. His birthplace was Byzantine Syria, on the Euphrates River, and his origins were Persian. Later he set out for Byzantine Egypt, intending to see hermits living there. On his way he was captured and spent five years as a prisoner. Once free, he went to Gaul, where he started a new community of monks close to the basilica of Saint Cyricus; the church of St. Illidius (St.Allyre) near Clermont was not far away. His death came around 479. St. Abraham''s grave bears an epitaph written by Apollinaris Sedonius, bishop of Clermont, and it gave us some facts of the saint''s life.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Abraham_of_Clermont", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
