UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Supposedly a resident of Palestine in the 4th century, Susanna the Deaconess was a martyr, a saint and a deaconess. Her hagiography says she resolved to give herself wholly to the Christian faith, so she disguised herself as a man and entered a monastery for men, taking the name "John". She lived piously there until false accusations of rape in the monastery led to her being discovered.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Susanna_the_Deaconess", "biography": "rewritten"}'::jsonb),
