UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pope Anterus (Latin: Anterus, Classical Greek: Ανθηρός, romanized: Antheros) was Rome''s bishop, serving from 21 November 235 until he died on 3 January 236.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Anterus", "biography": "rewritten"}'::jsonb),
