UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'An Irish monk and missionary, Aidan of Lindisfarne is credited with bringing the Anglo-Saxons of Northumbria to the Christian faith. On the island of Lindisfarne he established a ministry cathedral, called Lindisfarne Priory, and became its first bishop. He journeyed tirelessly across the countryside, preaching the gospel to Anglo-Saxon nobles and to the socially disenfranchised alike.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Aidan_of_Lindisfarne", "biography": "rewritten"}'::jsonb),
