  AND md5(content."payload"->>'biography') = 'be1aa7a3d46dc136fddb0a353d347d4c';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pope Mark (Latin: Marcus) served as bishop of Rome from 18 January 336 until he died on 7 October of that year. His early life is poorly documented. The Liber Pontificalis states that he was a Roman by birth and that his father was named Priscus. Sylvester I was his predecessor as pope, and Mark''s term began on 18 January 336. According to some evidence, the Depositio episcoporum and the Depositio martyrum, early lists of bishops and of martyrs, were started during his time as pope. The Liber Pontificalis also reports that he issued a constitution that granted the bishop of Ostia a pallium and confirmed his authority to consecrate newly elected popes. That same source credits him with founding the Basilica of San Marco, a Roman basilica, along with a cemetery church above the Catacomb of Balbina. The church stood just outside the city, on land that Emperor Constantine donated. Mark''s death, from natural causes, came on 7 October, and he was buried in the Balbina catacomb. His remains were moved to the town of Velletri in 1048, then in 1145 to Rome''s Basilica of San Marco, where they rest in an urn beneath the altar. His feast day falls on 7 October, and he is especially venerated at Monte Amiata, in the Abbadia San Salvatore.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Mark", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmvwzmuic000lbifqxuq5yk6p'
  AND content."slug" = 'saint-mark'
  AND md5(content."payload"->>'biography') = '431c3b12797c9386ed0f1c85c2ca2d49';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Frederick I held the see of Utrecht as its bishop from 815/816 until 834/838 AD. He is counted as a saint by both the Roman Catholic Church and the Eastern Orthodox Church. At times his name appears in Latin form as Fridericus Cridiodunus.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Frederick_of_Utrecht", "biography": "rewritten"}'::jsonb),
