UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Hryhoriy Khomyshyn was a bishop of the Ukrainian Greek Catholic Church and a hieromartyr. His name is also given as Hryhorij Khomyshyn, in Ukrainian as Григорій Лукич Хомишин, in Polish as Grzegorz Chomyszyn, and in Italian as Hryhoryj Chomyšyn or Gregorio Khomyšyn.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Hryhoriy_Khomyshyn", "biography": "rewritten"}'::jsonb),
