UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A Japanese Catholic physician and author, Takashi Nagai survived the atomic bombing of Nagasaki. The life of prayer and service he led afterward won him an endearing title, "saint of Urakami". In 2021 his cause for canonization was opened, and he bears the title Servant of God.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Takashi_Nagai", "biography": "rewritten"}'::jsonb),
