UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Felicianus of Foligno (Italian: San Feliciano di Foligno), who lived c. 160 to c. 250, is Foligno''s patron saint.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Felician_of_Foligno", "biography": "rewritten"}'::jsonb),
