UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Agilulfus (or Agigulf) was Abbot of Stavelot, then Bishop of Cologne, and a martyr. His death came about 750. Apart from his name, what happened in his life is uncertain. An early account by a monk of Malmedy is considered unreliable. His family was a good one, and Abbot Angelinus educated him at Stavelot. Shortly after he succeeded as Abbot of Stavelot, he was made Bishop of Cologne. Reportedly he urged King Pepin to pass over Charles Martel when choosing who would hold the throne, since Charles was illegitimate. His violent death soon afterward may have come from Martel''s desire for revenge. In a letter of 747, Pope Zachary praised Agilulfus for having signed the "Charta verae et orthodoxae professionis." The Abbey at Malmedy venerated him as an abbot and martyr. Bishop Anno brought his remains, in 1062, to Cologne, to the church named for Our Lady of the Steps. July 9 is his feast day.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Agilulfus_of_Cologne", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmvwztyl900ydu7z57b23souw'
  AND content."slug" = 'saint-agilulfus-of-cologne'
  AND md5(content."payload"->>'biography') = '08a65202a07c70820f7af0e82b043640';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Italian politician and statesman Alcide Amedeo Francesco De Gasperi founded the Christian Democracy party. He was prime minister of Italy from 1945 to 1953, leading eight coalition governments one after another.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Alcide_De_Gasperi", "biography": "rewritten"}'::jsonb),
