UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Born Pietro Francesco Orsini, and later called Vincenzo Maria Orsini, Pope Benedict XIII headed the Catholic Church and led the Papal States from the 29th of May 1724 until his death in February 1730.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Benedict_XIII", "biography": "rewritten"}'::jsonb),
