UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Vivianus, who is also called Bibianus, died c. 490. The first known bishop of Saintes, he is counted among the early saints of the French (Francian) church. Krush edited in 1896 a short Life of him dating from the middle of the 6th century. Gregory of Tours, writing later in the 6th century, mentions him too and refers back to that earlier text, saying that an already existing book about his life recounts most of his miracles.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Vivianus", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
