UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Juan María de la Cruz, S.C.I., was born Mariano García Méndez in San Esteban de los Patos, Province of Ávila, on 25 September 1891, and died in Silla, Valencia, on 23 August 1936. He was a Spanish priest of the Roman Catholic Church, which regards him as a martyr. In 2001 Pope John Paul II beatified him along with his fellow martyrs killed during the Spanish Civil War.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Juan_Mar%C3%ADa_de_la_Cruz", "biography": "rewritten"}'::jsonb),
