UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Simon de Crépy held the counties of Amiens, the Vexin and Valois from 1074 to 1077. His parents were Count Ralph IV of Valois and Adèle of Bar-sur-Aube, so he was the brother of Adele of Valois. Other names for him are Simon de Vexin, Simon of Crépy and Saint Simon.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Simon_de_Cr%C3%A9py", "biography": "rewritten"}'::jsonb),
