UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Hilarius of Aquileia (Italian: Ilario d''Aquileia, or Ellaro or Elaro), also called Hilary of Aquileia, died on 16 March, c. 284, as a martyr and saint and an early Bishop of Aquileia. He is supposed to have been Hermagoras''s successor as second bishop of that city. Under the prefect Beronius, he was tortured to death in the persecution of Numerian. He had refused to sacrifice to the pagan gods, and before he died his prayers made the temples of Aquileia fall down together with the images of the gods inside. His deacon Tatianus, otherwise Tatian, was martyred with him, and Hilarius''s name is often paired with his, for example in the dedication of Gorizia Cathedral. Their companions Felix, Largus and Dionysius died as martyrs as well. Hilarius and his companions are commemorated on the day they were martyred, 16 March.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Hilarius_of_Aquileia", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmvwzvb42012nu7z5f1rh78fk'
  AND content."slug" = 'saint-hilarius-of-aquileia'
  AND md5(content."payload"->>'biography') = 'c2b1cd9c1da7007883e0c470cbbcc3e4';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pope Pius XI beatified the English Catholic priest and martyr James Fenn on 15 December 1929. He had two brothers, Robert Fenn and John Fenn, the latter a Catholic priest and writer. The three brothers were all choristers and scholars.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/James_Fenn", "biography": "rewritten"}'::jsonb),
