UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Julius Kambarage Nyerere was a politician from Tanzania, and also a revolutionary, a political theorist and an anti-colonial activist. He governed Tanganyika as prime minister in 1961 to 1962, and as its president from 1962 to 1964. After that, from 1964 to 1985, he was president of Tanzania, which succeeded Tanganyika as a state. From 1954 to 1990 he was a founder and chair of the party known as the Tanganyika African National Union (TANU) and then of the party that came after it, Chama Cha Mapinduzi. He was an African nationalist and African socialist by ideology, and he promoted the political philosophy called Ujamaa.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Julius_Nyerere", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
