  AND content."slug" = 'saint-julius-nyerere'
  AND md5(content."payload"->>'biography') = '385480f7bbd017fa514699140264b20f';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A French princess and Discalced Carmelite, Louise of France, OCD, was the youngest of King Louis XV and Queen Maria Leszczyńska''s ten children. In 1770 she entered the convent of the Carmelites at Saint-Denis, taking the name Thérèse of Saint-Augustin as a religious. Her terms as prioress ran from 1773 to 1779 and from 1785 to 1787.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Louise_of_France", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
