  AND md5(content."payload"->>'biography') = '88494e99d662b9fac94eb1877aa4409d';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The Italian Franciscan friar Luca Belludi came from Padua. Born between 1200 and 1210, he died on 17 February 1286. He is said to have received the habit of the order at 25 from Francis of Assisi himself. He studied at the university in Padua and was ordained priest in 1227. Anthony of Padua was his close friend, and Belludi shared in his prayers and helped him draft his sermons. He prayed to St Anthony after the latter''s death, and through that prayer and Anthony''s intercession he helped to free Padua in 1256 from a tyrant, Ezzelino III da Romano. When death came to Belludi in Padua in 1286, he was laid in the urn that held St Anthony. The two stayed together until 1971, then were moved to a chapel now named for him (it is also named for Saints Philip and James the Less, and called the Conti Chapel), famed for frescoes by Giusto de'' Menabuoi. He was beatified on 18 May 1927 by Pope Pius XI, and the outer cloister of the Basilica of Saint Anthony of Padua now bears his name too.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Luca_Belludi", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmvwzz6ks015tu7z5pmxaw7dq'
  AND content."slug" = 'saint-luke-of-padua'
  AND md5(content."payload"->>'biography') = 'e5b5bae0b698af708023e5d738b87353';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Luisa Guidotti Mistrali, an Italian laywoman, belonged to the Roman Catholic Church and did missionary work in Rhodesia. She belonged to the Women''s Medical Missions Association. In a number of Rhodesian hospitals she cared for the sick, and on one occasion she even looked after the mother of Robert Mugabe. Under her efforts the hospitals grew to treat more patients, and she was valued across the country. This esteem helped lead to the dropping of charges against her; she had been accused of treating a guerrilla, and had in fact done so. The process for her beatification began in 1995 in Modena.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Luisa_Guidotti_Mistrali", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmvwzz7rj015wu7z5xyk2y0r0'
  AND content."slug" = 'saint-luisa-guidotti-mistrali'
  AND md5(content."payload"->>'biography') = '37149c7d8a9804499f39a0cd78431414';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Hugh Faringdon went by several names: first Hugh Cook, then Hugh Cook alias Faringdon, and also Hugh Cook of Faringdon. An English Benedictine monk, he was the last Abbot of Reading Abbey, which stood in Reading, in Berkshire, England. When King Henry VIII of England dissolved the monasteries, Faringdon was charged with high treason and executed. The Catholic Church declared him a martyr and beatified him in 1895.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Hugh_Faringdon", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
