  AND content."slug" = 'saint-hugh-cook-faringdon'
  AND md5(content."payload"->>'biography') = '080fc8551798b98f9aa2ce6ce7dd30b6';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Maurilius, called Maurille in French, was a priest from Milan who served as bishop of Angers from 423 to 453, and lived from about 336 until 453. He took an early part in the Christianization of Gaul.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Maurilius_of_Angers", "biography": "rewritten"}'::jsonb),
