  AND content."slug" = 'saint-petrus-armengol'
  AND md5(content."payload"->>'biography') = '2517ee893c87e38311d2afeaa3bc52d4';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Relindis was the daughter of count Adelard and the sister of Saint Herlindis. Both girls were raised at the Benedictine monastery in Valenciennes. Later, Adelard and his wife built a monastery for their daughters at Maaseik. In 728 the Abbey of Aldeneik was consecrated.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Relindis_of_Maaseik", "biography": "rewritten"}'::jsonb),
