  AND md5(content."payload"->>'biography') = '65b43615f698e1337f72c682ff7725b4';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Vigilius of Trent, known in Italian as San Vigilio di Trento and in German as Vigilius von Trient, lived from c. 353 to 26 June 405; he was bishop of Trent and is venerated as its patron saint.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Vigilius_of_Trent", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmvwzzl72016nu7z58kf9002w'
