  AND md5(content."payload"->>'biography') = '25d2decb717ab3a178c96eb5723a132a';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Solomon Leclercq, FSC, was born Guillaume-Nicolas-Louis Leclercq on 15 November 1745 and died on 2 September 1792. He was a religious brother of France, in the Institute of the De La Salle Brothers. After being arrested and held in prison in Paris, he was killed about a fortnight later, in 1792, in a Carmelite convent''s garden, because he would not swear allegiance to the new French Revolutionary regime. This happened nearly two weeks prior to the dissolution of the kingdom. No Brother of the Christian Schools had been martyred before him, nor beatified. His canonization took place on 16 October 2016, and his feast day is September 2.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Solomon_Leclercq", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmvwzzpcw016tu7z5x0gt5rqz'
  AND content."slug" = 'saint-salomon-leclerc'
  AND md5(content."payload"->>'biography') = '7a021f7f564a75878cc09447940583e4';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Born in Carmagnola on 14 February 1844, Anna Maria Rubatto, an Italian nun of the Roman Catholic Church, took the name Maria Francesca of Jesus and died in Montevideo on 6 August 1904. The Capuchin Sisters of Mother Rubatto is an institute of which she was the founder. She did most of her work in Uruguay, where she died in 1904 aged 59. On 10 October 1993 she was beatified by Pope John Paul II, and she is regarded as the first Uruguayan to be beatified. In early 2020 Pope Francis approved a miracle attributed to her and so confirmed her canonization, which was celebrated on 15 May 2022.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Anna_Maria_Rubatto", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
