UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Among several semi-legendary Breton saints from Armorica whom the Catholic Church recognizes is Saint Yban. His other names are Ethbin, Iboan, Diboan, Diboen, Iben, Ibe, Abibon, Languis, Langui, Idunet and Ivinec, each with the title saint. He followed Saint Winwaloe as a disciple, and he established a priory on the site of what is now the city of Châteaulin.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Ethbin", "biography": "rewritten"}'::jsonb),
