SET "payload" = content."payload" || jsonb_build_object('biography', 'An Italian bishop of Cervia, Gerontius (also called Gerontius of Ficocle), died in 501 AD and is venerated as a saint.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Gerontius_of_Cervia", "biography": "rewritten"}'::jsonb),
