UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Mary of Jesus, surnamed de León y Delgado, was a lay sister of the Dominicans in Spain during the 17th century, and a mystic and visionary. In the Canary Islands, La Siervita was the name by which she was widely known.
Her life was austere and simple, and many miracles were attributed to her.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Mary_of_Jesus_de_Le%C3%B3n_y_Delgado", "biography": "rewritten"}'::jsonb),
