UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A prelate of the Catholic Church from Korea, Stephen Kim Sou-hwan became the first Korean elevated to cardinal, and earlier served as archbishop of Seoul in South Korea. He was a prominent figure during South Korea''s violent and turbulent shift from military rule to democracy, and people in every part of South Korean society held him in high regard. Declared a Servant of God by Pope Francis, he is venerated within the Roman Catholic Church.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Stephen_Kim_Sou-hwan", "biography": "rewritten"}'::jsonb),
