  AND md5(content."payload"->>'biography') = 'f184428dd87a396870a63c1912df56a8';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A noblewoman who died c. 286, Saint Zoe of Rome was the wife of Nicostratus, a high official of the Roman court. She had been unable to speak for six years until Saint Sebastian traced the cross over her; she then spoke at once and glorified Jesus. Zoe requested baptism. She lived under Emperor Diocletian, at the start of his persecution of Christians. Greatly devoted to Saint Peter, she was found praying at his tomb at the time of her arrest for her faith. She was hung over a fire and died suffocated by the smoke, and her body was then cast into the River Tiber. The Roman Catholic Church and the Eastern Orthodox Church both consider her a saint with a feast day of 5 July, though the Eastern Orthodox Church also venerates her on 18 December together with Saint Sebastian and other martyrs.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Zoe_of_Rome", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmvx03bxg01fau7z5rs5btuse'
  AND content."slug" = 'saint-zoe-of-rome'
  AND md5(content."payload"->>'biography') = '96f61817f83b1c5a1d29e76917cafc96';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Donatus of Arezzo (Italian: San Donato di Arezzo) is Arezzo''s patron saint and is regarded as a bishop of that city. A Passio about his life, whose historical reliability is doubtful, was composed by Severinus, a bishop of Arezzo. Severinus calls Donatus a martyr, yet early sources instead speak of him as a confessor of the faith and a bishop, not as a martyr. Gregory the Great already knew of an early hagiography of Donatus. Tradition holds that he was a native of Nicomedia and was martyred on August 7, 362, under the emperor Julian the Apostate.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Donatus_of_Arezzo", "biography": "rewritten"}'::jsonb),
