UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Giocondo Pio Lorgna, who was born Giocondo Lorgna, was a Roman Catholic priest from Italy and also took vows in the Order of Preachers. In Venice he was parish priest of the Ss. Giovanni e Paolo church, and he acted as either a benefactor or a reviver of Christian movements or congregations founded throughout the city.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Giocondo_Pio_Lorgna", "biography": "rewritten"}'::jsonb),
