UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Julian of Norwich, also called Juliana of Norwich, the Lady Julian, Dame Julian or Mother Julian, was an English Catholic anchoress of the Middle Ages. The writings now titled Revelations of Divine Love are the oldest surviving works in English attributed to a woman, and the only surviving English works by an anchoress.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Julian_of_Norwich", "biography": "rewritten"}'::jsonb),
