UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Ferdinand III, called the Saint, became king of Castile in 1217, King of León in 1230 and King of Galicia in 1231. His parents were Alfonso IX of León and Berengaria of Castile, and by his second marriage he also became Count of Aumale. He ranks among Castile''s most successful kings: he secured the lasting union of the Castilian and Leonese crowns, and he directed the largest southward expansion of territory so far, in the Guadalquivir Valley, where Islamic rule was in disarray after the Almohad caliphate was defeated in the battle fought at Las Navas de Tolosa. Pope Gregory IX bestowed on him the title Athleta Christi (''Champion of Christ'') in recognition of his repeated, decisive victories against the Islamic Caliphate.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Ferdinand_III_of_Castile", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmvx04tr501icu7z5vxpjj7qw'
  AND content."slug" = 'saint-ferdinand-iii-of-castille'
  AND md5(content."payload"->>'biography') = '46c3bbd0bf4b950608374e5a64649f45';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Jacques Sevin SJ, a French Jesuit who lived from 7 December 1882 to 19 July 1951, is remembered for helping bring Scouting to France.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Jacques_Sevin", "biography": "rewritten"}'::jsonb),
