UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Tit Liviu Chinezu, a bishop of the Romanian Greek-Catholic Church, lived from 22 June 1904 to 15 January 1955. His father was a priest, and he was born in the village of Huduc, Mureș County. In 1925 he went to Rome, first studying at the Sant''Atanasio college, and in 1930 he became a Doctor of Sacred Theology at the Pontificium Institutum Internationale Angelicum, the future Pontifical University of Saint Thomas Aquinas, Angelicum. His priestly ordination took place on 31 January 1930. Officials of the newly installed Communist government, which had outlawed the church, arrested him in October 1948, and in December 1949 fellow detained bishops secretly ordained him bishop. He was never tried or sentenced, but was ultimately sent to Sighet Prison, where he died of hypothermia. On 2 June 2019 in Blaj, Pope Francis beatified him together with six other Romanian bishop martyrs.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Tit_Liviu_Chinezu", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmvx04w8701iiu7z5qsh1sjnz'
  AND content."slug" = 'saint-tit-liviu-chinezu'
  AND md5(content."payload"->>'biography') = '18198a5c694c8e7666e4929bc94e5bf5';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Francis Mary Paul Libermann was a French Jew who converted to the Catholic Church. He entered the Congregation of the Holy Spirit as a religious priest and is chiefly remembered as founder of a society later merged with the Spiritans, the Holy Heart of Mary Society. Pope Pius X declared him venerable in February 1910.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Francis_Libermann", "biography": "rewritten"}'::jsonb),
