WHERE content."id" = 'cmvx05cg401j7u7z53rve884n'
  AND content."slug" = 'saint-catherine-of-ricci'
  AND md5(content."payload"->>'biography') = '24e3805b17b4bdd8541efdcb70ff195c';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Elena Spirgevičiūtė was a Lithuanian student. Soviet partisans shot and killed her because she resisted rape. Alfonsas Čeponis, one of the four men, was later honored posthumously with the title Hero of the Soviet Union. Recognized as a Servant of God, she was a devout Catholic. In 2000 the Archdiocese of Kaunas began her beatification case.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Elena_Spirgevi%C4%8Di%C5%ABt%C4%97", "biography": "rewritten"}'::jsonb),
