WHERE content."id" = 'cmvx05dk201jau7z5sc28uieq'
  AND content."slug" = 'saint-elena-spirgeviciute'
  AND md5(content."payload"->>'biography') = 'd02445e0ad623729e6bdb4d22c5f1c72';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Gerald of Braga, a saint, served as archbishop of Braga. Cahors in Gascony was his birthplace, and at Moissac, France, he entered the Benedictine order as a monk. Bernhard, the Archbishop of Toledo and also a Cluniac monk, liked the liturgical singing at the monastery and invited Gerald to reform the liturgical music of Toledo. He served there as the cathedral''s choir director. In 1100 he was made Bishop of Braga in Portugal, and he ended lay investiture of church offices in his diocese. Afonso I of Portugal received baptism from him. He died on December 5, 1109, and his burial was in Braga Cathedral. The Vita Sancti Geraldi was composed by a certain Bernard, his companion and another Cluniac monk from France.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Gerald_of_Braga", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmvx05ezp01jdu7z5br5ltbbi'
  AND content."slug" = 'saint-gerald-of-braga'
  AND md5(content."payload"->>'biography') = '6d87a1ba9ae885d6b7f2dd5b35e7327e';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Theresa of Portugal, Queen of Léon, married King Alfonso IX of León, who was her first cousin, as his first wife. After the marriage was annulled on grounds of consanguinity, she withdrew to a convent. In 1705 she was beatified.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Theresa_of_Portugal%2C_Queen_of_Le%C3%B3n", "biography": "rewritten"}'::jsonb),
