UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'James Thompson, whose other name was James Hudson, was a martyr and Catholic priest hanged at York in the reign of Elizabeth I.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/James_Thompson_(martyr)", "biography": "rewritten"}'::jsonb),
