UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Cunera of Rhenen, also spelled Kunera, was a virgin and martyr, and her name first appears in records of the 11th century. She is patron saint of Rhenen, a city in the Netherlands, protects horses, and is invoked against animal diseases and sore throat. The key and the scarf are her attributes.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Cunera", "biography": "rewritten"}'::jsonb),
