  AND content."slug" = 'saint-cunera'
  AND md5(content."payload"->>'biography') = '2e66f751694ef3c074a0e341eea9d061';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Tommaso Bellacci (1370 - 31 October 1447) belonged to the Third Order of Saint Francis and came from Italy. A butcher by trade, he changed from a sinful life to one of penance and service to God and became a religious. Though not an ordained priest, he traveled through the Italian peninsula and the Middle East, preaching and ministering to people. His beatification was celebrated in 1771.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Tommaso_Bellacci", "biography": "rewritten"}'::jsonb),
