  AND md5(content."payload"->>'biography') = '20471a7636c088820d025ae025903ad2';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Godfrey of Amiens (French: Geoffroy d''Amiens), who lived from 1066 to 1115, served as a bishop of Amiens, and the Catholic Church counts him as a saint.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Godfrey_of_Amiens", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
