  AND content."slug" = 'saint-godfrey-of-amiens'
  AND md5(content."payload"->>'biography') = 'ffc6524c57bb6ab857cab2652f2c43fe';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Armentarius governed the see of Pavia as bishop from 711 until 732. He succeeded Bishop Damian. Throughout his episcopacy he quarrelled for a long time with the Bishop of Milan, Benedict, who held that Pavia had historically belonged to the Metropolitan See of Milan, whereas Armentarius maintained that Pavia answered directly to Rome. Pope Constantine decided in favour of Armentarius, possibly because the Kingdom of the Lombards had its capital at Pavia. Pilgrims came to his tomb in Pavia Cathedral, because he was thought a powerful intercessor. January 30 is the day he is commemorated. Augustine of Hippo''s remains were moved from Sardinia and brought to San Pietro in Ciel d''Oro; this is sometimes credited to Armentarius, but it probably took place under Peter, who followed him and was an uncle of King Liutprand.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Armentarius_of_Pavia", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmvx06xuk01ltu7z5bz814nml'
  AND content."slug" = 'saint-armentarius-of-pavia'
