  AND md5(content."payload"->>'biography') = 'd69ff0d6f101652be59ca319f9900415';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Élisabeth of France, a French princess, was also known as Madame Élisabeth. Her parents were Louis, Dauphin of France, and Duchess Maria Josepha of Saxony; she was the youngest of their children and a sister of King Louis XVI. Her father the Dauphin was the heir and son of King Louis XV, whose popular wife was Queen Marie Leszczyńska. During the French Revolution Élisabeth stayed at the side of her brother and his family, and she was put to death at the Place de la Révolution in the Reign of Terror. The Catholic Church has introduced her cause for beatification and canonization, and Pope Pius XII declared her a Servant of God.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/%C3%89lisabeth_of_France", "biography": "rewritten"}'::jsonb),
