UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A Jewish martyr, Eleazar died when King Antiochus IV Epiphanes ordered Judaism persecuted in Judea. He and the woman with seven sons are counted among the "Holy Maccabean Martyrs", whom the Roman Catholic, Eastern Orthodox, and Oriental Orthodox churches celebrate. The Eastern Orthodox calendar gives August 1 as their feast day.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Eleazar_(2_Maccabees)", "biography": "rewritten"}'::jsonb),
