UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Jury Kashyra was a Roman Catholic priest from Poland and an apostle in Belarus of unity between Catholic and Orthodox Christians. Along with his parishioners, he was killed by Nazi security forces and their collaborators during Operation Winterzauber, a punitive raid carried out under the name of "bandit fighting". In 1999 Pope John Paul II beatified Kashyra, along with the 108 Blessed Polish Martyrs.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Jury_Kashyra", "biography": "rewritten"}'::jsonb),
