  AND md5(content."payload"->>'biography') = 'd5e292e81574bc3210c751bbdc3582e1';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Dalmatius of Rodez (French: Saint Dalmas, Dalmace) held the see of Rodez from 524 to 580. Born in Gaul in the late 400s, he was still a relatively young man when he was made bishop in 524. The Catholic Church considers that he suffered at the hands of Amalaric, a follower of Arianism.

In 535 he took part in the Council of Arvernum, whose sixteen decrees included the principle that episcopal dignity should be conferred for merit and never as the result of intrigues. He then attended the Fourth Council of Orléans in 541, and on the journey home he visited, as a pilgrim, the tomb of Martin of Tours. According to Gregory of Tours, Dalmatius kept pulling down a church he was building in order to improve it, so that it was still unfinished when he died. His testament asked Childebert II to see that his successor was not a stranger to the see, not covetous and not married, but a man who devoted every hour to praising God. November 13 is his feast day.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Dalmatius_of_Rodez", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmvx0anea01ppu7z5o5mkp7k9'
  AND content."slug" = 'saint-dalmatius-of-rodez'
  AND md5(content."payload"->>'biography') = 'f1402424960fcec6874501b72ceec576';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Ralph Milner was a martyr of the Roman Catholic Church, from England. He died as a martyr at Winchester together with a Catholic priest, Roger Dicconson (also spelled Dickenson), and both were beatified in 1929.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Ralph_Milner_and_companion", "biography": "rewritten"}'::jsonb),
