UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Luke Kirby, an English Catholic priest, was a martyr. A native of the North of England, he was executed under Elizabeth I. He belongs to the group titled Forty Martyrs of England and Wales.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Luke_Kirby_(priest)", "biography": "rewritten"}'::jsonb),
