UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A Benedictine abbot, Abbo of Auxerre was also bishop of Auxerre. He entered the Abbey of Saint-Germain d''Auxerre as a monk and later became its abbot, and he followed Heribald of Auxerre, his brother, into the bishopric. In 859 he left the see, was present at the Poncy synod in 860, and that year, on 3 December, he died. The Roman Martyrology, the Roman Catholic Church''s official though incomplete list of recognized saints, does not include him. His biography appears in Les Petits Bollandistes.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Abbo_of_Auxerre", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmvx0bgnr01smu7z5dvcgehco'
  AND content."slug" = 'saint-abbo-of-auxerre'
  AND md5(content."payload"->>'biography') = '23304c3219c230d8bf91d4748a1a3df4';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Florentius of Anjou, a Christian of the 4th century, was a hermit, priest, abbot and saint. Legend holds that he evangelised the area around Saumur and that Florain of Lorch was his brother. His name is borne by Angevin monasteries at Saint-Florent-le-Vieil, and at Saint Florent-le-Jeune, and by the collegiate church in Roye, Somme. Saumur''s abbey of Saint-Florent ordered a tapestry with scenes from the saint''s life around 1524, and it remains in Saumur.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Florentius_of_Anjou", "biography": "rewritten"}'::jsonb),
