UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A Korean-Japanese Roman Catholic martyr, Agnes Takeya (イネス竹屋) lived from 1580 to 1622. In 1580 she was born in Korea. During the Japanese invasions of Korea of 1592–1598 she was kidnapped and enslaved and carried off to Japan, where she became a Christian. Takeya''s husband was Cosmas Takeya Sozaburō, also a Catholic layperson and also a Korean who had been enslaved and taken to Japan in the same way. The couple were beheaded at Nagasaki during the "Great Genna Martyrdom", together with Charles Spinola and companions. She was beatified in 1867.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Agnes_Takeya", "biography": "rewritten"}'::jsonb),
