UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Jan Leopold Tyranowski was a Roman Catholic from Poland. He greatly admired the Discalced Carmelite charism and followed it, though he was not a member of their order. He had a central role in shaping the spiritual life of Karol Józef Wojtyła, the future Pope John Paul II. During the 1940s he led the college parish of Saint Stanisław Kostka, which was the parish of his friend, and served as mentor to its students. He also ran a small group for the Salesians of Don Bosco in the years of the war.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Jan_Tyranowski", "biography": "rewritten"}'::jsonb),
