  AND content."slug" = 'saint-jan-tyranowski'
  AND md5(content."payload"->>'biography') = 'ce629409035cf89cd797cafc0b67cec7';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A French mystic and Carmelite friar within the Catholic Church, John of St. Samson lived from 1571 to 1636 and was also called Jean du Moulin or Jean de Saint-Samson. People call him the soul behind the Carmelite Order''s Touraine Reform, a movement stressing prayer, silence and solitude. Smallpox at age three, together with poor medical treatment of it, left John blind. He was very insistent on Carmelite mystical devotion. Students of Christian mysticism have nicknamed him the "French John of the Cross".'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/John_of_St._Samson", "biography": "rewritten"}'::jsonb),
