UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Also called Brun, Bruno of Querfurt (O.S.B. Cam.) was a martyr, bishop, Camaldolese monk and Christian missionary. He worked in the eastern territories of the Holy Roman Empire and was among the foremost figures of the first Christian missions among the peoples of northeastern Europe. He is venerated under the title "Second Apostle of the Prussians". He met his death in Prussia, near the border of Kyivan Rus'' and Lithuania, while trying to bring the Old Prussians to the Christian faith.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Bruno_of_Querfurt", "biography": "rewritten"}'::jsonb),
