UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Jules Chevalier, MSC, a French Catholic priest, was the founder of three congregations: Missionaries of the Sacred Heart, Missionary Sisters of the Sacred Heart, and Daughters of Our Lady of the Sacred Heart. Their lay associates and these groups together are known as the Chevalier Family.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Jules_Chevalier", "biography": "rewritten"}'::jsonb),
