WHERE content."id" = 'cmvx0cv6r01wdu7z5a66dtpeq'
  AND content."slug" = 'saint-peris'
  AND md5(content."payload"->>'biography') = '7ead6e46eb493c4751bd2349eee4388c';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Baculus of Sorrento is venerated as a saintly bishop of that city; in Italian he is called San Bacolo or San Baccolo di Sorrento. A text from the 9th century or later, the Life of Saint Antoninus, Abbot of Sorrento, names several of the city''s patron saints: Renatus, Athanasius, and Baculus, all bishops. It also describes these saints, drawing on a painting that hung in Sorrento''s cathedral at that time. The period of Baculus''s supposed episcopate in the city is uncertain. Ferdinando Ughelli relied on a manuscript found in Sorrento Cathedral that dates from after the 12th century, and concluded that Baculus was bishop in the 7th century. The Bollandists thought he lived around 660 AD. Francesco Lanzoni, by contrast, writes that the Vita Sancti Baculi gives no chronological detail at all in the part dealing with its hero''s time as bishop, and that nothing therefore stands in the way of believing that he lived, perhaps, during the fourth or fifth century.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Baculus_of_Sorrento", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmvx0cx1r01wgu7z5usb2oozc'
  AND content."slug" = 'saint-bacolo-di-sorrento'
  AND md5(content."payload"->>'biography') = '0112778919faaa110020ba7baa624d04';

