UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Agathonicus lived in the 3rd century and was a citizen of Nicomedia. During a stay in Greece he instructed the Greeks in the Christian faith. At that time the imperial governor, acting on orders from Emperor Maximian, began to persecute Christians. Agathonicus'' companion Zoticus was arrested in Carpe during this persecution, and crucifixion was the fate of his followers. Zoticus was sent to Nicomedia. From there, Agathonicus, his companions Princeps, Theoprepius, Acyndinus, Severian and Zeno, and many others were taken on to Byzantium. Many of the companions perished during the journey from exhaustion and abuse, and the rest were put to death at Chalcedon. Those who survived were brought to Selymbria in Thrace, where they were tortured before the Greek Emperor and then beheaded.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Agathonicus", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmvx0ddpe01x8u7z5mckhvdwu'
  AND content."slug" = 'saint-agathonicus'
  AND md5(content."payload"->>'biography') = 'a32299f48ddbb8ae581861a8a647fbab';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Edward Colman, sometimes spelled Coleman, was an English Catholic who served as a courtier to Charles II of England. Titus Oates implicated him in the false accusations he made about a Popish Plot, and he was executed by hanging, drawing and quartering on a charge of treason. He is a Catholic martyr; Pope Pius XI beatified him in 1929.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Edward_Colman_(martyr)", "biography": "rewritten"}'::jsonb),
