UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Hermogius, a Benedictine bishop, was the uncle of Pelagius of Cordova. A native of Tui, Spain, he founded Labrugia Monastery in 915, in the Spanish part of Galicia. Soon after, the Moors, who had lately conquered that area, took him prisoner. He was freed once Pelagius, his nephew, replaced him as a hostage held by the Moors. Pelagius later died as a martyr, while Hermogius withdrew to Ribas del Sil and died there in 942.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Hermogius", "biography": "rewritten"}'::jsonb),
