UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Felix of Como, venerated as Como''s first bishop, died on October 8, 391 AD. Ambrose, a friend of his, praised his missionary work, and ordained him priest in 379 and bishop in 386. Bassianus of Lodi built a church at Lodi dedicated to the Apostles, and consecrated it with Ambrose and Felix present. Felix is remembered as an ardent pastor of souls. 8 October is his feast day.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Felix_of_Como", "biography": "rewritten"}'::jsonb),
