UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Bernardin Gantin, a Beninese Catholic prelate, spent twenty years in senior positions of the Roman Curia, and for nine years he led the College of Cardinals as its top-ranking member. No African had previously risen so high in the Church''s hierarchy, and few non-Italians have matched it.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Bernardin_Gantin", "biography": "rewritten"}'::jsonb),
