UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saints Modestinus, Florentinus and Flavianus were three Christian martyrs from Campania, Italy, who were put to death in 311. Like others, they had sought refuge on Monte Vergine. Gugliemo, bishop of Avellino, rediscovered their relics in 1167.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Modestinus%2C_Florentinus_and_Flavianus", "biography": "rewritten"}'::jsonb),
