UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The English monk Richard Whiting O.S.B was Glastonbury''s last abbot; he lived from 1461 to 15 November 1539. He was abbot of Glastonbury Abbey when the monasteries were being dissolved under King Henry VIII of England, a process known as the Dissolution of the Monasteries that lasted 1536–1541. After being convicted of treason for staying loyal to Rome, he was hanged, drawn and quartered on the king''s order. The Catholic Church regards him as a martyr and beatified him on 13 May 1895.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Richard_Whiting_(abbot)", "biography": "rewritten"}'::jsonb),
