UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A member of the Order of Saint Benedict, John Eynon, OSB, was a monk who served as pastor of St Giles''s parish in Reading, England. Robert Aske''s proclamation explaining the reasons for the Pilgrimage of Grace had been circulated in copies at Reading, and Eynon was among those who made one.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/John_Eynon", "biography": "rewritten"}'::jsonb),
