UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Peter Lieou, also known as Liu Wenyuan Petrus / Baiduo / Peter Liu Wenyuan, was a Chinese Catholic convert, layman, missionary and martyr. Because he was a Christian and preached Christianity in China, he was exiled and then strangled to death in prison.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Peter_Lieou", "biography": "rewritten"}'::jsonb),
