UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Born in Ireland, Mary Angeline Teresa McCrory emigrated to the United States. As a Roman Catholic religious sister she advocated for poor elderly people, and to serve them she founded a new religious congregation, named Carmelite Sisters for the Aged and Infirm. Her beatification cause is now open. The Holy See has acknowledged that her life was one of heroic virtue, and the Catholic Church has declared her venerable.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Mary_Angeline_Teresa_McCrory", "biography": "rewritten"}'::jsonb),
