UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A Roman martyr, Saint Paulina died c. 302; June 6 is her feast day. Her parents were Saints Artemius and Candida of Rome. Saint Peter the Exorcist converted her to Christianity, and Saint Marcellinus baptized her. Tradition holds that she met her martyrdom through live burial under a pile of stones. Pope Gregory XV gave remains attributed to her to the Jesuit Mutio Vitelleschi in 1622. In 1623 Mikołaj Łęczycki, his subordinate, brought the remains to Olomouc, a town then hit by a Plague pandemic. Archbishop Franz von Dietrichstein made her patron saint of both Olomouc and its archdiocese.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Paulina_of_Rome", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmvx0ipw502biu7z5oor250rh'
