  AND md5(content."payload"->>'biography') = 'e62f320712cfa372cf6d770ceec77269';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Venerated as a martyr and saint, Silvanus of Ahun has a name that appears in other forms: Sylvanus, and in French Silvain, Sauvan, Salvan and Souvain. Tradition holds that he was a deacon killed by Vandals on 16 October 407, during the clash at Agedunum, which is also named Acitodunum (Ahun).'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Silvanus_of_Ahun", "biography": "rewritten"}'::jsonb),
