UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A Jesuit priest from England, Edward Oldcorne (alias Hall) was known to people with knowledge of the Gunpowder Plot, which aimed at killing King James I and destroying the Parliament of England; his own part is unclear, but he was drawn into the investigation that followed. The Roman Catholic Church counts him a martyr; he was beatified in 1929.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Edward_Oldcorne", "biography": "rewritten"}'::jsonb),
