UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Agricola of Nevers (French: Agricole de Nevers; d. 594) held the see of Nevers as bishop from 580 until 26 February 594. He was present at the Third Council of Mâcon (585), and earlier, in 581, at both the Second Council of Mâcon and the Council of Lyon (581). The Roman Catholic Church venerates him as a saint, with his feast day on 26 February.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Agricola_of_Nevers", "biography": "rewritten"}'::jsonb),
