  AND md5(content."payload"->>'biography') = '2fbda044ae646f63e8c91aa4e823f01a';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A Brazilian Catholic child, Benigna Cardoso da Silva lived from 15 October 1928 to 24 October 1941. After her parents died she was adopted, and she was known for helping with the housework and going to Mass regularly. She was murdered in 1942 after she turned down Raimundo Alves Riberio, a boy around her age who made sexual advances, so as to protect herself as the chaste girl she wished to be. She resisted until Riberio killed her with a machete he carried on him. Her cause for beatification started in 2013; on 24 October 2022 she was beatified.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Benigna_Cardoso_da_Silva", "biography": "rewritten"}'::jsonb),
