UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Argentine religious sister Camila Rolón, who took the religious name Camila of Saint Joseph, lived from 18 July 1842 to 16 February 1913. As founder, she established the Poor Sisters of Saint Joseph. In the 1870s she survived cholera in Buenos Aires, an outbreak in which her mother and brother died, and afterward tried to join either the Carmelites or the Capuchin Poor Clares. She moved to Mercedes in 1880 and established an orphanage there, which later developed into a religious congregation. The congregation grew until its motherhouse moved to Rome, and she moved there as well and died in that city. Her beatification process began in 1950, even though the cause was not formally introduced until 1975. She was named venerable in 1993, when Pope John Paul II confirmed that Rolón had lived a life of heroic virtue.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Camila_Rol%C3%B3n", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmvx0n1jr02liu7z5tqgex86m'
  AND content."slug" = 'saint-camila-rolon'
  AND md5(content."payload"->>'biography') = '3d6b1d4e825b591660bdd21cb6b013d3';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Antiochus of Sulcis was a martyr of the early Christian era in Sardinia. Both the island and the town of Sant''Antioco take their names from him.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Antiochus_of_Sulcis", "biography": "rewritten"}'::jsonb),
