UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Landulf of Yariglia (Italian: Beato Landolfo da Vareglate) was a Benedictine Bishop of Asti, Italy. He was born late in the eleventh century at ‘Vareglate’, a place identified both with the village of Vergiate, north of Milan, and with Variglié, a locality near Asti. At San Pietro in Ciel d''Oro, a Benedictine monastery in Pavia, he received his education, though he never became a monk.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Landulf_of_Yariglia", "biography": "rewritten"}'::jsonb),
