UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The deacon Apollonius and Philemon, whom he converted, were Christian martyrs in the Diocletianic Persecution around 303. At Antinoöpolis in Egypt, Philemon was a well-known flute player, mime and actor.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Apollonius_and_Philemon", "biography": "rewritten"}'::jsonb),
