UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Gregorio Pietro XV Agagianian, an Armenian Catholic prelate, held the office of Patriarch of Cilicia between 1937 and 1962. From 1958 to 1970 he also served as Prefect of Propaganda Fide, the Vatican congregation tasked with propagating the faith. Pope Pius XII created him a cardinal in 1946, and he was twice regarded as papabile, in 1958 and again in 1963.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Gregorio_Pietro_Agagianian", "biography": "rewritten"}'::jsonb),
