UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Born Filippo Latini on 6 February 1605, Bernardo da Corleone (died 12 January 1667) was a Capuchin friar from Sicily. Like his father he worked as a cobbler until his father died, after which he became a soldier with a violent temper, ready to challenge to a duel anyone who insulted him or the causes he championed. One duel went too far, however, and he nearly killed his opponent. He took refuge with the Franciscans in Palermo, where he underwent a radical conversion and repented of his earlier life. He was canonized by Pope John Paul II on 10 June 2001.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Bernard_of_Corleone", "biography": "rewritten"}'::jsonb),
