  AND md5(content."payload"->>'biography') = '90ae2c593f090625d8d79cf54326c50e';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'A Carthusian nun, Beatrice of Ornacieux (also Blessed Beatrix d''Ornacieux) lived c. 1240–1306/09, and her feast day is 25 November. She established a Carthusian house at Eymieux, in Drôme department. Her Vita, composed by Marguerite of Oingt, records her special devotion to the Passion of Christ; she is said to have pushed a nail through her left hand so as to feel the sufferings of the Crucifixion. In 1869 her cultus received confirmation from Pius IX; the reference is "Anal. jur. pont.", 1869, XI, 264. Bellanger and Chapuis wrote modern lives of her, and Lecoulteux gives a full account in "Ann. Ord. Cath." (V, 5). The current Carthusian Calendar likewise places her feast on 25 November.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Beatrice_of_Ornacieux", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmvx0qb6202v3u7z5x05n4omd'
  AND content."slug" = 'saint-beatrice-of-ornacieux'
  AND md5(content."payload"->>'biography') = 'f1c9c8f6ba00c4ceec1f13707793af4b';

