UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Moura, called Mart Moura as well, was a martyr, a Christian of the third century, venerated in Egypt and across the Middle East. Her feast falls on 3 May and again on 25 September, while the Coptic church keeps it on 5 Hathor and 8 Pashons.
A number of churches bear her name, particularly in northern Lebanon, and a monastery in Ehden is dedicated to her too.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Saint_Moura", "biography": "rewritten"}'::jsonb),
