UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Saint Berno of Cluny, or Berno of Baume, served as the first abbot of Cluny, holding the office from the abbey''s foundation in 909 until his death in 927. The Cluniac reforms, which his successors carried throughout Europe, began with him.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Berno_of_Cluny", "biography": "rewritten"}'::jsonb),
