UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Francisco Palau y Quer, OCD (Catalan: Francesc Palau i Quer; religious name Francisco of Jesus, Mary and Joseph), lived from 29 December 1811 to 20 March 1872 and was a Catalan Discalced Carmelite priest. He grew up amid the turmoil of the Peninsular War in Spain, and he lived both as a hermit and as a missionary preacher in the rural parts of Catalonia. In Barcelona he established the School of Virtue, which served as a pattern for catechetical teaching of adults. In 1860, in the Balearic Islands, he founded a congregation of the Carmelite Third Order open to both men and women. Two religious congregations of women, active around the world, continue the legacy of this foundation. Drawing on his Carmelite spiritual tradition, Palau sought to promote the view that the spiritual life must rest on recognizing God''s love and returning it, in opposition to the rationalism found in the theology of his time. Palau was beatified in 1988. One follower in spirit was Teresa of Jesus Jornet, his great-niece, who established a religious congregation of Carmelite sisters devoted to caring for the elderly poor. She is honored as a saint.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Francisco_Palau", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmvx0swi3033fu7z5oxg212jb'
  AND content."slug" = 'saint-francisco-palau'
  AND md5(content."payload"->>'biography') = '7d5207c776157bfc3f27847c24819492';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Turin was the birthplace of Maria Clotilde of Savoy, daughter of Vittorio Emanuele II, later King of Italy, and Adelaide of Austria, his first wife. Prince Napoléon-Jérôme Bonaparte was her husband. She was a Dominican tertiary, belonging to the Third Order of Saint Dominic. Pope Pius XII declared her a Servant of God.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Princess_Maria_Clotilde_of_Savoy", "biography": "rewritten"}'::jsonb),
