UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The bishop of Vienne in Dauphiné, a French region, during the 8th century''s first half was Austrebert, also called Austrebertus. A letter dated 31 August 719 from Pope Gregory II shows him in office, and he was still there on 7 March 742, when Pope Zachary wrote to him. Soon after that date, raids by the Saracens forced Austrebert to flee Vienne, and he died "very far from Vienne".'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Austrebert_of_Vienne", "biography": "rewritten"}'::jsonb),
