UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pope Urban II (known as Odo of Châtillon, and also as Otho de Lagery) led the Catholic Church, and governed the Papal States, beginning 12 March 1088 and continuing until his death. He is best remembered for calling the Council of Clermont, which set in motion the Catholic military expeditions called the Crusades.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Pope_Urban_II", "biography": "rewritten"}'::jsonb),
