UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Isabella I, known too as Isabella the Catholic, ruled as Queen of Castile and León between 1474 and her death in 1504. Through her marriage to King Ferdinand II she was likewise Queen of Aragon, from 1479 to the end of her life. The two monarchs governed a dynastically unified Spain together and are called the Catholic Monarchs. Under her rule the Reconquista came to an end and the Spanish Empire began, which let Spain grow into a leading power in European politics.'::text) || jsonb_build_object('provenance', '{"article": "https://en.wikipedia.org/wiki/Isabella_I_of_Castile", "biography": "rewritten"}'::jsonb),
