UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'John Felton was an English Catholic executed as a martyr under Elizabeth I. The Bishop of London''s palace stood near St. Paul''s, and Felton fixed at its gates a copy of Regnans in Excelsis, Pope Pius V''s bull, which excommunicated Queen Elizabeth. He was arrested for this.'::text) || jsonb_build_object('provenance', '{"feast": "wikipedia", "article": "https://en.wikipedia.org/wiki/John_Felton_(martyr)", "biography": "rewritten"}'::jsonb),
    "contentChecksum" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE content."id" = 'cmvx4gpw3000v5cqi41yq4uhl'
  AND content."slug" = 'saint-john-felton'
  AND md5(content."payload"->>'biography') = '9882111e1797a8e871ee3125f0b56f91';

