UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'In the 3rd century AD Demetrius of Antioch was the patriarch of Antioch. Shapur I took him to Persia as a captive in 253, and in that country he served as Gundeshapur''s first bishop. Though far removed from his original see, Demetrius kept the patriarchate of Antioch until 260, when Paul of Samosata succeeded to it.'::text) || jsonb_build_object('provenance', '{"feast": "roman-martyrology-1916", "article": "https://en.wikipedia.org/wiki/Demetrius_of_Antioch", "feastUrl": "https://archive.org/details/romanmartyrology00cathuoft", "biography": "rewritten"}'::jsonb),
