  AND md5(content."payload"->>'biography') = 'efedfb4cab8ff2721218549152ba68d7';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Elias of Palestine, an early Christian martyr, was a priest and one of four Christians who celebrated Mass for the persecuted Christians sentenced to labor in the quarries of Palestine after the Diocletianic Persecution. The Roman emperor Galerius, on hearing of this, ordered Elias and the other leaders burned alive, and the Christians were scattered to mines in Cyprus and Lebanon. The Roman Catholic Church and the Eastern Orthodox Church venerate him as a saint.'::text) || jsonb_build_object('provenance', '{"feast": "roman-martyrology-1916", "article": "https://en.wikipedia.org/wiki/Elias_of_Palestine", "feastUrl": "https://archive.org/details/romanmartyrology00cathuoft", "biography": "rewritten"}'::jsonb),
