WHERE content."id" = 'cmvx4w7px01p25cqii1zubhwk'
  AND content."slug" = 'saint-elias-of-palestine'
  AND md5(content."payload"->>'biography') = '4771fb4b2278fc8bdb24190266e2b19a';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Pope Leo IV is remembered for restoring the Roman churches damaged in the Arab raid on Rome, and for raising the Leonine Wall around Vatican Hill as a defense for the city. His time as bishop of Rome and ruler of the Papal States ran from 10 April 847 until he died in 855. He also brought together a league of Italian cities, which fought the Saracens and won the naval Battle of Ostia.'::text) || jsonb_build_object('provenance', '{"feast": "roman-martyrology-1916", "article": "https://en.wikipedia.org/wiki/Pope_Leo_IV", "feastUrl": "https://archive.org/details/romanmartyrology00cathuoft", "biography": "rewritten"}'::jsonb),
