  AND content."slug" = 'saint-leo-iv'
  AND md5(content."payload"->>'biography') = 'a2991fbaca206c2edf0324a8c75c6948';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Nilus of Palestine, an early Christian martyr, was an Egyptian bishop and one of four Christians who celebrated Mass for the persecuted Christians sentenced to labor in the quarries of Palestine after the Diocletianic Persecution. The Roman emperor Galerius, on hearing of this, ordered Nilus and the other leaders burned alive, and the Christians were scattered to mines in Cyprus and Lebanon. The Roman Catholic Church, the Eastern Orthodox Church and the Oriental Orthodox Churches venerate him as a saint.'::text) || jsonb_build_object('provenance', '{"feast": "roman-martyrology-1916", "article": "https://en.wikipedia.org/wiki/Nilus_of_Palestine", "feastUrl": "https://archive.org/details/romanmartyrology00cathuoft", "biography": "rewritten"}'::jsonb),
