UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Archippus was a poet of the Old Comedy in Athens. The Fishes was his most famous play, in which he mocked the Athenian epicures for loving fish. Four plays once assigned to Aristophanes were credited to him by the Alexandrian critics. His contemporaries ridiculed Archippus for his love of puns.'::text) || jsonb_build_object('provenance', '{"feast": "roman-martyrology-1916", "article": "https://en.wikipedia.org/wiki/Archippus_(poet)", "feastUrl": "https://archive.org/details/romanmartyrology00cathuoft", "biography": "rewritten"}'::jsonb),
