  AND content."slug" = 'saint-archippus-q276575'
  AND md5(content."payload"->>'biography') = 'cab7fc2d3312b6e2f21dd36cd7081cfc';

UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Born in France, Saint Bonitus (623–710) was named governor of Marseille in 667, became Bishop of Auvergne, and held several other important posts, including chancellor and referendary in Francia. The Eastern Orthodox Church and the Roman Catholic Church venerate him as a saint.'::text) || jsonb_build_object('provenance', '{"feast": "roman-martyrology-1916", "article": "https://en.wikipedia.org/wiki/Bonitus_(bishop)", "feastUrl": "https://archive.org/details/romanmartyrology00cathuoft", "biography": "rewritten"}'::jsonb),
