UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'Severus von Trier served as bishop of Trier beginning around 445/446. He preached to the Germanic peoples who lived in the lower Moselle and Middle Rhine regions and helped bring about their conversion.'::text) || jsonb_build_object('provenance', '{"feast": "roman-martyrology-1916", "article": "https://en.wikipedia.org/wiki/Severus_of_Trier", "feastUrl": "https://archive.org/details/romanmartyrology00cathuoft", "biography": "rewritten"}'::jsonb),
