UPDATE "PublishedContent" AS content
SET "payload" = content."payload" || jsonb_build_object('biography', 'The persecution of 177 AD took place in Lugdunum (modern Lyon) in Roman Gaul, under Marcus Aurelius, when Christians were attacked. A letter from the time describes these events, and it is preserved in book 5, chapter 1 of Eusebius''s Ecclesiastical History, which was composed 150 years later in Syria Palaestina. In the 6th century, Gregory of Tours also described the persecution, in De Gloria martyrum.'::text) || jsonb_build_object('provenance', '{"feast": "roman-martyrology-1916", "article": "https://en.wikipedia.org/wiki/Persecution_in_Lyon", "feastUrl": "https://archive.org/details/romanmartyrology00cathuoft", "biography": "rewritten"}'::jsonb),
